GACHA_COST = 100  # 1回あたりの消費Mコイン
GACHA_MAX_PERSONAS_PER_USER = 30  # 1ユーザーが保持できるペルソナの上限（超えたら最古のものを破棄）
GACHA_COOLDOWN_SECONDS = 7 * 24 * 60 * 60  # ガチャは1週間に1回まで


def _gacha_format_remaining(seconds: float) -> str:
    """クールダウン残り秒数を「〇日〇時間〇分」形式の文字列に整形します。"""
    seconds = max(0, int(seconds))
    days, rem = divmod(seconds, 86400)
    hours, rem = divmod(rem, 3600)
    minutes, _ = divmod(rem, 60)
    parts = []
    if days:
        parts.append(f"{days}日")
    if hours:
        parts.append(f"{hours}時間")
    if minutes or not parts:
        parts.append(f"{minutes}分")
    return "".join(parts)

# レアリティ: (表示名, 排出率%, 個性の強さの指示文)
GACHA_RARITIES = [
    ("N", 80, "ごく普通で親しみやすい、ありふれた個性にしてください。"),
    ("R", 17, "少し個性的で分かりやすい特徴を1つ持たせてください。"),
    ("SR", 2.5, "かなり尖った個性・強い口調や独特な世界観を持たせてください。"),
    ("SSR", 0.5, "非常に独特で強烈な、一度見たら忘れられないレベルの個性にしてください。"),
]

GACHA_RARITY_COLORS = {
    "N": discord.Color.light_grey(),
    "R": discord.Color.blue(),
    "SR": discord.Color.purple(),
    "SSR": discord.Color.gold(),
}

# レアリティ別の売却額（Mコイン）。GACHA_COST(100)より安く設定し、
# 「引く方が得」なバランスを保ちつつ、被り・不要ペルソナの整理手段として機能させる。
GACHA_SELL_PRICES = {
    "N": 10,
    "R": 30,
    "SR": 150,
    "SSR": 800,
}

# 称号: (称号ID, 表示名, 説明, 判定関数名)
# 判定関数は (persona_history: list[dict], draws: int, max_held: int) を引数に bool を返す。
# persona_history は「今まで一度でも獲得した全ペルソナのレアリティ履歴」（売却・交換しても消えない）。
# max_held は「同時所持数の歴代最大値」（コンプ系称号用）。
GACHA_TITLE_DEFS = [
    ("first_gacha", "はじめの一歩", "ガチャを1回引いた", lambda hist, draws, max_held: draws >= 1),
    ("ssr_hunter", "SSRハンター", "SSRを1体以上獲得した", lambda hist, draws, max_held: hist.count("SSR") >= 1),
    ("ssr_double", "強運の持ち主", "SSRを2体以上獲得した", lambda hist, draws, max_held: hist.count("SSR") >= 2),
    ("sr_collector", "SRコレクター", "SRを5体以上獲得した", lambda hist, draws, max_held: hist.count("SR") >= 5),
    ("veteran_10", "常連さん", "累計10回ガチャを引いた", lambda hist, draws, max_held: draws >= 10),
    ("veteran_50", "廃課金者予備軍", "累計50回ガチャを引いた", lambda hist, draws, max_held: draws >= 50),
    ("collector_full", "コンプリートを目指す者", "ペルソナを同時に30体所持した", lambda hist, draws, max_held: max_held >= GACHA_MAX_PERSONAS_PER_USER),
]


def _gacha_compute_titles(user_app_data: dict) -> list:
    """ユーザーの累計獲得履歴・累計抽選回数・歴代最大所持数から、達成済みの称号IDリストを計算します。"""
    hist = user_app_data.get("gacha_rarity_history", [])
    draws = user_app_data.get("gacha_total_draws", 0)
    max_held = user_app_data.get("gacha_max_held", len(user_app_data.get("gacha_personas", [])))
    earned = []
    for title_id, _name, _desc, check_fn in GACHA_TITLE_DEFS:
        try:
            if check_fn(hist, draws, max_held):
                earned.append(title_id)
        except Exception:
            pass
    return earned


def _gacha_title_display_name(title_id: str) -> Optional[str]:
    for tid, name, _desc, _fn in GACHA_TITLE_DEFS:
        if tid == title_id:
            return name
    return None


def _gacha_roll_rarity() -> tuple:
    """排出率に基づきレアリティを1つ抽選し、(name, flavor_instruction) を返します。"""
    import random
    roll = random.uniform(0, 100)
    cumulative = 0.0
    for name, rate, flavor in GACHA_RARITIES:
        cumulative += rate
        if roll <= cumulative:
            return name, flavor
    return GACHA_RARITIES[0][0], GACHA_RARITIES[0][2]  # 保険（丸め誤差対策）


def _gacha_persona_to_system_prompt(persona: dict) -> str:
    """ガチャで生成したペルソナ辞書を、/ai で使うシステムプロンプト文字列に変換します。"""
    name = persona.get("name", "名無し")
    first_person = persona.get("first_person", "私")
    personality = persona.get("personality", "")
    speech_style = persona.get("speech_style", "")
    catchphrase = persona.get("catchphrase", "")

    parts = [
        f"あなたは「{name}」という名前のキャラクターとして振る舞ってください。",
        f"一人称は「{first_person}」を使ってください。",
    ]
    if personality:
        parts.append(f"性格: {personality}")
    if speech_style:
        parts.append(f"話し方の特徴: {speech_style}")
    if catchphrase:
        parts.append(f"よく使う口癖・決め台詞: 「{catchphrase}」")
    parts.append("このキャラクター設定を一貫して維持し、キャラクターを崩さずに応答してください。")
    return "\n".join(parts)


