async def extract_text_from_image(image_url):
    try:
        async with aiohttp.ClientSession() as session:

            async with session.get(image_url) as image_response:
                image_data = await image_response.read()

            form = aiohttp.FormData()
            form.add_field(
                "file",
                image_data,
                filename="image.png"
            )

            async with session.post(
                "https://api.ocr.space/parse/image",
                data=form,
                headers={
                    "apikey": OCR_SPACE_API_KEY
                }
            ) as response:

                result = await response.json()

                if not result.get("ParsedResults"):
                    return ""

                text = ""

                for item in result["ParsedResults"]:
                    text += item.get("ParsedText", "")

                return text.lower()

    except Exception as e:
        print(f"OCR Error: {e}")
        return ""



def get_global_config(all_data: dict) -> dict:
    """グローバル設定（信頼できるユーザーなど）を取得します。"""
    if "global_config" not in all_data:
        all_data["global_config"] = {
            "trusted_users": []
        }
    cfg = all_data["global_config"]
    # 荒らしリスト（全サーバー共有）
    if "troll_list" not in cfg:
        cfg["troll_list"] = {}  # {user_id_str: {"username": str, "avatar_url": str, "reason": str, "date": str, "banned_in": [guild_id_str...]}}
    # グローバルコイン（全サーバー共通）
    if "global_balances" not in cfg:
        cfg["global_balances"] = {}   # {user_id_str: int}
    if "global_bank" not in cfg:
        cfg["global_bank"] = {}       # {user_id_str: int} 銀行預け入れ残高
    if "global_last_work" not in cfg:
        cfg["global_last_work"] = {}  # {user_id_str: unix_timestamp}
    if "global_last_sell" not in cfg:
        cfg["global_last_sell"] = {}  # {user_id_str: unix_timestamp} 売る機能（週1回）
    # ブラックリスト掲載チャンネル（サーバーごとに設定）
    if "troll_board_channel_id" not in cfg:
        cfg["troll_board_channel_id"] = {}  # {guild_id_str: channel_id_int}
    # グローバルコイン設定（オーナーのみ変更可能）
    if "global_coin_name" not in cfg:
        cfg["global_coin_name"] = "Mコイン"
    if "global_work_reward_min" not in cfg:
        cfg["global_work_reward_min"] = 10
    if "global_work_reward_max" not in cfg:
        cfg["global_work_reward_max"] = 50
    if "global_work_cooldown_seconds" not in cfg:
        cfg["global_work_cooldown_seconds"] = 7200  # 2時間
    if "global_msg_reward_min" not in cfg:
        cfg["global_msg_reward_min"] = 1
    if "global_msg_reward_max" not in cfg:
        cfg["global_msg_reward_max"] = 5
    if "global_msg_cooldown_seconds" not in cfg:
        cfg["global_msg_cooldown_seconds"] = 60
    if "global_msg_last_earned" not in cfg:
        cfg["global_msg_last_earned"] = {}  # {user_id_str: unix_timestamp}
    # プロフィールカードの背景画像（全サーバー共通。ユーザーが /profile background set でアップロード）
    if "profile_backgrounds" not in cfg:
        cfg["profile_backgrounds"] = {}  # {user_id_str: 画像URL}
    # プロフィールカードのアクセントカラー（全サーバー共通。ユーザーが /profile card_color set で設定）
    if "profile_card_colors" not in cfg:
        cfg["profile_card_colors"] = {}  # {user_id_str: [r, g, b]}
    # バッジ定義（オーナーが /profile badge create で作成）とユーザーへの付与記録
    if "badge_defs" not in cfg:
        cfg["badge_defs"] = {}  # {badge_id_str: {"name": str, "color": [r,g,b], "symbol": str, "created_at": iso_str}}
    if "user_badges" not in cfg:
        cfg["user_badges"] = {}  # {user_id_str: [badge_id_str, ...]}
    # サーバーブラックリスト（全サーバー共通）
    if "global_server_blacklist_ids" not in cfg:
        cfg["global_server_blacklist_ids"] = []  # [server_id_int, ...]
    # AFK機能: DM・グループDM用（サーバーに紐付かないためグローバル領域で管理）
    if "global_afk_users" not in cfg:
        cfg["global_afk_users"] = {}  # {user_id_str: {"reason": str, "since": unix_timestamp}}
    # ステータス表示用: 再起動をまたいで引き継ぐ累計値
    if "bot_stats_total_uptime_seconds" not in cfg:
        cfg["bot_stats_total_uptime_seconds"] = 0  # これまでの累計稼働秒数（Bot停止中の時間は含まない）
    if "bot_stats_command_exec_count" not in cfg:
        cfg["bot_stats_command_exec_count"] = 0    # これまでに実行されたスラッシュコマンドの累計回数
    # DM（/ai コマンド）でのAIチャット設定（サーバーに紐付かないためグローバル領域で管理）
    if "dm_ai_chat_enabled" not in cfg:
        cfg["dm_ai_chat_enabled"] = True            # True: /ai コマンドを許可する（オーナーが /ai_chat dm off で無効化可）
    if "dm_ai_chat_cooldown_seconds" not in cfg:
        cfg["dm_ai_chat_cooldown_seconds"] = 10      # /ai コマンドの連投制限（秒）
    if "dm_ai_chat_blocked_users" not in cfg:
        cfg["dm_ai_chat_blocked_users"] = []         # [user_id_int, ...] /ai コマンドの利用をブロックされたユーザー
    return cfg


def get_global_balance(all_data: dict, user_id: int) -> int:
    """ユーザーのグローバル所持金（財布）を取得します。"""
    global_cfg = get_global_config(all_data)
    return global_cfg["global_balances"].get(str(user_id), 0)


def get_global_bank(all_data: dict, user_id: int) -> int:
    """ユーザーのグローバル銀行残高を取得します。"""
    global_cfg = get_global_config(all_data)
    return global_cfg["global_bank"].get(str(user_id), 0)


def add_global_balance(all_data: dict, user_id: int, amount: int):
    """ユーザーのグローバル所持金に amount を加算（負数で減算、0未満にはならない）。"""
    global_cfg = get_global_config(all_data)
    uid = str(user_id)
    current = global_cfg["global_balances"].get(uid, 0)
    global_cfg["global_balances"][uid] = max(0, current + amount)


def format_mcoin(all_data: dict, amount: int) -> str:
    """Mコイン形式の金額表示文字列を作成します。"""
    global_cfg = get_global_config(all_data)
    name = global_cfg.get("global_coin_name", "Mコイン")
    return f"{amount:,} {name}"


def add_to_troll_list(all_data: dict, member: discord.Member, guild: discord.Guild, reason: str = "サーバーBLによるBAN"):
    """BANされたユーザーを全サーバー共有の荒らしリストに追加・更新します。"""
    global_cfg = get_global_config(all_data)
    troll_list = global_cfg["troll_list"]
    uid_str = str(member.id)
    avatar_url = str(member.display_avatar.url) if member.display_avatar else ""
    guild_id_str = str(guild.id)
    account_link = f"https://discord.com/users/{member.id}"
    if uid_str in troll_list:
        entry = troll_list[uid_str]
        if guild_id_str not in entry.get("banned_in", []):
            entry.setdefault("banned_in", []).append(guild_id_str)
        # アバターURL・ユーザー名・アカウントリンクは最新情報で更新
        entry["username"] = str(member)
        entry["avatar_url"] = avatar_url
        entry["account_link"] = account_link
    else:
        troll_list[uid_str] = {
            "username": str(member),
            "user_id": member.id,
            "avatar_url": avatar_url,
            "account_link": account_link,
            "reason": reason,
            "date": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "banned_in": [guild_id_str],
        }


async def resolve_owner_id(client) -> int | None:
    """
    Botの「オーナー」として扱うDiscordユーザーIDを解決します。

    - 個人所有アプリ（Team未使用）の場合:
        application_info().owner.id がそのまま個人ユーザーIDになります。
    - Team所有アプリ（Discord Developer Portalで「Team」に移行した場合）の場合:
        application_info().owner は個人ではなく Team を指すため、
        application_info().team.owner_id（＝そのTeamを作成した個人のユーザーID）を
        優先的にオーナーIDとして採用します。
        これにより、Bot認証（Verification）等の都合でアプリをTeam所有に切り替えても、
        オーナー専用コマンド（!sync, /owner_* , /customtrigger , /customcmd_manage 等）を
        従来どおりチームオーナー本人が実行できます。

    解決済みの値は client.owner_id にキャッシュされ、以後はAPI呼び出しなしで再利用されます。
    """
    if client.owner_id is not None:
        return client.owner_id

    try:
        app_info = await client.application_info()
    except Exception as e:
        print(f"[警告] application_info の取得に失敗しました: {e}")
        return None

    # Team所有アプリかどうかを判定
    team = getattr(app_info, "team", None)
    if team is not None and getattr(team, "owner_id", None):
        client.owner_id = team.owner_id
        print(f"[システム] Team所有アプリを検出しました。Teamオーナー（{team.owner_id}）をBotオーナーとして採用します。")
    else:
        client.owner_id = app_info.owner.id

    return client.owner_id


async def is_owner_check(interaction: discord.Interaction) -> bool:
    """インタラクションの実行者がBotのオーナーかどうかを判定します。"""
    owner_id = await resolve_owner_id(interaction.client)

    if interaction.user.id != owner_id:
        await interaction.response.send_message("このコマンドはアプリの所有者（オーナー）専用です。", ephemeral=True)
        return False
    return True


async def is_trusted_user(interaction: discord.Interaction) -> bool:
    """実行者がBotのオーナー、またはオーナーによって許可されたユーザーか判定します。"""
    owner_id = await resolve_owner_id(interaction.client)

    user_id = interaction.user.id
    if user_id == owner_id:
        return True

    all_data = load_data()
    global_cfg = get_global_config(all_data)
    if user_id in global_cfg.get("trusted_users", []):
        return True

    await interaction.response.send_message(
        "このコマンドはBotの所有者、または許可されたユーザー専用です。", ephemeral=True
    )
    return False


async def is_admin_or_allowed(interaction: discord.Interaction) -> bool:
    """実行者がサーバー管理者、または設定された『コマンド許可ユーザー』かどうかを判定します。"""
    owner_id = await resolve_owner_id(interaction.client)

    if interaction.user.id == owner_id:
        return True

    if not interaction.guild:
        # DM・グループDMはBotオーナーのみ許可（上記でオーナーは通過済み）
        await interaction.response.send_message("このコマンドを実行する権限がありません（管理者または許可ユーザー専用）。", ephemeral=True)
        return False

    if interaction.user.guild_permissions.administrator:
        return True
    
    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))
    if interaction.user.id in cfg.get("allowed_users", []):
        return True

    # 許可ロールを持っているか確認
    allowed_role_ids = set(cfg.get("allowed_roles", []))
    if allowed_role_ids:
        user_role_ids = {r.id for r in interaction.user.roles}
        if user_role_ids & allowed_role_ids:
            return True

    await interaction.response.send_message("このコマンドを実行する権限がありません（管理者または許可ユーザー専用）。", ephemeral=True)
    return False


async def is_moderator(interaction: discord.Interaction) -> bool:
    """
    実行者が「Botオーナー」「グローバル信頼ユーザー」「サーバー管理者」「サーバー内許可ユーザー」
    のいずれかに該当するかどうかを判定します（管理・モデレーションコマンド用）。
    """
    owner_id = await resolve_owner_id(interaction.client)

    user_id = interaction.user.id
    if user_id == owner_id:
        return True

    all_data = load_data()
    global_cfg = get_global_config(all_data)
    if user_id in global_cfg.get("trusted_users", []):
        return True

    if not interaction.guild:
        await interaction.response.send_message("このコマンドはサーバー内で実行してください。", ephemeral=True)
        return False

    if interaction.user.guild_permissions.administrator:
        return True

    cfg = get_guild_config(all_data, str(interaction.guild.id))
    if user_id in cfg.get("allowed_users", []):
        return True

    # 許可ロールを持っているか確認
    allowed_role_ids = set(cfg.get("allowed_roles", []))
    if allowed_role_ids:
        user_role_ids = {r.id for r in interaction.user.roles}
        if user_role_ids & allowed_role_ids:
            return True

    await interaction.response.send_message(
        "このコマンドを実行する権限がありません（モデレーター権限が必要です）。", ephemeral=True
    )
    return False


async def is_guild_admin(interaction: discord.Interaction) -> bool:
    """実行者がサーバーの管理者（Administrator）かどうかを判定します。"""
    owner_id = await resolve_owner_id(interaction.client)

    if interaction.user.id == owner_id:
        return True

    if not interaction.guild:
        await interaction.response.send_message("このコマンドはサーバー内で実行してください。", ephemeral=True)
        return False

    if interaction.user.guild_permissions.administrator:
        return True

    await interaction.response.send_message("このコマンドはサーバー管理者専用です。", ephemeral=True)
    return False


