def create_user_list_embed(allowed_users: list) -> discord.Embed:
    """コマンド使用を許可されたユーザー一覧の Embed を作成します。"""
    embed = discord.Embed(
        title="コマンド使用許可ユーザー一覧", 
        description="現在、以下のユーザーに権限が与えられています。\n※サーバー管理者は登録なしですべてのコマンドを使用できます。",
        color=discord.Color.blue()
    )
    if not allowed_users:
        embed.add_field(name="登録ユーザー", value="開示できるユーザーはいません。", inline=False)
        embed.set_footer(text="登録者数: 0名")
    else:
        user_mentions = [f"・<@{user_id}>" for user_id in allowed_users]
        embed.add_field(name="登録ユーザー", value="\n".join(user_mentions), inline=False)
        embed.set_footer(text=f"登録者数: {len(allowed_users)}名")
    return embed




GUILDS_PER_PAGE = 5

def build_guild_list_embed(guilds: list, page: int) -> discord.Embed:
    """導入中サーバーの一覧 Embed を改ページ対応で作成します。"""
    total_pages = max(1, (len(guilds) + GUILDS_PER_PAGE - 1) // GUILDS_PER_PAGE)
    start = page * GUILDS_PER_PAGE
    end = start + GUILDS_PER_PAGE
    page_guilds = guilds[start:end]

    embed = discord.Embed(
        title="導入中サーバー一覧",
        description=f"現在 **{len(guilds)}個** のサーバーに導入されています。",
        color=discord.Color.blurple()
    )

    for i, g in enumerate(page_guilds, start=start + 1):
        owner_text = f"<@{g.owner_id}>" if g.owner_id else "不明"
        embed.add_field(
            name=f"{i}. {g.name}",
            value=(
                f"ID: `{g.id}`\n"
                f"メンバー: **{g.member_count}人** | "
                f"オーナー: {owner_text}"
            ),
            inline=False
        )

    embed.set_footer(text=f"ページ {page + 1} / {total_pages}")
    return embed


async def update_bot_status(client, text=None):
    """Botのプレゼンス（カスタムステータス）を更新します。
    text（またはcurrent_custom_status）が設定されている間は、その文言を
    固定表示します。未設定の場合はローテーション表示（_status_rotation_loop）に
    委ねるため、ここではサーバー数のデフォルト表示のみを行います。"""
    global current_custom_status
    if text:
        current_custom_status = text

    status_text = current_custom_status if current_custom_status else f"{len(client.guilds)}個のサーバー"
    activity = discord.Activity(type=discord.ActivityType.watching, name=status_text)
    await client.change_presence(status=discord.Status.online, activity=activity)
    print(f"[ステータス更新] {status_text} を視聴中 (Online)")


async def _set_presence_text(client, text: str, activity_type: discord.ActivityType = discord.ActivityType.watching):
    """内部用: プレゼンスのテキストのみを直接変更します（current_custom_statusは変更しない）。
    ローテーション表示や起動中表示など、恒久設定ではない一時的なステータス切り替えに使用します。"""
    try:
        activity = discord.Activity(type=activity_type, name=text)
        await client.change_presence(status=discord.Status.online, activity=activity)
    except Exception as e:
        print(f"[警告] プレゼンス更新に失敗しました: {e}")


def _build_status_rotation_items(client) -> list:
    """ローテーション表示するステータス候補のリストを (ActivityType, テキスト) のタプルで返します。"""
    guild_count = len(client.guilds)
    command_count = len(client.tree.get_commands())
    # 稼働時間は「再起動前までの累計（_bot_prior_uptime_seconds）」+「今回起動からの経過」の合計で表示する。
    # これにより再起動を挟んでも稼働時間の表示がリセットされず、通算値として引き継がれる。
    uptime_seconds = _bot_prior_uptime_seconds + int(time.time() - _bot_start_time)
    days, rem = divmod(uptime_seconds, 86400)
    hours, rem = divmod(rem, 3600)
    minutes, _ = divmod(rem, 60)
    if days > 0:
        uptime_text = f"{days}日{hours}時間稼働中"
    elif hours > 0:
        uptime_text = f"{hours}時間{minutes}分稼働中"
    else:
        uptime_text = f"{minutes}分稼働中"

    items = [
        (discord.ActivityType.watching, f"{guild_count}個のサーバー"),
        (discord.ActivityType.playing, f"コマンド {command_count}種 / 実行 {_command_exec_count}回"),
        (discord.ActivityType.watching, uptime_text),
    ]
    # データ更新処理（統計チャンネル自動更新など）の実行中は「更新中」表示を挟む
    if _status_data_updating_count > 0:
        items.append((discord.ActivityType.playing, "データを更新中..."))
    return items


async def _status_rotation_loop(client):
    """current_custom_status が未設定の間、複数のステータス情報を一定間隔で
    自動的に切り替えて表示し続けるバックグラウンドループです。
    current_custom_status が設定された場合は自動的に一時停止し、
    解除（reset）されると自動的に再開します。"""
    index = 0
    while True:
        try:
            if _railway_deploy_status_override:
                # Railwayのデプロイ中は、他の何よりも優先してこの表示を維持する。
                await _set_presence_text(client, _railway_deploy_status_override, discord.ActivityType.watching)
                await asyncio.sleep(_status_rotation_interval)
                continue

            if current_custom_status:
                # カスタムステータスが手動設定されている間はローテーションを休止し、
                # 固定表示を維持する（update_bot_status側で既に反映済み）。
                await asyncio.sleep(_status_rotation_interval)
                continue

            items = _build_status_rotation_items(client)
            if not items:
                await asyncio.sleep(_status_rotation_interval)
                continue

            activity_type, text = items[index % len(items)]
            await _set_presence_text(client, text, activity_type)
            index += 1
        except asyncio.CancelledError:
            raise
        except Exception as e:
            print(f"[警告] ステータスローテーション中にエラーが発生しました: {e}")
        await asyncio.sleep(_status_rotation_interval)


def start_status_rotation(client):
    """ステータスローテーションのバックグラウンドタスクを起動します（重複起動防止つき）。"""
    global _status_rotation_task
    if _status_rotation_task is None or _status_rotation_task.done():
        _status_rotation_task = asyncio.create_task(_status_rotation_loop(client))
        print("[システム] ステータスローテーションを開始しました")


UPTIME_PERSIST_INTERVAL_SECONDS = 300  # 稼働時間を永続化する間隔（5分ごと）


async def _uptime_periodic_save_loop():
    """
    再起動をまたいでも稼働時間の表示・累計値がリセットされないよう、
    一定間隔で「これまでの累計稼働秒数」をディスクへ保存し続けるバックグラウンドタスクです。
    保存後は _bot_start_time を現在時刻にリセットすることで、次回保存までの増分だけを
    _bot_prior_uptime_seconds に加算していく方式にし、二重カウントを防ぎます。
    Botが不意に落ちた場合でも、直近の保存間隔（最大5分）以内の誤差に抑えられます。
    プロセス終了時（Ctrl+C等の正常終了）にも最後の一回を保存します。
    """
    global _bot_start_time, _bot_prior_uptime_seconds
    await bot.wait_until_ready()
    try:
        while True:
            await asyncio.sleep(UPTIME_PERSIST_INTERVAL_SECONDS)
            await _persist_uptime_once()
    except asyncio.CancelledError:
        # プロセス終了時などにキャンセルされた場合も、最後に一度だけ保存を試みる
        try:
            await _persist_uptime_once()
        except Exception:
            pass
        raise


async def _persist_uptime_once():
    """現在までの経過分を累計稼働秒数へ加算し、ディスクへ保存します。"""
    global _bot_start_time, _bot_prior_uptime_seconds
    now = time.time()
    elapsed = int(now - _bot_start_time)
    if elapsed <= 0:
        return
    try:
        all_data = await aload_data()
        global_cfg = get_global_config(all_data)
        new_total = global_cfg.get("bot_stats_total_uptime_seconds", 0) + elapsed
        global_cfg["bot_stats_total_uptime_seconds"] = new_total
        await asave_data(all_data)
        # 保存済み分を基準値に繰り込み、_bot_start_time をリセットして二重カウントを防ぐ
        _bot_prior_uptime_seconds = new_total
        _bot_start_time = now
    except Exception as e:
        print(f"[警告] 稼働時間の永続化に失敗しました: {e}")


# ====================================================================
# 招待トラッキング（/invite stats）
# ====================================================================
# discord.Invite.uses はキャッシュされた値のため、招待作成/削除イベントや
# 定期リフレッシュだけでは「誰が参加時にどの招待コードを使ったか」を直接は
# 特定できません。そこでギルドごとに「招待コード -> 直近のuses数」の
# スナップショットをメモリ上に保持し、on_member_join のたびに現在のuses数と
# 比較して増分（+1）があった招待コードを特定する方式を取ります。
# ※ メモリ上のキャッシュのため、Bot再起動直後は on_ready でのキャッシュ再構築が
#    完了するまでの短い間、新規参加者の招待元特定ができない場合があります。

_invite_uses_cache: dict = {}  # {guild_id: {invite_code: uses_count}}


async def _refresh_invite_cache_for_guild(guild: discord.Guild):
    """指定ギルドの招待コード一覧を取得し、uses数スナップショットを更新します。"""
    try:
        invites = await guild.invites()
        _invite_uses_cache[guild.id] = {inv.code: (inv.uses or 0) for inv in invites}
    except discord.Forbidden:
        # 「招待を管理」権限がない場合は静かにスキップ（招待トラッキングは無効扱いになる）
        _invite_uses_cache[guild.id] = {}
    except Exception as e:
        print(f"[招待トラッキング] キャッシュ更新エラー（{guild.name}）: {e}")
        _invite_uses_cache.setdefault(guild.id, {})


async def _refresh_all_invite_caches(client):
    """Bot起動時に、参加している全ギルドの招待キャッシュを一括構築します。"""
    for guild in client.guilds:
        await _refresh_invite_cache_for_guild(guild)
    print(f"[システム] 招待トラッキングキャッシュを構築しました（{len(client.guilds)}ギルド）")


async def _identify_used_invite(member: discord.Member):
    """新規参加者がどの招待コードを使ったかを特定し、対応する discord.Invite オブジェクト
    （招待作成者情報 .inviter を含む）を返します。特定できない場合はNoneを返します。
    実行後、内部キャッシュは最新状態に更新されます。"""
    guild = member.guild
    before = _invite_uses_cache.get(guild.id, {})

    try:
        after_invites = await guild.invites()
    except discord.Forbidden:
        return None
    except Exception as e:
        print(f"[招待トラッキング] 参加時の招待一覧取得エラー: {e}")
        return None

    used_invite = None
    for inv in after_invites:
        if (inv.uses or 0) > before.get(inv.code, 0):
            used_invite = inv
            break

    _invite_uses_cache[guild.id] = {inv.code: (inv.uses or 0) for inv in after_invites}
    return used_invite


def record_invite_stat(all_data: dict, guild_id_str: str, inviter_id_str: str, joined: bool):
    """招待統計（招待した人ごとの参加者数）を加算/減算します。joined=Trueで参加、Falseで退出時の減算。"""
    cfg = get_guild_config(all_data, guild_id_str)
    stats = cfg.setdefault("invite_stats", {})
    entry = stats.setdefault(inviter_id_str, {"joins": 0, "leaves": 0})
    if joined:
        entry["joins"] = entry.get("joins", 0) + 1
    else:
        entry["leaves"] = entry.get("leaves", 0) + 1


# ====================================================================
# AFK機能（/afk）
# ====================================================================

def set_afk_status(all_data: dict, guild_id_str: str, user_id_str: str, reason: str, old_nick: str | None):
    """ユーザーをAFK状態として記録します。"""
    cfg = get_guild_config(all_data, guild_id_str)
    afk_map = cfg.setdefault("afk_users", {})
    afk_map[user_id_str] = {
        "reason": reason,
        "since": int(time.time()),
        "old_nick": old_nick,
    }


def clear_afk_status(all_data: dict, guild_id_str: str, user_id_str: str) -> dict | None:
    """AFK状態を解除し、解除前の情報（旧ニックネーム等）を返します。未設定の場合はNoneを返します。"""
    cfg = get_guild_config(all_data, guild_id_str)
    afk_map = cfg.setdefault("afk_users", {})
    return afk_map.pop(user_id_str, None)


async def _handle_afk_logic(message: discord.Message, all_data: dict, guild_id_str: str) -> bool:
    """AFK機能のメッセージ処理を行います。
    1. 発言者自身がAFK中であれば自動解除する（ニックネームも復元）
    2. メッセージ中でメンションされた相手がAFK中であれば、離席中である旨を返信する
    戻り値: all_data に変更を加えた場合は True（呼び出し元で save_data させるため）"""
    cfg = get_guild_config(all_data, guild_id_str)
    afk_map = cfg.get("afk_users", {})
    if not afk_map:
        return False

    changed = False
    author_id_str = str(message.author.id)

    # 1. 本人発言による自動解除
    if author_id_str in afk_map:
        entry = clear_afk_status(all_data, guild_id_str, author_id_str)
        changed = True
        if entry:
            old_nick = entry.get("old_nick")
            member = message.guild.get_member(message.author.id) if message.guild else None
            if member and (member.nick or "").startswith("[AFK] "):
                try:
                    await member.edit(nick=old_nick, reason="AFK解除")
                except Exception:
                    pass
            try:
                await message.channel.send(
                    f"おかえりなさい、{message.author.mention}！ AFKを解除しました。",
                    delete_after=10
                )
            except Exception:
                pass

    # 2. メンションされた相手がAFK中であれば通知
    notified_ids = set()
    for mentioned in message.mentions:
        mentioned_id_str = str(mentioned.id)
        if mentioned_id_str == author_id_str or mentioned_id_str in notified_ids:
            continue
        entry = afk_map.get(mentioned_id_str)
        if entry:
            notified_ids.add(mentioned_id_str)
            reason = entry.get("reason", "離席中")
            since_ts = entry.get("since")
            since_text = f"（<t:{since_ts}:R>から）" if since_ts else ""
            try:
                await message.channel.send(
                    f"[AFK] {mentioned.mention} は現在離席中です{since_text}\n理由: {reason}",
                    allowed_mentions=discord.AllowedMentions(users=False)
                )
            except Exception:
                pass

    return changed


async def _handle_afk_logic_dm(message: discord.Message):
    """グループDM専用のAFK処理です。サーバーに紐付かないため、
    get_global_config 配下のグローバルAFKストレージ（global_afk_users）を使用します。
    ニックネーム変更はグループDMには存在しないため行いません。"""
    all_data = load_data()
    global_cfg = get_global_config(all_data)
    afk_map = global_cfg.get("global_afk_users", {})
    if not afk_map:
        return

    changed = False
    author_id_str = str(message.author.id)

    # 1. 本人発言による自動解除
    if author_id_str in afk_map:
        afk_map.pop(author_id_str, None)
        changed = True
        try:
            await message.channel.send(
                f"おかえりなさい、{message.author.mention}！ AFKを解除しました。"
            )
        except Exception:
            pass

    # 2. メンションされた相手がAFK中であれば通知
    notified_ids = set()
    for mentioned in message.mentions:
        mentioned_id_str = str(mentioned.id)
        if mentioned_id_str == author_id_str or mentioned_id_str in notified_ids:
            continue
        entry = afk_map.get(mentioned_id_str)
        if entry:
            notified_ids.add(mentioned_id_str)
            reason = entry.get("reason", "離席中")
            since_ts = entry.get("since")
            since_text = f"（<t:{since_ts}:R>から）" if since_ts else ""
            try:
                await message.channel.send(
                    f"[AFK] {mentioned.mention} は現在離席中です{since_text}\n理由: {reason}",
                    allowed_mentions=discord.AllowedMentions(users=False)
                )
            except Exception:
                pass

    if changed:
        save_data(all_data)


