class UserManageView(discord.ui.View):
    """コマンド許可ユーザーを追加・削除するためのユーザー選択メニュービューです。"""
    def __init__(self):
        super().__init__(timeout=300)

    @discord.ui.select(cls=discord.ui.UserSelect, placeholder="許可ユーザーを追加...", custom_id="manage_add_user")
    async def add_user_callback(self, interaction: discord.Interaction, select: discord.ui.UserSelect):
        if not interaction.guild: return
        if not interaction.user.guild_permissions.administrator: return

        target_user = select.values[0]
        guild_id_str = str(interaction.guild.id)
        all_data = load_data()
        guild_config = get_guild_config(all_data, guild_id_str)

        if target_user.id not in guild_config["allowed_users"]:
            guild_config["allowed_users"].append(target_user.id)
            save_data(all_data)
            
            updated_embed = create_user_list_embed(guild_config["allowed_users"])
            await interaction.response.edit_message(embed=updated_embed, view=self)
            await interaction.followup.send(f"{target_user.mention} を許可リストに追加しました。", ephemeral=True)
        else:
            await interaction.response.send_message(f"{target_user.mention} は既に登録されています。", ephemeral=True)

    @discord.ui.select(cls=discord.ui.UserSelect, placeholder="許可ユーザーを削除...", custom_id="manage_remove_user")
    async def remove_user_callback(self, interaction: discord.Interaction, select: discord.ui.UserSelect):
        if not interaction.guild: return
        if not interaction.user.guild_permissions.administrator: return

        target_user = select.values[0]
        guild_id_str = str(interaction.guild.id)
        all_data = load_data()
        guild_config = get_guild_config(all_data, guild_id_str)

        if target_user.id in guild_config["allowed_users"]:
            guild_config["allowed_users"].remove(target_user.id)
            save_data(all_data)
            
            updated_embed = create_user_list_embed(guild_config["allowed_users"])
            await interaction.response.edit_message(embed=updated_embed, view=self)
            await interaction.followup.send(f"{target_user.mention} を許可リストから削除しました。", ephemeral=True)
        else:
            await interaction.response.send_message(f"{target_user.mention} は登録されていません。", ephemeral=True)


class DynamicRoleSelect(discord.ui.Select):
    """ロールパネル用のセレクトメニュー（複数選択可・選択したロールを全付与）です。"""
    def __init__(self, roles):
        options = [
            discord.SelectOption(label=role.name[:100], value=str(role.id))
            for role in roles[:25]  # Discordのセレクトメニュー選択肢は最大25個
        ]
        super().__init__(
            placeholder="受け取りたいロールを選択してください（複数選択可）",
            min_values=1,
            max_values=len(options),
            options=options,
            custom_id="dynamic_role_select"
        )

    async def callback(self, interaction: discord.Interaction):
        guild = interaction.guild
        if not guild:
            return

        selected_role_ids = [int(v) for v in self.values]
        granted = []
        already_had = []
        failed = []

        for role_id in selected_role_ids:
            role = guild.get_role(role_id)
            if not role:
                continue
            if role in interaction.user.roles:
                already_had.append(role)
                continue
            try:
                await interaction.user.add_roles(role)
                granted.append(role)
            except discord.Forbidden:
                failed.append(role)

        parts = []
        if granted:
            parts.append("✅ 付与しました: " + ", ".join(r.name for r in granted))
        if already_had:
            parts.append("➖ すでに持っています: " + ", ".join(r.name for r in already_had))
        if failed:
            parts.append("❌ 付与に失敗しました（Botの権限不足）: " + ", ".join(r.name for r in failed))

        message = "\n".join(parts) if parts else "対象のロールが見つかりませんでした。"
        await interaction.response.send_message(message, ephemeral=True)


class DynamicRoleView(discord.ui.View):
    """ロール自動付与用のセレクトメニューを表示する動的パネルビューです。"""
    def __init__(self, roles):
        super().__init__(timeout=None)
        self.add_item(DynamicRoleSelect(roles))


class VerifyButtonView(discord.ui.View):
    """サーバー参加時のメンバー認証ボタン用ビューです。"""
    def __init__(self):
        super().__init__(timeout=None)

    @discord.ui.button(label="認証する", style=discord.ButtonStyle.primary, custom_id="persistent_verify_button")
    async def verify(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not interaction.guild: return
        guild_id_str = str(interaction.guild.id)
        all_data = load_data()
        guild_config = get_guild_config(all_data, guild_id_str)
        role_id = guild_config.get("verify_role")
        if not role_id: return
        role = interaction.guild.get_role(role_id)
        if not role: return

        if role in interaction.user.roles:
            await interaction.response.send_message("すでに認証されています。", ephemeral=True)
            return
        try:
            await interaction.user.add_roles(role)
            await _remove_arasi_quarantine_role(interaction.user, guild_config)
            await interaction.response.send_message("認証が完了しました。", ephemeral=True)
        except Exception as e:
            await interaction.response.send_message(f"エラーが発生しました: {e}", ephemeral=True)


async def _is_newspaper_publisher(interaction: discord.Interaction) -> bool:
    """実行者がサーバー管理者、または「新聞係」ロール保持者かどうかを判定します。"""
    owner_id = await resolve_owner_id(interaction.client)
    if interaction.user.id == owner_id:
        return True
    if not interaction.guild:
        await interaction.response.send_message("このコマンドはサーバー内で実行してください。", ephemeral=True)
        return False
    if interaction.user.guild_permissions.administrator:
        return True

    all_data = load_data()
    guild_config = get_guild_config(all_data, str(interaction.guild.id))
    role_id = guild_config.get("newspaper_role")
    if role_id:
        role = interaction.guild.get_role(role_id)
        if role and role in interaction.user.roles:
            return True

    await interaction.response.send_message(
        "このコマンドはサーバー管理者、または「新聞係」ロールを持つ人のみ使用できます。",
        ephemeral=True
    )
    return False


class NewspaperModal(discord.ui.Modal, title="帝国新聞の内容を入力"):
    """新聞発行用の入力フォーム（出来事・人事・お知らせ・新規入国者）。"""
    newcomers = discord.ui.TextInput(
        label="新規入国者（任意・改行区切りで複数可）",
        style=discord.TextStyle.paragraph,
        placeholder="例:\nたろう さんが入国しました。",
        required=False,
        max_length=1000
    )
    events = discord.ui.TextInput(
        label="帝国内の出来事（任意・改行区切りで複数可）",
        style=discord.TextStyle.paragraph,
        placeholder="例:\n新しいイベント企画が始動しました。",
        required=False,
        max_length=1000
    )
    personnel = discord.ui.TextInput(
        label="人事（任意・改行区切りで複数可）",
        style=discord.TextStyle.paragraph,
        placeholder="例:\n○○ さんが「大臣」に就任しました。",
        required=False,
        max_length=1000
    )
    notices = discord.ui.TextInput(
        label="お知らせ（任意・改行区切りで複数可）",
        style=discord.TextStyle.paragraph,
        placeholder="例:\n次回イベントは来週開催予定です。",
        required=False,
        max_length=1000
    )

    def __init__(self, target_channel: discord.TextChannel, issue_number: str):
        super().__init__()
        self.target_channel = target_channel
        self.issue_number = issue_number

    @staticmethod
    def _format_section(raw_text: str) -> str:
        """改行区切りの入力を「・」箇条書きに整形します。空欄なら「特になし」を返します。"""
        raw_text = (raw_text or "").strip()
        if not raw_text:
            return "特になし"
        lines = [line.strip() for line in raw_text.splitlines() if line.strip()]
        if not lines:
            return "特になし"
        return "\n".join(f"・{line}" for line in lines)

    async def on_submit(self, interaction: discord.Interaction):
        guild = interaction.guild
        if guild is None:
            await interaction.response.send_message("サーバー内で実行してください。", ephemeral=True)
            return

        member_count = guild.member_count
        role_count = len(guild.roles)
        publish_date = discord.utils.utcnow().strftime("%Y年%m月%d日")

        newcomers_text = self._format_section(self.newcomers.value)
        events_text = self._format_section(self.events.value)
        personnel_text = self._format_section(self.personnel.value)
        notices_text = self._format_section(self.notices.value)

        embed = discord.Embed(
            title=f"帝国新聞　第{self.issue_number}号",
            color=discord.Color.dark_gold(),
        )
        embed.add_field(name="発行日", value=publish_date, inline=False)
        embed.add_field(
            name="【 建国・国勢 】",
            value=(
                f"・帝国国民：{member_count}名\n"
                f"・新規入国者：\n{newcomers_text}\n"
                f"・総ロール数：{role_count}個"
            ),
            inline=False
        )
        embed.add_field(name="【 帝国内の出来事 】", value=events_text, inline=False)
        embed.add_field(name="【 人事 】", value=personnel_text, inline=False)
        embed.add_field(name="【 お知らせ 】", value=notices_text, inline=False)
        embed.add_field(
            name="【 編集後記 】",
            value="帝国新聞は、当帝国で起きた出来事を記録する広報誌です。次号もお楽しみに。",
            inline=False
        )
        embed.set_footer(text=f"編集: {interaction.user.display_name}")

        try:
            await self.target_channel.send(embed=embed)
        except discord.Forbidden:
            await interaction.response.send_message(
                f"[NG] {self.target_channel.mention} への送信権限がBotにありません。\n"
                f"チャンネルの権限設定でBotロールに「メッセージを送信」を許可してください。",
                ephemeral=True
            )
            return
        except discord.HTTPException as e:
            await interaction.response.send_message(f"送信に失敗しました: {e}", ephemeral=True)
            return

        await interaction.response.send_message(
            f"[OK] {self.target_channel.mention} に帝国新聞　第{self.issue_number}号を発行しました。",
            ephemeral=True
        )


