class ApologyBuilderView(discord.ui.View):
    def __init__(self, author: discord.abc.User):
        super().__init__(timeout=600)
        self.author = author
        self.action_text = None
        self.comment_text = None
        self.improvement_text = None
        self.action_is_custom = False
        self.comment_is_custom = False
        self.improvement_is_custom = False

        self.add_item(ApologyActionSelect(self))
        self.add_item(ApologyCommentSelect(self))
        self.add_item(ApologyImprovementSelect(self))
        self.add_item(ApologySendButton(self))
        self.add_item(ApologyResetButton(self))
        self.add_item(ApologyCancelButton(self))

    def set_value(self, field: str, text: str, is_custom: bool):
        if field == "action":
            self.action_text = text
            self.action_is_custom = is_custom
        elif field == "comment":
            self.comment_text = text
            self.comment_is_custom = is_custom
        elif field == "improvement":
            self.improvement_text = text
            self.improvement_is_custom = is_custom

    def is_ready(self) -> bool:
        return bool(self.action_text and self.comment_text and self.improvement_text)

    def build_final_text(self) -> str:
        return APOLOGY_TEMPLATE.format(
            action_text=self.action_text,
            comment_text=self.comment_text,
            improvement_text=self.improvement_text
        )

    def build_preview_embed(self) -> discord.Embed:
        embed = discord.Embed(
            title="謝罪文プレビュー",
            color=discord.Color.orange() if not self.is_ready() else discord.Color.green()
        )

        def fmt(text, is_custom):
            if text is None:
                return "（未選択）"
            return f"{text}" + ("（自由入力）" if is_custom else "")

        embed.add_field(name="① やってしまった行動", value=fmt(self.action_text, self.action_is_custom), inline=False)
        embed.add_field(name="② 指摘された一言", value=fmt(self.comment_text, self.comment_is_custom), inline=False)
        embed.add_field(name="③ 今後の改善行動", value=fmt(self.improvement_text, self.improvement_is_custom), inline=False)

        if self.is_ready():
            embed.add_field(name="完成文プレビュー", value=self.build_final_text()[:1024], inline=False)
            embed.set_footer(text="内容を確認し、「この内容で送信する」を押すとこのチャンネルに投稿されます。")
        else:
            embed.set_footer(text="①②③をすべて選択（または自由入力）すると完成文が表示されます。")

        return embed


# ====================================================================
# セクション 5: 内部処理・バックアップ・荒らし対策ヘルパー
# ====================================================================

def _perms_to_int(perms: discord.Permissions) -> int:
    return perms.value


def _overwrite_to_dict(overwrite: discord.PermissionOverwrite) -> dict:
    allow, deny = overwrite.pair()
    return {"allow": allow.value, "deny": deny.value}


async def _build_backup(guild: discord.Guild) -> dict:
    roles_data = []
    for role in sorted(guild.roles, key=lambda r: r.position):
        if role.is_default():
            continue
        roles_data.append({
            "id":          role.id,
            "name":        role.name,
            "color":       role.color.value,
            "hoist":       role.hoist,
            "mentionable": role.mentionable,
            "permissions": _perms_to_int(role.permissions),
            "position":    role.position,
            "managed":     role.managed,
        })

    everyone_perms = _perms_to_int(guild.default_role.permissions)

    categories_data = []
    for cat in sorted(guild.categories, key=lambda c: c.position):
        overwrites = {}
        for target, ow in cat.overwrites.items():
            key = f"role:{target.id}" if isinstance(target, discord.Role) else f"member:{target.id}"
            overwrites[key] = _overwrite_to_dict(ow)
        categories_data.append({
            "id":       cat.id,
            "name":     cat.name,
            "position": cat.position,
            "overwrites": overwrites,
        })

    text_channels_data = []
    for ch in sorted(guild.text_channels, key=lambda c: c.position):
        overwrites = {}
        for target, ow in ch.overwrites.items():
            key = f"role:{target.id}" if isinstance(target, discord.Role) else f"member:{target.id}"
            overwrites[key] = _overwrite_to_dict(ow)
        webhooks_data = []
        try:
            for wh in await ch.webhooks():
                webhooks_data.append({
                    "name":       wh.name,
                    "avatar_url": str(wh.avatar.url) if wh.avatar else None,
                })
        except discord.Forbidden:
            pass
        text_channels_data.append({
            "id":          ch.id,
            "name":        ch.name,
            "topic":       ch.topic,
            "position":    ch.position,
            "nsfw":        ch.is_nsfw(),
            "slowmode":    ch.slowmode_delay,
            "category_id": ch.category_id,
            "overwrites":  overwrites,
            "webhooks":    webhooks_data,
        })

    voice_channels_data = []
    for ch in sorted(guild.voice_channels, key=lambda c: c.position):
        overwrites = {}
        for target, ow in ch.overwrites.items():
            key = f"role:{target.id}" if isinstance(target, discord.Role) else f"member:{target.id}"
            overwrites[key] = _overwrite_to_dict(ow)
        voice_channels_data.append({
            "id":          ch.id,
            "name":        ch.name,
            "position":    ch.position,
            "bitrate":     ch.bitrate,
            "user_limit":  ch.user_limit,
            "category_id": ch.category_id,
            "overwrites":  overwrites,
        })

    forum_channels_data = []
    for ch in guild.forums:
        overwrites = {}
        for target, ow in ch.overwrites.items():
            key = f"role:{target.id}" if isinstance(target, discord.Role) else f"member:{target.id}"
            overwrites[key] = _overwrite_to_dict(ow)
        forum_channels_data.append({
            "id":          ch.id,
            "name":        ch.name,
            "topic":       ch.topic,
            "position":    ch.position,
            "category_id": ch.category_id,
            "overwrites":  overwrites,
        })

    return {
        "meta": {
            "version":        "1.0",
            "guild_id":       guild.id,
            "guild_name":     guild.name,
            "backed_up_at":   datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "member_count":   guild.member_count,
        },
        "everyone_permissions": everyone_perms,
        "roles":            roles_data,
        "categories":       categories_data,
        "text_channels":    text_channels_data,
        "voice_channels":   voice_channels_data,
        "forum_channels":   forum_channels_data,
    }


async def _wipe_guild(guild: discord.Guild) -> tuple[list[str], list[str]]:
    success_logs: list[str] = []
    fail_logs:    list[str] = []
    me = guild.me
    for ch in list(guild.channels):
        if isinstance(ch, discord.CategoryChannel):
            continue
        try:
            await ch.delete(reason="アンチnukeリストア: 全削除して再構築")
            success_logs.append(f"チャンネル「#{ch.name}」を削除しました")
        except discord.Forbidden:
            fail_logs.append(f"チャンネル「#{ch.name}」の削除に失敗（権限不足）")
        except Exception as e:
            fail_logs.append(f"チャンネル「#{ch.name}」の削除に失敗: {e}")
    for cat in list(guild.categories):
        try:
            await cat.delete(reason="アンチnukeリストア: 全削除して再構築")
            success_logs.append(f"カテゴリ「{cat.name}」を削除しました")
        except discord.Forbidden:
            fail_logs.append(f"カテゴリ「{cat.name}」の削除に失敗（権限不足）")
        except Exception as e:
            fail_logs.append(f"カテゴリ「{cat.name}」の削除に失敗: {e}")
    for role in list(guild.roles):
        if role.is_default():
            continue
        if role.managed:
            continue
        if me and role in me.roles and role >= me.top_role:
            fail_logs.append(f"ロール「{role.name}」はBotの権限保持に必要なためスキップしました")
            continue
        try:
            await role.delete(reason="アンチnukeリストア: 全削除して再構築")
            success_logs.append(f"ロール「{role.name}」を削除しました")
        except discord.Forbidden:
            fail_logs.append(f"ロール「{role.name}」の削除に失敗（権限不足）")
        except Exception as e:
            fail_logs.append(f"ロール「{role.name}」の削除に失敗: {e}")
    return success_logs, fail_logs


async def _safe_api_call(coro, fail_logs: list, label: str):
    for attempt in range(3):
        try:
            return await coro
        except discord.HTTPException as e:
            if e.status == 429:
                retry_after = float(e.response.headers.get("Retry-After", 1.0))
                print(f"[リストア] レート制限 - {retry_after:.1f}秒待機 ({label})")
                await asyncio.sleep(retry_after + 0.5)
            else:
                fail_logs.append(f"{label} の操作に失敗: {e}")
                return None
        except Exception as e:
            fail_logs.append(f"{label} の操作に失敗: {e}")
            return None
    fail_logs.append(f"{label} はリトライ上限に達しました")
    return None


async def _restore_from_backup(guild: discord.Guild, data: dict) -> tuple[list[str], list[str]]:
    success_logs = []
    fail_logs    = []
    try:
        everyone_val = data.get("everyone_permissions", 0)
        await guild.default_role.edit(permissions=discord.Permissions(everyone_val))
        success_logs.append("@everyone 権限を復元しました")
    except Exception as e:
        fail_logs.append(f"@everyone 権限の復元に失敗: {e}")
    old_role_id_map = {}
    for r_data in sorted(data.get("roles", []), key=lambda r: r["position"]):
        if r_data.get("managed"):
            fail_logs.append(f"ロール「{r_data['name']}」はBot管理ロールのためスキップ")
            continue
        label = f"ロール「{r_data['name']}」"
        role = await _safe_api_call(
            guild.create_role(
                name=r_data["name"],
                color=discord.Color(r_data["color"]),
                hoist=r_data["hoist"],
                mentionable=r_data["mentionable"],
                permissions=discord.Permissions(r_data["permissions"]),
            ),
            fail_logs, label
        )
        if role:
            success_logs.append(f"{label} を作成しました")
            old_role_id_map[r_data["id"]] = role
        await asyncio.sleep(0.5)

    def _build_overwrites(raw: dict) -> dict:
        overwrites = {}
        for key, val in raw.items():
            kind, oid = key.split(":", 1)
            oid = int(oid)
            if kind == "role":
                target = old_role_id_map.get(oid) or guild.get_role(oid)
            else:
                target = guild.get_member(oid)
            if target is None:
                continue
            allow = discord.Permissions(val["allow"])
            deny  = discord.Permissions(val["deny"])
            overwrites[target] = discord.PermissionOverwrite.from_pair(allow, deny)
        return overwrites

    old_cat_id_map = {}
    for c_data in sorted(data.get("categories", []), key=lambda c: c["position"]):
        label = f"カテゴリ「{c_data['name']}」"
        overwrites = _build_overwrites(c_data.get("overwrites", {}))
        cat = await _safe_api_call(
            guild.create_category(name=c_data["name"], overwrites=overwrites),
            fail_logs, label
        )
        if cat:
            success_logs.append(f"{label} を作成しました")
            old_cat_id_map[c_data["id"]] = cat
        await asyncio.sleep(0.5)

    for ch_data in sorted(data.get("text_channels", []), key=lambda c: c["position"]):
        label = f"テキストch「#{ch_data['name']}」"
        overwrites = _build_overwrites(ch_data.get("overwrites", {}))
        category   = old_cat_id_map.get(ch_data.get("category_id"))
        ch = await _safe_api_call(
            guild.create_text_channel(
                name=ch_data["name"],
                topic=ch_data.get("topic"),
                nsfw=ch_data.get("nsfw", False),
                slowmode_delay=ch_data.get("slowmode", 0),
                overwrites=overwrites,
                category=category,
            ),
            fail_logs, label
        )
        if ch:
            success_logs.append(f"{label} を作成しました")
            for wh_data in ch_data.get("webhooks", []):
                wh = await _safe_api_call(
                    ch.create_webhook(name=wh_data["name"]),
                    fail_logs, f"Webhook「{wh_data['name']}」"
                )
                if wh:
                    success_logs.append(f"  Webhook「{wh_data['name']}」を作成しました")
        await asyncio.sleep(0.5)

    for ch_data in sorted(data.get("voice_channels", []), key=lambda c: c["position"]):
        label = f"ボイスch「{ch_data['name']}」"
        overwrites = _build_overwrites(ch_data.get("overwrites", {}))
        category   = old_cat_id_map.get(ch_data.get("category_id"))
        ch = await _safe_api_call(
            guild.create_voice_channel(
                name=ch_data["name"],
                bitrate=min(ch_data.get("bitrate", 64000), guild.bitrate_limit),
                user_limit=ch_data.get("user_limit", 0),
                overwrites=overwrites,
                category=category,
            ),
            fail_logs, label
        )
        if ch:
            success_logs.append(f"{label} を作成しました")
        await asyncio.sleep(0.5)

    print(f"[リストア完了] 成功: {len(success_logs)}件 / 失敗: {len(fail_logs)}件")
    return success_logs, fail_logs


async def _smart_restore_from_backup(guild: discord.Guild, data: dict) -> tuple[list[str], list[str]]:
    success_logs: list[str] = []
    fail_logs:    list[str] = []
    me = guild.me

    def _build_overwrites(raw: dict, role_map: dict) -> dict:
        ow_dict = {}
        for key, val in raw.items():
            kind, oid = key.split(":", 1)
            oid = int(oid)
            if kind == "role":
                target = role_map.get(oid) or guild.get_role(oid)
            else:
                target = guild.get_member(oid)
            if target is None:
                continue
            allow = discord.Permissions(val["allow"])
            deny  = discord.Permissions(val["deny"])
            ow_dict[target] = discord.PermissionOverwrite.from_pair(allow, deny)
        return ow_dict

    old_role_id_map: dict[int, discord.Role] = {}
    existing_roles_by_name = {
        r.name: r for r in guild.roles
        if not r.is_default() and not r.managed
    }
    bot_role_names = {r.name for r in (me.roles if me else [])}

    backup_role_names: set[str] = set()
    for r_data in sorted(data.get("roles", []), key=lambda r: r["position"]):
        if r_data.get("managed"):
            continue
        rname = r_data["name"]
        backup_role_names.add(rname)
        label = f"ロール「{rname}」"
        existing = existing_roles_by_name.get(rname)
        if existing:
            role = await _safe_api_call(
                existing.edit(
                    color=discord.Color(r_data["color"]),
                    hoist=r_data["hoist"],
                    mentionable=r_data["mentionable"],
                    permissions=discord.Permissions(r_data["permissions"]),
                    reason="リストア: ロール設定を更新",
                ),
                fail_logs, label
            )
            if role is not None or existing:
                success_logs.append(f"{label} を更新しました")
                old_role_id_map[r_data["id"]] = existing
        else:
            role = await _safe_api_call(
                guild.create_role(
                    name=rname,
                    color=discord.Color(r_data["color"]),
                    hoist=r_data["hoist"],
                    mentionable=r_data["mentionable"],
                    permissions=discord.Permissions(r_data["permissions"]),
                    reason="リストア: ロールを新規作成",
                ),
                fail_logs, label
            )
            if role:
                success_logs.append(f"{label} を新規作成しました")
                old_role_id_map[r_data["id"]] = role
        await asyncio.sleep(0.5)

    for rname, role in existing_roles_by_name.items():
        if rname not in backup_role_names and rname not in bot_role_names:
            deleted = await _safe_api_call(
                role.delete(reason="リストア: バックアップにないロールを削除"),
                fail_logs, f"ロール「{rname}」削除"
            )
            if deleted is not None or True:
                success_logs.append(f"ロール「{rname}」を削除しました（バックアップにないため）")
            await asyncio.sleep(0.3)

    try:
        everyone_val = data.get("everyone_permissions", 0)
        await guild.default_role.edit(permissions=discord.Permissions(everyone_val))
        success_logs.append("@everyone 権限を復元しました")
    except Exception as e:
        fail_logs.append(f"@everyone 権限の復元に失敗: {e}")

    old_cat_id_map: dict[int, discord.CategoryChannel] = {}
    existing_cats_by_name = {c.name: c for c in guild.categories}
    backup_cat_names: set[str] = set()

    for c_data in sorted(data.get("categories", []), key=lambda c: c["position"]):
        cname = c_data["name"]
        backup_cat_names.add(cname)
        label = f"カテゴリ「{cname}」"
        overwrites = _build_overwrites(c_data.get("overwrites", {}), old_role_id_map)
        existing_cat = existing_cats_by_name.get(cname)
        if existing_cat:
            await _safe_api_call(
                existing_cat.edit(overwrites=overwrites, reason="リストア: カテゴリ設定を更新"),
                fail_logs, label
            )
            success_logs.append(f"{label} を更新しました")
            old_cat_id_map[c_data["id"]] = existing_cat
        else:
            cat = await _safe_api_call(
                guild.create_category(name=cname, overwrites=overwrites, reason="リストア: カテゴリを新規作成"),
                fail_logs, label
            )
            if cat:
                success_logs.append(f"{label} を新規作成しました")
                old_cat_id_map[c_data["id"]] = cat
        await asyncio.sleep(0.5)

    for cname, cat in existing_cats_by_name.items():
        if cname not in backup_cat_names:
            for ch in list(cat.channels):
                await _safe_api_call(
                    ch.edit(category=None, reason="リストア: カテゴリ削除前にチャンネルを移動"),
                    fail_logs, f"ch「{ch.name}」の移動"
                )
                await asyncio.sleep(0.3)
            await _safe_api_call(
                cat.delete(reason="リストア: バックアップにないカテゴリを削除"),
                fail_logs, f"カテゴリ「{cname}」削除"
            )
            success_logs.append(f"カテゴリ「{cname}」を削除しました（バックアップにないため）")
            await asyncio.sleep(0.3)

    existing_text_by_name = {c.name: c for c in guild.text_channels}
    backup_text_names: set[str] = set()

    for ch_data in sorted(data.get("text_channels", []), key=lambda c: c["position"]):
        chname = ch_data["name"]
        backup_text_names.add(chname)
        label = f"テキストch「#{chname}」"
        overwrites = _build_overwrites(ch_data.get("overwrites", {}), old_role_id_map)
        category   = old_cat_id_map.get(ch_data.get("category_id"))
        existing_ch = existing_text_by_name.get(chname)
        if existing_ch:
            await _safe_api_call(
                existing_ch.edit(
                    topic=ch_data.get("topic"),
                    nsfw=ch_data.get("nsfw", False),
                    slowmode_delay=ch_data.get("slowmode", 0),
                    overwrites=overwrites,
                    category=category,
                    reason="リストア: チャンネル設定を更新",
                ),
                fail_logs, label
            )
            success_logs.append(f"{label} を更新しました")
        else:
            ch = await _safe_api_call(
                guild.create_text_channel(
                    name=chname,
                    topic=ch_data.get("topic"),
                    nsfw=ch_data.get("nsfw", False),
                    slowmode_delay=ch_data.get("slowmode", 0),
                    overwrites=overwrites,
                    category=category,
                    reason="リストア: テキストchを新規作成",
                ),
                fail_logs, label
            )
            if ch:
                success_logs.append(f"{label} を新規作成しました")
                for wh_data in ch_data.get("webhooks", []):
                    wh = await _safe_api_call(
                        ch.create_webhook(name=wh_data["name"]),
                        fail_logs, f"Webhook「{wh_data['name']}」"
                    )
                    if wh:
                        success_logs.append(f"  Webhook「{wh_data['name']}」を作成しました")
        await asyncio.sleep(0.5)

    for chname, ch in existing_text_by_name.items():
        if chname not in backup_text_names:
            await _safe_api_call(
                ch.delete(reason="リストア: バックアップにないchを削除"),
                fail_logs, f"テキストch「#{chname}」削除"
            )
            success_logs.append(f"テキストch「#{chname}」を削除しました（バックアップにないため）")
            await asyncio.sleep(0.3)

    existing_voice_by_name = {c.name: c for c in guild.voice_channels}
    backup_voice_names: set[str] = set()

    for ch_data in sorted(data.get("voice_channels", []), key=lambda c: c["position"]):
        chname = ch_data["name"]
        backup_voice_names.add(chname)
        label = f"ボイスch「{chname}」"
        overwrites = _build_overwrites(ch_data.get("overwrites", {}), old_role_id_map)
        category   = old_cat_id_map.get(ch_data.get("category_id"))
        existing_ch = existing_voice_by_name.get(chname)
        if existing_ch:
            await _safe_api_call(
                existing_ch.edit(
                    bitrate=min(ch_data.get("bitrate", 64000), guild.bitrate_limit),
                    user_limit=ch_data.get("user_limit", 0),
                    overwrites=overwrites,
                    category=category,
                    reason="リストア: ボイスch設定を更新",
                ),
                fail_logs, label
            )
            success_logs.append(f"{label} を更新しました")
        else:
            ch = await _safe_api_call(
                guild.create_voice_channel(
                    name=chname,
                    bitrate=min(ch_data.get("bitrate", 64000), guild.bitrate_limit),
                    user_limit=ch_data.get("user_limit", 0),
                    overwrites=overwrites,
                    category=category,
                    reason="リストア: ボイスchを新規作成",
                ),
                fail_logs, label
            )
            if ch:
                success_logs.append(f"{label} を新規作成しました")
        await asyncio.sleep(0.5)

    for chname, ch in existing_voice_by_name.items():
        if chname not in backup_voice_names:
            await _safe_api_call(
                ch.delete(reason="リストア: バックアップにないchを削除"),
                fail_logs, f"ボイスch「{chname}」削除"
            )
            success_logs.append(f"ボイスch「{chname}」を削除しました（バックアップにないため）")
            await asyncio.sleep(0.3)

    print(f"[段階的リストア完了] 成功: {len(success_logs)}件 / 失敗: {len(fail_logs)}件")
    return success_logs, fail_logs




# ====================================================================
# 荒らし対策 (Anti-nuke) ロジック
# ====================================================================

DEFAULT_ANTINUKE_CONFIG = {
    "enabled":           False,
    "threshold_count":   3,
    "threshold_seconds": 10,
    "action":            "role_strip",
    "exempt_roles":      [],
    "log_channel":       None,
}


def get_antinuke_config(all_data: dict, guild_id_str: str) -> dict:
    cfg = get_guild_config(all_data, guild_id_str)
    if "antinuke" not in cfg:
        cfg["antinuke"] = DEFAULT_ANTINUKE_CONFIG.copy()
    else:
        for k, v in DEFAULT_ANTINUKE_CONFIG.items():
            if k not in cfg["antinuke"]:
                cfg["antinuke"][k] = v
    return cfg["antinuke"]


guild_id_to_user_id_to_action_type = collections.defaultdict(
    lambda: collections.defaultdict(lambda: collections.defaultdict(list))
)

_already_handled: set[tuple[int, int]] = set()


def _record_action(guild_id: int, user_id: int, action_type: str) -> int:
    now = time.time()
    history = guild_id_to_user_id_to_action_type[guild_id][user_id][action_type]
    history.append(now)
    cutoff = now - 60
    while history and history[0] < cutoff:
        history.pop(0)
    return len(history)


def _count_within_window(guild_id: int, user_id: int, action_type: str, window_seconds: int) -> int:
    now = time.time()
    history = guild_id_to_user_id_to_action_type[guild_id][user_id][action_type]
    cutoff = now - window_seconds
    return sum(1 for t in history if t >= cutoff)


async def _strip_roles(guild: discord.Guild, member: discord.Member):
    dangerous_perms = [
        "administrator", "manage_guild", "manage_channels", "manage_roles",
        "ban_members", "kick_members", "manage_webhooks"
    ]
    roles_to_remove = []
    for role in member.roles:
        if role.is_default():
            continue
        if any(getattr(role.permissions, p, False) for p in dangerous_perms):
            roles_to_remove.append(role)
    if roles_to_remove:
        try:
            await member.remove_roles(*roles_to_remove, reason="antinuke: 緊急ロール剥奪")
        except discord.Forbidden:
            pass
        except Exception:
            pass


async def _handle_nuke_detected(guild: discord.Guild, suspect: discord.Member, action_type: str, cfg: dict):
    key = (guild.id, suspect.id)
    if key in _already_handled:
        return
    _already_handled.add(key)

    action_label = {
        "ban_member":     "メンバーBAN",
        "channel_delete": "チャンネル削除",
        "role_delete":    "ロール削除",
        "webhook_create": "Webhook作成",
    }.get(action_type, action_type)

    result_text = ""
    try:
        if cfg["action"] == "ban":
            try:
                await guild.ban(suspect, reason=f"antinuke: {action_label}の連続実行を検出")
                result_text = f"{suspect} をBANしました。"
            except discord.Forbidden:
                result_text = f"{suspect} のBANに失敗しました（権限不足）。ロール剥奪を試みます。"
                await _strip_roles(guild, suspect)
            except Exception as e:
                result_text = f"{suspect} のBAN中にエラー: {e}。ロール剥奪を試みます。"
                await _strip_roles(guild, suspect)
        else:
            await _strip_roles(guild, suspect)
            result_text = f"{suspect} の危険な権限を持つロールを剥奪しました。"
    except Exception as e:
        result_text = f"自動対応中にエラーが発生しました: {e}"

    embed = discord.Embed(
        title="antinuke: 不審な操作を検出しました",
        color=discord.Color.red()
    )
    embed.add_field(name="検出内容", value=f"{action_label}が短時間に連続実行されました", inline=False)
    embed.add_field(name="対象ユーザー", value=f"{suspect.mention} (`{suspect.id}`)", inline=False)
    embed.add_field(name="実行した対応", value=result_text, inline=False)
    embed.timestamp = discord.utils.utcnow()
    embed.set_footer(text=f"サーバー: {guild.name}")

    all_data = load_data()
    cfg_full = get_antinuke_config(all_data, str(guild.id))
    log_ch_id = cfg_full.get("log_channel")
    if log_ch_id:
        ch = guild.get_channel(log_ch_id)
        if ch:
            try:
                await ch.send(embed=embed)
            except Exception:
                pass

    try:
        client = guild._state._get_client()
        owner_id = await resolve_owner_id(client)
        owner = client.get_user(owner_id) or await client.fetch_user(owner_id)
        if owner:
            await owner.send(embed=embed)
    except Exception:
        pass

    print(f"[antinuke] {guild.name}: {suspect} による {action_label} の連続実行を検出しました。")
    await asyncio.sleep(300)
    _already_handled.discard(key)


def _is_exempt(member: discord.Member, guild: discord.Guild, cfg: dict, owner_id: int) -> bool:
    if member.id == owner_id:
        return True
    if member.id == guild.owner_id:
        return True
    if member.bot:
        return True
    exempt_role_ids = set(cfg.get("exempt_roles", []))
    if exempt_role_ids and any(r.id in exempt_role_ids for r in member.roles):
        return True
    return False


def _build_antinuke_status_embed(guild: discord.Guild, cfg: dict) -> discord.Embed:
    embed = discord.Embed(
        title=f"{guild.name} - antinuke 設定状況",
        color=discord.Color.blue() if cfg["enabled"] else discord.Color.greyple()
    )
    embed.add_field(name="状態", value="有効" if cfg["enabled"] else "無効", inline=True)
    embed.add_field(
        name="対応レベル",
        value="BANも試行" if cfg["action"] == "ban" else "ロール剥奪のみ",
        inline=True
    )
    embed.add_field(
        name="検出条件",
        value=f"{cfg['threshold_seconds']}秒間に{cfg['threshold_count']}回以上",
        inline=True
    )
    log_ch_id = cfg.get("log_channel")
    log_ch = guild.get_channel(log_ch_id) if log_ch_id else None
    embed.add_field(
        name="通知先チャンネル",
        value=log_ch.mention if log_ch else "未設定（オーナーDMのみ）",
        inline=False
    )
    exempt_role_ids = cfg.get("exempt_roles", [])
    exempt_roles = [guild.get_role(rid) for rid in exempt_role_ids]
    exempt_roles = [r for r in exempt_roles if r]
    embed.add_field(
        name="免除ロール",
        value=", ".join(r.mention for r in exempt_roles) if exempt_roles else "なし",
        inline=False
    )
    embed.add_field(
        name="監視対象の操作",
        value="メンバーBAN / チャンネル削除 / ロール削除 / Webhook作成",
        inline=False
    )
    return embed


# ====================================================================
# セクション 6: ボットイベントリスナー
# ====================================================================

@bot.event
async def on_ready():
    """Bot起動完了時に呼び出されます。ビューの永続化再登録やプレゼンス設定を行います。"""

    # 累計稼働秒数・コマンド実行数を永続化データから読み込む（初回接続時のみ）。
    # on_readyは再接続のたびに複数回呼ばれうるため、二重加算を防ぐグローバルフラグで一度だけ実行する。
    global _bot_prior_uptime_seconds, _command_exec_count, _uptime_periodic_save_task
    global _stats_bootstrap_done
    if not globals().get("_stats_bootstrap_done", False):
        try:
            _bootstrap_data = load_data()
            _bootstrap_global_cfg = get_global_config(_bootstrap_data)
            _bot_prior_uptime_seconds = _bootstrap_global_cfg.get("bot_stats_total_uptime_seconds", 0)
            _command_exec_count = _bootstrap_global_cfg.get("bot_stats_command_exec_count", 0)
            print(
                f"[システム] 再起動をまたいだ累計値を読み込みました: "
                f"稼働時間={_bot_prior_uptime_seconds}秒 / コマンド実行数={_command_exec_count}回"
            )
        except Exception as e:
            print(f"[警告] 累計稼働時間・コマンド実行数の読み込みに失敗しました: {e}")
        _stats_bootstrap_done = True

        # 稼働時間を定期的に永続化するバックグラウンドタスクを起動（再接続時の重複起動を防止）
        if _uptime_periodic_save_task is None or _uptime_periodic_save_task.done():
            _uptime_periodic_save_task = asyncio.create_task(_uptime_periodic_save_loop())

    # 起動処理（ビュー再登録・タスク復元など）が完了するまでの間、
    # ひと目で「起動作業中」と分かるようにステータスを一時表示する。
    try:
        await _set_presence_text(bot, "起動中...", discord.ActivityType.playing)
    except Exception as e:
        print(f"[警告] 起動中ステータスの表示に失敗しました: {e}")

    # --- Web検索APIキーの設定状況を起動時に必ずログ出力する ---
    # 「/aiで検索が発動しない」という不具合報告の大半は、コードの不具合ではなく
    # Web検索APIキー（TAVILY_API_KEY / EXA_API_KEY / FIRECRAWL_API_KEY / NEWSDATA_API_KEY）が
    # 実行環境（Railway/Replit等）に1つも設定されていないことが原因（この場合、AIは
    # web_searchツール自体を渡されないため、生成AIが「知識は〇〇年以前まで」という
    # 自然な断り文で応答する＝一見正常な応答に見えてしまう）。
    # 起動ログを見るだけで即座に切り分けできるよう、ここで明示的に出力する。
    _search_key_status = {
        "TAVILY_API_KEY": bool(TAVILY_API_KEY),
        "EXA_API_KEY": bool(EXA_API_KEY),
        "FIRECRAWL_API_KEY": bool(FIRECRAWL_API_KEY),
        "NEWSDATA_API_KEY": bool(NEWSDATA_API_KEY),
    }
    if WEB_SEARCH_AVAILABLE:
        _configured = [name for name, ok in _search_key_status.items() if ok]
        print(f"[Web検索] 有効です。設定済みのAPIキー: {', '.join(_configured)}")
    else:
        print(
            "[Web検索] 警告: TAVILY_API_KEY / EXA_API_KEY / FIRECRAWL_API_KEY / NEWSDATA_API_KEY "
            "のいずれも設定されていません。/ai の検索機能は無効化され、AIは検索せずに"
            "自身の知識のみで応答します（一見普通の回答に見えるため気付きにくい不具合の典型例です）。"
            "実行環境（Railway/Replitの環境変数など）にキーを設定してください。"
        )

    # --- AIプロバイダ（フォールバック先）の設定状況も併せてログ出力する ---
    _provider_status = {
        "Groq": bool(GROQ_API_KEY),
        "Cerebras": bool(CEREBRAS_API_KEY),
        "Mistral": bool(MISTRAL_API_KEY),
        "OpenRouter": bool(OPENROUTER_API_KEY),
        "Gemini": bool(GEMINI_API_KEY),
    }
    _configured_providers = [name for name, ok in _provider_status.items() if ok]
    _unconfigured_providers = [name for name, ok in _provider_status.items() if not ok]
    print(f"[AIプロバイダ] 設定済み: {', '.join(_configured_providers) if _configured_providers else 'なし'}")
    if _unconfigured_providers:
        print(f"[AIプロバイダ] 未設定（フォールバック対象外）: {', '.join(_unconfigured_providers)}")

    # Opusライブラリを自動検索してロードする（Nixpacks環境対応）
    if not discord.opus.is_loaded():
        import ctypes.util
        import glob
        opus_candidates = (
            glob.glob("/root/.nix-profile/lib/libopus*")
            + glob.glob("/nix/store/*/lib/libopus*")
            + glob.glob("/usr/lib/*/libopus*")
            + glob.glob("/usr/lib/libopus*")
        )
        opus_path = next((p for p in opus_candidates if p.endswith(".so") or ".so." in p), None)
        if opus_path:
            try:
                discord.opus.load_opus(opus_path)
                print(f"[システム] Opusをロードしました: {opus_path}")
            except Exception as e:
                print(f"[警告] Opusのロードに失敗しました: {e}")
        else:
            # ctypes.util.find_library でも試みる
            lib = ctypes.util.find_library("opus")
            if lib:
                try:
                    discord.opus.load_opus(lib)
                    print(f"[システム] Opusをロードしました (ctypes): {lib}")
                except Exception as e:
                    print(f"[警告] Opusのロードに失敗しました (ctypes): {e}")
            else:
                print("[警告] Opusライブラリが見つかりませんでした。音声機能が使えない可能性があります。")

    bot.add_view(VerifyButtonView())
    bot.add_view(VerifyBlacklistButtonView())  # サーバーブラックリスト認証ボタンの永続化
    bot.add_view(GiveawayJoinView())  # プレゼント参加ボタンの永続化
    bot.add_view(TicketPanelView())  # チケット作成パネルの永続化（custom_idが固定のため全ギルド共通で1回登録すればよい）
    bot.add_view(TicketCloseView())  # チケットクローズボタンの永続化
    bot.add_view(InterviewPanelView())  # 面接パネル（面接を受けるボタン）の永続化
    all_data = load_data()

    resolved_owner_id = await resolve_owner_id(bot)
    if resolved_owner_id is not None:
        print(f"[システム] オーナーIDを確定しました: {resolved_owner_id}")
    else:
        print("[警告] オーナー情報の取得に失敗しました。")

    # 設置型ロールショップパネルの永続化View再登録（再起動後もボタンが反応するようにする）
    for guild_id_str, config in all_data.items():
        if guild_id_str in ("user_apps", "global_config"):
            continue
        if not isinstance(config, dict):
            continue
        panel_message_id = config.get("role_shop_panel_message_id")
        panel_channel_id = config.get("role_shop_panel_channel_id")
        if not panel_message_id or not panel_channel_id:
            continue
        try:
            shop_items = config.get("role_shop", [])
            view = RoleShopView(shop_items) if shop_items else discord.ui.View(timeout=None)
            bot.add_view(view, message_id=panel_message_id)
        except Exception as e:
            print(f"[警告] ロールショップパネルの再登録に失敗しました（guild={guild_id_str}）: {e}")

    # 設置型自販機パネルの永続化View再登録（再起動後もボタンが反応するようにする）
    for guild_id_str, config in all_data.items():
        if guild_id_str in ("user_apps", "global_config"):
            continue
        if not isinstance(config, dict):
            continue
        panel_message_id = config.get("vending_panel_message_id")
        panel_channel_id = config.get("vending_panel_channel_id")
        if not panel_message_id or not panel_channel_id:
            continue
        try:
            items = config.get("vending_items", [])
            view = VendingMachineView(items) if items else discord.ui.View(timeout=None)
            bot.add_view(view, message_id=panel_message_id)
        except Exception as e:
            print(f"[警告] 自販機パネルの再登録に失敗しました（guild={guild_id_str}）: {e}")

    # 面接結果パネル（合格/不合格/保留ボタン）の永続化View再登録
    for guild_id_str, config in all_data.items():
        if guild_id_str in ("user_apps", "global_config"):
            continue
        if not isinstance(config, dict):
            continue
        records = config.get("interview_records", {})
        for record_id_str, record in records.items():
            if not isinstance(record, dict) or record.get("status") != "pending_review":
                continue
            msg_id = record.get("result_message_id")
            ch_id = record.get("result_channel_id")
            if not msg_id or not ch_id:
                continue
            try:
                view = InterviewResultView(int(guild_id_str), int(record_id_str))
                bot.add_view(view, message_id=msg_id)
            except Exception as e:
                print(f"[警告] 面接結果パネルの再登録に失敗しました（guild={guild_id_str}, record={record_id_str}）: {e}")

    # 面接の質問回答ボタン（進行中セッション）の永続化View再登録
    # custom_idにguild_id/record_id/question_indexを埋め込んでいるため、message_id指定なしで
    # 汎用登録（bot.add_view(view)）すればcustom_id一致で全メッセージに反応する。
    for guild_id_str, config in all_data.items():
        if guild_id_str in ("user_apps", "global_config"):
            continue
        if not isinstance(config, dict):
            continue
        records = config.get("interview_records", {})
        for record_id_str, record in records.items():
            if not isinstance(record, dict) or record.get("status") != "in_progress":
                continue
            question_index = record.get("current_question_index", 0)
            try:
                view = InterviewQuestionView(int(guild_id_str), int(record_id_str), question_index)
                bot.add_view(view)
            except Exception as e:
                print(f"[警告] 面接質問ボタンの再登録に失敗しました（guild={guild_id_str}, record={record_id_str}）: {e}")

    # Embedビルダーの回答フォーム（Modal）付きパネルの永続化View再登録
    # custom_idにguild_id/panel_idを埋め込んでいるため、message_id指定なしの汎用登録でよい。
    for guild_id_str, config in all_data.items():
        if guild_id_str in ("user_apps", "global_config"):
            continue
        if not isinstance(config, dict):
            continue
        panels = config.get("embed_response_panels", {})
        for panel_id_str, panel in panels.items():
            if not isinstance(panel, dict):
                continue
            try:
                view = EmbedResponsePanelView(int(guild_id_str), int(panel_id_str), panel.get("button_label", "回答する"))
                bot.add_view(view)
            except Exception as e:
                print(f"[警告] Embed回答パネルの再登録に失敗しました（guild={guild_id_str}, panel={panel_id_str}）: {e}")

    # 設置型サーバーブラックリスト認証パネルの永続化View再登録
    for guild_id_str, config in all_data.items():
        if guild_id_str in ("user_apps", "global_config"):
            continue
        if not isinstance(config, dict):
            continue
        panel_message_id = config.get("server_blacklist_verify_message_id")
        panel_channel_id = config.get("server_blacklist_verify_channel_id")
        if not panel_message_id or not panel_channel_id:
            continue
        try:
            bot.add_view(VerifyBlacklistButtonView(), message_id=panel_message_id)
            print(f"  > サーバーBL認証パネル: 再活性化しました（message_id={panel_message_id}）")
        except Exception as e:
            print(f"[警告] サーバーBL認証パネルの再登録に失敗しました（guild={guild_id_str}）: {e}")

    # /poll 投票パネルの永続化View再登録（締め切り済みのものはボタン無効状態で再登録）
    for guild_id_str, config in all_data.items():
        if guild_id_str in ("user_apps", "global_config"):
            continue
        if not isinstance(config, dict):
            continue
        polls = config.get("polls", {})
        for poll_id_str, record in polls.items():
            if not isinstance(record, dict):
                continue
            try:
                guild_id_int = int(guild_id_str)
                poll_id_int = int(poll_id_str)
                view = PollView(guild_id_int, poll_id_int, record.get("choices", []))
                if record.get("status") != "open":
                    for item in view.children:
                        item.disabled = True
                bot.add_view(view)
            except Exception as e:
                print(f"[警告] 投票パネルの再登録に失敗しました（guild={guild_id_str}, poll={poll_id_str}）: {e}")

    try:
        if current_custom_status:
            # 手動設定済みのカスタムステータスがあれば、それを優先して固定表示する
            await update_bot_status(bot)
        # ローテーション表示タスクを起動（カスタムステータス設定中は内部で自動休止する）
        start_status_rotation(bot)
    except Exception as e:
        print(f"初期ステータス設定エラー: {e}")

    # 招待トラッキング用キャッシュの構築（再接続のたびに呼ばれても軽量なため毎回リフレッシュする）
    try:
        await _refresh_all_invite_caches(bot)
    except Exception as e:
        print(f"[警告] 招待トラッキングキャッシュの構築に失敗しました: {e}")

    print("--- 起動完了: 現在のサーバー設定一覧 ---")
    for guild_id_str, config in all_data.items():
        if guild_id_str in ("user_apps", "global_config"):
            continue
        if not isinstance(config, dict):
            continue
        try:
            guild_id_int = int(guild_id_str)
        except ValueError:
            print(f"[警告] 不正なサーバーIDキーをスキップしました: {guild_id_str}")
            continue
        guild = bot.get_guild(guild_id_int)
        guild_name = guild.name if guild else "不明なサーバー"
        print(f"サーバー: {guild_name} (ID: {guild_id_str})")
        print(f"  > Message転送: {'有効' if config.get('from_channel') else '未設定'}")
        print(f"  > サーバー認証: {'有効' if config.get('verify_channel') else '未設定'}")
        print(f"  > 配信お知らせ: {'有効' if config.get('announce_channel') else '未設定'}")
        print(f"  > 自動メンション: {'有効' if config.get('mention_trigger_channel') else '未設定'}")
        panel_roles = config.get("panel_roles", [])
        if panel_roles and guild:
            roles = [guild.get_role(rid) for rid in panel_roles if guild.get_role(rid)]
            if roles:
                bot.add_view(DynamicRoleView(roles))
                print(f"  > ロールパネル: {len(roles)}個のロールを含むセレクトメニューを再活性化しました")

        # 統計チャンネルの自動更新ループを再起動
        stats_ch_ids = [
            config.get("stats_member_ch_id"),
            config.get("stats_online_ch_id"),
            config.get("stats_bot_ch_id"),
        ]
        if guild and any(stats_ch_ids):
            _stats_tasks[guild_id_int] = asyncio.create_task(_stats_loop(guild))
            print("  > 統計ループ: 再起動しました")

        # 進行中プレゼントのタスクを再起動
        # [修正] on_ready はDiscordとの再接続のたびに複数回呼び出される可能性があり、
        # 以前はここで無条件に asyncio.create_task していたため、再接続が起きるたびに
        # 同一giveawayに対して複数のタスクが重複して起動していました。
        # 複数タスクが同時に走ると、片方が抽選・データ削除・メッセージ編集を終えた後、
        # もう片方が既に存在しないデータや編集済みメッセージへアクセスして失敗し、
        # 「giveawayがしばらく時間が経つとインタラクションに失敗する」不具合の
        # 直接的な原因になっていました。
        # _cancel_giveaway_task() で同一msg_idの既存タスクを必ずキャンセルしてから
        # 新しいタスクを起動することで、重複起動を防止します。
        giveaways = config.get("giveaways", {})
        now_utc = discord.utils.utcnow()
        for msg_id_str, gw in list(giveaways.items()):
            try:
                end_dt = datetime.datetime.fromisoformat(gw["end_at"])
                if end_dt.tzinfo is None:
                    end_dt = end_dt.replace(tzinfo=datetime.timezone.utc)
                ch_id = gw.get("channel_id")
                ch = guild.get_channel(ch_id) if guild and ch_id else None
                msg_id = int(msg_id_str)
                if ch and end_dt > now_utc:
                    _cancel_giveaway_task(msg_id)  # 既存タスクがあれば必ずキャンセルしてから再起動
                    task = asyncio.create_task(_run_giveaway(ch, msg_id, guild_id_int, end_dt))
                    _giveaway_tasks[msg_id] = task
                    print(f"  > プレゼントタスク: msg_id={msg_id_str} を再起動しました")
                elif end_dt <= now_utc:
                    # 期限切れのプレゼントを即時処理
                    ch2 = guild.get_channel(gw.get("channel_id")) if guild else None
                    if ch2:
                        _cancel_giveaway_task(msg_id)
                        task = asyncio.create_task(_run_giveaway(ch2, msg_id, guild_id_int, now_utc))
                        _giveaway_tasks[msg_id] = task
            except Exception as e:
                print(f"  > [警告] プレゼントタスク復元に失敗: {e}")
    print("---------------------------------------")
    print(f"ログインユーザー: {bot.user.name} (ID: {bot.user.id})")

    # サーバー活動AIサマリーの定期実行スケジューラを起動（再接続時の重複起動を防止）
    global _ai_summary_loop_task
    if _ai_summary_loop_task is None or _ai_summary_loop_task.done():
        _ai_summary_loop_task = asyncio.create_task(_ai_summary_scheduler_loop())
        print("  > AIサマリースケジューラ: 起動しました")

    # AI自動モデレーションのバッチ判定ループを起動（再接続時の重複起動を防止）
    global _ai_automod_loop_task
    if _ai_automod_loop_task is None or _ai_automod_loop_task.done():
        _ai_automod_loop_task = asyncio.create_task(_ai_automod_loop())
        print("  > AI自動モデレーションループ: 起動しました")

    # Vibeモニター（空気・緊張度監視）のバッチ判定ループを起動（再接続時の重複起動を防止）
    global _vibe_monitor_loop_task
    if _vibe_monitor_loop_task is None or _vibe_monitor_loop_task.done():
        _vibe_monitor_loop_task = asyncio.create_task(_vibe_monitor_loop())
        print("  > Vibeモニターループ: 起動しました")

    # ストレージ自動監視ループを起動（/app/data が存在する本番環境のみ。再接続時の重複起動を防止）
    global _storage_monitor_loop_task
    if STORAGE_MONITOR_ENABLED and (_storage_monitor_loop_task is None or _storage_monitor_loop_task.done()):
        _storage_monitor_loop_task = asyncio.create_task(_storage_monitor_loop())
        print(f"  > ストレージ自動監視ループ: 起動しました（閾値{STORAGE_CLEANUP_THRESHOLD_PERCENT:.0f}% / {STORAGE_MONITOR_INTERVAL_SECONDS // 3600}時間ごと）")

    # 起動時にスラッシュコマンドを自動同期（コマンド候補欄に表示されない問題の対策）
    try:
        synced = await bot.tree.sync()
        print(f"[システム] スラッシュコマンドを自動同期しました: {len(synced)}個（反映まで最大1時間）")
    except Exception as e:
        print(f"[警告] スラッシュコマンドの自動同期に失敗しました: {e}")

    print("スラッシュコマンドを即時反映したい場合は、サーバー上で '!sync' と発言してください。")


@bot.event
async def on_guild_join(guild: discord.Guild):
    print(f"[サーバー参加] {guild.name} (ID: {guild.id}) に導入されました。")
    # カスタムステータス固定表示中のみ即時反映（ローテーション表示中は次回切り替え時に自動反映される）
    if current_custom_status:
        await update_bot_status(bot)
    # 招待トラッキング用キャッシュを初期化（このサーバー分）
    await _refresh_invite_cache_for_guild(guild)


@bot.event
async def on_guild_remove(guild: discord.Guild):
    print(f"[サーバー脱退] {guild.name} (ID: {guild.id}) から削除されました。")
    if current_custom_status:
        await update_bot_status(bot)
    _invite_uses_cache.pop(guild.id, None)

    # そのサーバー専用に登録されていた音声ファイル（/voice_sound add）を削除し、
    # ストレージ（Railwayボリューム等）が使われなくなったサーバー分だけ肥大化し続けるのを防ぐ。
    try:
        guild_sounds_dir = os.path.join(SOUNDS_DIR, str(guild.id))
        if os.path.isdir(guild_sounds_dir):
            shutil.rmtree(guild_sounds_dir, ignore_errors=True)
            print(f"[サーバー脱退] 音声フォルダを削除しました: {guild_sounds_dir}")
    except Exception as e:
        print(f"[警告] サーバー脱退時の音声フォルダ削除に失敗しました（guild_id={guild.id}）: {e}")

    # そのサーバーの面接記録（/interview）も削除する。応募のたびに増え、
    # 従来は削除処理がなかったため、使われなくなったサーバー分だけ allowed_users.json が
    # 肥大化し続けるのを防ぐ（面接記録以外のサーバー設定は残す）。
    try:
        all_data = load_data()
        guild_id_str = str(guild.id)
        if guild_id_str in all_data and isinstance(all_data[guild_id_str], dict):
            records = all_data[guild_id_str].get("interview_records")
            if records:
                record_count = len(records)
                all_data[guild_id_str]["interview_records"] = {}
                save_data(all_data)
                print(f"[サーバー脱退] 面接記録を削除しました: {record_count}件（guild_id={guild.id}）")
    except Exception as e:
        print(f"[警告] サーバー脱退時の面接記録削除に失敗しました（guild_id={guild.id}）: {e}")


@bot.event
async def on_invite_create(invite: discord.Invite):
    """招待リンクが新規作成された際、招待トラッキング用キャッシュに反映します。"""
    if invite.guild is None:
        return
    cache = _invite_uses_cache.setdefault(invite.guild.id, {})
    cache[invite.code] = invite.uses or 0


@bot.event
async def on_invite_delete(invite: discord.Invite):
    """招待リンクが削除された際、招待トラッキング用キャッシュから除去します。"""
    if invite.guild is None:
        return
    cache = _invite_uses_cache.get(invite.guild.id)
    if cache:
        cache.pop(invite.code, None)


# ====================================================================
# 自動モデレーション共通ヘルパー
# ====================================================================

def _is_automod_target(author: discord.Member, guild_config: dict, all_data: dict) -> bool:
    """
    メッセージ送信者がAutoModの対象かどうかを判定します。
    管理者・許可ユーザー・Botオーナー・信頼ユーザーはすべてスキップします。

    注: ここでは同期関数の制約上 resolve_owner_id() を呼べないため、
    bot.owner_id を直接参照します。on_ready() 内で起動時に
    resolve_owner_id(bot) を実行しキャッシュ済みのため、通常稼働中は
    Team所有アプリでも正しいオーナーID（Teamオーナー）が入っています。
    """
    if author.guild_permissions.administrator:
        return False
    if author.id in guild_config.get("allowed_users", []):
        return False
    # 許可ロールを持っているか確認
    allowed_role_ids = set(guild_config.get("allowed_roles", []))
    if allowed_role_ids:
        user_role_ids = {r.id for r in author.roles}
        if user_role_ids & allowed_role_ids:
            return False
    if author.id == bot.owner_id:
        return False
    global_cfg = get_global_config(all_data)
    if author.id in global_cfg.get("trusted_users", []):
        return False
    return True


def _is_invite_automod_target(author: discord.Member, guild_config: dict, all_data: dict) -> bool:
    """
    招待リンク削除（automod_invite_enabled）専用の対象判定です。
    サーバー宣伝・引き抜き対策という性質上、「管理者権限を持つロールが付与された
    一般メンバー」であっても検知対象に含めます（_is_automod_targetとの唯一の違いは
    administrator権限による除外を行わない点です）。
    ただし、Botの設定で明示的に信頼されている人（allowed_users/allowed_roles・
    Botオーナー・trusted_users）は、他の自動モデレーション機能と同様に引き続き除外します
    （こちらは「管理者だから」ではなく「運営者が個別に信頼を与えたから」という別の理由のため）。
    """
    if author.id in guild_config.get("allowed_users", []):
        return False
    allowed_role_ids = set(guild_config.get("allowed_roles", []))
    if allowed_role_ids:
        user_role_ids = {r.id for r in author.roles}
        if user_role_ids & allowed_role_ids:
            return False
    if author.id == bot.owner_id:
        return False
    global_cfg = get_global_config(all_data)
    if author.id in global_cfg.get("trusted_users", []):
        return False
    return True


async def _check_iplogger(message: discord.Message) -> bool:
    """
    メッセージ内のURLをスキャンし、既知のIPロガー系ドメインまたは
    短縮URLの展開先がIPロガーであれば削除・通知します。
    通常のメッセージ本文に加え、転送(Forward)メッセージのスナップショット・埋め込みも
    走査対象に含みます（_collect_automod_scan_texts参照）。
    True を返すと呼び出し元でメッセージ処理を中断します。
    """
    # 既知のIPロガー・フィッシング系ドメイン一覧
    IPLOGGER_DOMAINS = {
        "grabify.link", "iplogger.org", "iplogger.com", "iplogger.ru",
        "2no.co", "yip.su", "ps3cfw.com", "stopify.co", "lovebird.guru",
        "blasze.com", "blasze.tk", "iplis.ru", "02ip.ru", "ezstat.ru",
        "linezing.com", "trackyou.live", "ipgrab.io", "loggly.io",
        "track.ly", "link.tl", "bc.vc", "shorturl.at",
        "jackass.wtf", "screenshot.exposed",
    }
    # URL短縮サービス（展開チェック対象）
    URL_SHORTENERS = {
        "bit.ly", "tinyurl.com", "t.co", "ow.ly", "is.gd",
        "buff.ly", "adf.ly", "goo.gl", "cutt.ly", "rebrand.ly",
        "tiny.cc", "rb.gy", "short.io",
    }

    import re
    scan_text = "\n".join(_collect_automod_scan_texts(message))
    urls = re.findall(r"https?://[^\s<>\"']+", scan_text)
    if not urls:
        return False

    detected_url = None
    detected_reason = None

    for url in urls:
        try:
            from urllib.parse import urlparse
            parsed = urlparse(url)
            domain = parsed.netloc.lower().lstrip("www.")
        except Exception:
            continue

        # 直接一致チェック
        if any(domain == d or domain.endswith("." + d) for d in IPLOGGER_DOMAINS):
            detected_url = url
            detected_reason = f"既知のIPロガードメイン: `{domain}`"
            break

        # 短縮URL展開チェック
        if any(domain == d or domain.endswith("." + d) for d in URL_SHORTENERS):
            try:
                async with aiohttp.ClientSession() as session:
                    async with session.head(url, allow_redirects=True, timeout=aiohttp.ClientTimeout(total=5)) as resp:
                        final_url = str(resp.url)
                        final_domain = urlparse(final_url).netloc.lower().lstrip("www.")
                        if any(final_domain == d or final_domain.endswith("." + d) for d in IPLOGGER_DOMAINS):
                            detected_url = url
                            detected_reason = f"短縮URL展開先がIPロガー: `{final_domain}`"
                            break
            except Exception:
                pass

    if not detected_url:
        return False

    try:
        await message.delete()
    except Exception:
        pass

    warn_embed = discord.Embed(
        title=" IPロガーリンクを検知・削除しました",
        color=discord.Color.red()
    )
    warn_embed.add_field(name="送信者", value=message.author.mention, inline=True)
    warn_embed.add_field(name="検知理由", value=detected_reason, inline=False)
    warn_embed.set_footer(text="このリンクは個人情報（IPアドレス）を収集する危険なURLです")

    try:
        await message.channel.send(
            f"[!] {message.author.mention} 危険なIPロガーリンクを検知したため削除しました。",
            delete_after=10
        )
    except Exception:
        pass

    await _send_mod_log(message.guild, warn_embed)
    return True


# OCR結果（画像から読み取ったテキスト）から招待リンクらしき文字列を一次検知する正規表現。
# OCR誤読で起こりやすいゆらぎ（"."が","や"9"に化ける、スペース混入等）を最小限吸収する。
# 過度に緩めると誤検知が増えAI補助判定のコストも上がるため、実際に起こりやすい誤読パターンに絞る。
_OCR_INVITE_LINK_PATTERN = re.compile(
    r"discord[\s.,:;9]{0,3}(gg|com\s*/\s*invite)[\s/]{0,3}[a-z0-9\-_]{2,}"
    r"|dsc[\s.,:;9]{0,3}gg[\s/]{0,3}[a-z0-9\-_]{2,}"
    # OCR誤読で「discord」の文字自体が崩れたケース（例: d1scord、discorcl、di5cord）
    r"|d[il1]sco[rn][dcl][\s.,:;9]{0,3}(gg|com)"
    # "invite" という単語だけが読み取れたケース（discordの文字が欠落していても拾う）
    r"|(?<![a-z])invite[\s/]{0,3}[a-z0-9\-_]{4,}"
    # 「.gg」だけが読み取れ、直前にdiscordが無くても招待コードらしき文字列が続く場合
    r"|(?<![a-z0-9])\.gg[\s/]{0,3}[a-z0-9\-_]{4,}",
    re.IGNORECASE
)

# 上記正規表現に一切ヒットしなくても、画像から一定量のテキストが読み取れた場合は
# AIに丸ごと判定させる（正規表現の再現率がそのまま検知率の上限になるのを避けるため）。
# サーバー招待の埋め込みプレビューカード（サーバー名・オンライン人数・「サーバーへ移動」ボタン等）は
# "discord.gg" という文字列自体がカード内に存在しないことが多く、正規表現では原理的に検知できない。
_OCR_MIN_TEXT_LENGTH_FOR_AI_CHECK = 6

_AI_OCR_INVITE_JUDGE_SYSTEM_PROMPT = (
    "あなたはDiscordの自動モデレーションシステムの一部です。"
    "OCR（画像文字認識）で画像から読み取ったテキストが渡されます。"
    "これはOCRの誤読を含む可能性があります（記号の読み間違い、スペースの混入・欠落、"
    "文字化け、改行位置のずれ、フォントの装飾による誤認識等）。\n\n"
    "この画像が、Discordサーバーへの招待（招待リンクや招待コード、または「サーバーへ移動」"
    "「Join Server」等のボタンを含むサーバー招待の埋め込みプレビューカード）を含んでいるかを"
    "判定してください。次のようなケースはすべて招待とみなしてflaggedをtrueにしてください:\n"
    "- discord.gg/xxxxx、discord.com/invite/xxxxx 形式のURL（OCR誤読による表記ゆれを含む）\n"
    "- サーバー名・メンバー数（オンライン人数表示等）・「サーバーへ移動」「Join」ボタンなど、"
    "Discordのサーバー招待プレビューカードに特有の構成要素が読み取れる場合"
    "（URLの文字列自体が読み取れていなくても、これらの要素があれば招待とみなしてください）\n"
    "- 招待コードらしき英数字の羅列＋「invite」「参加」「join」等の語が近くにある場合\n\n"
    "一方、以下のような場合はflaggedをfalseにしてください:\n"
    "- 単に「discord」という単語がアプリ名として言及されているだけで、招待の要素が無い場合\n"
    "- discordという英単語（不和・不一致の意）として使われている場合\n"
    "- OCRで読み取れたテキストが断片的すぎて、招待かどうか判断できない場合（安全側でfalse）\n\n"
    "必ず以下のJSON形式のみで出力してください（前後に説明文やコードブロック記号は不要）:\n"
    '{"flagged": true または false, "reason": "判定理由を一文で"}'
)


async def _ai_judge_ocr_invite_link(ocr_text: str, guild_id: Optional[int] = None) -> Tuple[bool, str]:
    """
    OCRで画像から読み取ったテキスト全体をAIに渡し、Discordサーバーへの招待
    （URL・招待コード・招待プレビューカードの構成要素等）が含まれるかを判定します。
    正規表現による一次フィルタは行わず、一定量のテキストが取れていれば毎回この判定を行います
    （正規表現はサーバー招待プレビューカードのようにURL文字列自体が画像内に存在しないケースを
    検知できないため、AI判定を主とし、正規表現はログ用の補助シグナルに留めます）。
    AI呼び出しに失敗した場合は安全側（flagged=False、誤検知で削除しない）にフォールバックします。
    """
    messages = [
        {"role": "system", "content": _AI_OCR_INVITE_JUDGE_SYSTEM_PROMPT},
        {"role": "user", "content": ocr_text[:1000]},
    ]
    try:
        provider_override = await _ai_get_provider_override(guild_id)
        raw, _provider = await _ai_call_llm_with_fallback(messages, provider_override=provider_override)
    except Exception as e:
        print(f"[画像OCR招待リンク検知] AI判定の呼び出しに失敗（安全側でflagged=False）: {e}")
        return False, "AI判定を利用できなかったため見送りました"

    cleaned = raw.strip()
    if cleaned.startswith("```"):
        cleaned = re.sub(r"^```(?:json)?\s*|\s*```$", "", cleaned, flags=re.IGNORECASE | re.DOTALL).strip()

    try:
        parsed = json.loads(cleaned)
        flagged = bool(parsed.get("flagged", False))
        reason = str(parsed.get("reason", "")).strip() or "AIが招待リンクと判定しました"
        return flagged, reason
    except (json.JSONDecodeError, AttributeError, ValueError) as e:
        print(f"[画像OCR招待リンク検知] AI判定結果の解析に失敗（安全側でflagged=False）: {e} / raw={cleaned[:200]}")
        return False, "AI判定結果の解析に失敗したため見送りました"


async def _check_image_invite_link(message: discord.Message) -> bool:
    """
    メッセージに添付された画像をOCR解析し、画像内に書かれた招待リンク文字列を検知した場合
    メッセージを削除・通知します。True を返すと呼び出し元でメッセージ処理を中断します。
    既存のテキスト本文向け招待リンク検知（automod_invite_enabled）とは独立した機能で、
    OCR_SPACE_API_KEY が未設定の場合は何もせず False を返します。
    Discordのネイティブ「転送」機能で送られたメッセージは、画像添付が message.attachments
    ではなく message.message_snapshots[].attachments 側に入るため、そちらも走査します。

    検知方式: 正規表現による一次フィルタは行わず、画像から一定量のOCRテキストが
    読み取れた場合は常にAIへ判定を委ねます（サーバー招待の埋め込みプレビューカードは
    "discord.gg" という文字列自体が画像内に存在しないことが多く、正規表現では
    原理的に検知できないため）。正規表現はログ記録用の補助シグナルとしてのみ使用します。
    1メッセージに複数枚の画像が添付されている場合、招待の痕跡が見つかるまで順に確認します
    （最大 _OCR_MAX_IMAGES_PER_MESSAGE 枚まで。無制限に確認するとOCR/AI呼び出しコストが
    青天井になるため上限を設けています）。
    """
    if not OCR_SPACE_API_KEY:
        return False

    _IMAGE_EXTENSIONS = (".png", ".jpg", ".jpeg", ".gif", ".webp", ".bmp")
    _OCR_MAX_IMAGES_PER_MESSAGE = 3

    def _image_urls(attachments) -> list:
        urls = []
        for attachment in attachments or []:
            filename_lower = (getattr(attachment, "filename", "") or "").lower()
            if filename_lower.endswith(_IMAGE_EXTENSIONS):
                urls.append(attachment.url)
        return urls

    image_urls = _image_urls(message.attachments)
    if not image_urls:
        for snapshot in getattr(message, "message_snapshots", None) or []:
            image_urls = _image_urls(getattr(snapshot, "attachments", None))
            if image_urls:
                break

    if not image_urls:
        return False

    for image_url in image_urls[:_OCR_MAX_IMAGES_PER_MESSAGE]:
        ocr_text = await extract_text_from_image(image_url)
        if not ocr_text or len(ocr_text.strip()) < _OCR_MIN_TEXT_LENGTH_FOR_AI_CHECK:
            continue

        # 正規表現ヒットはログ用の補助シグナル（AI判定の可否には影響しない）
        regex_hit = bool(_OCR_INVITE_LINK_PATTERN.search(ocr_text))

        flagged, reason = await _ai_judge_ocr_invite_link(ocr_text, guild_id=message.guild.id if message.guild else None)
        if not flagged:
            continue
        if regex_hit:
            reason = f"{reason}（正規表現パターンにも一致）"
        break
    else:
        return False

    try:
        await message.delete()
    except Exception:
        pass

    warn_embed = discord.Embed(
        title=" 画像内の招待リンクを検知・削除しました",
        color=discord.Color.red()
    )
    warn_embed.add_field(name="送信者", value=message.author.mention, inline=True)
    warn_embed.add_field(name="検知理由", value=reason, inline=False)
    warn_embed.set_footer(text="画像OCR招待リンク検知（AI補助判定）による自動削除")

    try:
        await message.channel.send(
            f"[!] {message.author.mention} 画像内に含まれる招待リンクを検知したため削除しました。",
            delete_after=10
        )
    except Exception:
        pass

    await _send_mod_log(message.guild, warn_embed)
    return True


