async def _gacha_generate_persona(
    guild_id: Optional[int] = None,
    avoid_names: Optional[list] = None,
) -> Optional[dict]:
    """
    レアリティを抽選し、AIにキャラクター設定を生成させます。失敗時はNoneを返します。
    avoid_names: そのユーザーが既に持っている名前のリスト。指定すると、これらと
    被らない名前にするようAIへ明示的に指示し、生成結果の重複を防ぎます。
    """
    import random

    rarity_name, flavor_instruction = _gacha_roll_rarity()
    theme = random.choice(GACHA_THEME_HINTS)
    theme_instruction = f"今回の題材の方向性: {theme}。この方向性を踏まえて考案してください。"

    avoid_instruction = ""
    if avoid_names:
        # プロンプト肥大化を避けるため直近分のみに絞る
        sample = avoid_names[-15:]
        avoid_instruction = (
            "すでに存在する次の名前とは異なる、新しい名前を考えてください: "
            + "、".join(sample) + "\n"
        )

    prompt = _GACHA_PERSONA_SYSTEM_PROMPT_TEMPLATE.format(
        flavor_instruction=flavor_instruction,
        theme_instruction=theme_instruction,
        avoid_instruction=avoid_instruction,
    )
    messages = [
        {"role": "system", "content": prompt},
        {"role": "user", "content": "オリジナルキャラクターを1体生成してください。"},
    ]

    try:
        provider_override = await _ai_get_provider_override(guild_id)
        raw, _provider = await _ai_call_llm_with_fallback(messages, provider_override=provider_override)
    except Exception as e:
        print(f"[AI人格ガチャ] LLM呼び出しに失敗: {e}")
        return None

    parsed = _ai_extract_json_response(raw)
    if not isinstance(parsed, dict):
        return None

    persona_id = uuid.uuid4().hex[:12]
    return {
        "id": persona_id,
        "rarity": rarity_name,
        "name": str(parsed.get("name", "名無し")).strip()[:20] or "名無し",
        "first_person": str(parsed.get("first_person", "私")).strip()[:10] or "私",
        "personality": str(parsed.get("personality", "")).strip()[:100],
        "speech_style": str(parsed.get("speech_style", "")).strip()[:100],
        "catchphrase": str(parsed.get("catchphrase", "")).strip()[:50],
        "flavor_text": str(parsed.get("flavor_text", "")).strip()[:100],
        "obtained_at": datetime.datetime.now(datetime.timezone.utc).isoformat(),
    }


async def _translate_message_text(text: str, secondary_lang: str, guild_id: Optional[int] = None) -> Optional[Tuple[str, str]]:
    """
    メッセージ本文の言語を検出し、必要な言語へ翻訳します。
    戻り値: (detected_lang, translated_text)。翻訳する必要がない・失敗した場合はNone。
    """
    if not text or not text.strip():
        return None

    user_prompt = (
        f"ターゲット言語コード（投稿者が日本語で書いていた場合の翻訳先）: {secondary_lang}\n\n"
        f"翻訳対象の文章:\n{text}"
    )
    messages = [
        {"role": "system", "content": TRANSLATE_SYSTEM_PROMPT},
        {"role": "user", "content": user_prompt},
    ]

    try:
        provider_override = await _ai_get_provider_override(guild_id)
        raw, _provider = await _ai_call_llm_with_fallback(messages, provider_override=provider_override)
    except Exception as e:
        print(f"[自動翻訳] LLM呼び出しエラー: {e}")
        return None

    parsed = _ai_extract_json_response(raw)
    if not parsed:
        return None

    detected_lang = str(parsed.get("detected_lang", "")).strip().lower()
    translated_text = str(parsed.get("translated_text", "")).strip()
    if not translated_text:
        return None

    return detected_lang, translated_text


async def _handle_auto_translate(message: discord.Message, guild_config: dict):
    """
    自動翻訳対象チャンネルに投稿されたメッセージを翻訳し、embedで返信します。
    AIチャットの自動応答（returnして他処理を止める仕組み）とは独立しており、
    この処理自体が他の機能をブロックすることはありません。
    """
    if not message.content or not message.content.strip():
        return
    if not GROQ_API_KEY:
        return

    secondary_lang = guild_config.get("translate_secondary_lang", "en")
    result = await _translate_message_text(message.content, secondary_lang, guild_id=message.guild.id if message.guild else None)
    if not result:
        return

    detected_lang, translated_text = result
    if not translated_text or translated_text.strip() == message.content.strip():
        return

    embed = discord.Embed(description=translated_text, color=discord.Color.blurple())
    embed.set_author(
        name=f"{message.author.display_name} の翻訳（検出言語: {detected_lang or '不明'}）",
        icon_url=message.author.display_avatar.url if message.author.display_avatar else None
    )

    try:
        await message.reply(embed=embed, mention_author=False)
    except discord.Forbidden:
        try:
            await message.channel.send(embed=embed)
        except Exception:
            pass
    except Exception as e:
        print(f"[自動翻訳] embed送信エラー: {e}")


class GroqAPIError(RuntimeError):
    """Groq API呼び出しに関する汎用エラー。"""
    pass


class GroqRateLimitError(GroqAPIError):
    """
    Groq APIがレート制限（HTTP 429）を返した場合に送出される専用例外。
    呼び出し側でこれを個別にキャッチし、ユーザーに分かりやすい文言を表示するために使用します。
    """
    def __init__(self, retry_after: Optional[float] = None, raw_message: str = "", limit_scope: Optional[str] = None):
        self.retry_after = retry_after
        self.raw_message = raw_message
        self.limit_scope = limit_scope  # "TPM" / "TPD" / "RPM" / "RPD" / None（不明）
        suffix = f"（推定復帰まで約{_format_duration(retry_after)}）" if retry_after else ""
        super().__init__(f"Groq APIのレート制限に達しました{suffix}")


def _format_duration(seconds: float) -> str:
    """秒数を「7分7秒」のような日本語表記に変換します。0秒未満の端数は切り上げ、最低1秒として表示します。"""
    seconds = max(1, math.ceil(seconds))
    if seconds < 60:
        return f"{seconds}秒"
    minutes, secs = divmod(seconds, 60)
    if minutes < 60:
        return f"{minutes}分{secs}秒" if secs else f"{minutes}分"
    hours, minutes = divmod(minutes, 60)
    return f"{hours}時間{minutes}分" if minutes else f"{hours}時間"


# Groqのレート制限エラーメッセージから "Please try again in 11.325s" や
# "Please try again in 7m7.248s" のような待機時間を抽出するための正規表現。
# 時(h)・分(m)・秒(s)は任意の組み合わせで出現しうる（例: "1h2m3.4s", "7m7.248s", "11.325s"）。
_GROQ_RETRY_AFTER_PATTERN = re.compile(
    r"try again in (?:(\d+)h)?(?:(\d+)m)?(?:([\d.]+)s)?",
    re.IGNORECASE
)

# エラーメッセージ中の "on tokens per day (TPD)" / "on tokens per minute (TPM)" 等から
# どの種類の制限に達したかを判定するための正規表現。
_GROQ_LIMIT_SCOPE_PATTERN = re.compile(r"\(([A-Z]{3})\)")


def _parse_groq_retry_after(err_text: str) -> Optional[float]:
    """Groqのエラーメッセージから待機秒数を抽出します（時/分/秒の混在に対応）。"""
    m = _GROQ_RETRY_AFTER_PATTERN.search(err_text)
    if not m or not any(m.groups()):
        return None
    hours = float(m.group(1)) if m.group(1) else 0.0
    minutes = float(m.group(2)) if m.group(2) else 0.0
    secs = float(m.group(3)) if m.group(3) else 0.0
    total = hours * 3600 + minutes * 60 + secs
    return total if total > 0 else None


def _inject_no_search_notice(messages: list) -> list:
    """
    Cerebras/Mistral等、Web検索（Tool Use）に対応させていない呼び出し経路向けに、
    system メッセージへ「今回はweb_searchツールが実際には使えない」旨の注記を追記した
    新しいメッセージ配列を返す（元のリスト・辞書は変更しない）。

    背景: messages配列には、Groqでの検索対応を前提に組み立てられた
    AI_CHAT_SEARCH_USAGE_GUIDE（「web_searchツールが利用可能」という案内）が
    既に含まれていることがある。Cerebras/Mistral、またはGroqのフォールバックモデル
    （検索機能なしで呼び出される）にフォールバックした場合、実際にはツール定義を
    渡していないため、この案内を放置するとモデルが「ツールがあるはず」と誤認し、
    本文中にツール呼び出しらしきJSONを自分で書いてしまう（結果、検索結果を捏造する／
    JSON漏れとして弾かれ、ユーザーには意味不明な断り文言だけが返る）不具合の原因になっていた。
    """
    if not messages:
        return messages

    notice = (
        "\n\n【重要・システムからの追加通知】"
        "都合により、今回のこの応答ではWeb検索ツール（web_search）は実際には利用できません。"
        "先の指示に「web_searchツールが利用可能」という記述が含まれていても、それは今回は無効です。"
        "ツール呼び出しの真似としてJSON形式の文字列を本文に書くことは絶対にしないでください。"
        "検索結果を自分で創作することも禁止です。"
        "最新情報が必要な質問であっても、あなた自身が知っている範囲の一般的な知識のみで、"
        "「これは学習データの時点の情報であり、最新の状況とは異なる可能性がある」と"
        "一言添えた上で回答してください。"
    )

    new_messages = list(messages)
    if new_messages and new_messages[0].get("role") == "system":
        new_messages[0] = {
            "role": "system",
            "content": (new_messages[0].get("content") or "") + notice
        }
    else:
        new_messages.insert(0, {"role": "system", "content": notice.strip()})
    return new_messages


async def _ai_chat_call_groq(messages: list, model: Optional[str] = None) -> str:
    """
    Groq Chat Completions APIを呼び出し、応答テキストを返します。
    失敗時は例外を送出するので、呼び出し側でtry/exceptしてください。
    HTTP 429（レート制限）の場合は GroqRateLimitError を送出し、
    それ以外のエラーは GroqAPIError を送出します。

    DeepSeek-R1やQwen3など「推論(reasoning)モデル」は応答に <think>...</think> 形式で
    思考過程を含めることがあります。reasoning_format="hidden" で抑制を試みつつ、
    対応していないモデル向けに文字列側でも <think> タグを除去するフォールバックを行います。

    Args:
        messages: Chat Completions形式のメッセージ配列。
        model: 使用するモデル名。省略時はグローバル既定値（GROQ_MODEL）を使用します。
               ユーザー個別設定でモデルが指定されている場合はここに渡してください。
    """
    if not GROQ_API_KEY:
        raise RuntimeError("GROQ_API_KEY が設定されていません。Botの環境変数を確認してください。")

    headers = {
        "Authorization": f"Bearer {GROQ_API_KEY}",
        "Content-Type": "application/json"
    }
    payload = {
        "model": model or GROQ_MODEL,
        "messages": _inject_no_search_notice(messages),
        "temperature": 0.7,
        "max_tokens": GROQ_MAX_TOKENS,
        "reasoning_format": "hidden",  # 推論モデルの思考過程を応答本文に含めない（対応モデルのみ有効）
    }

    async with aiohttp.ClientSession() as session:
        async with session.post(
            "https://api.groq.com/openai/v1/chat/completions",
            headers=headers,
            json=payload,
            timeout=aiohttp.ClientTimeout(total=30)
        ) as resp:
            if resp.status == 429:
                err_text = await resp.text()
                retry_after: Optional[float] = None
                # Retry-Afterヘッダがあれば優先的に使用
                header_val = resp.headers.get("Retry-After")
                if header_val:
                    try:
                        retry_after = float(header_val)
                    except ValueError:
                        retry_after = None
                if retry_after is None:
                    retry_after = _parse_groq_retry_after(err_text)

                limit_scope: Optional[str] = None
                scope_m = _GROQ_LIMIT_SCOPE_PATTERN.search(err_text)
                if scope_m:
                    limit_scope = scope_m.group(1)  # 例: "TPM", "TPD", "RPM", "RPD"

                raise GroqRateLimitError(retry_after=retry_after, raw_message=err_text[:300], limit_scope=limit_scope)
            if resp.status != 200:
                err_text = await resp.text()
                raise GroqAPIError(f"Groq APIエラー（HTTP {resp.status}）: {err_text[:300]}")
            data = await resp.json()

    try:
        choice = data["choices"][0]
        raw_content = choice["message"]["content"]
    except (KeyError, IndexError, TypeError):
        raise GroqAPIError(f"Groq APIの応答形式が想定と異なります: {data}")

    reply_text = _sanitize_ai_reply_content(raw_content)

    # 推論モデルは思考過程もmax_tokensを消費するため、本文が生成しきれず
    # 途中で打ち切られる（finish_reason == "length"）ことがある。
    # その場合は目立つように注記を付ける（GROQ_MAX_TOKENSを増やすことで軽減可能）。
    if choice.get("finish_reason") == "length":
        reply_text += "\n\n*（⚠️ 出力上限のため応答が途中で切れている可能性があります）*"

    return reply_text


# ====================================================================
# Web検索API群（AIチャットのWeb検索・最新情報取得機能）
# ====================================================================
# GroqのモデルはあくまでAPIが提供するChat Completions（テキスト生成）のみを行い、
# それ自体はインターネットに接続できない。最新情報が必要な場合は、
# 1. Groqに「web_search」というツールを使えることを伝える（Tool Use/Function Calling）
# 2. Groqが必要と判断した場合、検索クエリを含むtool_callを返してくる
# 3. こちらが実際にWeb検索APIで検索し、結果をテキストとしてGroqに返す
# 4. Groqがその検索結果を踏まえて最終的な応答文を生成する
# という2往復のやり取りで実現する。
#
# 各社無料枠には月間・日次の上限があるため、1社が上限（レート制限/エラー）に達しても
# 検索機能自体が完全に止まらないよう、以下の優先順位で自動フォールバックする
# （Groq→Cerebras→Mistralの考え方と同じ）:
#   1. Tavily      （TAVILY_API_KEY）
#   2. Exa          （EXA_API_KEY）
#   3. Firecrawl    （FIRECRAWL_API_KEY）
# 未設定のAPIはスキップされる。全て未設定 or 全て失敗した場合のみ、その旨のテキストを返す。
# ====================================================================

class WebSearchError(RuntimeError):
    """Web検索API呼び出しに関する汎用エラー（各プロバイダの失敗時にraiseし、次のプロバイダへ回す）。"""
    pass


# ====================================================================
# Playwright（Web検索結果の記事本文取得: JavaScript必須サイト対応）
# ====================================================================
# 各検索API（Tavily/Exa/Firecrawl/NewsData.io）が返す本文は要約・snippet程度（〜500字）に
# 留まることが多く、SPA（React/Vue等でクライアント側描画するサイト）では
# そもそも検索API側のクローラーが本文を取得できていないことがある。
# そのため、検索結果の出典URLのうち上位数件のみ、実ブラウザ（Chromium）で開いて
# レンダリング後のテキストを抽出し、AIに渡す情報を補強する。
#
# 常時起動のブラウザプロセスは持たず、必要な呼び出しのたびに起動・終了する
# （Botのメモリ・CPU負荷を抑えるため。Railway等の小規模インスタンスを想定）。
# playwrightパッケージ、およびブラウザバイナリ（`playwright install chromium`）が
# 未導入の環境でもBot自体は起動できるよう、_PLAYWRIGHT_AVAILABLEで判定してスキップする。
# ====================================================================

# Playwrightで本文取得を試みる出典URLの最大件数（検索結果の上位から）。
# 1件あたり数秒かかるため、AIチャットの応答速度への影響を抑えるために少なめにする。
PLAYWRIGHT_FETCH_MAX_URLS = int(os.getenv("PLAYWRIGHT_FETCH_MAX_URLS", "2"))
# 1ページあたりのタイムアウト（ミリ秒）。
PLAYWRIGHT_FETCH_TIMEOUT_MS = int(os.getenv("PLAYWRIGHT_FETCH_TIMEOUT_MS", "12000"))
# 本文として抽出するテキストの最大文字数（AIへの入力トークンを抑えるため）。
PLAYWRIGHT_FETCH_MAX_CHARS = int(os.getenv("PLAYWRIGHT_FETCH_MAX_CHARS", "2000"))

_URL_PATTERN = re.compile(r"https?://[^\s\)\]\}\"']+")


async def _fetch_article_text_playwright(url: str) -> Optional[str]:
    """
    Playwrightで指定URLを開き、レンダリング後の本文らしきテキストを抽出して返します。
    Playwright未導入、タイムアウト、その他エラー時はNoneを返します（呼び出し元は
    その場合スニペットのみで継続するため、例外を外へ伝播させません）。
    """
    if not _PLAYWRIGHT_AVAILABLE:
        return None

    try:
        async with async_playwright() as p:
            browser = await p.chromium.launch(
                headless=True,
                args=["--no-sandbox", "--disable-dev-shm-usage"],  # コンテナ環境（Railway等）での起動対策
            )
            try:
                context = await browser.new_context(
                    user_agent=(
                        "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 "
                        "(KHTML, like Gecko) Chrome/124.0.0.0 Safari/537.36"
                    )
                )
                page = await context.new_page()
                await page.goto(url, timeout=PLAYWRIGHT_FETCH_TIMEOUT_MS, wait_until="domcontentloaded")
                # SPA等、JS描画に時間がかかるサイトのため短時間だけ追加待機する
                try:
                    await page.wait_for_timeout(1500)
                except Exception:
                    pass

                # <script>/<style>/<nav>/<header>/<footer>等のノイズ要素を除いた本文テキストを
                # ブラウザ内のJSで抽出する（記事本文らしき<article>/<main>があればそれを優先）。
                text = await page.evaluate("""
                    () => {
                        const removeSelectors = ['script', 'style', 'nav', 'header', 'footer', 'noscript', 'iframe'];
                        const root = document.querySelector('article') || document.querySelector('main') || document.body;
                        if (!root) return '';
                        const clone = root.cloneNode(true);
                        removeSelectors.forEach(sel => {
                            clone.querySelectorAll(sel).forEach(el => el.remove());
                        });
                        return clone.innerText || '';
                    }
                """)
            finally:
                await browser.close()
    except Exception as e:
        print(f"[Web検索/Playwright] {url} の本文取得に失敗しました: {e}")
        return None

    if not text:
        return None
    # 連続する空白・改行を整理してから文字数を絞る
    cleaned = re.sub(r"[ \t]+", " ", text)
    cleaned = re.sub(r"\n{3,}", "\n\n", cleaned).strip()
    if not cleaned:
        return None
    return cleaned[:PLAYWRIGHT_FETCH_MAX_CHARS]


async def _augment_search_result_with_playwright(result_text: str, guild_config: Optional[dict] = None) -> str:
    """
    検索APIが返したテキスト（スニペット中心）から出典URLを抽出し、Playwrightが利用可能であれば
    上位数件についてブラウザで本文を取得して追記します。
    Playwright未導入、サーバー側で無効化されている、または全件取得失敗の場合は元のテキストをそのまま返します。
    """
    if not _PLAYWRIGHT_AVAILABLE:
        return result_text
    # サーバーごとにPlaywrightでの本文取得を無効化できる（既定: 有効）。
    if not (guild_config or {}).get("ai_chat_playwright_fetch_enabled", True):
        return result_text

    urls = _URL_PATTERN.findall(result_text)
    if not urls:
        return result_text

    # 同一URLの重複を除きつつ順序を保持
    seen = set()
    unique_urls = []
    for u in urls:
        if u not in seen:
            seen.add(u)
            unique_urls.append(u)

    target_urls = unique_urls[:PLAYWRIGHT_FETCH_MAX_URLS]
    fetched_sections = []
    for url in target_urls:
        article_text = await _fetch_article_text_playwright(url)
        if article_text:
            fetched_sections.append(f"--- 本文（実ブラウザ取得）: {url} ---\n{article_text}")

    if not fetched_sections:
        return result_text

    return (
        result_text
        + "\n\n"
        + "\n\n".join(fetched_sections)
        + "\n\n（注: 上記「本文（実ブラウザ取得）」はJavaScriptで描画されるページも含め、"
          "実際にブラウザでレンダリングして取得した本文です。要約より詳細な情報が必要な場合はこちらを優先してください。）"
    )


async def _tavily_web_search(query: str, max_results: int = 5) -> str:
    """Tavily Search APIを呼び出し、検索結果をテキスト形式に整形して返します。失敗時はWebSearchErrorをraiseします。"""
    payload = {
        "api_key": TAVILY_API_KEY,
        "query": query,
        "max_results": max_results,
        "search_depth": "basic",
    }
    try:
        async with aiohttp.ClientSession() as session:
            async with session.post(
                "https://api.tavily.com/search",
                json=payload,
                timeout=aiohttp.ClientTimeout(total=15)
            ) as resp:
                if resp.status != 200:
                    err_text = await resp.text()
                    raise WebSearchError(f"Tavily APIエラー（HTTP {resp.status}）: {err_text[:300]}")
                data = await resp.json()
    except WebSearchError:
        raise
    except Exception as e:
        raise WebSearchError(f"Tavily 呼び出しエラー: {e}") from e

    results = data.get("results", [])
    if not results:
        return "（検索結果が見つかりませんでした。）"

    lines = []
    # Tavilyが要約（answer）を返す場合、最も端的な情報として先頭に含める
    if data.get("answer"):
        lines.append(f"要約: {data['answer']}")

    for i, r in enumerate(results[:max_results], start=1):
        title = r.get("title", "").strip()
        content = (r.get("content") or "").strip()
        url = r.get("url", "")
        # AIへ渡す用の中間データのため文字数を絞る（そのままユーザーに見せるものではない）
        content_snippet = content[:500]
        lines.append(f"[{i}] {title}\n{content_snippet}\n出典URL: {url}")

    return "\n\n".join(lines)


async def _exa_web_search(query: str, max_results: int = 5) -> str:
    """Exa Search APIを呼び出し、検索結果をテキスト形式に整形して返します。失敗時はWebSearchErrorをraiseします。"""
    headers = {
        "x-api-key": EXA_API_KEY,
        "Content-Type": "application/json",
    }
    payload = {
        "query": query,
        "numResults": max_results,
        "contents": {"text": {"maxCharacters": 500}},
    }
    try:
        async with aiohttp.ClientSession() as session:
            async with session.post(
                "https://api.exa.ai/search",
                json=payload,
                headers=headers,
                timeout=aiohttp.ClientTimeout(total=15)
            ) as resp:
                if resp.status != 200:
                    err_text = await resp.text()
                    raise WebSearchError(f"Exa APIエラー（HTTP {resp.status}）: {err_text[:300]}")
                data = await resp.json()
    except WebSearchError:
        raise
    except Exception as e:
        raise WebSearchError(f"Exa 呼び出しエラー: {e}") from e

    results = data.get("results", [])
    if not results:
        return "（検索結果が見つかりませんでした。）"

    lines = []
    for i, r in enumerate(results[:max_results], start=1):
        title = (r.get("title") or "").strip()
        text = (r.get("text") or "").strip()[:500]
        url = r.get("url", "")
        lines.append(f"[{i}] {title}\n{text}\n出典URL: {url}")

    return "\n\n".join(lines)


async def _firecrawl_web_search(query: str, max_results: int = 5) -> str:
    """Firecrawl Search APIを呼び出し、検索結果をテキスト形式に整形して返します。失敗時はWebSearchErrorをraiseします。"""
    headers = {
        "Authorization": f"Bearer {FIRECRAWL_API_KEY}",
        "Content-Type": "application/json",
    }
    payload = {
        "query": query,
        "limit": max_results,
    }
    try:
        async with aiohttp.ClientSession() as session:
            async with session.post(
                "https://api.firecrawl.dev/v1/search",
                json=payload,
                headers=headers,
                timeout=aiohttp.ClientTimeout(total=15)
            ) as resp:
                if resp.status != 200:
                    err_text = await resp.text()
                    raise WebSearchError(f"Firecrawl APIエラー（HTTP {resp.status}）: {err_text[:300]}")
                data = await resp.json()
    except WebSearchError:
        raise
    except Exception as e:
        raise WebSearchError(f"Firecrawl 呼び出しエラー: {e}") from e

    results = data.get("data", [])
    if not results:
        return "（検索結果が見つかりませんでした。）"

    lines = []
    for i, r in enumerate(results[:max_results], start=1):
        title = (r.get("title") or "").strip()
        description = (r.get("description") or "").strip()[:500]
        url = r.get("url", "")
        lines.append(f"[{i}] {title}\n{description}\n出典URL: {url}")

    return "\n\n".join(lines)


async def _newsdata_web_search(query: str, max_results: int = 5) -> str:
    """
    NewsData.io の latest エンドポイントを呼び出し、検索結果をテキスト形式に整形して返します。
    失敗時はWebSearchErrorをraiseします。
    他プロバイダと異なりニュース記事専門のAPIのため、直近48時間以内の報道記事のみが対象です
    （一般的なWebページやドキュメント等はヒットしません）。
    """
    params = {
        "apikey": NEWSDATA_API_KEY,
        "q": query,
        "language": "ja,en",
    }
    try:
        async with aiohttp.ClientSession() as session:
            async with session.get(
                "https://newsdata.io/api/1/latest",
                params=params,
                timeout=aiohttp.ClientTimeout(total=15)
            ) as resp:
                if resp.status != 200:
                    err_text = await resp.text()
                    raise WebSearchError(f"NewsData.io APIエラー（HTTP {resp.status}）: {err_text[:300]}")
                data = await resp.json()
    except WebSearchError:
        raise
    except Exception as e:
        raise WebSearchError(f"NewsData.io 呼び出しエラー: {e}") from e

    if data.get("status") != "success":
        raise WebSearchError(f"NewsData.io APIエラー: {str(data.get('results', ''))[:300]}")

    results = data.get("results") or []
    if not results:
        return "（検索結果が見つかりませんでした。）"

    lines = []
    for i, r in enumerate(results[:max_results], start=1):
        title = (r.get("title") or "").strip()
        # descriptionが空の場合はcontent（本文、APIにより200字程度に切り詰め）で代替
        description = (r.get("description") or r.get("content") or "").strip()[:500]
        url = r.get("link", "")
        source = (r.get("source_name") or "").strip()
        pub_date = (r.get("pubDate") or "").strip()
        meta = " / ".join(x for x in [source, pub_date] if x)
        header = f"[{i}] {title}" + (f"（{meta}）" if meta else "")
        lines.append(f"{header}\n{description}\n出典URL: {url}")

    return "\n\n".join(lines)


# 優先順位付きのプロバイダ一覧: (内部ID, 表示名, APIキーが設定されているか判定する関数, 検索実行関数)
# 内部IDはサーバーごとの優先順位設定（ai_chat_search_provider_order）で参照するために使用する。
_WEB_SEARCH_PROVIDERS = [
    ("tavily", "Tavily", lambda: bool(TAVILY_API_KEY), _tavily_web_search),
    ("exa", "Exa", lambda: bool(EXA_API_KEY), _exa_web_search),
    ("firecrawl", "Firecrawl", lambda: bool(FIRECRAWL_API_KEY), _firecrawl_web_search),
    ("newsdata", "NewsData.io", lambda: bool(NEWSDATA_API_KEY), _newsdata_web_search),
]
_WEB_SEARCH_PROVIDER_IDS = [p[0] for p in _WEB_SEARCH_PROVIDERS]


def _resolve_search_provider_order(guild_config: Optional[dict] = None) -> list:
    """
    実際に試す順番でプロバイダのタプル一覧を返します。
    guild_configに ai_chat_search_provider_order（["tavily","firecrawl","exa"]等）が
    設定されていればその順を使用し、未指定・不正な値が混ざっている場合はコード既定の順序
    （Tavily→Exa→Firecrawl→NewsData.io）にフォールバックします。
    設定リストに含まれないプロバイダIDがあっても無視し、既定順の末尾に追加はしません
    （管理者が明示的に選んだプロバイダのみを、指定された順で試す）。
    """
    custom_order = (guild_config or {}).get("ai_chat_search_provider_order")
    if not custom_order or not isinstance(custom_order, list):
        return _WEB_SEARCH_PROVIDERS

    by_id = {p[0]: p for p in _WEB_SEARCH_PROVIDERS}
    ordered = [by_id[pid] for pid in custom_order if pid in by_id]
    # 不正な設定（全IDが無効等）で結果が空になった場合は既定順にフォールバック
    return ordered or _WEB_SEARCH_PROVIDERS


async def _web_search_fallback(query: str, max_results: int = 5, guild_config: Optional[dict] = None) -> str:
    """
    設定済みのWeb検索APIを優先順位（既定: Tavily→Exa→Firecrawl→NewsData.io。サーバーごとにカスタム順設定可）
    の順に試し、最初に成功したものの結果を返します。
    どのAPIキーも未設定の場合、または全プロバイダが失敗した場合のみ、
    その旨を示す短いテキストを返します（検索に失敗してもAIチャット自体は継続させたいため）。
    """
    tried_any = False
    for _pid, name, is_configured, search_func in _resolve_search_provider_order(guild_config):
        if not is_configured():
            continue
        tried_any = True
        try:
            result_text = await search_func(query, max_results)
            # JS必須サイト等でスニペットだけでは不十分な場合に備え、Playwrightが利用可能なら
            # 出典URL上位数件の本文を実ブラウザで取得して補強する（未導入時は元のテキストのまま）。
            result_text = await _augment_search_result_with_playwright(result_text, guild_config=guild_config)
            # 検索結果本文にツール結果として直接付与する念押し。
            # AIが「Tavilyによると」「Exa.aiの検索結果では」のように検索ツール自体の名称を
            # 情報源として書いてしまう不具合を防ぐため、tool結果の中にも明記しておく
            # （システムプロンプトより優先度の高い位置に効かせる狙い）。
            return (
                result_text
                + "\n\n（注: 上記は検索ツールを使って取得した結果です。回答内で情報源に触れる場合は、"
                  "各結果に記載の記事タイトルや出典URLのサイト名を使ってください。"
                  "検索に使用したツールやサービス名自体には言及しないでください。）"
            )
        except Exception as e:
            print(f"[Web検索] {name} が失敗したため次のプロバイダへフォールバックします: {e}")
            continue

    if not tried_any:
        return "（Web検索機能は現在利用できません。APIキーが設定されていません。）"
    return "（Web検索に失敗しました。検索結果なしで回答してください。）"


_WEB_SEARCH_TOOL_DEFINITION = {
    "type": "function",
    "function": {
        "name": "web_search",
        "description": (
            "現在の日付・最新ニュース・現在の状況・最近発生した出来事など、"
            "学習データの時点では知り得ない最新情報が必要な場合にWeb検索を行います。"
            "一般的な知識や過去の確定した事実については使用しないでください。"
        ),
        "parameters": {
            "type": "object",
            "properties": {
                "query": {
                    "type": "string",
                    "description": "検索したい内容を表す簡潔な検索キーワード（日本語または英語）"
                }
            },
            "required": ["query"]
        }
    }
}


# ====================================================================
# Open-Meteo API（AIチャットの天気質問用ツール）
# ====================================================================
# Open-Meteo（https://open-meteo.com）はAPIキー登録不要・無料で使える気象APIのため、
# Web検索とは別に「天気専用ツール」としてAIに持たせる。
# 地名から直接は天気を引けないため、次の2段階で呼び出す:
#   1. ジオコーディングAPI（geocoding-api.open-meteo.com）で地名→緯度経度に変換
#   2. 予報API（api.open-meteo.com）でその緯度経度の天気予報を取得
# Web検索と同様Tool Use方式で、AIが天気の質問と判断した場合のみ呼び出される。
# APIキーが不要なため常時有効（他のWeb検索APIキーの設定有無とは独立）。
# ====================================================================

class WeatherLookupError(RuntimeError):
    """Open-Meteo呼び出しに関する汎用エラー。"""
    pass


# WMO Weather interpretation codes (Open-Meteoが返すweathercode)を日本語の天気表現に変換
_WMO_WEATHER_CODE_JA = {
    0: "快晴", 1: "ほぼ晴れ", 2: "一部曇り", 3: "曇り",
    45: "霧", 48: "霧氷を伴う霧",
    51: "弱い霧雨", 53: "霧雨", 55: "強い霧雨",
    56: "弱い着氷性の霧雨", 57: "着氷性の霧雨",
    61: "弱い雨", 63: "雨", 65: "強い雨",
    66: "弱い着氷性の雨", 67: "着氷性の雨",
    71: "弱い雪", 73: "雪", 75: "強い雪",
    77: "霧雪",
    80: "弱いにわか雨", 81: "にわか雨", 82: "激しいにわか雨",
    85: "弱いにわか雪", 86: "激しいにわか雪",
    95: "雷雨", 96: "雹を伴う雷雨", 99: "激しい雹を伴う雷雨",
}


def _weather_code_to_ja(code: Optional[int]) -> str:
    if code is None:
        return "不明"
    return _WMO_WEATHER_CODE_JA.get(int(code), f"不明な天気コード({code})")


async def _open_meteo_geocode(location: str) -> dict:
    """
    地名文字列から緯度経度・正規化された地名を取得します。
    見つからない場合はWeatherLookupErrorをraiseします。
    """
    params = {
        "name": location,
        "count": 1,
        "language": "ja",
        "format": "json",
    }
    try:
        async with aiohttp.ClientSession() as session:
            async with session.get(
                "https://geocoding-api.open-meteo.com/v1/search",
                params=params,
                timeout=aiohttp.ClientTimeout(total=10)
            ) as resp:
                if resp.status != 200:
                    err_text = await resp.text()
                    raise WeatherLookupError(f"Open-Meteo ジオコーディングAPIエラー（HTTP {resp.status}）: {err_text[:300]}")
                data = await resp.json()
    except WeatherLookupError:
        raise
    except Exception as e:
        raise WeatherLookupError(f"Open-Meteo ジオコーディング呼び出しエラー: {e}") from e

    results = data.get("results") or []
    if not results:
        # 日本語地名でヒットしない場合、英語名でも1回だけ再試行する
        if params["language"] == "ja":
            params["language"] = "en"
            try:
                async with aiohttp.ClientSession() as session:
                    async with session.get(
                        "https://geocoding-api.open-meteo.com/v1/search",
                        params=params,
                        timeout=aiohttp.ClientTimeout(total=10)
                    ) as resp:
                        if resp.status == 200:
                            data = await resp.json()
                            results = data.get("results") or []
            except Exception:
                pass
        if not results:
            raise WeatherLookupError(f"「{location}」という地名が見つかりませんでした。")

    top = results[0]
    return {
        "name": top.get("name", location),
        "admin1": top.get("admin1", ""),
        "country": top.get("country", ""),
        "latitude": top.get("latitude"),
        "longitude": top.get("longitude"),
        "timezone": top.get("timezone", "auto"),
    }


async def _open_meteo_forecast(latitude: float, longitude: float, timezone: str = "auto") -> dict:
    """指定した緯度経度の現在の天気・当日/週間予報を取得します。失敗時はWeatherLookupErrorをraiseします。"""
    params = {
        "latitude": latitude,
        "longitude": longitude,
        "current": "temperature_2m,relative_humidity_2m,apparent_temperature,precipitation,weather_code,wind_speed_10m",
        "daily": "weather_code,temperature_2m_max,temperature_2m_min,precipitation_probability_max",
        "timezone": timezone or "auto",
        "forecast_days": 4,
    }
    try:
        async with aiohttp.ClientSession() as session:
            async with session.get(
                "https://api.open-meteo.com/v1/forecast",
                params=params,
                timeout=aiohttp.ClientTimeout(total=10)
            ) as resp:
                if resp.status != 200:
                    err_text = await resp.text()
                    raise WeatherLookupError(f"Open-Meteo 予報APIエラー（HTTP {resp.status}）: {err_text[:300]}")
                return await resp.json()
    except WeatherLookupError:
        raise
    except Exception as e:
        raise WeatherLookupError(f"Open-Meteo 予報呼び出しエラー: {e}") from e


async def _weather_lookup(location: str) -> str:
    """
    地名を受け取り、現在の天気・当日を含む4日間の予報をAIに渡すためのテキストに整形して返します。
    失敗時はエラー内容を短い日本語テキストとして返します（例外はraiseせず、AIチャット自体は継続させる）。
    """
    location = (location or "").strip()
    if not location:
        return "（地名が指定されなかったため、天気を取得できませんでした。）"

    try:
        geo = await _open_meteo_geocode(location)
        forecast = await _open_meteo_forecast(
            geo["latitude"], geo["longitude"], geo.get("timezone", "auto")
        )
    except WeatherLookupError as e:
        return f"（天気情報の取得に失敗しました: {e}）"
    except Exception as e:
        return f"（天気情報の取得中に予期しないエラーが発生しました: {e}）"

    place_label = geo["name"]
    if geo.get("admin1"):
        place_label += f"（{geo['admin1']}, {geo.get('country', '')}）"
    elif geo.get("country"):
        place_label += f"（{geo['country']}）"

    lines = [f"地点: {place_label}"]

    current = forecast.get("current") or {}
    if current:
        temp = current.get("temperature_2m")
        feels = current.get("apparent_temperature")
        humidity = current.get("relative_humidity_2m")
        precip = current.get("precipitation")
        wind = current.get("wind_speed_10m")
        code = current.get("weather_code")
        lines.append(
            f"現在: {_weather_code_to_ja(code)} / 気温 {temp}℃"
            + (f"（体感 {feels}℃）" if feels is not None else "")
            + (f" / 湿度 {humidity}%" if humidity is not None else "")
            + (f" / 降水量 {precip}mm" if precip is not None else "")
            + (f" / 風速 {wind}m/s" if wind is not None else "")
        )

    daily = forecast.get("daily") or {}
    dates = daily.get("time") or []
    codes = daily.get("weather_code") or []
    tmax = daily.get("temperature_2m_max") or []
    tmin = daily.get("temperature_2m_min") or []
    pop = daily.get("precipitation_probability_max") or []
    if dates:
        lines.append("今後の予報:")
        for i, d in enumerate(dates):
            day_label = "今日" if i == 0 else ("明日" if i == 1 else d)
            code = codes[i] if i < len(codes) else None
            hi = tmax[i] if i < len(tmax) else "?"
            lo = tmin[i] if i < len(tmin) else "?"
            p = pop[i] if i < len(pop) else None
            line = f"  {day_label}（{d}）: {_weather_code_to_ja(code)} / 最高{hi}℃ 最低{lo}℃"
            if p is not None:
                line += f" / 降水確率{p}%"
            lines.append(line)

    lines.append("（出典: Open-Meteo）")
    return "\n".join(lines)


