# ====================================================================
# OpenRouter API（Mistralの後の追加フォールバック先）
# ====================================================================
# OpenRouterはOpenAI互換のchat completionsエンドポイントで、複数社のモデルを
# 単一のAPIキーで呼び分けられる。無料モデル（モデル名末尾に:freeが付くもの）を使えば
# 実質無料枠として利用できる（ただしOpenRouter全体で1日あたりのリクエスト数上限あり）。
# ====================================================================

class OpenRouterAPIError(RuntimeError):
    """OpenRouter API呼び出しに関する汎用エラー。"""
    pass


class OpenRouterRateLimitError(OpenRouterAPIError):
    """OpenRouter APIがレート制限（HTTP 429）を返した場合に送出される専用例外。"""
    def __init__(self, retry_after: Optional[float] = None, raw_message: str = ""):
        self.retry_after = retry_after
        self.raw_message = raw_message
        suffix = f"（推定復帰まで約{_format_duration(retry_after)}）" if retry_after else ""
        super().__init__(f"OpenRouter APIのレート制限に達しました{suffix}")


def _openrouter_headers() -> dict:
    return {
        "Authorization": f"Bearer {OPENROUTER_API_KEY}",
        "Content-Type": "application/json",
        # OpenRouterはこの2つのヘッダーを推奨している（無くても動作するが、
        # 統計・ランキングへの計上やダッシュボード表示のために付与しておく）。
        "HTTP-Referer": "https://github.com/",
        "X-Title": "MakuMaku BOT",
    }


async def _ai_chat_call_openrouter(messages: list, model: Optional[str] = None) -> str:
    """
    OpenRouter Chat Completions APIを呼び出し、応答テキストを返します。
    インターフェースは他プロバイダの呼び出し関数と揃えてあります。
    """
    if not OPENROUTER_API_KEY:
        raise RuntimeError("OPENROUTER_API_KEY が設定されていません。Botの環境変数を確認してください。")

    payload = {
        "model": model or OPENROUTER_MODEL,
        "messages": _inject_no_search_notice(messages),
        "temperature": 0.7,
        "max_tokens": OPENROUTER_MAX_TOKENS,
    }

    async with aiohttp.ClientSession() as session:
        async with session.post(
            "https://openrouter.ai/api/v1/chat/completions",
            headers=_openrouter_headers(),
            json=payload,
            timeout=aiohttp.ClientTimeout(total=30)
        ) as resp:
            if resp.status == 429:
                err_text = await resp.text()
                retry_after: Optional[float] = None
                header_val = resp.headers.get("Retry-After")
                if header_val:
                    try:
                        retry_after = float(header_val)
                    except ValueError:
                        retry_after = None
                if retry_after is None:
                    retry_after = _parse_groq_retry_after(err_text)
                raise OpenRouterRateLimitError(retry_after=retry_after, raw_message=err_text[:300])
            if resp.status != 200:
                err_text = await resp.text()
                if resp.status in (400, 404) and "model" in err_text.lower():
                    raise OpenRouterAPIError(
                        f"OpenRouter APIエラー（HTTP {resp.status}）: 指定されたモデル「{model or OPENROUTER_MODEL}」が"
                        f"見つからないか無効です。Botの環境変数 OPENROUTER_MODEL を、"
                        f"OpenRouter公式サイト（openrouter.ai/models）で現在利用可能なモデル名に"
                        f"更新してください。詳細: {err_text[:200]}"
                    )
                raise OpenRouterAPIError(f"OpenRouter APIエラー（HTTP {resp.status}）: {err_text[:300]}")
            data = await resp.json()

    try:
        choice = data["choices"][0]
        raw_content = choice["message"]["content"]
    except (KeyError, IndexError, TypeError):
        raise OpenRouterAPIError(f"OpenRouter APIの応答形式が想定と異なります: {data}")

    reply_text = _sanitize_ai_reply_content(raw_content)
    if choice.get("finish_reason") == "length":
        reply_text += "\n\n*（出力上限のため応答が途中で切れている可能性があります）*"

    return reply_text


async def _ai_chat_call_openrouter_with_search(
    messages: list,
    model: Optional[str] = None,
    guild_config: Optional[dict] = None
) -> str:
    """
    Web検索（Tool Use）に対応したOpenRouter呼び出し。_ai_chat_call_groq_with_search /
    _ai_chat_call_cerebras_with_search と同じロジックです
    （OpenRouterもOpenAI互換のtools形式に対応しているため）。
    どのWeb検索APIキーも未設定の場合は検索機能なしの通常呼び出しにフォールバックします。
    """
    if not WEB_SEARCH_AVAILABLE:
        return await _ai_chat_call_openrouter(messages, model=model)

    if not OPENROUTER_API_KEY:
        raise RuntimeError("OPENROUTER_API_KEY が設定されていません。Botの環境変数を確認してください。")

    working_messages = list(messages)  # 呼び出し元のリストは書き換えない
    max_search_rounds = 2

    _force_search_first_round = _query_likely_needs_search(_extract_latest_user_text(working_messages))

    for round_idx in range(max_search_rounds + 1):
        payload = {
            "model": model or OPENROUTER_MODEL,
            "messages": working_messages,
            "temperature": 0.7,
            "max_tokens": OPENROUTER_MAX_TOKENS,
        }
        if round_idx < max_search_rounds:
            payload["tools"] = [_WEB_SEARCH_TOOL_DEFINITION, _WEATHER_TOOL_DEFINITION]
            if round_idx == 0 and _force_search_first_round:
                payload["tool_choice"] = "required"
                print(f"[Web検索/OpenRouter] 時事系キーワードを検知したため、検索ツールの呼び出しを必須化します: {_extract_latest_user_text(working_messages)!r}")
            else:
                payload["tool_choice"] = "auto"

        async with aiohttp.ClientSession() as session:
            async with session.post(
                "https://openrouter.ai/api/v1/chat/completions",
                headers=_openrouter_headers(),
                json=payload,
                timeout=aiohttp.ClientTimeout(total=30)
            ) as resp:
                if resp.status == 429:
                    err_text = await resp.text()
                    retry_after: Optional[float] = None
                    header_val = resp.headers.get("Retry-After")
                    if header_val:
                        try:
                            retry_after = float(header_val)
                        except ValueError:
                            retry_after = None
                    if retry_after is None:
                        retry_after = _parse_groq_retry_after(err_text)
                    raise OpenRouterRateLimitError(retry_after=retry_after, raw_message=err_text[:300])
                if resp.status != 200:
                    err_text = await resp.text()
                    if resp.status in (400, 404) and "model" in err_text.lower():
                        raise OpenRouterAPIError(
                            f"OpenRouter APIエラー（HTTP {resp.status}）: 指定されたモデル「{model or OPENROUTER_MODEL}」が"
                            f"見つからないか無効です。詳細: {err_text[:200]}"
                        )
                    raise OpenRouterAPIError(f"OpenRouter APIエラー（HTTP {resp.status}）: {err_text[:300]}")
                data = await resp.json()

        try:
            choice = data["choices"][0]
            message_obj = choice["message"]
        except (KeyError, IndexError, TypeError):
            raise OpenRouterAPIError(f"OpenRouter APIの応答形式が想定と異なります: {data}")

        tool_calls = message_obj.get("tool_calls")
        if not tool_calls:
            if round_idx == 0 and _force_search_first_round:
                print("[Web検索/OpenRouter] tool_choice=requiredにも関わらず、モデルがweb_searchツールを呼び出しませんでした。")
            raw_content = message_obj.get("content") or ""

            has_leaked_prefix = _strip_leaked_tool_call_prefix(raw_content) != raw_content
            leaked_call = _try_parse_leaked_tool_call_json(raw_content)
            if leaked_call is None and has_leaked_prefix:
                leaked_call = _try_extract_query_from_leaked_prefix(raw_content)

            if leaked_call is not None and round_idx < max_search_rounds:
                query = str(leaked_call.get("query", "")).strip()
                print(f"[AIチャット/Web検索/OpenRouter] 本文へのJSON漏れを検知し、破棄して再検索します。クエリ: {query!r}")
                if query:
                    search_result_text = await _web_search_fallback(query, guild_config=guild_config)
                    _search_performed_var.set(True)
                else:
                    search_result_text = "（検索クエリが空だったため検索できませんでした。）"
                working_messages.append({
                    "role": "assistant",
                    "content": "（内部処理: Web検索を実行しました）"
                })
                working_messages.append({
                    "role": "user",
                    "content": (
                        f"（システム）先ほどの応答は無効になりました。改めて実際の検索結果を渡します:\n"
                        f"{search_result_text}\n\n"
                        "上記の実際の検索結果のみを根拠に、通常の文章で回答してください。"
                        "JSON形式では出力せず、検索結果に無い情報を付け加えないでください。"
                    )
                })
                continue

            if leaked_call is not None or has_leaked_prefix:
                return "（検索処理でエラーが発生したため、検索結果なしで回答できませんでした。質問を変えて再度お試しください。）"
            reply_text = _sanitize_ai_reply_content(raw_content)
            if choice.get("finish_reason") == "length":
                reply_text += "\n\n*（出力上限のため応答が途中で切れている可能性があります）*"
            return reply_text

        working_messages.append(message_obj)
        for tool_call in tool_calls:
            func = tool_call.get("function", {})
            func_name = func.get("name", "")
            try:
                func_args = json.loads(func.get("arguments") or "{}")
            except json.JSONDecodeError:
                func_args = {}

            if func_name == "web_search":
                query = str(func_args.get("query", "")).strip()
                if query:
                    print(f"[AIチャット/Web検索/OpenRouter] クエリ: {query}")
                    search_result_text = await _web_search_fallback(query, guild_config=guild_config)
                    _search_performed_var.set(True)
                else:
                    search_result_text = "（検索クエリが空だったため検索できませんでした。）"
            elif func_name == "get_weather":
                location = str(func_args.get("location", "")).strip()
                print(f"[AIチャット/天気] 地点: {location}")
                search_result_text = await _weather_lookup(location)
                _search_performed_var.set(True)

            else:
                search_result_text = f"（未対応のツール呼び出しです: {func_name}）"

            working_messages.append({
                "role": "tool",
                "tool_call_id": tool_call.get("id", ""),
                "content": search_result_text
            })

    return "（検索処理が複雑すぎたため、応答を生成できませんでした。質問を変えて再度お試しください。）"


# ====================================================================
# Google Gemini API（最終フォールバック先）
# ====================================================================
# GeminiはOpenAI互換ではなく専用のGenerative Language API（REST）を使うため、
# リクエスト/レスポンスの形式が他プロバイダと異なる。
# メッセージ形式の変換（system→systemInstruction、assistant→model等）と、
# 関数呼び出し（functionCall/functionResponse）の扱いだけ専用に実装し、
# 検索まわりのロジック（キーワード判定・JSON漏れ検知・_web_search_fallback呼び出し）は
# 他プロバイダと共通の関数をそのまま再利用する。
# ====================================================================

class GeminiAPIError(RuntimeError):
    """Gemini API呼び出しに関する汎用エラー。"""
    pass


class GeminiRateLimitError(GeminiAPIError):
    """Gemini APIがレート制限（HTTP 429）を返した場合に送出される専用例外。"""
    def __init__(self, retry_after: Optional[float] = None, raw_message: str = ""):
        self.retry_after = retry_after
        self.raw_message = raw_message
        suffix = f"（推定復帰まで約{_format_duration(retry_after)}）" if retry_after else ""
        super().__init__(f"Gemini APIのレート制限に達しました{suffix}")


# Gemini独自のfunction calling形式で使う、web_search関数の宣言
# （他プロバイダの _WEB_SEARCH_TOOL_DEFINITION と内容は同じだが、Geminiは
#  "functionDeclarations" というOpenAIとは異なるラップ構造を要求するため専用に定義する）
_GEMINI_WEB_SEARCH_FUNCTION_DECLARATION = {
    "name": "web_search",
    "description": "最新のニュース・出来事・情報など、学習データだけでは分からない時事的な内容を調べるためにWeb検索を実行します。",
    "parameters": {
        "type": "object",
        "properties": {
            "query": {
                "type": "string",
                "description": "検索したい内容を表す、具体的で簡潔な検索クエリ"
            }
        },
        "required": ["query"]
    }
}


def _convert_openai_messages_to_gemini(messages: list) -> Tuple[str, list]:
    """
    このBOT内で共通利用しているOpenAI形式のmessages配列
    （{"role": "system"|"user"|"assistant", "content": str} のリスト）を、
    Geminiの (systemInstructionテキスト, contents配列) 形式に変換します。

    - role "system" → systemInstruction用テキストとして連結
    - role "user" → Geminiの "user" ロール
    - role "assistant" → Geminiの "model" ロール
    - role "tool" 等（OpenAI形式のツール実行結果）は変換対象外
      （Gemini側のfunction calling往復は _ai_chat_call_gemini_with_search 内で
      Gemini独自の形式で別途組み立てるため、ここでは無視してよい）
    """
    system_parts = []
    contents = []
    for msg in messages:
        role = msg.get("role")
        content = msg.get("content")
        if not isinstance(content, str):
            content = "" if content is None else str(content)
        if role == "system":
            if content:
                system_parts.append(content)
        elif role == "user":
            if content:
                contents.append({"role": "user", "parts": [{"text": content}]})
        elif role == "assistant":
            if content:
                contents.append({"role": "model", "parts": [{"text": content}]})
        # "tool" 等はここでは無視する
    system_text = "\n\n".join(system_parts)
    return system_text, contents


def _extract_gemini_retry_after(err_text: str) -> Optional[float]:
    """
    Gemini APIのレート制限エラー応答（RetryInfo）から、再試行までの待機秒数を抽出します。
    例: "retryDelay": "23s" のような文字列を含む場合がある。
    """
    match = re.search(r'"retryDelay"\s*:\s*"(\d+(?:\.\d+)?)s"', err_text)
    if match:
        try:
            return float(match.group(1))
        except ValueError:
            return None
    return None


async def _ai_chat_call_gemini(messages: list, model: Optional[str] = None) -> str:
    """
    Google Gemini（Generative Language API）を呼び出し、応答テキストを返します。
    インターフェースは他プロバイダの呼び出し関数と揃えてあります。
    """
    if not GEMINI_API_KEY:
        raise RuntimeError("GEMINI_API_KEY が設定されていません。Botの環境変数を確認してください。")

    notice_messages = _inject_no_search_notice(messages)
    system_text, contents = _convert_openai_messages_to_gemini(notice_messages)
    if not contents:
        contents = [{"role": "user", "parts": [{"text": "（内容なし）"}]}]

    payload = {
        "contents": contents,
        "generationConfig": {"temperature": 0.7, "maxOutputTokens": GEMINI_MAX_TOKENS},
    }
    if system_text:
        payload["systemInstruction"] = {"parts": [{"text": system_text}]}

    gemini_model = model or GEMINI_MODEL
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{gemini_model}:generateContent?key={GEMINI_API_KEY}"

    async with aiohttp.ClientSession() as session:
        async with session.post(
            url, json=payload, timeout=aiohttp.ClientTimeout(total=30)
        ) as resp:
            if resp.status == 429:
                err_text = await resp.text()
                retry_after = _extract_gemini_retry_after(err_text)
                raise GeminiRateLimitError(retry_after=retry_after, raw_message=err_text[:300])
            if resp.status != 200:
                err_text = await resp.text()
                if resp.status == 404:
                    raise GeminiAPIError(
                        f"Gemini APIエラー（HTTP 404）: 指定されたモデル「{gemini_model}」が見つかりません。"
                        f"Botの環境変数 GEMINI_MODEL を、Google AI Studio（aistudio.google.com）で"
                        f"現在利用可能なモデル名（例: gemini-2.0-flash）に更新してください。詳細: {err_text[:200]}"
                    )
                raise GeminiAPIError(f"Gemini APIエラー（HTTP {resp.status}）: {err_text[:300]}")
            data = await resp.json()

    try:
        candidate = data["candidates"][0]
        parts = candidate.get("content", {}).get("parts", [])
        raw_content = "".join(p.get("text", "") for p in parts)
    except (KeyError, IndexError, TypeError):
        raise GeminiAPIError(f"Gemini APIの応答形式が想定と異なります: {data}")

    if not raw_content and candidate.get("finishReason") == "SAFETY":
        raise GeminiAPIError("Gemini APIがセーフティフィルターにより応答をブロックしました。")

    reply_text = _sanitize_ai_reply_content(raw_content)
    if candidate.get("finishReason") == "MAX_TOKENS":
        reply_text += "\n\n*（出力上限のため応答が途中で切れている可能性があります）*"

    return reply_text


async def _ai_chat_call_gemini_with_search(
    messages: list,
    model: Optional[str] = None,
    guild_config: Optional[dict] = None
) -> str:
    """
    Web検索（function calling）に対応したGemini呼び出し。
    ロジックの流れ（時事キーワード検知→1回目は強制的にツールを呼ばせる／
    tool_callsが無ければJSON漏れを疑う／検索結果を積んで再度応答生成させる）は
    Groq/Cerebras/OpenRouter版と同じですが、リクエスト/レスポンスの形式が
    Gemini独自のため専用に実装しています。
    """
    if not WEB_SEARCH_AVAILABLE:
        return await _ai_chat_call_gemini(messages, model=model)

    if not GEMINI_API_KEY:
        raise RuntimeError("GEMINI_API_KEY が設定されていません。Botの環境変数を確認してください。")

    system_text, contents = _convert_openai_messages_to_gemini(messages)
    if not contents:
        contents = [{"role": "user", "parts": [{"text": "（内容なし）"}]}]

    gemini_model = model or GEMINI_MODEL
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{gemini_model}:generateContent?key={GEMINI_API_KEY}"

    _force_search_first_round = _query_likely_needs_search(_extract_latest_user_text(messages))
    max_search_rounds = 2

    for round_idx in range(max_search_rounds + 1):
        payload = {
            "contents": contents,
            "generationConfig": {"temperature": 0.7, "maxOutputTokens": GEMINI_MAX_TOKENS},
        }
        if system_text:
            payload["systemInstruction"] = {"parts": [{"text": system_text}]}
        if round_idx < max_search_rounds:
            payload["tools"] = [{"functionDeclarations": [_GEMINI_WEB_SEARCH_FUNCTION_DECLARATION, _GEMINI_WEATHER_FUNCTION_DECLARATION]}]
            if round_idx == 0 and _force_search_first_round:
                payload["toolConfig"] = {
                    "functionCallingConfig": {"mode": "ANY", "allowedFunctionNames": ["web_search"]}
                }
                print(f"[Web検索/Gemini] 時事系キーワードを検知したため、検索ツールの呼び出しを必須化します: {_extract_latest_user_text(messages)!r}")
            else:
                payload["toolConfig"] = {"functionCallingConfig": {"mode": "AUTO"}}

        async with aiohttp.ClientSession() as session:
            async with session.post(
                url, json=payload, timeout=aiohttp.ClientTimeout(total=30)
            ) as resp:
                if resp.status == 429:
                    err_text = await resp.text()
                    retry_after = _extract_gemini_retry_after(err_text)
                    raise GeminiRateLimitError(retry_after=retry_after, raw_message=err_text[:300])
                if resp.status != 200:
                    err_text = await resp.text()
                    if resp.status == 404:
                        raise GeminiAPIError(
                            f"Gemini APIエラー（HTTP 404）: 指定されたモデル「{gemini_model}」が見つかりません。詳細: {err_text[:200]}"
                        )
                    raise GeminiAPIError(f"Gemini APIエラー（HTTP {resp.status}）: {err_text[:300]}")
                data = await resp.json()

        try:
            candidate = data["candidates"][0]
            parts = candidate.get("content", {}).get("parts", [])
        except (KeyError, IndexError, TypeError):
            raise GeminiAPIError(f"Gemini APIの応答形式が想定と異なります: {data}")

        function_call_part = next((p for p in parts if isinstance(p, dict) and "functionCall" in p), None)

        if function_call_part is None:
            if round_idx == 0 and _force_search_first_round:
                print("[Web検索/Gemini] toolConfig=ANYにも関わらず、Geminiモデルがweb_searchツールを呼び出しませんでした。")
            raw_content = "".join(p.get("text", "") for p in parts)

            has_leaked_prefix = _strip_leaked_tool_call_prefix(raw_content) != raw_content
            leaked_call = _try_parse_leaked_tool_call_json(raw_content)
            if leaked_call is None and has_leaked_prefix:
                leaked_call = _try_extract_query_from_leaked_prefix(raw_content)

            if leaked_call is not None and round_idx < max_search_rounds:
                query = str(leaked_call.get("query", "")).strip()
                print(f"[AIチャット/Web検索/Gemini] 本文へのJSON漏れを検知し、破棄して再検索します。クエリ: {query!r}")
                if query:
                    search_result_text = await _web_search_fallback(query, guild_config=guild_config)
                    _search_performed_var.set(True)
                else:
                    search_result_text = "（検索クエリが空だったため検索できませんでした。）"
                contents.append({"role": "model", "parts": [{"text": "（内部処理: Web検索を実行しました）"}]})
                contents.append({"role": "user", "parts": [{"text": (
                    f"（システム）先ほどの応答は無効になりました。改めて実際の検索結果を渡します:\n"
                    f"{search_result_text}\n\n"
                    "上記の実際の検索結果のみを根拠に、通常の文章で回答してください。"
                    "JSON形式では出力せず、検索結果に無い情報を付け加えないでください。"
                )}]})
                continue

            if leaked_call is not None or has_leaked_prefix:
                return "（検索処理でエラーが発生したため、検索結果なしで回答できませんでした。質問を変えて再度お試しください。）"

            if not raw_content and candidate.get("finishReason") == "SAFETY":
                raise GeminiAPIError("Gemini APIがセーフティフィルターにより応答をブロックしました。")

            reply_text = _sanitize_ai_reply_content(raw_content)
            if candidate.get("finishReason") == "MAX_TOKENS":
                reply_text += "\n\n*（出力上限のため応答が途中で切れている可能性があります）*"
            return reply_text

        func_call = function_call_part["functionCall"]
        func_name = func_call.get("name", "")
        func_args = func_call.get("args") or {}

        contents.append({"role": "model", "parts": [{"functionCall": func_call}]})

        if func_name == "web_search":
            query = str(func_args.get("query", "")).strip()
            if query:
                print(f"[AIチャット/Web検索/Gemini] クエリ: {query}")
                search_result_text = await _web_search_fallback(query, guild_config=guild_config)
                _search_performed_var.set(True)
            else:
                search_result_text = "（検索クエリが空だったため検索できませんでした。）"
        elif func_name == "get_weather":
            location = str(func_args.get("location", "")).strip()
            print(f"[AIチャット/天気] 地点: {location}")
            search_result_text = await _weather_lookup(location)
            _search_performed_var.set(True)

        else:
            search_result_text = f"（未対応のツール呼び出しです: {func_name}）"

        contents.append({
            "role": "function",
            "parts": [{
                "functionResponse": {
                    "name": func_name,
                    "response": {"content": search_result_text}
                }
            }]
        })

    return "（検索処理が複雑すぎたため、応答を生成できませんでした。質問を変えて再度お試しください。）"


async def _ai_get_provider_override(guild_id: Optional[int]) -> Optional[str]:
    """
    guild_configに保存されたai_provider設定を読み込みます。
    "auto"（既定）の場合はNoneを返し、_ai_call_llm_with_fallback側の自動フォールバック動作に委ねます。
    guild_idがNone、または設定読み込みに失敗した場合もNone（=auto扱い）を返します。
    """
    if guild_id is None:
        return None
    try:
        all_data = load_data()
        guild_config = get_guild_config(all_data, str(guild_id))
        provider = guild_config.get("ai_provider", "auto")
        if provider in ("groq", "cerebras", "mistral", "openrouter", "gemini"):
            return provider
        return None
    except Exception as e:
        print(f"[AIプロバイダ設定] 読み込みに失敗しました（autoとして扱います）: {e}")
        return None


async def _ai_call_llm_with_fallback(
    messages: list,
    model: Optional[str] = None,
    provider_override: Optional[str] = None,
    enable_search: bool = False,
    guild_config: Optional[dict] = None,
) -> Tuple[str, str]:
    """
    Groq（メインモデル → GROQ_FALLBACK_MODELS）を順に試し、
    すべて日次上限（TPD/RPD）で失敗した場合はCerebrasを、Cerebrasも失敗した場合はMistralを、
    Mistralも失敗した場合はOpenRouterを、それも失敗した場合は最後にGeminiを試す統一ラッパーです。
    Groqの一時的なレート制限（TPM/RPM）や、日次上限以外のエラーはフォールバックせず
    そのまま例外を送出します（TPMは短時間で回復するため、プロバイダを跨ぐ必要が薄いため）。

    enable_search: True の場合、全プロバイダ（Groq/Cerebras/Mistral/OpenRouter/Gemini）
    でWeb検索（既定: Tavily→Exa→Firecrawl→NewsData.ioの優先順位で自動フォールバック。guild_configで
    サーバーごとにON/OFF・優先順位をカスタム設定可能）機能を持たせます
    （どのAPIキーも未設定の場合、またはそのサーバーで検索が無効化されている場合は
    自動的に検索なし呼び出しにフォールバックします）。

    guild_config: そのサーバーの設定辞書。ai_chat_web_search_enabled（bool）で
    Web検索の有効/無効を、ai_chat_search_provider_order（リスト）で検索プロバイダの
    優先順位をサーバーごとに上書きできる。Noneの場合はコード既定の動作（検索有効・既定順）。

    provider_override:
      - "groq": Groqのみ使用（フォールバックモデルは試すが、他プロバイダへは切り替えない）
      - "cerebras": Cerebrasのみ使用
      - "mistral": Mistralのみ使用
      - "openrouter": OpenRouterのみ使用
      - "gemini": Geminiのみ使用
      - None（既定）: 従来通りの自動フォールバック（Groq→Cerebras→Mistral→OpenRouter→Gemini）

    戻り値: (応答テキスト, 実際に使用したプロバイダ名"groq"|"cerebras"|"mistral"|"openrouter"|"gemini")
    """
    if provider_override == "cerebras":
        if not CEREBRAS_API_KEY:
            raise RuntimeError(
                "このサーバーはAIプロバイダが「Cerebras固定」に設定されていますが、"
                "CEREBRAS_API_KEYが未設定のため利用できません。/ai_chat set_provider で変更するか、"
                "Botの環境変数を確認してください。"
            )
        search_enabled_for_guild = (guild_config or {}).get("ai_chat_web_search_enabled", True)
        if enable_search and search_enabled_for_guild:
            reply_text = await _ai_chat_call_cerebras_with_search(messages, model=model, guild_config=guild_config)
        else:
            reply_text = await _ai_chat_call_cerebras(messages, model=model)
        return reply_text, "cerebras"

    if provider_override == "mistral":
        if not MISTRAL_API_KEY:
            raise RuntimeError(
                "このサーバーはAIプロバイダが「Mistral固定」に設定されていますが、"
                "MISTRAL_API_KEYが未設定のため利用できません。/ai_chat set_provider で変更するか、"
                "Botの環境変数を確認してください。"
            )
        search_enabled_for_guild = (guild_config or {}).get("ai_chat_web_search_enabled", True)
        if enable_search and search_enabled_for_guild:
            reply_text = await _ai_chat_call_mistral_with_search(messages, model=model, guild_config=guild_config)
        else:
            reply_text = await _ai_chat_call_mistral(messages, model=model)
        return reply_text, "mistral"

    if provider_override == "openrouter":
        if not OPENROUTER_API_KEY:
            raise RuntimeError(
                "このサーバーはAIプロバイダが「OpenRouter固定」に設定されていますが、"
                "OPENROUTER_API_KEYが未設定のため利用できません。/ai_chat set_provider で変更するか、"
                "Botの環境変数を確認してください。"
            )
        search_enabled_for_guild = (guild_config or {}).get("ai_chat_web_search_enabled", True)
        if enable_search and search_enabled_for_guild:
            reply_text = await _ai_chat_call_openrouter_with_search(messages, model=model, guild_config=guild_config)
        else:
            reply_text = await _ai_chat_call_openrouter(messages, model=model)
        return reply_text, "openrouter"

    if provider_override == "gemini":
        if not GEMINI_API_KEY:
            raise RuntimeError(
                "このサーバーはAIプロバイダが「Gemini固定」に設定されていますが、"
                "GEMINI_API_KEYが未設定のため利用できません。/ai_chat set_provider で変更するか、"
                "Botの環境変数を確認してください。"
            )
        search_enabled_for_guild = (guild_config or {}).get("ai_chat_web_search_enabled", True)
        if enable_search and search_enabled_for_guild:
            reply_text = await _ai_chat_call_gemini_with_search(messages, model=model, guild_config=guild_config)
        else:
            reply_text = await _ai_chat_call_gemini(messages, model=model)
        return reply_text, "gemini"

    candidate_models = [model] + GROQ_FALLBACK_MODELS

    # サーバーごとの検索ON/OFF設定を反映（未設定なら既定でTrue=有効）
    search_enabled_for_guild = (guild_config or {}).get("ai_chat_web_search_enabled", True)
    effective_enable_search = enable_search and search_enabled_for_guild

    last_error: Optional[Exception] = None
    for idx, candidate in enumerate(candidate_models):
        try:
            if effective_enable_search and idx == 0:
                reply_text = await _ai_chat_call_groq_with_search(messages, model=candidate, guild_config=guild_config)
            else:
                reply_text = await _ai_chat_call_groq(messages, model=candidate)
            return reply_text, "groq"
        except GroqRateLimitError as e:
            last_error = e
            is_daily_limit = e.limit_scope in ("TPD", "RPD")
            is_last_candidate = (idx == len(candidate_models) - 1)
            if not is_daily_limit:
                raise  # TPM等の短期レート制限はプロバイダを跨がず即座に通知する
            if idx == 0 and effective_enable_search:
                # 検索対応の主モデルが日次上限に達し、以降はGroqの検索非対応フォールバックモデル
                # （設定されていれば）、それも尽きればCerebras（検索対応版）に切り替わる。
                print(
                    f"[Web検索] 主モデル（{candidate}）が本日の利用上限（{e.limit_scope}）に達したため、"
                    "別プロバイダにフォールバックします（Cerebrasが設定済みなら検索は引き続き利用可能です）。"
                )
            if not is_last_candidate:
                continue  # 次のGroqフォールバックモデルを試す
            # Groq側の候補をすべてTPD/RPDで使い切った → Cerebrasへ最終フォールバック
            break

    if provider_override == "groq":
        # Groq固定設定の場合はCerebras/Mistralへ切り替えず、Groqのエラーをそのまま送出する
        raise last_error

    if CEREBRAS_API_KEY:
        try:
            if effective_enable_search:
                reply_text = await _ai_chat_call_cerebras_with_search(messages, guild_config=guild_config)
            else:
                reply_text = await _ai_chat_call_cerebras(messages)
            return reply_text, "cerebras"
        except Exception as e:
            print(f"[AIフォールバック] Cerebrasへの切り替えにも失敗しました: {e}")
            last_error = e

    if not MISTRAL_API_KEY:
        # Mistral未設定なら、そのままOpenRouterを試す（最終的にlast_errorは下のOpenRouter/Gemini節で処理）
        pass
    else:
        try:
            if effective_enable_search:
                reply_text = await _ai_chat_call_mistral_with_search(messages, guild_config=guild_config)
            else:
                reply_text = await _ai_chat_call_mistral(messages)
            return reply_text, "mistral"
        except Exception as e:
            print(f"[AIフォールバック] Mistralへの切り替えにも失敗しました: {e}")
            last_error = e

    if OPENROUTER_API_KEY:
        try:
            if effective_enable_search:
                reply_text = await _ai_chat_call_openrouter_with_search(messages, guild_config=guild_config)
            else:
                reply_text = await _ai_chat_call_openrouter(messages)
            return reply_text, "openrouter"
        except Exception as e:
            print(f"[AIフォールバック] OpenRouterへの切り替えにも失敗しました: {e}")
            last_error = e

    if not GEMINI_API_KEY:
        # Gemini未設定なら、ここまでの最後のエラーをそのまま送出する
        raise last_error

    try:
        if effective_enable_search:
            reply_text = await _ai_chat_call_gemini_with_search(messages, guild_config=guild_config)
        else:
            reply_text = await _ai_chat_call_gemini(messages)
        return reply_text, "gemini"
    except Exception as e:
        print(f"[AIフォールバック] Geminiへの切り替えにも失敗しました: {e}")
        raise last_error from e


# ====================================================================
# サーバー活動のAIサマリー機能
# ====================================================================

AI_SUMMARY_PERIOD_DAYS = 7           # サマリー対象期間（固定7日間）
AI_SUMMARY_MAX_MESSAGES_PER_CHANNEL = 300  # 1チャンネルあたり収集する最大メッセージ数（負荷制御）
AI_SUMMARY_MAX_TOTAL_SAMPLE_CHARS = 12000  # AIに渡す発言サンプルの合計文字数上限（トークン節約）

_AI_SUMMARY_SYSTEM_PROMPT = (
    "あなたはDiscordサーバーの活動を分析するアシスタントです。"
    "これから提示されるチャンネルごとの発言サンプルと統計情報をもとに、"
    "過去1週間のサーバー活動を日本語で要約してください。\n"
    "以下の構成でまとめてください（Discordのメッセージとして自然な長さ、見出しは太字で）:\n"
    "・**全体の傾向**: サーバー全体としてどんな1週間だったか（2〜3文程度）\n"
    "・**よく話題になったこと**: 主なトピックを箇条書きで3〜5個\n"
    "・**活発だったチャンネル**: 統計情報を参考に、特に活発だったチャンネルとその理由を簡潔に\n"
    "個人を過度に特定するような書き方は避け、全体の雰囲気や傾向を伝えることを重視してください。"
)


async def _ai_summary_collect_guild_activity(guild: discord.Guild) -> dict:
    """
    サーバー内の全テキストチャンネルから過去7日分のメッセージを収集し、
    チャンネルごとの統計情報と、AIに渡すための発言サンプルテキストを構築します。
    Botが読み取り権限を持たないチャンネルはスキップします。
    """
    since = datetime.datetime.now(datetime.timezone.utc) - datetime.timedelta(days=AI_SUMMARY_PERIOD_DAYS)

    channel_stats = []  # [{"name": str, "message_count": int, "unique_authors": int}]
    sample_lines = []   # AIに渡す発言サンプル（チャンネル名付き、Bot発言は除外）
    total_messages = 0
    total_sample_chars = 0

    for channel in guild.text_channels:
        perms = channel.permissions_for(guild.me)
        if not (perms.read_messages and perms.read_message_history):
            continue

        message_count = 0
        authors = set()
        channel_samples = []

        try:
            async for msg in channel.history(limit=AI_SUMMARY_MAX_MESSAGES_PER_CHANNEL, after=since, oldest_first=False):
                if msg.author.bot:
                    continue
                message_count += 1
                authors.add(msg.author.id)
                text = msg.content.strip()
                if text and len(channel_samples) < 15:
                    # 長すぎる発言は切り詰めてサンプルに含める
                    channel_samples.append(text[:200])
        except discord.Forbidden:
            continue
        except Exception as e:
            print(f"[AIサマリー] チャンネル {channel.name} の履歴取得に失敗: {e}")
            continue

        if message_count == 0:
            continue

        channel_stats.append({
            "name": channel.name,
            "message_count": message_count,
            "unique_authors": len(authors),
        })
        total_messages += message_count

        if channel_samples and total_sample_chars < AI_SUMMARY_MAX_TOTAL_SAMPLE_CHARS:
            block = f"# #{channel.name}（発言{message_count}件, 発言者{len(authors)}人）\n"
            block += "\n".join(f"- {s}" for s in channel_samples[:8])
            if total_sample_chars + len(block) <= AI_SUMMARY_MAX_TOTAL_SAMPLE_CHARS:
                sample_lines.append(block)
                total_sample_chars += len(block)

    channel_stats.sort(key=lambda c: c["message_count"], reverse=True)

    return {
        "channel_stats": channel_stats,
        "sample_text": "\n\n".join(sample_lines),
        "total_messages": total_messages,
        "period_days": AI_SUMMARY_PERIOD_DAYS,
    }


async def _ai_summary_generate(guild: discord.Guild) -> Tuple[Optional[str], dict]:
    """
    サーバー活動を収集し、Groqで自然文サマリーを生成します。
    戻り値: (サマリー本文 or None, 収集した統計情報dict)
    活動が無い、またはGROQ_API_KEY未設定の場合は summary=None を返します。
    """
    activity = await _ai_summary_collect_guild_activity(guild)

    if not GROQ_API_KEY:
        return None, activity

    if activity["total_messages"] == 0:
        return None, activity

    stats_text = "\n".join(
        f"- #{c['name']}: {c['message_count']}件（発言者{c['unique_authors']}人）"
        for c in activity["channel_stats"][:15]
    )

    user_prompt = (
        f"【集計期間】過去{activity['period_days']}日間\n"
        f"【総発言数】{activity['total_messages']}件\n\n"
        f"【チャンネル別統計（発言数上位）】\n{stats_text}\n\n"
        f"【発言サンプル】\n{activity['sample_text'] or '（サンプルなし）'}"
    )

    messages = [
        {"role": "system", "content": _AI_SUMMARY_SYSTEM_PROMPT},
        {"role": "user", "content": user_prompt},
    ]

    try:
        provider_override = await _ai_get_provider_override(guild.id)
        summary_text, _provider = await _ai_call_llm_with_fallback(messages, provider_override=provider_override)
    except Exception as e:
        print(f"[AIサマリー] LLM呼び出しに失敗: {e}")
        return None, activity

    return summary_text, activity


def _ai_summary_build_embed(guild: discord.Guild, summary_text: str, activity: dict) -> discord.Embed:
    """サマリー結果をEmbedに整形します。"""
    embed = discord.Embed(
        title=f"[サーバー活動レポート] 過去{activity['period_days']}日間",
        description=summary_text[:4000],
        color=discord.Color.blue(),
        timestamp=datetime.datetime.now(datetime.timezone.utc)
    )
    embed.add_field(name="総発言数", value=f"{activity['total_messages']}件", inline=True)
    top_channels = activity["channel_stats"][:3]
    if top_channels:
        top_text = "\n".join(f"#{c['name']}（{c['message_count']}件）" for c in top_channels)
        embed.add_field(name="活発だったチャンネル（上位）", value=top_text, inline=True)
    embed.set_footer(text=f"{guild.name} のサーバー活動AIサマリー")
    return embed


_ai_summary_loop_task: Optional[asyncio.Task] = None


async def _ai_summary_scheduler_loop():
    """
    全ギルドを対象に、1時間ごとに「定期自動実行の条件を満たしたギルドがないか」をチェックし、
    条件を満たしていればサマリーを生成して投稿します。
    条件: ai_summary_enabled=True かつ 現在のUTC曜日・時刻が設定と一致 かつ 本日まだ未実行。
    """
    await bot.wait_until_ready()
    while True:
        try:
            now = datetime.datetime.now(datetime.timezone.utc)
            today_str = now.strftime("%Y-%m-%d")
            all_data = load_data()
            data_changed = False

            for guild_id_str, guild_config in list(all_data.items()):
                if not isinstance(guild_config, dict):
                    continue
                if not guild_config.get("ai_summary_enabled", False):
                    continue
                if guild_config.get("ai_summary_weekday", 0) != now.weekday():
                    continue
                if guild_config.get("ai_summary_hour", 9) != now.hour:
                    continue
                if guild_config.get("ai_summary_last_run") == today_str:
                    continue  # 本日分は実行済み

                channel_id = guild_config.get("ai_summary_channel_id")
                if not channel_id:
                    continue

                try:
                    guild_id_int = int(guild_id_str)
                except (TypeError, ValueError):
                    continue

                guild = bot.get_guild(guild_id_int)
                if guild is None:
                    continue
                channel = guild.get_channel(channel_id)
                if not isinstance(channel, discord.TextChannel):
                    continue

                try:
                    summary_text, activity = await _ai_summary_generate(guild)
                    if summary_text is not None:
                        embed = _ai_summary_build_embed(guild, summary_text, activity)
                        await channel.send(embed=embed)
                except Exception as e:
                    print(f"[AIサマリー自動実行] {guild.name} でエラー: {e}")
                finally:
                    # 成否に関わらず「本日は試行済み」として記録し、同日中の再試行ループを防ぐ
                    guild_config["ai_summary_last_run"] = today_str
                    data_changed = True

            if data_changed:
                save_data(all_data)

        except Exception as e:
            print(f"[AIサマリースケジューラ] ループ内エラー: {e}")

        await asyncio.sleep(3600)  # 1時間ごとにチェック


# ====================================================================
# AIディベート機能（2人格によるAI同士の自動会話・Groq API）
# ====================================================================
# ・オーナーが /ai_debate start で2つの人格（システムプロンプト）とお題を指定すると、
#   指定チャンネルでAI同士が交互に発言を続けます。
# ・/ai_debate random start では、お題・2人格（名前+プロンプト）をGroq自身に
#   都度ランダム生成させてから開始します（実行のたびに完全に新しい内容）。
# ・停止するまで無限に続くため、暴走防止として以下の制御を入れています：
#     1. 発言間隔（既定10秒、変更可）を必ず空けてから次の発言を生成する
#     2. 1チャンネルにつき同時に1つのディベートのみ実行可（二重起動防止）
#     3. 最大ターン数は既定で無制限（stopするまで継続）。指定する場合も上限は設けない
#     4. Groqのレート制限エラーを検知した場合は自動で一時停止し、通知する
# ・会話履歴はメモリ上のみで保持し、直近の往復数のみ渡してトークン消費を抑えます
#   （プロセス再起動やBot再起動でディベートは自動停止します＝再開はオーナーが再実行）
# ====================================================================

AI_DEBATE_HISTORY_MAX_TURNS = 12          # Groqに渡す直近の発言数（多すぎるとトークンを圧迫するため制限）
AI_DEBATE_DEFAULT_INTERVAL_SECONDS = 10   # 発言間隔の既定値
AI_DEBATE_MIN_INTERVAL_SECONDS = 5        # 発言間隔の最小値（連投防止のための下限）
AI_DEBATE_MAX_INTERVAL_SECONDS = 600      # 発言間隔の最大値
AI_DEBATE_MAX_MESSAGE_LENGTH = 800        # 1発言あたりの最大文字数（Discord表示・トークン節約のため）

_AI_DEBATE_RANDOM_GEN_SYSTEM_PROMPT = (
    "あなたはDiscord上で行う「AI同士の自動ディベート（会話）」の設定を考えるアシスタントです。"
    "毎回まったく新しく、ユニークで面白いお題と、性格が対照的な2人のキャラクター設定を考えてください。\n"
    "・お題は雑談、討論、ロールプレイ、コント等、幅広いジャンルから自由に発想してください。\n"
    "・2人のキャラクターは名前・口調・性格が明確に異なるようにしてください。\n"
    "・過激な性的表現、暴力的表現、差別的表現は避けてください。\n\n"
    "必ず次のJSON形式のみで出力してください。説明文やコードブロックは不要です。\n"
    '{"topic": "お題（80文字以内）", '
    '"persona_a_name": "1人目の名前（20文字以内）", "persona_a_prompt": "1人目の人格・口調の指示（150文字以内）", '
    '"persona_b_name": "2人目の名前（20文字以内）", "persona_b_prompt": "2人目の人格・口調の指示（150文字以内）"}'
)

# {channel_id: {"task": asyncio.Task, ...state...}}
_ai_debate_sessions: dict = {}


async def _ai_debate_generate_random_setup(guild_id: Optional[int] = None) -> dict:
    """
    Groqに「面白いお題と対照的な2人格」をJSON形式で生成させます。
    戻り値: {"topic": str, "persona_a_name": str, "persona_a_prompt": str,
             "persona_b_name": str, "persona_b_prompt": str}
    生成・解析に失敗した場合は GroqAPIError または ValueError を送出します。
    """
    messages = [
        {"role": "system", "content": _AI_DEBATE_RANDOM_GEN_SYSTEM_PROMPT},
        {"role": "user", "content": "新しいお題と2人格を考えてください。"},
    ]
    provider_override = await _ai_get_provider_override(guild_id)
    raw, _provider = await _ai_call_llm_with_fallback(messages, provider_override=provider_override)

    cleaned = raw.strip()
    if cleaned.startswith("```"):
        cleaned = re.sub(r"^```(?:json)?\s*|\s*```$", "", cleaned, flags=re.IGNORECASE | re.DOTALL).strip()

    try:
        parsed = json.loads(cleaned)
    except json.JSONDecodeError as e:
        raise ValueError(f"ランダム設定の生成結果を解析できませんでした: {e}")

    required_keys = ("topic", "persona_a_name", "persona_a_prompt", "persona_b_name", "persona_b_prompt")
    if not all(k in parsed and str(parsed[k]).strip() for k in required_keys):
        raise ValueError("ランダム設定の生成結果に必要な項目が不足しています。")

    return {
        "topic": str(parsed["topic"]).strip()[:200],
        "persona_a_name": str(parsed["persona_a_name"]).strip()[:80],
        "persona_a_prompt": str(parsed["persona_a_prompt"]).strip()[:400],
        "persona_b_name": str(parsed["persona_b_name"]).strip()[:80],
        "persona_b_prompt": str(parsed["persona_b_prompt"]).strip()[:400],
    }


def _ai_debate_build_system_prompt(persona_name: str, persona_prompt: str, opponent_name: str, topic: str) -> str:
    """ディベート参加者（AI人格）用のシステムプロンプトを構築します。"""
    base = (
        f"あなたはDiscord上でのAI同士の会話に参加しているキャラクター「{persona_name}」です。"
        f"会話相手は「{opponent_name}」という別のAIです。"
        f"以下の人格設定に従って発言してください:\n{persona_prompt}\n\n"
        f"会話のお題・状況: {topic}\n\n"
        "ルール:\n"
        "・日本語で、Discordのメッセージとして自然な長さ（2〜4文程度）で発言してください。\n"
        "・自分の発言だけを出力し、相手のセリフや地の文（ナレーション）は書かないでください。\n"
        "・会話が停滞しないよう、相手の発言を踏まえて話を展開・深掘りしてください。\n"
        f"・「{persona_name}:」のような名前の接頭辞は付けず、セリフ本文のみを出力してください。"
    )
    return base


async def _ai_debate_generate_turn(session: dict, speaker_key: str) -> str:
    """
    指定した話者（speaker_key: "a" または "b"）の次の発言をGroqで生成します。
    session["history"] は {"speaker": "a"|"b", "content": str} のリストで、
    話者から見て自分の発言はassistant、相手の発言はuserとして組み立てます。
    """
    persona = session["personas"][speaker_key]
    opponent_key = "b" if speaker_key == "a" else "a"
    opponent_persona = session["personas"][opponent_key]

    system_prompt = _ai_chat_finalize_system_prompt(
        _ai_debate_build_system_prompt(
            persona["name"], persona["prompt"], opponent_persona["name"], session["topic"]
        ),
        include_search_guide=False
    )

    messages = [{"role": "system", "content": system_prompt}]
    recent_history = session["history"][-AI_DEBATE_HISTORY_MAX_TURNS:]
    for turn in recent_history:
        role = "assistant" if turn["speaker"] == speaker_key else "user"
        messages.append({"role": role, "content": turn["content"]})

    if not recent_history:
        # 最初の発言者には、お題から会話を始めるよう明示的に促す
        messages.append({"role": "user", "content": "それでは、このお題について話を始めてください。"})

    provider_override = await _ai_get_provider_override(session.get("guild_id"))
    reply_text, _provider = await _ai_call_llm_with_fallback(
        messages, model=session.get("model") or None, provider_override=provider_override
    )
    reply_text = reply_text.strip()
    if len(reply_text) > AI_DEBATE_MAX_MESSAGE_LENGTH:
        reply_text = reply_text[:AI_DEBATE_MAX_MESSAGE_LENGTH] + "…"
    return reply_text or "（応答の生成に失敗しました）"


async def _ai_debate_loop(channel_id: int):
    """
    指定チャンネルでAI同士の会話を無限に継続するバックグラウンドタスクです。
    _ai_debate_sessions から自身のセッション情報を都度取得し、
    stopフラグが立つかタスクがキャンセルされるまでターンを繰り返します。
    """
    session = _ai_debate_sessions.get(channel_id)
    if session is None:
        return

    channel = session["channel"]
    current_speaker = "a"  # 「a」から会話を開始する

    try:
        while True:
            session = _ai_debate_sessions.get(channel_id)
            if session is None or session.get("stopped"):
                return

            try:
                async with channel.typing():
                    reply_text = await _ai_debate_generate_turn(session, current_speaker)
            except GroqRateLimitError as e:
                wait_hint = f"（あと約{_format_duration(e.retry_after)}ほどで復帰する見込みです）" if e.retry_after else ""
                try:
                    await channel.send(
                        f"[AIディベート] APIのレート制限に達したため、ディベートを自動停止しました。{wait_hint}\n"
                        "しばらく時間をおいてから `/ai_debate start` で再開してください。"
                    )
                except discord.HTTPException:
                    pass
                _ai_debate_sessions.pop(channel_id, None)
                return
            except Exception:
                try:
                    await channel.send("[AIディベート] 発言生成中にエラーが発生したため停止しました。しばらく時間をおいて再度お試しください。")
                except discord.HTTPException:
                    pass
                _ai_debate_sessions.pop(channel_id, None)
                return

            session = _ai_debate_sessions.get(channel_id)
            if session is None or session.get("stopped"):
                return

            persona = session["personas"][current_speaker]
            session["history"].append({"speaker": current_speaker, "content": reply_text})
            session["turn_count"] += 1

            embed = discord.Embed(
                description=reply_text,
                color=discord.Color.blue() if current_speaker == "a" else discord.Color.orange()
            )
            embed.set_author(name=persona["name"])
            embed.set_footer(text=f"ターン {session['turn_count']} / AIディベート")

            try:
                await channel.send(embed=embed)
            except discord.Forbidden:
                _ai_debate_sessions.pop(channel_id, None)
                return
            except discord.HTTPException:
                pass

            # 上限ターン数が設定されていれば、到達時点で自動終了する（未設定＝無制限）
            max_turns = session.get("max_turns")
            if max_turns and session["turn_count"] >= max_turns:
                try:
                    await channel.send(f"[AIディベート] 設定されたターン数（{max_turns}）に達したため終了しました。")
                except discord.HTTPException:
                    pass
                _ai_debate_sessions.pop(channel_id, None)
                return

            current_speaker = "b" if current_speaker == "a" else "a"
            await asyncio.sleep(session.get("interval_seconds", AI_DEBATE_DEFAULT_INTERVAL_SECONDS))

    except asyncio.CancelledError:
        # /ai_debate stop によるキャンセル。静かに終了する。
        raise
    finally:
        _ai_debate_sessions.pop(channel_id, None)


async def _ai_debate_launch(
    interaction: discord.Interaction,
    *,
    topic: str,
    persona_a_name: str,
    persona_a_prompt: str,
    persona_b_name: str,
    persona_b_prompt: str,
    interval_seconds: int,
    max_turns: Optional[int],
    model: Optional[str],
    is_random: bool,
):
    """
    /ai_debate start と /ai_debate random start の共通処理。
    事前チェック（権限・チャンネル種別・二重起動・送信権限）を行い、
    セッションを登録してバックグラウンドタスクを起動、開始メッセージを送信します。
    """
    channel = interaction.channel
    if not isinstance(channel, discord.TextChannel):
        await interaction.followup.send("このコマンドはテキストチャンネルで実行してください。", ephemeral=True)
        return

    if channel.id in _ai_debate_sessions:
        await interaction.followup.send(
            "このチャンネルでは既にAIディベートが進行中です。`/ai_debate stop` で停止してから再開してください。",
            ephemeral=True
        )
        return

    perms = channel.permissions_for(interaction.guild.me)
    if not perms.send_messages or not perms.view_channel:
        await interaction.followup.send(
            f"Botに {channel.mention} での発言権限がありません。チャンネル権限を確認してください。",
            ephemeral=True
        )
        return

    session = {
        "channel": channel,
        "guild_id": interaction.guild.id,
        "topic": topic,
        "personas": {
            "a": {"name": persona_a_name[:80], "prompt": persona_a_prompt},
            "b": {"name": persona_b_name[:80], "prompt": persona_b_prompt},
        },
        "history": [],
        "turn_count": 0,
        "interval_seconds": interval_seconds,
        "max_turns": max_turns,
        "model": model,
        "started_by": interaction.user.id,
        "stopped": False,
    }
    _ai_debate_sessions[channel.id] = session

    task = asyncio.create_task(_ai_debate_loop(channel.id))
    session["task"] = task

    embed = discord.Embed(
        title="[AIディベート] " + ("ランダム設定で開始しました" if is_random else "開始しました"),
        description=f"お題: {topic}",
        color=discord.Color.green()
    )
    embed.add_field(name="人格A", value=f"**{persona_a_name}**\n{persona_a_prompt[:200]}", inline=True)
    embed.add_field(name="人格B", value=f"**{persona_b_name}**\n{persona_b_prompt[:200]}", inline=True)
    embed.add_field(
        name="設定",
        value=(
            f"発言間隔: {interval_seconds}秒\n"
            f"最大ターン数: {max_turns if max_turns else '無制限（/ai_debate stopまで継続）'}"
        ),
        inline=False
    )
    embed.set_footer(text="停止するには /ai_debate stop を実行してください")
    await interaction.followup.send(embed=embed)


@ai_debate_group.command(name="start", description="【オーナー限定】2つの人格を決めて、AI同士がこのチャンネルで会話するのを見てみます")
@app_commands.describe(
    お題="会話のお題・シチュエーション",
    人格a名前="1人目のAIの名前（表示名）",
    人格aプロンプト="1人目のAIの人格・話し方の指示",
    人格b名前="2人目のAIの名前（表示名）",
    人格bプロンプト="2人目のAIの人格・話し方の指示",
    発言間隔秒="次の発言までの待機秒数（既定10秒、5〜600秒）",
    最大ターン数="指定した往復数に達すると自動終了します（未指定なら無制限、stopするまで継続）",
    モデル="使用するモデル名（管理者向け・未指定ならサーバー既定値を使用）"
)
async def ai_debate_start(
    interaction: discord.Interaction,
    お題: str,
    人格a名前: str,
    人格aプロンプト: str,
    人格b名前: str,
    人格bプロンプト: str,
    発言間隔秒: app_commands.Range[int, AI_DEBATE_MIN_INTERVAL_SECONDS, AI_DEBATE_MAX_INTERVAL_SECONDS] = AI_DEBATE_DEFAULT_INTERVAL_SECONDS,
    最大ターン数: Optional[int] = None,
    モデル: Optional[str] = None,
):
    if not await is_owner_check(interaction):
        return
    if not interaction.guild:
        await interaction.response.send_message("このコマンドはサーバー内で実行してください。", ephemeral=True)
        return

    if not GROQ_API_KEY:
        await interaction.response.send_message(
            "GROQ_API_KEY が設定されていないため、この機能は利用できません。", ephemeral=True
        )
        return

    if 最大ターン数 is not None and 最大ターン数 < 1:
        await interaction.response.send_message("最大ターン数は1以上で指定してください（未指定なら無制限）。", ephemeral=True)
        return

    await interaction.response.defer()
    await _ai_debate_launch(
        interaction,
        topic=お題,
        persona_a_name=人格a名前,
        persona_a_prompt=人格aプロンプト,
        persona_b_name=人格b名前,
        persona_b_prompt=人格bプロンプト,
        interval_seconds=発言間隔秒,
        max_turns=最大ターン数,
        model=モデル,
        is_random=False,
    )


@ai_debate_random_group.command(name="start", description="【オーナー限定】お題と2つの人格をAIにおまかせで決めさせて、AI同士の会話をこのチャンネルで始めます")
@app_commands.describe(
    発言間隔秒="次の発言までの待機秒数（既定10秒、5〜600秒）",
    最大ターン数="指定した往復数に達すると自動終了します（未指定なら無制限、stopするまで継続）",
    モデル="使用するモデル名（管理者向け・未指定ならサーバー既定値を使用）"
)
async def ai_debate_random_start(
    interaction: discord.Interaction,
    発言間隔秒: app_commands.Range[int, AI_DEBATE_MIN_INTERVAL_SECONDS, AI_DEBATE_MAX_INTERVAL_SECONDS] = AI_DEBATE_DEFAULT_INTERVAL_SECONDS,
    最大ターン数: Optional[int] = None,
    モデル: Optional[str] = None,
):
    if not await is_owner_check(interaction):
        return
    if not interaction.guild:
        await interaction.response.send_message("このコマンドはサーバー内で実行してください。", ephemeral=True)
        return

    if not GROQ_API_KEY:
        await interaction.response.send_message(
            "GROQ_API_KEY が設定されていないため、この機能は利用できません。", ephemeral=True
        )
        return

    if 最大ターン数 is not None and 最大ターン数 < 1:
        await interaction.response.send_message("最大ターン数は1以上で指定してください（未指定なら無制限）。", ephemeral=True)
        return

    channel = interaction.channel
    if isinstance(channel, discord.TextChannel) and channel.id in _ai_debate_sessions:
        await interaction.response.send_message(
            "このチャンネルでは既にAIディベートが進行中です。`/ai_debate stop` で停止してから再開してください。",
            ephemeral=True
        )
        return

    await interaction.response.defer(thinking=True)

    try:
        setup = await _ai_debate_generate_random_setup(guild_id=interaction.guild.id)
    except GroqRateLimitError as e:
        wait_hint = f"（あと約{_format_duration(e.retry_after)}ほどで復帰する見込みです）" if e.retry_after else ""
        await interaction.followup.send(
            f"APIのレート制限に達しているため、ランダム設定を生成できませんでした。{wait_hint}",
            ephemeral=True
        )
        return
    except Exception:
        await interaction.followup.send("ランダム設定の生成に失敗しました。しばらく時間をおいて再度お試しください。", ephemeral=True)
        return

    await _ai_debate_launch(
        interaction,
        topic=setup["topic"],
        persona_a_name=setup["persona_a_name"],
        persona_a_prompt=setup["persona_a_prompt"],
        persona_b_name=setup["persona_b_name"],
        persona_b_prompt=setup["persona_b_prompt"],
        interval_seconds=発言間隔秒,
        max_turns=最大ターン数,
        model=モデル,
        is_random=True,
    )


@ai_debate_group.command(name="stop", description="【オーナー限定】このチャンネルで進んでいるAIディベートを止めます")
async def ai_debate_stop(interaction: discord.Interaction):
    if not await is_owner_check(interaction):
        return
    if not interaction.guild:
        await interaction.response.send_message("このコマンドはサーバー内で実行してください。", ephemeral=True)
        return

    channel_id = interaction.channel_id
    session = _ai_debate_sessions.get(channel_id)
    if session is None:
        await interaction.response.send_message("このチャンネルでは現在AIディベートは実行されていません。", ephemeral=True)
        return

    session["stopped"] = True
    task = session.get("task")
    if task and not task.done():
        task.cancel()
    _ai_debate_sessions.pop(channel_id, None)

    await interaction.response.send_message(
        f"[AIディベート] 停止しました。（合計 {session.get('turn_count', 0)} ターン実施）"
    )


@ai_debate_group.command(name="status", description="今このサーバーでAIディベートが動いているか確認できます")
async def ai_debate_status(interaction: discord.Interaction):
    if not interaction.guild:
        await interaction.response.send_message("このコマンドはサーバー内で実行してください。", ephemeral=True)
        return

    guild_sessions = [
        (ch_id, s) for ch_id, s in _ai_debate_sessions.items()
        if s.get("guild_id") == interaction.guild.id
    ]

    if not guild_sessions:
        await interaction.response.send_message("このサーバーでは現在AIディベートは実行されていません。", ephemeral=True)
        return

    embed = discord.Embed(title="[AIディベート] 実行状況", color=discord.Color.blue())
    for ch_id, s in guild_sessions:
        ch = interaction.guild.get_channel(ch_id)
        personas = s["personas"]
        embed.add_field(
            name=ch.mention if ch else f"チャンネルID: {ch_id}",
            value=(
                f"お題: {s['topic'][:80]}\n"
                f"{personas['a']['name']} vs {personas['b']['name']}\n"
                f"ターン数: {s['turn_count']} / "
                f"{s['max_turns'] if s.get('max_turns') else '無制限'}\n"
                f"発言間隔: {s['interval_seconds']}秒"
            ),
            inline=False
        )
    await interaction.response.send_message(embed=embed, ephemeral=True)


async def _handle_ai_chat_message(message: discord.Message, guild_config: dict):
    """AIチャット専用チャンネルでのメッセージを処理し、Groq経由で応答します。"""
    if not GROQ_API_KEY:
        return  # APIキー未設定時は無反応（オーナーが気付けるようログにだけ出す）

    # 人間が発言した時点で、他Bot連鎖応答のターン数カウンタをリセットする
    # （bot_reply機能が有効な場合、次にターゲットBotが話し始めたら1ターン目から再度カウントする）
    _ai_chat_bot_reply_reset_turn_count(message.channel.id)

    # サーバー単位の一時停止（オーナーが /ai_chat pause で設定）
    if guild_config.get("ai_chat_paused", False):
        return  # 一時停止中は無反応（オーナーが意図的に止めているため通知もしない）

    # ユーザー個別設定の取得（モデル切替・システムプロンプト・利用ブロック）
    user_setting = _ai_chat_get_user_setting(guild_config, message.author.id)
    if user_setting["blocked"]:
        return  # ブロック済みユーザーには無反応

    # 画像添付の検出（1枚のみ対応。対応拡張子の最初の1枚を使用し、それ以外は無視）
    image_url: Optional[str] = None
    _IMAGE_EXTENSIONS = (".png", ".jpg", ".jpeg", ".gif", ".webp")
    for attachment in message.attachments:
        filename_lower = (attachment.filename or "").lower()
        if filename_lower.endswith(_IMAGE_EXTENSIONS):
            image_url = attachment.url
            break

    content = message.content.strip()
    if not content and image_url is None:
        return  # テキストも画像も無い場合はスキップ

    if image_url is not None and not GROQ_VISION_MODEL:
        # Vision対応モデルが未設定の場合、画像添付には対応できない旨を伝える
        if not content:
            try:
                await message.reply(
                    "[AIチャット] 画像を確認しましたが、この機能は現在利用できません"
                    "（Botの画像認識モデルが設定されていません）。テキストで質問してください。",
                    mention_author=False
                )
            except Exception:
                pass
            return
        image_url = None  # テキストがあれば画像を無視してテキストのみで続行

    # クールダウン（連投制限）チェック（オーナーが /ai_chat set_cooldown で設定）
    cooldown_seconds = guild_config.get("ai_chat_cooldown_seconds", 0)
    remaining = _ai_chat_check_cooldown(message.guild.id, message.author.id, cooldown_seconds)
    if remaining is not None:
        try:
            await message.reply(
                f"[AIチャット] 連続利用の間隔が短すぎます。あと{_format_duration(remaining)}待ってください。",
                mention_author=False
            )
        except Exception:
            pass
        return

    system_prompt = _ai_chat_finalize_system_prompt(
        user_setting["system_prompt"] or _ai_chat_resolve_default_system_prompt(guild_config),
        guild_config=guild_config
    )
    model = user_setting["model"] or None  # Noneなら _ai_chat_call_groq側でGROQ_MODELが使われる

    # mem0による長期記憶の検索（サーバー・チャンネルを跨いで覚えている、このユーザーについての情報）
    use_memory = _mem0_is_enabled(guild_config)
    if use_memory and content:
        memories = await _mem0_search_memories(message.author.id, content)
        system_prompt += _mem0_build_context_block(memories)

    history = _ai_chat_get_history(message.channel.id, message.author.id)

    if image_url is not None:
        # マルチモーダル形式（テキスト＋画像）でユーザーメッセージを構築
        user_message_content = [
            {"type": "text", "text": content or "この画像について説明してください。"},
            {"type": "image_url", "image_url": {"url": image_url}},
        ]
    else:
        user_message_content = content

    messages = [{"role": "system", "content": system_prompt}] + history + [
        {"role": "user", "content": user_message_content}
    ]

    reply_text: Optional[str] = None
    used_model: Optional[str] = None
    used_provider: str = "groq"

    # クールダウンはAPI呼び出しの成否に関わらず「利用した」時点で記録する
    # （エラー時に即座に連投できてしまうと日次上限の浪費を防げないため）
    _ai_chat_record_request(message.guild.id, message.author.id)

    try:
        async with message.channel.typing():
            _search_performed_var.set(False)  # 今回の応答生成における検索実行有無を再集計する
            if image_url is not None:
                # 画像添付時はVision対応モデル固定（Cerebrasへのフォールバックは行わない）
                reply_text = await _ai_chat_call_groq(messages, model=GROQ_VISION_MODEL)
                used_model = GROQ_VISION_MODEL
                used_provider = "groq"
            else:
                provider_override = guild_config.get("ai_provider", "auto")
                if provider_override not in ("groq", "cerebras", "mistral", "openrouter", "gemini"):
                    provider_override = None
                reply_text, used_provider = await _ai_call_llm_with_fallback(
                    messages, model=model, provider_override=provider_override, enable_search=True,
                    guild_config=guild_config
                )
                if used_provider == "groq":
                    used_model = model or GROQ_MODEL
                elif used_provider == "cerebras":
                    used_model = CEREBRAS_MODEL
                elif used_provider == "mistral":
                    used_model = MISTRAL_MODEL
                elif used_provider == "openrouter":
                    used_model = OPENROUTER_MODEL
                else:
                    used_model = GEMINI_MODEL
    except (GroqRateLimitError, CerebrasRateLimitError, MistralRateLimitError, OpenRouterRateLimitError, GeminiRateLimitError) as e:
        try:
            wait_hint = f"（あと約{_format_duration(e.retry_after)}ほどで復帰する見込みです）" if e.retry_after else ""

            limit_scope = getattr(e, "limit_scope", None)
            if limit_scope in ("TPD", "RPD"):
                scope_text = "本日の利用上限"
            elif limit_scope in ("TPM", "RPM"):
                scope_text = "レート制限（短時間の利用集中）"
            else:
                scope_text = "レート制限"

            await message.reply(
                f"[AIチャット] 現在{scope_text}に引っかかっています。BOTを少し休ませてください。"
                f"{wait_hint}\nしばらく時間をおいてから、もう一度お試しください。",
                mention_author=False
            )
        except Exception:
            pass
        return
    except Exception as e:
        print(f"[AIチャット] 応答生成エラー: {e}")
        try:
            await message.reply("[AIチャット] 応答生成に失敗しました。時間をおいて再度お試しください。", mention_author=False)
        except Exception:
            pass
        return

    if not reply_text:
        # 思考過程のみが返って本文が空になった等のケース
        reply_text = "（応答の生成に失敗しました。もう一度お試しください）"

    # フォールバックプロバイダ/モデルで応答した場合、一般ユーザーには実装詳細（プロバイダ名・モデル名）を
    # 見せず「一時的に別方式で応答した」旨のみ簡潔に伝える（AI実装のプロバイダ/モデル名の外部露出防止）。
    # あわせて、Web検索が有効なサーバーであれば「今回は検索が使えていない」旨も伝える
    # （検索できないまま学習データだけで回答している事実をユーザーが把握できるようにするため）。
    primary_model = model or GROQ_MODEL
    search_note = "" if (not WEB_SEARCH_AVAILABLE or _search_performed_var.get()) else "（今回はWeb検索は利用できていません）"
    if used_provider in ("cerebras", "mistral", "openrouter", "gemini"):
        reply_text += f"\n\n*（本日の利用上限のため、一時的に別方式で応答しました{search_note}）*"
    elif used_model and used_model != primary_model:
        reply_text += f"\n\n*（本日の利用上限のため、代替モデルで応答しました{search_note}）*"

    # 履歴には画像URLそのものではなくテキストのみ保存する（画像のみ送信時はプレースホルダーを使用）。
    # 添付画像のURLは時間経過で失効するため、履歴として持ち回らせない設計。
    history_user_content = content if content else "（画像を送信）"
    _ai_chat_append_history(message.channel.id, message.author.id, history_user_content, reply_text)

    # mem0への記憶保存はレイテンシに影響させないよう、応答送信を待たせずバックグラウンドで実行する
    if use_memory and history_user_content and history_user_content != "（画像を送信）":
        asyncio.create_task(_mem0_add_memory(message.author.id, history_user_content, reply_text))

    # Discordの1メッセージ2000文字制限に合わせて分割送信
    chunks = [reply_text[i:i + 1900] for i in range(0, len(reply_text), 1900)] or [""]
    try:
        await message.reply(chunks[0], mention_author=False)
        for chunk in chunks[1:]:
            await message.channel.send(chunk)
    except discord.Forbidden:
        pass


# ====================================================================
# 他BOTの発言への自動応答（bot_reply機能）
# ====================================================================
# ・オーナーが /ai_chat bot_reply add で明示的に登録したBotの発言にのみ反応する。
# ・対象はAIチャット専用チャンネル（ai_chat_channel_id）に限定。
# ・無限ループ・高頻度連投を防ぐため、以下の安全対策を必ず経由する:
#     1. 連鎖ターン数の上限（ai_chat_bot_reply_max_turns）— 人間の発言でリセットされる
#     2. チャンネル単位のクールダウン（ai_chat_bot_reply_cooldown_seconds）
#     3. 自分自身（このBot）の発言には反応しない（on_message冒頭のmessage.author.botチェックで
#        そもそもBot全般が弾かれ、bot_reply_target_idsに登録されたIDのみ通過するため、
#        このBot自身のIDを誤って登録しない限り自己応答は起こらない）
# ====================================================================

async def _handle_ai_chat_bot_reply(message: discord.Message, guild_config: dict):
    """登録済みの他Botの発言に対し、安全対策を経た上でAIチャットチャンネルにて自動応答します。"""
    if not GROQ_API_KEY:
        return

    # 安全対策0: 自分自身のIDが誤って登録されていた場合の自己応答ループを確実に防ぐ
    if bot.user is not None and message.author.id == bot.user.id:
        return

    if guild_config.get("ai_chat_paused", False):
        return  # サーバー全体のAIチャット一時停止中は、他Botへの応答も止める

    content = message.content.strip()
    if not content:
        return  # 他Bot側がEmbedのみ等でテキスト本文が無い場合は反応しない（誤爆防止）

    channel_id = message.channel.id

    # 安全対策1: 連鎖ターン数の上限チェック
    max_turns = guild_config.get("ai_chat_bot_reply_max_turns", 4)
    current_turns = _ai_chat_bot_reply_turn_count.get(channel_id, 0)
    if current_turns >= max_turns:
        return  # 上限に達した場合は無反応（人間が発言するまで再開しない）

    # 安全対策2: クールダウンチェック
    cooldown_seconds = guild_config.get("ai_chat_bot_reply_cooldown_seconds", 15)
    last_time = _ai_chat_bot_reply_last_time.get(channel_id)
    if last_time is not None and cooldown_seconds > 0:
        remaining = cooldown_seconds - (time.time() - last_time)
        if remaining > 0:
            return  # クールダウン中は無反応（他Bot側にエラーメッセージを送っても意味がないため）

    system_prompt = _ai_chat_finalize_system_prompt(
        _ai_chat_resolve_default_system_prompt(guild_config) + (
            "\n\n（補足: 今、会話相手は人間ではなく別のBotです。"
            "自然な相槌や短めの受け答えを意識し、同じような話を無限に広げすぎないようにしてください。）"
        ),
        include_search_guide=False
    )

    # 履歴はチャンネル単位・「Bot同士の会話」専用のuser_id（0）で管理し、
    # 人間ユーザーとの会話履歴（_handle_ai_chat_message側）とは混同しない
    _BOT_REPLY_HISTORY_USER_ID = 0
    history = _ai_chat_get_history(channel_id, _BOT_REPLY_HISTORY_USER_ID)
    messages = [{"role": "system", "content": system_prompt}] + history + [
        {"role": "user", "content": content}
    ]

    provider_override = guild_config.get("ai_provider", "auto")
    if provider_override not in ("groq", "cerebras", "mistral", "openrouter", "gemini"):
        provider_override = None

    try:
        async with message.channel.typing():
            reply_text, _used_provider = await _ai_call_llm_with_fallback(
                messages, provider_override=provider_override
            )
    except (GroqRateLimitError, CerebrasRateLimitError, MistralRateLimitError, OpenRouterRateLimitError, GeminiRateLimitError):
        # レート制限時は他Botに向けてエラーメッセージを送らず、静かに諦める
        print(f"[AIチャット/bot_reply] レート制限のため応答を見送りました（channel_id={channel_id}）")
        return
    except Exception as e:
        print(f"[AIチャット/bot_reply] 応答生成エラー: {e}")
        return

    if not reply_text:
        return

    # ターン数・クールダウンを記録（実際に応答した場合のみカウントする）
    _ai_chat_bot_reply_turn_count[channel_id] = current_turns + 1
    _ai_chat_bot_reply_last_time[channel_id] = time.time()

    _ai_chat_append_history(channel_id, _BOT_REPLY_HISTORY_USER_ID, content, reply_text)

    chunks = [reply_text[i:i + 1900] for i in range(0, len(reply_text), 1900)] or [""]
    try:
        await message.reply(chunks[0], mention_author=False)
        for chunk in chunks[1:]:
            await message.channel.send(chunk)
    except discord.Forbidden:
        pass


# ====================================================================
# /ai コマンド（DM・グループDM・サーバー内どこからでも使える汎用AI質問コマンド）
# ====================================================================
# ・サーバー内の専用チャンネル自動応答（_handle_ai_chat_message）とは別に、
#   場所を問わず単発で質問できるスラッシュコマンドを用意する。
# ・DMには「サーバー設定」が存在しないため、クールダウン・ブロック等は
#   グローバル設定（dm_ai_chat_*）で一元管理する。
# ・会話履歴はチャンネルID単位で _ai_chat_histories をそのまま流用する
#   （DMチャンネルにも一意のchannel.idがあるため、既存の仕組みと共存できる）。
# ・ギルド疑似IDとして 0 を用いてクールダウンキャッシュ（_ai_chat_last_request）を
#   共有する（実在のDiscordギルドIDは0にならないため衝突しない）。
# ====================================================================

_AI_COMMAND_DM_GUILD_KEY = 0  # DM/グループDMからの /ai 利用時に使う疑似ギルドID（クールダウン管理用）


@bot.tree.command(name="ai", description="AIに何でも聞けます（DMでもグループDMでもサーバー内でも使えます）")
@app_commands.describe(質問="AIに聞きたい内容を入力してください")
@app_commands.allowed_contexts(guilds=True, dms=True, private_channels=True)
@app_commands.allowed_installs(guilds=True, users=True)
async def ai_command(interaction: discord.Interaction, 質問: str):
    if not GROQ_API_KEY:
        await interaction.response.send_message(
            "現在この機能は利用できません（Botの設定が未完了です）。", ephemeral=True
        )
        return

    all_data = load_data()
    global_cfg = get_global_config(all_data)

    if not global_cfg.get("dm_ai_chat_enabled", True):
        await interaction.response.send_message(
            "現在 `/ai` コマンドは無効化されています。管理者にお問い合わせください。", ephemeral=True
        )
        return

    if interaction.user.id in global_cfg.get("dm_ai_chat_blocked_users", []):
        await interaction.response.send_message("このコマンドの利用が制限されています。", ephemeral=True)
        return

    cooldown_seconds = global_cfg.get("dm_ai_chat_cooldown_seconds", 10)
    remaining = _ai_chat_check_cooldown(_AI_COMMAND_DM_GUILD_KEY, interaction.user.id, cooldown_seconds)
    if remaining is not None:
        await interaction.response.send_message(
            f"連続利用の間隔が短すぎます。あと{_format_duration(remaining)}待ってください。", ephemeral=True
        )
        return

    await interaction.response.defer(thinking=True)

    # サーバー内で実行された場合、そのサーバーのユーザー個別設定（人格・ブロック等）を尊重する。
    # DM/グループDMではサーバー設定が存在しないため既定のシステムプロンプトを使用する。
    system_prompt = AI_CHAT_SYSTEM_PROMPT
    model: Optional[str] = None
    provider_override: Optional[str] = None
    guild_config: Optional[dict] = None
    if interaction.guild is not None:
        guild_config = get_guild_config(all_data, str(interaction.guild.id))
        user_setting = _ai_chat_get_user_setting(guild_config, interaction.user.id)
        if user_setting["blocked"]:
            await interaction.followup.send("このコマンドの利用が制限されています。", ephemeral=True)
            return
        system_prompt = user_setting["system_prompt"] or _ai_chat_resolve_default_system_prompt(guild_config)
        model = user_setting["model"] or None
        provider_override = guild_config.get("ai_provider", "auto")
        if provider_override not in ("groq", "cerebras", "mistral", "openrouter", "gemini"):
            provider_override = None

    # AI人格ガチャで引いたペルソナを適用中の場合、システムプロンプトを差し替える
    # （ユーザーが /my_prompt 等で個別プロンプトを設定していても、ガチャペルソナ適用中は
    #  そちらを優先する。/gacha use none で解除するまで有効）
    user_app_data = get_user_app_data(all_data, str(interaction.user.id))
    active_persona_id = user_app_data.get("gacha_active_persona_id")
    if active_persona_id:
        persona = next(
            (p for p in user_app_data.get("gacha_personas", []) if p.get("id") == active_persona_id),
            None
        )
        if persona:
            system_prompt = _gacha_persona_to_system_prompt(persona)
        else:
            # 参照先が見つからない（データ不整合）場合は静かに解除しておく
            user_app_data["gacha_active_persona_id"] = None

    # 履歴キー: DM/グループDM/サーバーいずれもチャンネルID単位（既存の自動応答と同じ仕組みを再利用）
    channel_id = interaction.channel_id
    history = _ai_chat_get_history(channel_id, interaction.user.id)

    final_system_prompt = _ai_chat_finalize_system_prompt(system_prompt, guild_config=guild_config)

    # mem0による長期記憶の検索（サーバー・チャンネルを跨いで覚えている、このユーザーについての情報）
    use_memory = _mem0_is_enabled(guild_config)
    if use_memory:
        memories = await _mem0_search_memories(interaction.user.id, 質問)
        final_system_prompt += _mem0_build_context_block(memories)

    messages = [{"role": "system", "content": final_system_prompt}] + history + [
        {"role": "user", "content": 質問}
    ]

    _ai_chat_record_request(_AI_COMMAND_DM_GUILD_KEY, interaction.user.id)
    _ai_command_record_usage(
        interaction.guild.id if interaction.guild is not None else None,
        interaction.user.id,
        getattr(interaction.user, "display_name", None) or str(interaction.user)
    )

    try:
        reply_text, _used_provider = await _ai_call_llm_with_fallback(
            messages, model=model, provider_override=provider_override, enable_search=True,
            guild_config=guild_config
        )
    except (GroqRateLimitError, CerebrasRateLimitError, MistralRateLimitError, OpenRouterRateLimitError, GeminiRateLimitError) as e:
        wait_hint = f"（あと約{_format_duration(e.retry_after)}ほどで復帰する見込みです）" if e.retry_after else ""
        limit_scope = getattr(e, "limit_scope", None)
        if limit_scope in ("TPD", "RPD"):
            scope_text = "本日の利用上限"
        elif limit_scope in ("TPM", "RPM"):
            scope_text = "レート制限（短時間の利用集中）"
        else:
            scope_text = "レート制限"
        await interaction.followup.send(
            f"現在{scope_text}に引っかかっています。BOTを少し休ませてください。{wait_hint}\n"
            "しばらく時間をおいてから、もう一度お試しください。"
        )
        return
    except Exception as e:
        print(f"[/ai] 応答生成エラー: {e}")
        await interaction.followup.send("応答の生成に失敗しました。時間をおいて再度お試しください。")
        return

    if not reply_text:
        reply_text = "（応答の生成に失敗しました。もう一度お試しください）"

    _ai_chat_append_history(channel_id, interaction.user.id, 質問, reply_text)

    # mem0への記憶保存はレイテンシに影響させないよう、応答送信を待たせずバックグラウンドで実行する
    if use_memory:
        asyncio.create_task(_mem0_add_memory(interaction.user.id, 質問, reply_text))

    # Discordの1メッセージ2000文字制限に合わせて分割送信
    chunks = [reply_text[i:i + 1900] for i in range(0, len(reply_text), 1900)] or [""]
    await interaction.followup.send(chunks[0])
    for chunk in chunks[1:]:
        try:
            await interaction.channel.send(chunk)
        except Exception:
            pass


# ====================================================================
# /image コマンド（画像生成機能）
# ====================================================================
# 3段構成のフォールバックで画像生成を行う:
#   1. Gemini（Gemini 2.5 Flash Image） — GEMINI_API_KEY流用。日本語プロンプトの
#      理解精度が高く、翻訳を挟まなくても日本語の意図を汲んだ画像が生成されやすい。
#   2. Cloudflare Workers AI（Stable Diffusion XL） — 要アカウント・APIトークン。
#      英語プロンプト向き。1が未設定または失敗した場合のフォールバック先。
#   3. Pollinations.ai — APIキー・サインアップ不要の無料エンドポイント。
#      1・2の両方が未設定時、またはエラー時の最終フォールバック先として使う。
# どのサービス名・使用モデル名もユーザーには開示しない（/helpやコマンド説明文・埋め込み等）。
# ====================================================================

_IMAGE_COMMAND_GUILD_KEY = -2  # /image 利用時のクールダウン管理用の疑似ギルドID（他機能のキーと衝突しないよう負の値にする）
IMAGE_COMMAND_COOLDOWN_SECONDS = 15  # キー不要側（Pollinations）の匿名レート制限目安に合わせた最小間隔
IMAGE_COMMAND_MIN_SIZE = 256
IMAGE_COMMAND_MAX_SIZE = 1536


async def _gemini_generate_image(prompt: str, width: int, height: int) -> bytes:
    """
    Gemini（Gemini 2.5 Flash Image）を呼び出し、画像バイナリを返します。
    AIチャット機能と同じGEMINI_API_KEYを流用します。
    日本語プロンプトをそのまま渡せます（内部で高精度に解釈される）。
    失敗した場合は例外を送出します（呼び出し元でハンドリングする）。
    """
    if not GEMINI_API_KEY:
        raise RuntimeError("GEMINI_API_KEY が設定されていません。")

    # Gemini 2.5 Flash Imageはピクセル指定のwidth/heightパラメータを持たないため、
    # 縦横比が近いアスペクト比ヒントをプロンプトに含めて誘導する。
    aspect_hint = ""
    if width and height:
        ratio = width / height
        if abs(ratio - 1.0) > 0.05:
            if ratio > 1.0:
                aspect_hint = f"（横長・アスペクト比おおよそ{ratio:.2f}:1の画像として生成してください）"
            else:
                aspect_hint = f"（縦長・アスペクト比おおよそ1:{(1/ratio):.2f}の画像として生成してください）"

    payload = {
        "contents": [
            {"role": "user", "parts": [{"text": prompt + aspect_hint}]}
        ],
        "generationConfig": {"responseModalities": ["IMAGE"]},
    }
    url = (
        f"https://generativelanguage.googleapis.com/v1beta/models/"
        f"{GEMINI_IMAGE_MODEL}:generateContent?key={GEMINI_API_KEY}"
    )

    async with aiohttp.ClientSession() as session:
        async with session.post(
            url, json=payload, timeout=aiohttp.ClientTimeout(total=60)
        ) as resp:
            if resp.status == 429:
                err_text = await resp.text()
                retry_after = _extract_gemini_retry_after(err_text)
                raise RuntimeError(
                    f"画像生成プロバイダG レート制限（HTTP 429）"
                    f"{f'、{retry_after:.0f}秒後に再試行可能' if retry_after else ''}: {err_text[:200]}"
                )
            if resp.status != 200:
                err_text = await resp.text()
                raise RuntimeError(f"画像生成プロバイダG エラー（HTTP {resp.status}）: {err_text[:300]}")
            data = await resp.json()

    try:
        candidate = data["candidates"][0]
        parts = candidate.get("content", {}).get("parts", [])
    except (KeyError, IndexError, TypeError):
        raise RuntimeError(f"画像生成プロバイダG の応答形式が想定と異なります: {data}")

    for part in parts:
        inline_data = part.get("inlineData") or part.get("inline_data")
        if inline_data and inline_data.get("data"):
            try:
                return base64.b64decode(inline_data["data"])
            except Exception as e:
                raise RuntimeError(f"画像生成プロバイダG の画像データ解析に失敗しました: {e}")

    finish_reason = candidate.get("finishReason", "")
    if finish_reason == "SAFETY" or finish_reason == "IMAGE_SAFETY":
        raise RuntimeError("画像生成プロバイダG がセーフティフィルターにより画像生成をブロックしました。")
    raise RuntimeError(f"画像生成プロバイダG のレスポンスに画像データが含まれていません（finishReason: {finish_reason}）。")


async def _cloudflare_generate_image(prompt: str, width: int, height: int) -> bytes:
    """
    Cloudflare Workers AI（Stable Diffusion XL）を呼び出し、画像バイナリを返します。
    失敗した場合は例外を送出します（呼び出し元でハンドリングする）。
    """
    url = (
        f"https://api.cloudflare.com/client/v4/accounts/{CLOUDFLARE_ACCOUNT_ID}"
        f"/ai/run/@cf/stabilityai/stable-diffusion-xl-base-1.0"
    )
    headers = {
        "Authorization": f"Bearer {CLOUDFLARE_API_TOKEN}",
        "Content-Type": "application/json",
    }
    # Cloudflare側は256〜2048の範囲かつ8の倍数でないと400エラーになることがあるため、
    # 安全のため8の倍数に丸めてから渡す（見た目上の差はほぼ無視できるレベル）。
    safe_width = max(256, min(width - (width % 8), 2048))
    safe_height = max(256, min(height - (height % 8), 2048))

    payload = {
        "prompt": prompt,
        "width": safe_width,
        "height": safe_height,
    }
    async with aiohttp.ClientSession() as session:
        async with session.post(
            url,
            json=payload,
            headers=headers,
            timeout=aiohttp.ClientTimeout(total=60)
        ) as resp:
            content_type = resp.headers.get("Content-Type", "")
            if resp.status != 200:
                err_text = await resp.text()
                raise RuntimeError(f"画像生成プロバイダA エラー（HTTP {resp.status}）: {err_text[:300]}")
            if not content_type.startswith("image/"):
                # エラー時はJSONで返ってくることがあるため、失敗として扱う
                err_text = await resp.text()
                raise RuntimeError(f"画像生成プロバイダA 想定外のレスポンス: {err_text[:300]}")
            return await resp.read()


async def _pollinations_generate_image(prompt: str, width: int, height: int) -> bytes:
    """
    Pollinations.ai の画像生成エンドポイントを呼び出し、画像バイナリを返します。
    失敗した場合は例外を送出します（呼び出し元でハンドリングする）。
    """
    encoded_prompt = urllib.parse.quote(prompt, safe="")
    url = f"https://image.pollinations.ai/prompt/{encoded_prompt}"
    params = {
        "width": width,
        "height": height,
        "nologo": "true",
        # 同一プロンプトでもCDNキャッシュで同じ画像が返り続けないよう、毎回ランダムなseedを付与する
        "seed": random.randint(0, 2**31 - 1),
    }
    async with aiohttp.ClientSession() as session:
        async with session.get(
            url,
            params=params,
            timeout=aiohttp.ClientTimeout(total=60)
        ) as resp:
            if resp.status != 200:
                err_text = await resp.text()
                raise RuntimeError(f"画像生成プロバイダB エラー（HTTP {resp.status}）: {err_text[:300]}")
            content_type = resp.headers.get("Content-Type", "")
            if not content_type.startswith("image/"):
                raise RuntimeError(f"画像生成プロバイダB 想定外のレスポンス形式です（Content-Type: {content_type}）")
            return await resp.read()


async def _generate_image_with_fallback(prompt: str, width: int, height: int) -> bytes:
    """
    設定済みの画像生成プロバイダを優先順位（Gemini→Cloudflare→Pollinations）の順に試し、
    最初に成功したものの画像バイナリを返します。
    Gemini・Cloudflareが未設定の場合はPollinationsのみを使用します。
    すべて失敗した場合は最後に発生した例外を送出します。
    """
    last_error: Optional[Exception] = None

    if IMAGE_GEN_GEMINI_AVAILABLE:
        try:
            return await _gemini_generate_image(prompt, width, height)
        except Exception as e:
            print(f"[画像生成] プロバイダG（Gemini）が失敗したため次のプロバイダへフォールバックします: {e}")
            last_error = e

    if IMAGE_GEN_PRIMARY_AVAILABLE:
        try:
            return await _cloudflare_generate_image(prompt, width, height)
        except Exception as e:
            print(f"[画像生成] プロバイダA が失敗したため予備プロバイダへフォールバックします: {e}")
            last_error = e

    try:
        return await _pollinations_generate_image(prompt, width, height)
    except Exception as e:
        print(f"[画像生成] 予備プロバイダも失敗しました: {e}")
        last_error = e

    raise last_error or RuntimeError("画像生成に失敗しました。")


@bot.tree.command(name="image", description="AIに好きな画像を作ってもらえます（無料）")
@app_commands.describe(
    プロンプト="生成したい画像の内容（日本語も可。具体的・詳細なほど精度が上がります）",
    横幅=f"画像の幅（ピクセル、{IMAGE_COMMAND_MIN_SIZE}〜{IMAGE_COMMAND_MAX_SIZE}、省略時は1024）",
    縦幅=f"画像の高さ（ピクセル、{IMAGE_COMMAND_MIN_SIZE}〜{IMAGE_COMMAND_MAX_SIZE}、省略時は1024）",
)
@app_commands.allowed_contexts(guilds=True, dms=True, private_channels=True)
@app_commands.allowed_installs(guilds=True, users=True)
async def image_command(
    interaction: discord.Interaction,
    プロンプト: str,
    横幅: Optional[int] = 1024,
    縦幅: Optional[int] = 1024,
):
    remaining = _ai_chat_check_cooldown(_IMAGE_COMMAND_GUILD_KEY, interaction.user.id, IMAGE_COMMAND_COOLDOWN_SECONDS)
    if remaining is not None:
        await interaction.response.send_message(
            f"連続利用の間隔が短すぎます。あと{_format_duration(remaining)}待ってください。", ephemeral=True
        )
        return

    width = max(IMAGE_COMMAND_MIN_SIZE, min(横幅 or 1024, IMAGE_COMMAND_MAX_SIZE))
    height = max(IMAGE_COMMAND_MIN_SIZE, min(縦幅 or 1024, IMAGE_COMMAND_MAX_SIZE))

    await interaction.response.defer(thinking=True)
    _ai_chat_record_request(_IMAGE_COMMAND_GUILD_KEY, interaction.user.id)

    try:
        image_bytes = await _generate_image_with_fallback(プロンプト, width, height)
    except asyncio.TimeoutError:
        await interaction.followup.send("画像生成がタイムアウトしました。時間をおいて再度お試しください。")
        return
    except Exception as e:
        print(f"[/image] 画像生成エラー: {e}")
        await interaction.followup.send("画像生成に失敗しました。プロンプトを変えるか、時間をおいて再度お試しください。")
        return

    file_obj = discord.File(io.BytesIO(image_bytes), filename="generated.png")
    embed = discord.Embed(
        description=f"**プロンプト:** {プロンプト[:1000]}",
        color=discord.Color.purple()
    )
    embed.set_image(url="attachment://generated.png")
    embed.set_footer(text=f"AI画像生成 ・ {width}x{height}")
    await interaction.followup.send(embed=embed, file=file_obj)


# ====================================================================
# /avatar コマンド（DiceBear の公開HTTP APIを使ったイラスト風ランダムアバター生成）
# ・DiceBear（https://www.dicebear.com）はAPIキー不要・無料で使える公開HTTP APIを
#   提供しており、スタイル名とシード文字列を指定するだけでイラスト風アバター画像が
#   取得できる（同じスタイル+シードなら常に同じ絵が返るため再現性がある）。
# ====================================================================

_AVATAR_COMMAND_GUILD_KEY = -3  # /avatar 利用時のクールダウン管理用の疑似ギルドID（他機能のキーと衝突しないよう負の値にする）
AVATAR_COMMAND_COOLDOWN_SECONDS = 5  # DiceBearの公開APIへの過度な連打を避けるための最小間隔
DICEBEAR_API_VERSION = "10.x"

# ユーザーに選ばせるスタイルの一覧（DiceBearが提供する30以上のスタイルのうち、
# イラスト・キャラクター系で見た目の差がわかりやすいものを抜粋）。
DICEBEAR_STYLE_CHOICES = [
    app_commands.Choice(name="おまかせ（ランダム）", value="random"),
    app_commands.Choice(name="アドベンチャラー（イラスト風の人物）", value="adventurer"),
    app_commands.Choice(name="アバタース（丸顔の人物）", value="avataaars"),
    app_commands.Choice(name="ロレレイ（線画イラスト風）", value="lorelei"),
    app_commands.Choice(name="ノーショニスト（おしゃれイラスト風）", value="notionists"),
    app_commands.Choice(name="ボッツ（ロボット）", value="bottts"),
    app_commands.Choice(name="ドット絵", value="pixel-art"),
    app_commands.Choice(name="サムズ（親指キャラ）", value="thumbs"),
    app_commands.Choice(name="絵文字風", value="fun-emoji"),
    app_commands.Choice(name="図形（シェイプ）", value="shapes"),
]
_DICEBEAR_RANDOM_STYLES = [c.value for c in DICEBEAR_STYLE_CHOICES if c.value != "random"]


async def _dicebear_generate_avatar(style: str, seed: str) -> bytes:
    """
    DiceBearの公開HTTP APIを呼び出し、指定スタイル・シードのアバターPNG画像バイナリを返します。
    認証不要・無料の公開エンドポイントのため、APIキーの設定は不要です。
    失敗した場合は例外を送出します（呼び出し元でハンドリングする）。
    """
    url = f"https://api.dicebear.com/{DICEBEAR_API_VERSION}/{style}/png"
    params = {"seed": seed, "size": 512}
    async with aiohttp.ClientSession() as session:
        async with session.get(
            url,
            params=params,
            timeout=aiohttp.ClientTimeout(total=20)
        ) as resp:
            if resp.status != 200:
                err_text = await resp.text()
                raise RuntimeError(f"DiceBear APIエラー（HTTP {resp.status}）: {err_text[:300]}")
            return await resp.read()


class _AvatarRegenerateView(discord.ui.View):
    """
    /avatar コマンドの結果に付けるビュー。
    ボタンを押すと同じスタイル（おまかせの場合はスタイルも再抽選）で、
    新しいシードのアバターをその場（同じメッセージ）で再生成する。
    """
    def __init__(self, style_choice: str, requester_id: int):
        super().__init__(timeout=180)
        self.style_choice = style_choice  # "random" または具体的なスタイル名
        self.requester_id = requester_id

    @discord.ui.button(label="別の一枚を生成", style=discord.ButtonStyle.primary, emoji="🔀")
    async def regenerate(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.requester_id:
            await interaction.response.send_message(
                "このボタンはコマンドを実行した本人のみ使えます。", ephemeral=True
            )
            return

        remaining = _ai_chat_check_cooldown(
            _AVATAR_COMMAND_GUILD_KEY, interaction.user.id, AVATAR_COMMAND_COOLDOWN_SECONDS
        )
        if remaining is not None:
            await interaction.response.send_message(
                f"連続利用の間隔が短すぎます。あと{_format_duration(remaining)}待ってください。", ephemeral=True
            )
            return

        await interaction.response.defer()
        _ai_chat_record_request(_AVATAR_COMMAND_GUILD_KEY, interaction.user.id)

        actual_style = (
            random.choice(_DICEBEAR_RANDOM_STYLES) if self.style_choice == "random" else self.style_choice
        )
        seed = secrets.token_hex(8)
        try:
            image_bytes = await _dicebear_generate_avatar(actual_style, seed)
        except Exception as e:
            print(f"[/avatar] 再生成エラー: {e}")
            await interaction.followup.send(
                "アバター生成に失敗しました。時間をおいて再度お試しください。", ephemeral=True
            )
            return

        file_obj = discord.File(io.BytesIO(image_bytes), filename="avatar.png")
        embed = discord.Embed(color=discord.Color.teal())
        embed.set_image(url="attachment://avatar.png")
        embed.set_footer(text=f"スタイル: {actual_style} ・ シード: {seed}")
        await interaction.edit_original_response(embed=embed, attachments=[file_obj], view=self)


