@profile_badge_delete.autocomplete("バッジ名")
async def profile_badge_name_autocomplete(interaction: discord.Interaction, current: str):
    all_data = load_data()
    global_cfg = get_global_config(all_data)
    badge_defs = global_cfg.get("badge_defs", {})
