# ====================================================================
# AI自動モデレーション機能
# ====================================================================
# ・既存のng_words（単純な文字列一致）では、言い換えや遠回しな表現による
#   荒らし・誹謗中傷・迷惑勧誘をすり抜けられてしまう問題に対応します。
# ・全テキストチャンネルの発言を対象に、一定間隔（既定30秒）でメッセージを
#   まとめてGroqへ送りバッチ判定することで、リアルタイム判定に比べて
#   API呼び出し回数・トークン消費を大きく抑えます。
# ・不適切と判定された発言は削除し、既存の warnings システムに警告を1件
#   追加します（担当者（moderator）はBot自身のIDとして記録されます）。
# ====================================================================

AI_AUTOMOD_BATCH_INTERVAL_SECONDS = 30   # バッチ判定の実行間隔
AI_AUTOMOD_MAX_BATCH_SIZE = 30           # 1回のバッチで判定するメッセージの最大件数（トークン節約のため上限を設ける）
AI_AUTOMOD_MAX_QUEUE_SIZE = 300          # キューの最大保持件数（あふれた場合は古いものから破棄）

_AI_AUTOMOD_SYSTEM_PROMPT = (
    "あなたはDiscordサーバーの自動モデレーターです。"
    "これから複数のメッセージ（連番付き）が提示されます。それぞれについて、"
    "単純なNGワード一致では検出できない、以下のような不適切な発言かどうかを判定してください。\n"
    "・遠回しな言い方や隠語・言い換えによる誹謗中傷・侮辱・嫌がらせ\n"
    "・荒らし行為（意図的な妨害、挑発、スパム的な連投を想起させる内容）\n"
    "・差別・ヘイトを助長する内容（直接的な表現でなくても）\n"
    "・詐欺・違法な勧誘（遠回しな表現を含む）\n"
    "通常の雑談、冗談、議論、感情表現（明確な誹謗中傷を伴わないもの）は不適切と判定しないでください。"
    "判定に迷う場合は「不適切ではない」側に倒してください（過検知を避けるため）。\n\n"
    "必ず次のJSON配列形式のみで出力してください。説明文やコードブロックは不要です。\n"
    '[{"id": 連番, "flagged": true または false, "reason": "簡潔な理由（日本語、30文字以内。flagged=falseなら空文字でよい）"}, ...]\n'
    "配列の要素数は必ず提示されたメッセージ数と一致させてください。"
)

# {(guild_id, channel_id, message_id): {"content": str, "author_id": int, "queued_at": epoch}}
_ai_automod_queue: dict = {}
_ai_automod_loop_task: Optional[asyncio.Task] = None


def _ai_automod_enqueue(message: discord.Message):
    """AIモデレーション判定用にメッセージをキューへ積みます。"""
    if not message.content or not message.content.strip():
        return  # 添付ファイルのみ等、判定対象テキストが無いものはスキップ

    key = (message.guild.id, message.channel.id, message.id)
    _ai_automod_queue[key] = {
        "content": message.content[:800],  # 極端に長い発言はトークン節約のため切り詰める
        "author_id": message.author.id,
        "queued_at": time.time(),
    }

    # キューが上限を超えたら、古いものから破棄する（バッチ処理が追いつかない状況への保険）
    if len(_ai_automod_queue) > AI_AUTOMOD_MAX_QUEUE_SIZE:
        oldest_keys = sorted(_ai_automod_queue.keys(), key=lambda k: _ai_automod_queue[k]["queued_at"])
        for old_key in oldest_keys[:len(_ai_automod_queue) - AI_AUTOMOD_MAX_QUEUE_SIZE]:
            _ai_automod_queue.pop(old_key, None)


async def _ai_automod_judge_batch(items: list, guild_id: Optional[int] = None) -> dict:
    """
    items: [(key, content), ...] 形式のバッチをGroqへ送り、判定結果を取得します。
    戻り値: {index(int): (flagged: bool, reason: str)}
    Groq呼び出しや解析に失敗した場合は空の辞書を返します（安全側＝何もしない）。
    """
    if not items:
        return {}

    numbered_lines = "\n".join(f"{i}. {content}" for i, (_key, content) in enumerate(items))
    messages = [
        {"role": "system", "content": _AI_AUTOMOD_SYSTEM_PROMPT},
        {"role": "user", "content": numbered_lines},
    ]

    try:
        provider_override = await _ai_get_provider_override(guild_id)
        raw, _provider = await _ai_call_llm_with_fallback(messages, provider_override=provider_override)
    except Exception as e:
        print(f"[AI自動モデレーション] LLM呼び出しに失敗: {e}")
        return {}

    cleaned = raw.strip()
    if cleaned.startswith("```"):
        cleaned = re.sub(r"^```(?:json)?\s*|\s*```$", "", cleaned, flags=re.IGNORECASE | re.DOTALL).strip()

    try:
        parsed = json.loads(cleaned)
        if not isinstance(parsed, list):
            raise ValueError("配列形式ではありません")
    except (json.JSONDecodeError, ValueError) as e:
        print(f"[AI自動モデレーション] 判定結果の解析に失敗: {e} / raw={cleaned[:200]}")
        return {}

    results = {}
    for entry in parsed:
        if not isinstance(entry, dict):
            continue
        try:
            idx = int(entry.get("id"))
        except (TypeError, ValueError):
            continue
        flagged = bool(entry.get("flagged", False))
        reason = str(entry.get("reason", "")).strip() or "不適切な発言と判定されました"
        results[idx] = (flagged, reason)

    return results


async def _ai_automod_process_batch():
    """
    キューに溜まったメッセージを、サーバーごとに（automod_ai_enabledが有効なサーバーのみ）
    グループ化してバッチ判定し、フラグが立ったメッセージを削除・警告付与します。
    """
    if not _ai_automod_queue:
        return
    if not GROQ_API_KEY:
        _ai_automod_queue.clear()
        return

    all_data = load_data()

    # サーバーごとにグループ化
    by_guild: dict = {}
    for key, info in _ai_automod_queue.items():
        guild_id = key[0]
        by_guild.setdefault(guild_id, []).append((key, info))
    _ai_automod_queue.clear()

    for guild_id, entries in by_guild.items():
        guild_config = all_data.get(str(guild_id))
        if not isinstance(guild_config, dict) or not guild_config.get("automod_ai_enabled", False):
            continue  # 機能が無効なサーバーのキューは判定せず破棄

        guild = bot.get_guild(guild_id)
        if guild is None:
            continue

        # 1回のバッチサイズ上限を超える場合は分割して処理（古い順）
        entries.sort(key=lambda e: e[1]["queued_at"])
        for batch_start in range(0, len(entries), AI_AUTOMOD_MAX_BATCH_SIZE):
            batch = entries[batch_start:batch_start + AI_AUTOMOD_MAX_BATCH_SIZE]
            items = [(key, info["content"]) for key, info in batch]
            results = await _ai_automod_judge_batch(items, guild_id=guild_id)

            for idx, (key, info) in enumerate(batch):
                flagged, reason = results.get(idx, (False, ""))
                if not flagged:
                    continue

                _guild_id, channel_id, message_id = key
                channel = guild.get_channel(channel_id)
                if channel is None:
                    continue

                member = guild.get_member(info["author_id"])
                if member is None:
                    continue

                # モデレーター・管理者・許可ユーザー等は対象外（automod共通ルールを踏襲）
                if not _is_automod_target(member, guild_config, all_data):
                    continue

                try:
                    target_message = await channel.fetch_message(message_id)
                    await target_message.delete()
                except (discord.NotFound, discord.Forbidden, discord.HTTPException):
                    pass

                # 警告を1件追加（Bot自身を担当者として記録）
                warnings_dict = guild_config.setdefault("warnings", {})
                user_warnings = warnings_dict.setdefault(str(member.id), [])
                user_warnings.append({
                    "reason": f"[AI自動検知] {reason}",
                    "date": datetime.datetime.now(datetime.timezone.utc).isoformat(),
                    "moderator": bot.user.id if bot.user else 0,
                })

                try:
                    await channel.send(
                        f"[AI自動モデレーション] {member.mention} の発言を削除し、警告を追加しました。\n理由: {reason}",
                        delete_after=10
                    )
                except (discord.Forbidden, discord.HTTPException):
                    pass

                try:
                    await member.send(
                        f"[警告] **{guild.name}** でAI自動モデレーションにより発言が削除され、警告が追加されました。\n理由: {reason}"
                    )
                except (discord.Forbidden, discord.HTTPException):
                    pass

                log_embed = discord.Embed(
                    title="[ログ] AI自動モデレーション - 発言削除・警告",
                    color=discord.Color.red()
                )
                log_embed.add_field(name="対象ユーザー", value=f"{member.mention} (`{member.id}`)", inline=False)
                log_embed.add_field(name="チャンネル", value=channel.mention if hasattr(channel, "mention") else str(channel_id), inline=True)
                log_embed.add_field(name="判定理由", value=reason, inline=False)
                log_embed.timestamp = discord.utils.utcnow()
                try:
                    await _send_mod_log(guild, log_embed)
                except Exception:
                    pass

        save_data(all_data)


async def _ai_automod_loop():
    """一定間隔でAIモデレーションのバッチ判定を実行するループタスクです。"""
    await bot.wait_until_ready()
    while True:
        try:
            await _ai_automod_process_batch()
        except Exception as e:
            print(f"[AI自動モデレーション] ループ内エラー: {e}")
        await asyncio.sleep(AI_AUTOMOD_BATCH_INTERVAL_SECONDS)


# ====================================================================
# Vibeモニター（サーバーの空気・緊張度をAIが監視する機能）
# ====================================================================
# 既存のAI自動モデレーション（_ai_automod_*）は「1件ずつの発言」が
# 誹謗中傷・荒らしに該当するかを個別判定し、該当すれば削除・警告する仕組みです。
# Vibeモニターはそれとは異なり、削除・警告のような介入は一切行わず、
# 「チャンネル全体の会話の流れ」を定期的にAIへまとめて見せ、
# 険悪さ・煽り合いの兆候といった空気感を 1〜10 のスコアで評価してもらい、
# スコアが閾値を超えたときだけ管理者向けに通知するという、
# 早期警戒・可視化のための補助機能です（自動介入はしません＝誤判定リスクを抑える設計）。

_VIBE_SYSTEM_PROMPT = (
    "あなたはDiscordサーバーの空気（雰囲気）を分析する観測者です。"
    "これから1つのチャンネルにおける直近の会話ログ（発言者名: 発言内容 の連続）が提示されます。"
    "その場の空気がどれくらい険悪・緊迫しているかを 1（穏やか・平常）〜10（激しい喧嘩・大荒れ）の"
    "整数スコアで評価してください。\n"
    "評価の際は次の点を考慮してください。\n"
    "・単なる activeな雑談、ノリの良い冗談、ゲームでの興奮した発言は高スコアにしないでください。\n"
    "・特定の個人への継続的な攻撃、罵り合いのエスカレーション、複数人が険悪になっている兆候を重視してください。\n"
    "・判定に迷う場合は低め（穏当な方）に倒してください（過検知を避けるため）。\n\n"
    "必ず次のJSON形式のみで出力してください。説明文やコードブロックは不要です。\n"
    '{"score": 1から10の整数, "reason": "日本語で40文字以内の簡潔な理由", "summary": "会話で今何が起きているかの日本語一行要約(30文字以内)"}'
)

# {channel_id: [{"author": str, "content": str, "ts": epoch}, ...]}
_vibe_monitor_buffer: dict = {}
_vibe_monitor_loop_task: Optional[asyncio.Task] = None

VIBE_MONITOR_BUFFER_MAX = 25          # チャンネルあたり最大バッファ件数（超えたら古い順に判定対象へ）
VIBE_MONITOR_MIN_MESSAGES = 6         # この件数未満では判定を行わない（材料不足のため）
VIBE_MONITOR_LOOP_INTERVAL_SECONDS = 60  # 何秒おきに各チャンネルのバッファを確認するか
VIBE_MONITOR_ALERT_COOLDOWN_SECONDS = 600  # 同一チャンネルでの再アラートまでの最短間隔


def _vibe_monitor_enqueue(message: discord.Message):
    """Vibeモニター用に発言をバッファへ積みます（判定は別タスクでバッチ実行）。"""
    if not message.content or not message.content.strip():
        return

    channel_id = message.channel.id
    buf = _vibe_monitor_buffer.setdefault(channel_id, [])
    buf.append({
        "author": str(message.author.display_name)[:32],
        "content": message.content[:300],
        "ts": time.time(),
    })
    if len(buf) > VIBE_MONITOR_BUFFER_MAX:
        del buf[: len(buf) - VIBE_MONITOR_BUFFER_MAX]


async def _vibe_monitor_judge(channel_id: int, guild_id: int) -> Optional[dict]:
    """バッファ中の会話ログをAIに渡し、緊張度スコアを取得します。失敗時はNoneを返します。"""
    buf = _vibe_monitor_buffer.get(channel_id) or []
    if len(buf) < VIBE_MONITOR_MIN_MESSAGES:
        return None

    log_lines = "\n".join(f"{item['author']}: {item['content']}" for item in buf)
    messages = [
        {"role": "system", "content": _VIBE_SYSTEM_PROMPT},
        {"role": "user", "content": log_lines},
    ]

    try:
        provider_override = await _ai_get_provider_override(guild_id)
        raw, _provider = await _ai_call_llm_with_fallback(messages, provider_override=provider_override)
    except Exception as e:
        print(f"[Vibeモニター] LLM呼び出しに失敗: {e}")
        return None

    parsed = _ai_extract_json_response(raw)
    if not isinstance(parsed, dict):
        return None

    try:
        score = int(parsed.get("score"))
    except (TypeError, ValueError):
        return None
    score = max(1, min(10, score))

    return {
        "score": score,
        "reason": str(parsed.get("reason", "")).strip()[:100] or "詳細不明",
        "summary": str(parsed.get("summary", "")).strip()[:60],
    }


async def _vibe_monitor_process_all():
    """全チャンネルのバッファを確認し、vibe_monitor_enabledなサーバーのみ判定・通知します。"""
    if not _vibe_monitor_buffer:
        return
    if not GROQ_API_KEY:
        return

    all_data = load_data()
    target_channel_ids = list(_vibe_monitor_buffer.keys())
    data_dirty = False

    for channel_id in target_channel_ids:
        channel = bot.get_channel(channel_id)
        if channel is None or not hasattr(channel, "guild") or channel.guild is None:
            _vibe_monitor_buffer.pop(channel_id, None)
            continue

        guild = channel.guild
        guild_config = get_guild_config(all_data, str(guild.id))
        if not guild_config.get("vibe_monitor_enabled", False):
            # 無効化されているサーバーのバッファは溜め続けても無意味なので破棄
            _vibe_monitor_buffer.pop(channel_id, None)
            continue

        result = await _vibe_monitor_judge(channel_id, guild.id)
        # 判定を消費したら（成功/失敗問わず）バッファはクリアし、以降の会話で再蓄積させる
        _vibe_monitor_buffer.pop(channel_id, None)

        if result is None:
            continue

        threshold = guild_config.get("vibe_monitor_threshold", 7)
        if result["score"] < threshold:
            continue

        # クールダウン確認（チャンネルごと）
        last_alert_map = guild_config.setdefault("vibe_monitor_last_alert_ts", {})
        last_ts = last_alert_map.get(str(channel_id), 0)
        now_ts = time.time()
        if now_ts - last_ts < VIBE_MONITOR_ALERT_COOLDOWN_SECONDS:
            continue

        notify_channel_id = guild_config.get("vibe_monitor_channel_id") or channel_id
        notify_channel = guild.get_channel(notify_channel_id)
        if notify_channel is None:
            notify_channel = channel

        embed = discord.Embed(
            title="[Vibeモニター] 空気の緊張度が高まっています",
            description=(
                f"チャンネル: {channel.mention if hasattr(channel, 'mention') else channel_id}\n"
                f"緊張度スコア: **{result['score']}/10**\n"
                f"状況: {result['summary'] or '（要約なし）'}\n"
                f"理由: {result['reason']}"
            ),
            color=discord.Color.orange()
        )
        embed.set_footer(text="これは自動介入ではなく通知のみです。必要に応じて状況を確認してください。")
        try:
            await notify_channel.send(embed=embed)
        except (discord.Forbidden, discord.HTTPException):
            pass

        last_alert_map[str(channel_id)] = now_ts
        data_dirty = True

    if data_dirty:
        save_data(all_data)


async def _vibe_monitor_loop():
    """一定間隔でVibeモニターのバッチ判定を実行するループタスクです。"""
    await bot.wait_until_ready()
    while True:
        try:
            await _vibe_monitor_process_all()
        except Exception as e:
            print(f"[Vibeモニター] ループ内エラー: {e}")
        await asyncio.sleep(VIBE_MONITOR_LOOP_INTERVAL_SECONDS)


@bot.event
async def on_message_delete(message: discord.Message):
    if message.author.bot or not message.guild:
        return
    embed = discord.Embed(
        title="[ログ] メッセージ削除",
        description=f"**送信者:** {message.author.mention}\n**チャンネル:** {message.channel.mention}",
        color=discord.Color.red()
    )
    embed.add_field(name="内容", value=message.content or "（内容なし / Embed・画像など）", inline=False)
    await _send_mod_log(message.guild, embed)


@bot.event
async def on_message_edit(before: discord.Message, after: discord.Message):
    """
    メッセージ編集時に呼び出されます。
    ① 監査ログへの記録
    ② 編集後テキストへの招待リンク・NGワード自動モデレーション
    （スパム検知はメッセージ数が変わらないため対象外）
    """
    if before.author.bot or not before.guild or before.content == after.content:
        return

    # --- ① 監査ログ記録 ---
    embed = discord.Embed(
        title="[ログ] メッセージ編集",
        description=(
            f"**送信者:** {before.author.mention}\n"
            f"**チャンネル:** {before.channel.mention}\n"
            f"[メッセージへジャンプ]({after.jump_url})"
        ),
        color=discord.Color.yellow()
    )
    embed.add_field(name="編集前", value=before.content or "（なし）", inline=False)
    embed.add_field(name="編集後", value=after.content or "（なし）", inline=False)
    await _send_mod_log(before.guild, embed)

    # --- ② 編集後メッセージへの自動モデレーション ---
    guild_id_str = str(after.guild.id)
    all_data = load_data()

    if guild_id_str not in all_data:
        return

    guild_config = all_data[guild_id_str]

    # 招待リンク削除は管理者権限を持つ一般メンバーも対象に含めるため、
    # ここでは _is_automod_target による早期returnを行わず、
    # _run_automod_checks 内部の個別判定（_is_invite_automod_target等）に委ねる。
    deleted = await _run_automod_checks(after, guild_config, all_data)
    if deleted and guild_config.get("automod_invite_enabled", False):
        after_scan_lower = "\n".join(_collect_automod_scan_texts(after)).lower()
        if any(kw in after_scan_lower for kw in ("discord.gg/", "discord.com/invite/", "discord.me/", "dsc.gg/")):
            # チャンネル全体の過去メッセージをスキャンして即削除（直近100件）
            try:
                async for msg in after.channel.history(limit=100):
                    if msg.id == after.id:
                        continue
                    if msg.author.bot:
                        continue
                    if not _is_invite_automod_target(msg.author, guild_config, all_data):
                        continue
                    m_scan_lower = "\n".join(_collect_automod_scan_texts(msg)).lower()
                    if any(kw in m_scan_lower for kw in ("discord.gg/", "discord.com/invite/", "discord.me/", "dsc.gg/")):
                        try:
                            await msg.delete()
                        except Exception:
                            pass
            except Exception as e:
                print(f"[自動モデレーション] チャンネルスキャンエラー: {e}")



@bot.event
async def on_member_join(member: discord.Member):
    all_data = load_data()
    cfg = get_guild_config(all_data, str(member.guild.id))

    # =========================================================
    # 荒らしリスト（ブラックリスト）: 登録済みユーザーを参加時に自動BAN
    # =========================================================
    if cfg.get("troll_autoban_enabled", False):
        global_cfg_check = get_global_config(all_data)
        troll_entry = global_cfg_check.get("troll_list", {}).get(str(member.id))
        if troll_entry:
            try:
                await member.ban(
                    reason=f"荒らしリスト(ブラックリスト)登録ユーザーのため自動BAN: {troll_entry.get('reason', '不明')}"
                )
                add_to_troll_list(
                    all_data, member, member.guild,
                    reason=troll_entry.get("reason", "荒らしリスト登録ユーザー")
                )
                save_data(all_data)

                ban_embed = discord.Embed(
                    title="[BL] 荒らしリスト自動BAN",
                    description=f"{member.mention} (`{member.id}`) は荒らしリスト（ブラックリスト）に登録されているため、参加時に自動BANされました。",
                    color=discord.Color.red()
                )
                ban_embed.set_thumbnail(url=member.display_avatar.url)
                ban_embed.add_field(name="登録理由", value=troll_entry.get("reason", "不明"), inline=False)
                ban_embed.add_field(name="登録日時", value=(troll_entry.get("date", "") or "不明")[:19].replace("T", " "), inline=True)
                ban_embed.timestamp = discord.utils.utcnow()
                await _send_mod_log(member.guild, ban_embed)
                print(f"[荒らしリスト] {member} を自動BANしました。")
                return  # BAN済みのため以降のウェルカム処理等は行わない
            except discord.Forbidden:
                print(f"[荒らしリスト] {member} の自動BAN権限がありません。Botのロール権限をご確認ください。")
            except Exception as e:
                print(f"[荒らしリスト] 自動BANエラー: {e}")
            # BANに失敗した場合は通常の参加処理を続行する

    embed = discord.Embed(
        title="[ログ] メンバー参加",
        description=f"{member.mention} (`{member.id}`)",
        color=discord.Color.green()
    )
    embed.set_thumbnail(url=member.display_avatar.url)
    embed.add_field(name="アカウント作成日時", value=member.created_at.strftime("%Y/%m/%d %H:%M:%S UTC"), inline=False)

    # =========================================================
    # 招待トラッキング: どの招待コード・誰の招待で参加したかを特定して記録
    # =========================================================
    if cfg.get("invite_tracking_enabled", True):
        try:
            used_invite = await _identify_used_invite(member)
            if used_invite is not None:
                inviter = used_invite.inviter
                if inviter is not None:
                    inviter_id_str = str(inviter.id)
                    record_invite_stat(all_data, str(member.guild.id), inviter_id_str, joined=True)
                    cfg.setdefault("invite_join_log", {})[str(member.id)] = inviter_id_str
                    embed.add_field(
                        name="招待元",
                        value=f"{inviter.mention}（コード: `{used_invite.code}`）",
                        inline=False
                    )
                else:
                    # Vanity URL等、招待者不明のケース
                    embed.add_field(name="招待元", value=f"不明（コード: `{used_invite.code}`）", inline=False)
        except Exception as e:
            print(f"[招待トラッキング] 参加時の招待元特定エラー: {e}")

    await _send_mod_log(member.guild, embed)

    # 荒らし対策: 隔離ロールの自動付与（未認証状態にする）
    await _grant_arasi_quarantine_role(member, cfg)

    # ウェルカムメッセージ送信
    welcome_ch_id = cfg.get("welcome_channel_id")
    welcome_msg = cfg.get("welcome_message")
    welcome_role_id = cfg.get("welcome_role_id")

    if welcome_ch_id and welcome_msg:
        ch = member.guild.get_channel(welcome_ch_id)
        if ch:
            try:
                # {user} {server} {count} プレースホルダー対応
                formatted = welcome_msg.replace("{user}", member.mention)
                formatted = formatted.replace("{username}", str(member))
                formatted = formatted.replace("{server}", member.guild.name)
                formatted = formatted.replace("{count}", str(member.guild.member_count))
                welcome_embed = discord.Embed(
                    description=formatted,
                    color=discord.Color.green()
                )
                welcome_embed.set_thumbnail(url=member.display_avatar.url)
                welcome_embed.set_footer(text=f"{member.guild.name} へようこそ！")
                await ch.send(embed=welcome_embed)
            except Exception as e:
                print(f"[ウェルカム送信エラー] {e}")

    if welcome_role_id:
        role = member.guild.get_role(welcome_role_id)
        if role:
            try:
                await member.add_roles(role, reason="ウェルカム自動ロール付与")
            except Exception:
                pass

    # alt_check: 新規アカウント検知
    alt_enabled = cfg.get("alt_check_enabled", False)
    if alt_enabled:
        threshold_days = cfg.get("alt_check_days", 30)
        account_age = (discord.utils.utcnow() - member.created_at).days
        if account_age < threshold_days:
            action = cfg.get("alt_check_action", "notify")
            alt_embed = discord.Embed(
                title="[!] 新規アカウント検知 (alt_check)",
                color=discord.Color.orange()
            )
            alt_embed.set_thumbnail(url=member.display_avatar.url)
            alt_embed.add_field(name="ユーザー", value=f"{member.mention} (`{member.id}`)", inline=False)
            alt_embed.add_field(name="アカウント作成日", value=member.created_at.strftime("%Y/%m/%d"), inline=True)
            alt_embed.add_field(name="アカウント日齢", value=f"{account_age}日", inline=True)
            alt_embed.add_field(name="閾値", value=f"{threshold_days}日未満", inline=True)
            alt_embed.add_field(name="実行アクション", value={"notify": "通知のみ", "kick": "キック", "ban": "BAN"}.get(action, action), inline=True)
            alt_embed.timestamp = discord.utils.utcnow()

            await _send_mod_log(member.guild, alt_embed)

            if action == "kick":
                try:
                    await member.send(
                        f"**{member.guild.name}** への参加が拒否されました。\n"
                        f"アカウントが作成されてから{threshold_days}日以上経過していないと参加できません（現在{account_age}日）。"
                    )
                except Exception:
                    pass
                try:
                    await member.kick(reason=f"alt_check: アカウント日齢 {account_age}日（閾値: {threshold_days}日）")
                except Exception:
                    pass
            elif action == "ban":
                try:
                    await member.ban(reason=f"alt_check: アカウント日齢 {account_age}日（閾値: {threshold_days}日）")
                except Exception:
                    pass

    # =========================================================
    # サーバーブラックリスト: 特定サーバー参加者を自動BAN/KICK
    # =========================================================
    if cfg.get("server_blacklist_enabled", False):
        global_bl_cfg = get_global_config(all_data)
        blacklist_ids = global_bl_cfg.get("global_server_blacklist_ids", [])
        if blacklist_ids:
            web_auth_mode = cfg.get("web_auth_mode", "panel")

            if web_auth_mode == "dm":
                # --- DMモード: 参加時に個人宛て認証URLをDMで直接送信 ---
                if OAUTH_REDIRECT_URI and DISCORD_CLIENT_ID and DISCORD_CLIENT_SECRET:
                    try:
                        state = _generate_web_auth_state(member.guild.id, member.id)
                        terms_url = _build_terms_url(state)
                        custom_title = cfg.get("web_auth_panel_title")
                        custom_desc = cfg.get("web_auth_panel_description")
                        dm_title = custom_title if custom_title else f"[!] {member.guild.name} への入室認証が必要です"
                        dm_desc = custom_desc if custom_desc else (
                            "当サーバーへ参加するには、**ウェブ認証**を完了させる必要があります。\n\n"
                            "下のリンクをクリックし、利用規約をご確認のうえ認証を進めてください。\n"
                            "他サーバーの在籍状況を確認し、問題がなければ自動的に認証が完了します。\n\n"
                            "⚠️ このリンクはあなた専用です。他の人に共有しないでください。"
                        )
                        dm_embed = discord.Embed(
                            title=dm_title,
                            description=dm_desc,
                            color=discord.Color.orange()
                        )
                        dm_embed.add_field(
                            name="認証リンク（利用規約の確認 → 認証）",
                            value=f"[ここをクリックして認証を開始する]({terms_url})",
                            inline=False
                        )
                        dm_embed.set_footer(text=f"送信元: {member.guild.name} の管理Bot")
                        await member.send(embed=dm_embed)
                        print(f"[ウェブ認証/DM] {member} に認証URL付きDMを送信しました")
                    except discord.Forbidden:
                        print(f"[ウェブ認証/DM] {member} へのDM送信に失敗しました（DM無効）")
                        # DM無効のユーザーへのフォールバック: パネルチャンネルがあれば案内
                        verify_ch_id = cfg.get("server_blacklist_verify_channel_id")
                        if verify_ch_id:
                            ch = member.guild.get_channel(verify_ch_id)
                            if ch:
                                try:
                                    await ch.send(
                                        f"{member.mention} DMが届かなかったため、こちらで認証をお願いします。",
                                        delete_after=60
                                    )
                                except Exception:
                                    pass
                    except Exception as e:
                        print(f"[ウェブ認証/DM] DM送信エラー: {e}")
                else:
                    print(f"[ウェブ認証/DM] OAuth2設定が不完全なためDMを送信できません（{member}）")

            else:
                # --- パネルモード（従来動作）: 認証チャンネルへ誘導するDMを送信 ---
                verify_ch_id = cfg.get("server_blacklist_verify_channel_id")
                if verify_ch_id:
                    try:
                        dm_embed = discord.Embed(
                            title=f"[!] {member.guild.name} への入室認証について",
                            description=(
                                f"当サーバーへ参加するには、認証チャンネル <#{verify_ch_id}> にて\n"
                                "外部サービスアカウント連携認証を完了させてください。"
                            ),
                            color=discord.Color.orange()
                        )
                        await member.send(embed=dm_embed)
                        print(f"[サーバーBL] {member} に認証案内DMを送信しました")
                    except discord.Forbidden:
                        print(f"[サーバーBL] {member} へのDM送信に失敗しました（DM無効）")
                    except Exception as e:
                        print(f"[サーバーBL] DM送信エラー: {e}")

    # 招待トラッキング等、この関数内で all_data に加えた変更を保存
    save_data(all_data)


@bot.event
async def on_member_ban(guild: discord.Guild, user: discord.User):
    """
    メンバーがBANされた際に発火します（/moderation ban 経由でも、Discord標準のBAN機能でも、
    alt_check・ip_ban_check自身のBANでも発火します）。
    IP対策(ip_ban_check)が有効な場合、このユーザーが直近のウェブ認証時に記録したIPハッシュを
    「BAN済みIPハッシュ一覧」へ移行します。以降、同じIPで別アカウントが認証しに来ると検知されます。
    """
    try:
        all_data = load_data()
        guild_id_str = str(guild.id)
        cfg = get_guild_config(all_data, guild_id_str)

        if not cfg.get("ip_ban_check_enabled", False):
            return

        ip_hashes = cfg.get("ip_hashes", {})
        ip_hash = ip_hashes.pop(str(user.id), None)
        if not ip_hash:
            return  # このユーザーはウェブ認証を経由していない（IPを記録していない）

        banned_ip_hashes = cfg.setdefault("banned_ip_hashes", {})
        banned_ip_hashes[ip_hash] = {
            "banned_user_id": str(user.id),
            "date": discord.utils.utcnow().strftime("%Y/%m/%d %H:%M")
        }
        save_data(all_data)
        print(f"[ip_ban_check] {user} (guild={guild.id}) のIPハッシュをBAN済みリストへ登録しました")
    except Exception as e:
        print(f"[ip_ban_check] on_member_ban処理エラー: {e}")


@bot.event
async def on_member_remove(member: discord.Member):
    embed = discord.Embed(
        title="[ログ] メンバー退出",
        description=f"{member.mention} (`{member.id}`)",
        color=discord.Color.dark_gray()
    )
    embed.set_thumbnail(url=member.display_avatar.url)
    await _send_mod_log(member.guild, embed)

    # 招待トラッキング: 招待元がいれば退出数を加算し、AFK登録も後片付けする
    all_data = load_data()
    guild_id_str = str(member.guild.id)
    cfg = get_guild_config(all_data, guild_id_str)
    changed = False

    inviter_id_str = cfg.get("invite_join_log", {}).pop(str(member.id), None)
    if inviter_id_str:
        record_invite_stat(all_data, guild_id_str, inviter_id_str, joined=False)
        changed = True

    if str(member.id) in cfg.get("afk_users", {}):
        clear_afk_status(all_data, guild_id_str, str(member.id))
        changed = True

    if changed:
        save_data(all_data)


@bot.event
async def on_audit_log_entry_create(entry: discord.AuditLogEntry):
    """監査ログ作成時に呼び出されます。短期間の連続操作を検知して緊急処置を起動します。"""
    guild = entry.guild
    if not guild:
        return

    all_data = load_data()
    cfg = get_antinuke_config(all_data, str(guild.id))
    if not cfg.get("enabled"):
        return

    action_map = {
        discord.AuditLogAction.ban:             "ban_member",
        discord.AuditLogAction.channel_delete:  "channel_delete",
        discord.AuditLogAction.role_delete:     "role_delete",
        discord.AuditLogAction.webhook_create:  "webhook_create",
    }
    action_type = action_map.get(entry.action)
    if action_type is None:
        return

    user = entry.user
    if user is None:
        return

    member = guild.get_member(user.id)
    if member is None:
        return

    owner_id_for_exempt = await resolve_owner_id(bot)

    if _is_exempt(member, guild, cfg, owner_id_for_exempt):
        return

    _record_action(guild.id, member.id, action_type)
    threshold_count   = cfg.get("threshold_count", 3)
    threshold_seconds = cfg.get("threshold_seconds", 10)
    recent_count = _count_within_window(guild.id, member.id, action_type, threshold_seconds)

    if recent_count >= threshold_count:
        asyncio.create_task(_handle_nuke_detected(guild, member, action_type, cfg))


@bot.event
async def on_guild_role_create(role: discord.Role):
    """荒らし対策（/server protect arasi_setup）: 新規作成されたロールの『@everyoneメンション』
    『外部アプリのスラッシュコマンド使用』権限を自動でOFFにします。"""
    guild = role.guild
    all_data = load_data()
    cfg = get_guild_config(all_data, str(guild.id))

    if not cfg.get("arasi_newrole_autolimit_enabled", True):
        return

    # @everyoneロール自体や、権限変更が不要なケースはスキップ
    if role.is_default():
        return
    if not role.permissions.mention_everyone and not role.permissions.use_external_apps:
        return

    new_permissions = role.permissions
    new_permissions.update(mention_everyone=False, use_external_apps=False)

    try:
        await role.edit(permissions=new_permissions, reason="荒らし対策: 新規ロールのメンション/外部コマンド権限を自動OFF")
    except discord.Forbidden:
        print(f"[荒らし対策] ロール「{role.name}」の権限自動制限に失敗しました（Botの権限不足）。")
    except discord.HTTPException as e:
        print(f"[荒らし対策] ロール「{role.name}」の権限自動制限に失敗しました: {e}")


@bot.event
async def on_guild_channel_create(channel: discord.abc.GuildChannel):
    """荒らし対策（/server protect arasi_setup）: 新規作成されたチャンネルを隔離ロールから見えないようにします。
    認証チャンネルとして設定されているチャンネルのみ、閲覧を許可します。
    カテゴリーチャンネルは対象外（個々のテキスト/ボイス等チャンネルのみ処理）です。"""
    if isinstance(channel, discord.CategoryChannel):
        return

    guild = channel.guild
    all_data = load_data()
    cfg = get_guild_config(all_data, str(guild.id))

    role_id = cfg.get("arasi_quarantine_role_id")
    if not role_id:
        return
    role = guild.get_role(role_id)
    if role is None:
        return

    verify_channel_id = cfg.get("arasi_verify_channel_id")
    is_verify_channel = verify_channel_id is not None and channel.id == verify_channel_id

    try:
        if is_verify_channel:
            await channel.set_permissions(
                role,
                view_channel=True,
                send_messages=False,
                add_reactions=False,
                reason="荒らし対策: 新規作成された認証チャンネルに隔離ロールの閲覧を許可"
            )
        else:
            await channel.set_permissions(
                role,
                view_channel=False,
                send_messages=False,
                reason="荒らし対策: 新規作成されたチャンネルを隔離ロールから非表示に設定"
            )
    except discord.Forbidden:
        print(f"[荒らし対策] チャンネル「{channel.name}」の隔離ロール権限設定に失敗しました（Botの権限不足）。")
    except discord.HTTPException as e:
        print(f"[荒らし対策] チャンネル「{channel.name}」の隔離ロール権限設定に失敗しました: {e}")


@bot.event
async def on_guild_channel_delete(channel: discord.abc.GuildChannel):
    """
    チャンネルが削除された際、そのチャンネルでAIディベートが実行中であれば
    バックグラウンドタスクを停止します（削除済みチャンネルへの送信でエラーが
    出続けるのを防ぐため）。
    """
    session = _ai_debate_sessions.get(channel.id)
    if session is None:
        return
    session["stopped"] = True
    task = session.get("task")
    if task and not task.done():
        task.cancel()
    _ai_debate_sessions.pop(channel.id, None)
    print(f"[AIディベート] チャンネル「{channel.name}」が削除されたためディベートを停止しました。")


async def _grant_arasi_quarantine_role(member: discord.Member, cfg: dict):
    """荒らし対策（/server protect arasi_setup）: 新規参加者に隔離ロールを自動付与します。
    隔離ロールが未設定・存在しない場合は何もしません（エラーにしません）。"""
    role_id = cfg.get("arasi_quarantine_role_id")
    if not role_id:
        return
    role = member.guild.get_role(role_id)
    if role is None:
        return
    try:
        await member.add_roles(role, reason="荒らし対策: 新規参加者に隔離ロールを自動付与")
    except discord.Forbidden:
        print(f"[荒らし対策] {member} への隔離ロール付与権限がありません。")
    except discord.HTTPException as e:
        print(f"[荒らし対策] {member} への隔離ロール付与に失敗しました: {e}")


async def _remove_arasi_quarantine_role(member: discord.Member, cfg: dict):
    """荒らし対策（/server protect arasi_setup）: 認証完了時に隔離ロールを解除します。
    隔離ロールが未設定・付与されていない場合は何もしません（エラーにしません）。
    ボタン認証・ウェブ認証の両方の完了処理から呼び出されます。"""
    role_id = cfg.get("arasi_quarantine_role_id")
    if not role_id:
        return
    role = member.guild.get_role(role_id)
    if role is None:
        return
    if role not in member.roles:
        return
    try:
        await member.remove_roles(role, reason="荒らし対策: 認証完了により隔離ロールを解除")
    except discord.Forbidden:
        print(f"[荒らし対策] {member} の隔離ロール解除権限がありません。")
    except discord.HTTPException as e:
        print(f"[荒らし対策] {member} の隔離ロール解除に失敗しました: {e}")


