@say_group.command(name="text", description="指定したメッセージをBotに代わりに発言してもらいます")
@app_commands.describe(
    message="Botに発言させる内容",
    reply_to_message_id="このメッセージID宛に返信（リプライ）形式で送信したい場合に指定します（省略時は通常送信）"
)
@app_commands.allowed_contexts(guilds=True, dms=True, private_channels=True)
@app_commands.allowed_installs(guilds=True, users=True)
async def say(interaction: discord.Interaction, message: str, reply_to_message_id: str = None):
    # DM・グループDMの場合はBotオーナーまたは信頼ユーザー(owner_trust)のみ許可、サーバー内は通常の権限チェック
    if not interaction.guild:
        # DM / グループDM
        if not await is_trusted_user(interaction):
            return
    else:
        # サーバー内は従来の権限チェック
        if not await is_admin_or_allowed(interaction):
            return

    # 返信先メッセージIDが指定されている場合は事前に解析・取得しておく
    target_message = None
    if reply_to_message_id:
        try:
            target_message_id = int(reply_to_message_id.strip())
        except ValueError:
            await interaction.response.send_message(
                "メッセージIDの形式が正しくありません。数字のみで指定してください。", ephemeral=True
            )
            return

        if interaction.channel:
            try:
                target_message = await interaction.channel.fetch_message(target_message_id)
            except discord.NotFound:
                await interaction.response.send_message(
                    "指定されたメッセージIDがこのチャンネル内で見つかりませんでした。", ephemeral=True
                )
                return
            except discord.Forbidden:
                await interaction.response.send_message(
                    "そのメッセージを取得する権限がありません。", ephemeral=True
                )
                return
        else:
            await interaction.response.send_message(
                "このコンテキストではメッセージID指定の返信を利用できません。", ephemeral=True
            )
            return

    try:
        if interaction.guild:
            # サーバー内: Botがチャンネルへの通常アクセス権を持っているため、
            # 従来通りチャンネル送信・メッセージへのリプライを行う
            if target_message:
                await target_message.reply(message, mention_author=False)
            else:
                channel = interaction.channel
                if channel is None:
                    try:
                        channel = await interaction.client.fetch_channel(interaction.channel_id)
                    except (discord.Forbidden, discord.HTTPException, discord.NotFound):
                        channel = None

                if channel is not None:
                    await channel.send(message)
                else:
                    await interaction.response.send_message(message)
                    return

            await interaction.response.send_message("メッセージを送信しました。", ephemeral=True)

        else:
            # DM・グループDM: ユーザーインストールされたBotはチャンネルへの
            # 直接アクセス権限を持たないため、チャンネル送信やメッセージへの
            # リプライ（reply）はできない。インタラクションの応答（Webhook経由）
            # のみが送信手段となるため、常にこちらを使う。
            # ※この方法では特定メッセージへの「返信」形式にはできないため、
            #   reply_to_message_id が指定されていた場合は引用形式で代替する。
            if target_message:
                quoted = target_message.content or "(内容なし/添付ファイルのみ)"
                quoted = quoted if len(quoted) <= 200 else quoted[:200] + "…"
                content = f"> {quoted}\n{message}"
            else:
                content = message
            await interaction.response.send_message(content)

    except discord.Forbidden:
        await interaction.response.send_message(
            "このチャンネルにメッセージを送信する権限がBotにありません。", ephemeral=True
        )
    except discord.HTTPException as e:
        await interaction.response.send_message(
            f"メッセージの送信に失敗しました: {e}", ephemeral=True
        )


