@server_group.command(name="role_bulk_create", description="【管理者専用】カンマ区切りで名前を並べるだけで、複数のロールをまとめて作れます")
@app_commands.describe(
    role_names="作成したいロール名をカンマ（,）区切りで入力してください（例: 初心者,中級者,上級者）",
    color="作成する全ロールに適用する色（16進数カラーコード、例: ff0000）。省略時はデフォルト色",
    hoist="メンバーリストでロールごとに表示を分ける（デフォルト: しない）",
    mentionable="このロールを誰でもメンションできるようにする（デフォルト: しない）"
)
async def server_role_bulk_create(
    interaction: discord.Interaction,
    role_names: str,
    color: str = None,
    hoist: bool = False,
    mentionable: bool = False
):
    if not await is_guild_admin(interaction): return
    if not interaction.guild: return

    # カンマ区切りで分解し、空白除去・空文字除外
    names = [n.strip() for n in role_names.split(",") if n.strip()]
    if not names:
        await interaction.response.send_message(
            "作成するロール名が指定されていません。カンマ（,）区切りで1つ以上入力してください。", ephemeral=True
        )
        return
    if len(names) > 20:
        await interaction.response.send_message(
            "一度に作成できるロールは20個までです。件数を減らして再度お試しください。", ephemeral=True
        )
        return

    # 色の解析（未指定時はデフォルト色）
    role_color = discord.Color.default()
    if color:
        color_str = color.strip().lstrip("#")
        try:
            role_color = discord.Color(int(color_str, 16))
        except ValueError:
            await interaction.response.send_message(
                "カラーコードの形式が正しくありません。16進数（例: ff0000）で指定してください。", ephemeral=True
            )
            return

    await interaction.response.defer(ephemeral=True)

    created = []
    failed = []
    for name in names:
        try:
            new_role = await interaction.guild.create_role(
                name=name,
                color=role_color,
                hoist=hoist,
                mentionable=mentionable,
                reason=f"{interaction.user} によるロール一括作成"
            )
            created.append(new_role)
        except discord.Forbidden:
            failed.append((name, "Botの権限不足"))
        except discord.HTTPException as e:
            failed.append((name, str(e)))

    embed = discord.Embed(
        title="[ロール一括作成] 結果",
        color=discord.Color.green() if created else discord.Color.red()
    )
    if created:
        embed.add_field(
            name=f"✅ 作成成功（{len(created)}件）",
            value="\n".join(r.mention for r in created),
            inline=False
        )
    if failed:
        embed.add_field(
            name=f"❌ 作成失敗（{len(failed)}件）",
            value="\n".join(f"・{name}: {reason}" for name, reason in failed),
            inline=False
        )
    await interaction.followup.send(embed=embed, ephemeral=True)


@server_group.command(name="disable_external_apps", description="【管理者専用】サーバー内の全ロールから『外部アプリの使用』権限を一括で外します")
async def server_disable_external_apps(interaction: discord.Interaction):
    if not await is_guild_admin(interaction): return
    if not interaction.guild: return

    await interaction.response.defer(ephemeral=True)

    updated = []
    skipped = []
    failed = []

    for role in interaction.guild.roles:
        if role.is_default():
            continue
        if not role.permissions.use_external_apps:
            skipped.append(role)
            continue
        try:
            new_permissions = role.permissions
            new_permissions.update(use_external_apps=False)
            await role.edit(
                permissions=new_permissions,
                reason=f"{interaction.user} により全ロールの外部アプリ使用権限をOFF"
            )
            updated.append(role)
        except discord.Forbidden:
            failed.append((role.name, "Botの権限不足（ロール階層を確認してください）"))
        except discord.HTTPException as e:
            failed.append((role.name, str(e)))

    embed = discord.Embed(
        title="[外部アプリ使用] 一括OFF処理結果",
        description="サーバー内すべてのロールの『外部アプリの使用（use_external_apps）』権限を確認し、有効になっていたロールをOFFにしました。",
        color=discord.Color.green() if not failed else discord.Color.orange()
    )
    embed.add_field(name="✅ OFFにしたロール", value=str(len(updated)) + "件", inline=True)
    embed.add_field(name="➖ 元からOFFだったロール", value=str(len(skipped)) + "件", inline=True)
    embed.add_field(name="❌ 失敗", value=str(len(failed)) + "件", inline=True)

    if updated:
        embed.add_field(
            name="OFFにしたロール一覧",
            value="\n".join(r.mention for r in updated)[:1024],
            inline=False
        )
    if failed:
        embed.add_field(
            name="失敗したロール",
            value="\n".join(f"・{name}: {reason}" for name, reason in failed)[:1024],
            inline=False
        )

    await interaction.followup.send(embed=embed, ephemeral=True)


@server_group.command(name="role_lockdown_channels", description="【管理者専用】指定したロールについて、全チャンネルで『@everyoneメンション』と『外部アプリ使用』をまとめて禁止にします")
@app_commands.describe(role="制限を適用するロール")
async def server_role_lockdown_channels(interaction: discord.Interaction, role: discord.Role):
    if not await is_guild_admin(interaction): return
    if not interaction.guild: return

    guild = interaction.guild

    if role.is_default():
        await interaction.response.send_message(
            "@everyone ロールは指定できません。個別のロールを指定してください。", ephemeral=True
        )
        return

    if role >= guild.me.top_role:
        await interaction.response.send_message(
            "指定されたロールがBotのロールと同じか、より上位にあるため操作できません。ロール階層を確認してください。",
            ephemeral=True
        )
        return

    await interaction.response.defer(ephemeral=True)

    updated = []
    skipped = []
    failed = []

    all_channels = list(guild.channels)  # カテゴリ含む全チャンネル（フォーラム・ステージ等も対象）

    for ch in all_channels:
        try:
            existing = ch.overwrites_for(role)
            if existing.mention_everyone is False and existing.use_external_apps is False:
                skipped.append(ch)
                continue
            existing.update(mention_everyone=False, use_external_apps=False)
            await ch.set_permissions(
                role,
                overwrite=existing,
                reason=f"{interaction.user} によりロール「{role.name}」の全チャンネル権限を一括制限"
            )
            updated.append(ch)
        except discord.Forbidden:
            failed.append((ch.name, "Botの権限不足"))
        except discord.HTTPException as e:
            failed.append((ch.name, str(e)))
        await asyncio.sleep(0.5)  # レート制限対策

    embed = discord.Embed(
        title=f"[チャンネル権限一括制限] {role.name}",
        description=(
            f"{role.mention} について、サーバー内すべてのチャンネル（全 {len(all_channels)} 件）の権限オーバーライドで\n"
            "『@everyoneメンション（mention_everyone）』『外部アプリの使用（use_external_apps）』を **不可** に設定しました。"
        ),
        color=discord.Color.green() if not failed else discord.Color.orange()
    )
    embed.add_field(name="✅ 更新したチャンネル", value=f"{len(updated)}件", inline=True)
    embed.add_field(name="➖ 元から設定済みだったチャンネル", value=f"{len(skipped)}件", inline=True)
    embed.add_field(name="❌ 失敗", value=f"{len(failed)}件", inline=True)

    if failed:
        fail_text = "\n".join(f"・{name}: {reason}" for name, reason in failed)[:1024]
        embed.add_field(name="失敗したチャンネル", value=fail_text, inline=False)

    await interaction.followup.send(embed=embed, ephemeral=True)


@ai_chat_group.command(name="set_channel", description="【オーナー限定】AIチャットが自動で返事してくれるチャンネルを決めます")
@app_commands.describe(channel="AIチャット専用にするチャンネル")
async def ai_chat_set_channel(interaction: discord.Interaction, channel: discord.TextChannel):
    if not await is_owner_check(interaction): return
    if not interaction.guild: return

    if not GROQ_API_KEY:
        await interaction.response.send_message(
            "GROQ_API_KEY が設定されていません。Botの環境変数に設定してから再度お試しください。",
            ephemeral=True
        )
        return

    perms = channel.permissions_for(interaction.guild.me)
    if not perms.send_messages or not perms.view_channel:
        await interaction.response.send_message(
            f"Botに {channel.mention} での発言権限がありません。チャンネル権限を確認してください。",
            ephemeral=True
        )
        return

    all_data = load_data()
    guild_config = get_guild_config(all_data, str(interaction.guild.id))
    guild_config["ai_chat_channel_id"] = channel.id
    save_data(all_data)

    await interaction.response.send_message(
        f"[設定完了] {channel.mention} をAIチャット専用チャンネルに設定しました。\n"
        f"このチャンネルでの発言にAIが自動応答します。",
        ephemeral=True
    )


@ai_chat_group.command(name="unset_channel", description="【オーナー限定】このサーバーでのAIチャット自動応答を止めます")
async def ai_chat_unset_channel(interaction: discord.Interaction):
    if not await is_owner_check(interaction): return
    if not interaction.guild: return

    all_data = load_data()
    guild_config = get_guild_config(all_data, str(interaction.guild.id))
    had_channel = guild_config.pop("ai_chat_channel_id", None)
    save_data(all_data)

    if had_channel:
        await interaction.response.send_message("AIチャット機能を無効化しました。", ephemeral=True)
    else:
        await interaction.response.send_message("このサーバーではAIチャットは設定されていません。", ephemeral=True)


