@server_protect_group.command(name="role_channel_mute", description="【管理者専用】指定したロールの発言・スレッド作成権限を、複数チャンネルまとめてOFFにできます")
@discord.app_commands.describe(
    role="発言・スレッド作成を禁止するロール",
    channel1="対象チャンネル1（必須）",
    channel2="対象チャンネル2（任意）",
    channel3="対象チャンネル3（任意）",
    channel4="対象チャンネル4（任意）",
    channel5="対象チャンネル5（任意）",
)
async def role_channel_mute(
    interaction: discord.Interaction,
    role: discord.Role,
    channel1: MuteTargetChannel,
    channel2: Optional[MuteTargetChannel] = None,
    channel3: Optional[MuteTargetChannel] = None,
    channel4: Optional[MuteTargetChannel] = None,
    channel5: Optional[MuteTargetChannel] = None,
):
    if not await is_guild_admin(interaction):
        return
    guild = interaction.guild
    if guild is None:
        return

    await interaction.response.defer(ephemeral=True, thinking=True)

    target_channels = [c for c in (channel1, channel2, channel3, channel4, channel5) if c is not None]

    success_channels = []
    failed_channels = []

    for channel in target_channels:
        if isinstance(channel, discord.CategoryChannel):
            failed_channels.append(f"{channel.name}（カテゴリは対象外）")
            continue
        try:
            await channel.set_permissions(
                role,
                send_messages=False,
                send_messages_in_threads=False,
                create_public_threads=False,
                create_private_threads=False,
                reason=f"/server protect role_channel_mute によりロール「{role.name}」の発言・スレッド作成権限をOFF（実行者: {interaction.user}）"
            )
            success_channels.append(channel.mention)
        except discord.Forbidden:
            failed_channels.append(f"{channel.mention}（Botに権限がありません）")
        except discord.HTTPException as e:
            failed_channels.append(f"{channel.mention}（エラー: {e}）")

    embed = discord.Embed(
        title="[OK] チャンネル発言権限の一括OFFが完了しました",
        description=f"対象ロール: {role.mention}\n\n"
                     f"発言（メッセージ送信・スレッド内発言）とスレッド作成の権限をOFFにしました。",
        color=discord.Color.orange(),
        timestamp=discord.utils.utcnow()
    )
    if success_channels:
        embed.add_field(name=f"[OK] 成功（{len(success_channels)}件）", value="\n".join(success_channels), inline=False)
    if failed_channels:
        embed.add_field(name=f"[NG] 失敗（{len(failed_channels)}件）", value="\n".join(failed_channels), inline=False)

    await interaction.followup.send(embed=embed, ephemeral=True)


@server_protect_group.command(name="arasi_setup", description="【管理者専用】荒らし対策として、隔離ロールの作成と新規ロールの権限自動制限をまとめて設定します")
@discord.app_commands.describe(
    隔離ロール名="作成する隔離ロールの名前（未指定時は「隔離」）。既に同名ロールがあれば再利用します",
    認証チャンネル="隔離ロールでも閲覧を許可するチャンネル（認証用チャンネルなど。任意）",
    新規ロール自動制限="新規作成されたロールの「@everyoneメンション」「外部アプリのコマンド使用」権限を自動でOFFにするか"
)
async def arasi_setup(
    interaction: discord.Interaction,
    隔離ロール名: str = "隔離",
    認証チャンネル: discord.TextChannel = None,
    新規ロール自動制限: bool = True
):
    if not await is_guild_admin(interaction):
        return
    guild = interaction.guild
    if not guild:
        return

    await interaction.response.defer(ephemeral=True)

    all_data = load_data()
    cfg = get_guild_config(all_data, str(guild.id))

    # --- 隔離ロールの作成 or 再利用 ---
    quarantine_role = None
    existing_role_id = cfg.get("arasi_quarantine_role_id")
    if existing_role_id:
        quarantine_role = guild.get_role(existing_role_id)

    if quarantine_role is None:
        # 同名の既存ロールがあれば再利用する
        quarantine_role = discord.utils.find(lambda r: r.name == 隔離ロール名, guild.roles)

    created_new_role = False
    if quarantine_role is None:
        try:
            quarantine_role = await guild.create_role(
                name=隔離ロール名,
                permissions=discord.Permissions.none(),
                reason="荒らし対策(/server protect arasi_setup): 隔離ロールを作成"
            )
            created_new_role = True
        except discord.Forbidden:
            await interaction.followup.send("ロールを作成する権限がBotにありません。管理者にご確認ください。", ephemeral=True)
            return
        except discord.HTTPException as e:
            await interaction.followup.send(f"隔離ロールの作成に失敗しました: {e}", ephemeral=True)
            return

    # --- 全チャンネルで閲覧・発言不可にする（認証チャンネルのみ例外で許可） ---
    channel_update_errors = []
    for channel in guild.channels:
        if isinstance(channel, discord.CategoryChannel):
            continue
        try:
            if 認証チャンネル is not None and channel.id == 認証チャンネル.id:
                await channel.set_permissions(
                    quarantine_role,
                    view_channel=True,
                    send_messages=False,
                    add_reactions=False,
                    reason="荒らし対策(/server protect arasi_setup): 認証チャンネルのみ隔離ロールに閲覧を許可"
                )
            else:
                await channel.set_permissions(
                    quarantine_role,
                    view_channel=False,
                    send_messages=False,
                    reason="荒らし対策(/server protect arasi_setup): 隔離ロールを全チャンネル非表示に設定"
                )
        except discord.Forbidden:
            channel_update_errors.append(channel.mention)
        except discord.HTTPException:
            channel_update_errors.append(channel.mention)

    # --- 設定を保存 ---
    cfg["arasi_quarantine_role_id"] = quarantine_role.id
    cfg["arasi_quarantine_role_name"] = quarantine_role.name
    cfg["arasi_verify_channel_id"] = 認証チャンネル.id if 認証チャンネル else None
    cfg["arasi_newrole_autolimit_enabled"] = 新規ロール自動制限
    save_data(all_data)

    # --- 結果報告 ---
    lines = []
    if created_new_role:
        lines.append(f"[OK] 隔離ロール {quarantine_role.mention} を新規作成しました。")
    else:
        lines.append(f"[OK] 既存のロール {quarantine_role.mention} を隔離ロールとして設定しました。")
    lines.append("全チャンネルで閲覧・発言不可に設定しました。")
    if 認証チャンネル is not None:
        lines.append(f"認証チャンネル {認証チャンネル.mention} のみ閲覧を許可しました（発言は不可）。")
    else:
        lines.append("認証チャンネルは指定されていません（すべてのチャンネルが非表示です）。")
    lines.append(f"新規ロール自動制限: {'有効' if 新規ロール自動制限 else '無効'}"
                 "（新しく作成されたロールの「@everyoneメンション」「外部アプリのコマンド使用」権限を自動でOFFにします）")
    if channel_update_errors:
        lines.append(f"[警告] 以下のチャンネルは権限変更に失敗しました（Botの権限をご確認ください）: {', '.join(channel_update_errors[:10])}")
    lines.append(
        "\n新規参加者には自動で隔離ロールが付与されます。\n"
        "ボタン認証（/verify系パネル）またはウェブ認証（OAuth2）が完了すると、隔離ロールは自動的に解除されます。"
    )

    await interaction.followup.send("\n".join(lines), ephemeral=True)


@moderation_group.command(name="warn", description="【モデレーター専用】ユーザーに警告を出せます")
async def warn(interaction: discord.Interaction, user: discord.Member, reason: str = "理由なし"):
    if not await is_moderator(interaction): return
    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))
    warnings = cfg.setdefault("warnings", {})
    user_warnings = warnings.setdefault(str(user.id), [])
    timestamp = datetime.datetime.now(datetime.timezone.utc).isoformat()
    user_warnings.append({"reason": reason, "date": timestamp, "moderator": interaction.user.id})
    save_data(all_data)
    await interaction.response.send_message(f"[警告] {user.mention} に警告を与えました。\n理由: {reason}")
    try:
        await user.send(f"[警告] **{interaction.guild.name}** で警告を受けました。\n理由: {reason}")
    except Exception:
        pass


@moderation_group.command(name="warnings", description="【モデレーター専用】そのユーザーが今まで受けた警告を確認できます")
async def warnings(interaction: discord.Interaction, user: discord.Member):
    if not await is_moderator(interaction): return
    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))
    user_warnings = cfg.get("warnings", {}).get(str(user.id), [])
    if not user_warnings:
        await interaction.response.send_message(f"{user.mention} には警告履歴がありません。", ephemeral=True)
        return
    embed = discord.Embed(title=f"[ 警告履歴: {user.display_name} ]", color=discord.Color.orange())
    for i, w in enumerate(user_warnings, 1):
        date = w["date"][:19].replace("T", " ")
        embed.add_field(name=f"警告 {i} ({date})", value=f"理由: {w['reason']}\n担当: <@{w['moderator']}>", inline=False)
    await interaction.response.send_message(embed=embed, ephemeral=True)


@moderation_group.command(name="mute", description="【モデレーター専用】ユーザーを一定時間ミュート（タイムアウト）できます")
async def mute(interaction: discord.Interaction, user: discord.Member, minutes: int, reason: str = "理由なし"):
    if not await is_moderator(interaction): return
    try:
        duration = datetime.timedelta(minutes=minutes)
        await user.timeout(duration, reason=reason)
        await interaction.response.send_message(f"[ミュート] {user.mention} を {minutes} 分間ミュートしました。\n理由: {reason}")
    except discord.Forbidden:
        await interaction.response.send_message("権限が不足しているためミュートできません。", ephemeral=True)
    except Exception as e:
        await interaction.response.send_message(f"エラーが発生しました: {e}", ephemeral=True)


class BanTrollListView(discord.ui.View):
    """BAN後に荒らしリストへ追加するかを選択するボタンビューです。"""
