        all_data = load_data()
        uid_str = str(self.member.id)
        add_to_troll_list(all_data, self.member, self.guild, reason=f"/moderation ban コマンド: {self.reason}")
        save_data(all_data)
        await _post_troll_board(all_data, uid_str)
        for item in self.children:
            item.disabled = True
