@moderation_group.command(name="purge", description="【モデレーター専用】今いるチャンネルのメッセージをまとめて削除できます")
async def purge(interaction: discord.Interaction, amount: int):
    if not await is_moderator(interaction): return
    if amount < 1 or amount > 100:
        await interaction.response.send_message("1〜100の範囲で指定してください。", ephemeral=True)
        return
    await interaction.response.defer(ephemeral=True)
    try:
        deleted = await interaction.channel.purge(limit=amount)
        await interaction.followup.send(f"[一括削除] {len(deleted)} 件のメッセージを削除しました。", ephemeral=True)
    except discord.Forbidden:
        await interaction.followup.send("権限が不足しているため削除できません。", ephemeral=True)


@moderation_group.command(name="purge_user", description="【モデレーター専用】指定したチャンネルで、指定したメンバーのメッセージだけまとめて削除します")
@app_commands.describe(
    member="メッセージを削除する対象メンバー",
    channel="対象チャンネル（省略時は現在のチャンネル）",
    amount="遡って確認するメッセージ件数（1〜1000、既定200）。この件数の中から対象メンバーの発言のみ削除します"
)
async def purge_user(
    interaction: discord.Interaction,
    member: discord.Member,
    channel: Optional[MuteTargetChannel] = None,
    amount: app_commands.Range[int, 1, 1000] = 200
):
    if not await is_moderator(interaction): return

    target_channel = channel or interaction.channel
    if not isinstance(target_channel, (discord.TextChannel, discord.VoiceChannel, discord.StageChannel, discord.Thread)):
        await interaction.response.send_message("このコマンドはテキスト系チャンネルでのみ使用できます。", ephemeral=True)
        return

    perms = target_channel.permissions_for(interaction.guild.me)
    if not perms.manage_messages or not perms.read_message_history:
        await interaction.response.send_message(
            f"Botに {target_channel.mention} でのメッセージ管理権限（メッセージの管理・メッセージ履歴の閲覧）がありません。",
            ephemeral=True
        )
        return

    await interaction.response.defer(ephemeral=True)
    try:
        deleted = await target_channel.purge(
            limit=amount,
            check=lambda m: m.author.id == member.id
        )
        await interaction.followup.send(
            f"[一括削除] {target_channel.mention} 内の {member.mention} のメッセージを "
            f"{len(deleted)} 件削除しました（直近{amount}件を確認）。",
            ephemeral=True
        )
    except discord.Forbidden:
        await interaction.followup.send("権限が不足しているため削除できません。", ephemeral=True)
    except discord.HTTPException as e:
        await interaction.followup.send(f"削除中にエラーが発生しました: {e}", ephemeral=True)


class PurgeExternalAppsAllChannelsConfirmView(discord.ui.View):
    """
    「すべてのチャンネル」を対象にした外部アプリメッセージ一括削除の実行確認用ボタンビューです。
    サーバー内の全テキスト系チャンネルを横断して処理するため、誤操作防止のためにボタン確認を挟みます。
    """

    def __init__(self, guild: discord.Guild, bot_user_id: int, app_filter: Optional[discord.Member], amount: int):
        super().__init__(timeout=180)
        self.guild = guild
        self.bot_user_id = bot_user_id
        self.app_filter = app_filter
        self.amount = amount
        self._running = False

    def _is_external_app_message(self, m: discord.Message) -> bool:
        meta = getattr(m, "interaction_metadata", None) or getattr(m, "interaction", None)
        if meta is None:
            return False
        meta_user = getattr(meta, "user", None)
        if meta_user is not None and meta_user.id == self.bot_user_id:
            return False
        if self.app_filter is not None and meta_user is not None and meta_user.id != self.app_filter.id:
            return False
        return True

    @discord.ui.button(label="全チャンネルで実行する", style=discord.ButtonStyle.danger)
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button):
        if self._running:
            await interaction.response.send_message("すでに実行中です。しばらくお待ちください。", ephemeral=True)
            return
        self._running = True

        for item in self.children:
            item.disabled = True
        await interaction.response.defer(ephemeral=True)
        try:
            await interaction.edit_original_response(view=self)
        except Exception:
            pass

        target_channels = list(self.guild.text_channels)
        total_deleted = 0
        processed = []
        skipped = []
        failed = []

        for ch in target_channels:
            perms = ch.permissions_for(self.guild.me)
            if not perms.manage_messages or not perms.read_message_history:
                skipped.append(ch.name)
                continue
            try:
                deleted = await ch.purge(limit=self.amount, check=self._is_external_app_message)
                total_deleted += len(deleted)
                if deleted:
                    processed.append(f"{ch.mention}: {len(deleted)}件")
            except discord.Forbidden:
                failed.append(f"{ch.name}: 権限不足")
            except discord.HTTPException as e:
                failed.append(f"{ch.name}: {e}")
            await asyncio.sleep(1)  # レート制限対策

        target_desc = f"（{self.app_filter.mention} のみ）" if self.app_filter is not None else "（全ての外部アプリ）"
        summary_lines = (
            [f"[一括削除完了] 全 {len(target_channels)} チャンネルを確認し、外部アプリのメッセージ{target_desc}を合計 {total_deleted} 件削除しました。\n"]
            + (["", "**削除があったチャンネル**"] + processed if processed else [])
            + (["", "**スキップ（権限不足）**"] + skipped if skipped else [])
            + (["", "**エラー**"] + failed if failed else [])
        )
        chunk = ""
        messages = []
        for line in summary_lines:
            if len(chunk) + len(line) + 1 > 1900:
                messages.append(chunk)
                chunk = line + "\n"
            else:
                chunk += line + "\n"
        if chunk:
            messages.append(chunk)
        for msg in messages:
            await interaction.followup.send(msg, ephemeral=True)

        self._running = False

    @discord.ui.button(label="キャンセル", style=discord.ButtonStyle.secondary)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button):
        if self._running:
            await interaction.response.send_message("すでに実行中のためキャンセルできません。", ephemeral=True)
            return
        for item in self.children:
            item.disabled = True
        await interaction.response.edit_message(content="キャンセルしました。", view=self)


@moderation_group.command(name="purge_external_apps", description="【モデレーター専用】他Botのコマンド実行で送られたメッセージをまとめて削除します")
@app_commands.describe(
    channel="対象チャンネル（省略時は現在のチャンネル）",
    all_channels="Trueにするとサーバー内の全テキストチャンネルを対象にします（channel指定より優先、実行前に確認あり）",
    app="削除対象を特定のアプリ/Botに絞り込む場合に指定（省略時は全ての外部アプリが対象）",
    amount="遡って確認するメッセージ件数（1〜1000、既定200）。全チャンネル対象時はチャンネルごとにこの件数を確認します"
)
async def purge_external_apps(
    interaction: discord.Interaction,
    channel: Optional[MuteTargetChannel] = None,
    all_channels: bool = False,
    app: Optional[discord.Member] = None,
    amount: app_commands.Range[int, 1, 1000] = 200
):
    if not await is_moderator(interaction): return
    if not interaction.guild:
        await interaction.response.send_message("このコマンドはサーバー内で実行してください。", ephemeral=True)
        return

    if app is not None and not app.bot:
        await interaction.response.send_message("`app` にはBot/アプリのユーザーを指定してください。", ephemeral=True)
        return

    if all_channels:
        target_desc = f"（{app.mention} のみ）" if app is not None else "（全ての外部アプリ）"
        view = PurgeExternalAppsAllChannelsConfirmView(
            guild=interaction.guild,
            bot_user_id=interaction.client.user.id,
            app_filter=app,
            amount=amount
        )
        await interaction.response.send_message(
            f"[確認] サーバー内の **すべてのテキストチャンネル（{len(interaction.guild.text_channels)}件）** を対象に、"
            f"外部アプリのメッセージ{target_desc}を各チャンネル直近{amount}件から検索して削除します。\n"
            "チャンネル数が多い場合、時間がかかることがあります。実行しますか？",
            view=view,
            ephemeral=True
        )
        return

    target_channel = channel or interaction.channel
    if not isinstance(target_channel, (discord.TextChannel, discord.VoiceChannel, discord.StageChannel, discord.Thread)):
        await interaction.response.send_message("このコマンドはテキスト系チャンネルでのみ使用できます。", ephemeral=True)
        return

    perms = target_channel.permissions_for(interaction.guild.me)
    if not perms.manage_messages or not perms.read_message_history:
        await interaction.response.send_message(
            f"Botに {target_channel.mention} でのメッセージ管理権限（メッセージの管理・メッセージ履歴の閲覧）がありません。",
            ephemeral=True
        )
        return

    def _is_external_app_message(m: discord.Message) -> bool:
        # discord.py 2.x: interaction_metadata（新API）を優先し、
        # 環境によっては存在しない旧バージョン向けに interaction（非推奨）にもフォールバックする
        meta = getattr(m, "interaction_metadata", None) or getattr(m, "interaction", None)
        if meta is None:
            return False
        # 自分（このBot自身）のコマンド実行結果は対象外にする
        meta_user = getattr(meta, "user", None)
        if meta_user is not None and meta_user.id == interaction.client.user.id:
            return False
        if app is not None and meta_user is not None and meta_user.id != app.id:
            return False
        return True

    await interaction.response.defer(ephemeral=True)
    try:
        deleted = await target_channel.purge(
            limit=amount,
            check=_is_external_app_message
        )
        target_desc = f"（{app.mention} のみ）" if app is not None else "（全ての外部アプリ）"
        await interaction.followup.send(
            f"[一括削除] {target_channel.mention} 内で外部アプリのコマンド実行によるメッセージ{target_desc}を "
            f"{len(deleted)} 件削除しました（直近{amount}件を確認）。",
            ephemeral=True
        )
    except discord.Forbidden:
        await interaction.followup.send("権限が不足しているため削除できません。", ephemeral=True)
    except discord.HTTPException as e:
        await interaction.followup.send(f"削除中にエラーが発生しました: {e}", ephemeral=True)


@automod_group.command(name="toggle", description="【モデレーター専用】自動モデレーションをON/OFF切り替えできます")
@discord.app_commands.choices(機能=[
    discord.app_commands.Choice(name="スパム検知", value="spam"),
    discord.app_commands.Choice(name="招待リンク削除", value="invite"),
    discord.app_commands.Choice(name="NGワード検知", value="ngword"),
    discord.app_commands.Choice(name="AI自動モデレーション（言い換え・遠回しな迷惑発言を検知）", value="ai"),
    discord.app_commands.Choice(name="画像OCR招待リンク検知（AI補助判定）", value="image_ocr_invite"),
    discord.app_commands.Choice(name="画像NSFW検知（AI判定）", value="nsfw_image"),
])
async def automod_toggle(interaction: discord.Interaction, 機能: discord.app_commands.Choice[str], 有効化: bool):
    if not await is_moderator(interaction): return
    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))
    key = f"automod_{機能.value}_enabled"
    if 機能.value == "ngword":
        key = "automod_ng_words_enabled"

    if 機能.value == "ai" and 有効化 and not GROQ_API_KEY:
        await interaction.response.send_message(
            "GROQ_API_KEY が設定されていないため、AI自動モデレーションを有効化できません。Botの環境変数を確認してください。",
            ephemeral=True
        )
        return

    if 機能.value == "image_ocr_invite" and 有効化 and not OCR_SPACE_API_KEY:
        await interaction.response.send_message(
            "OCR_SPACE_API_KEY が設定されていないため、画像OCR招待リンク検知を有効化できません。Botの環境変数を確認してください。",
            ephemeral=True
        )
        return

    if 機能.value == "nsfw_image" and 有効化 and not GROQ_VISION_MODEL:
        await interaction.response.send_message(
            "GROQ_VISION_MODEL が設定されていないため、画像NSFW検知を有効化できません。Botの環境変数を確認してください。",
            ephemeral=True
        )
        return

    cfg[key] = 有効化
    save_data(all_data)
    status = "ON" if 有効化 else "OFF"
    extra_note = ""
    if 機能.value == "ai" and 有効化:
        extra_note = f"\n（判定は{AI_AUTOMOD_BATCH_INTERVAL_SECONDS}秒間隔でまとめて実行されるため、削除まで多少のタイムラグがあります）"
    if 機能.value == "image_ocr_invite" and 有効化:
        extra_note = "\n（テキスト本文の招待リンク削除とは独立した設定です。画像添付があるメッセージのみOCR解析を行います）"
    if 機能.value == "nsfw_image" and 有効化:
        extra_note = "\n（NSFWチャンネルとして設定済みのチャンネルは対象外です。管理者権限を持つユーザーは自動モデレーションの対象外です）"
    await interaction.response.send_message(
        f"[設定変更] 自動モデレーション「{機能.name}」を **{status}** に設定しました。{extra_note}",
        ephemeral=True
    )


