def _format_bytes_human(num_bytes: int) -> str:
    """バイト数を読みやすい単位（KB/MB/GB）の文字列に変換します。"""
    size = float(num_bytes)
    for unit in ("B", "KB", "MB", "GB"):
        if size < 1024.0:
            return f"{size:.1f}{unit}"
        size /= 1024.0
    return f"{size:.1f}TB"


def _get_dir_size_bytes(path: str) -> int:
    """指定ディレクトリ配下の合計サイズ（バイト）を再帰的に計算します。"""
    total = 0
    for dirpath, _dirnames, filenames in os.walk(path):
        for fn in filenames:
            fp = os.path.join(dirpath, fn)
            try:
                total += os.path.getsize(fp)
            except OSError:
                pass
    return total


@voice_sound_group.command(
    name="cleanup_orphaned",
    description="【Botオーナー限定】既にBotが在籍していないサーバーの残留データ（音声ファイル・面接記録）を検出・削除します"
)
@app_commands.describe(実行="falseの場合は削除対象を一覧表示するだけで、実際には削除しません（既定）")
async def voice_sound_cleanup_orphaned(interaction: discord.Interaction, 実行: Optional[bool] = False):
    if not await is_owner_check(interaction):
        return

    await interaction.response.defer(ephemeral=True, thinking=True)

    orphaned_sounds = _find_orphaned_sound_dirs() if os.path.isdir(SOUNDS_DIR) else []
    orphaned_interviews = _find_orphaned_interview_records()

    if not orphaned_sounds and not orphaned_interviews:
        await interaction.followup.send("在籍していないサーバーの残留データ（音声ファイル・面接記録）は見つかりませんでした。", ephemeral=True)
        return

    total_size = sum(s for _, _, s in orphaned_sounds)
    total_interview_records = sum(c for _, c in orphaned_interviews)

    lines = []
    if orphaned_sounds:
        lines.append("**音声ファイル:**")
        lines.extend(f"・サーバーID `{gid}` : {_format_bytes_human(size)}" for gid, _, size in orphaned_sounds[:15])
        if len(orphaned_sounds) > 15:
            lines.append(f"...ほか{len(orphaned_sounds) - 15}件")
    if orphaned_interviews:
        lines.append("**面接記録:**")
        lines.extend(f"・サーバーID `{gid}` : {count}件" for gid, count in orphaned_interviews[:15])
        if len(orphaned_interviews) > 15:
            lines.append(f"...ほか{len(orphaned_interviews) - 15}件")

    if not 実行:
        embed = discord.Embed(
            title="残留データの検出結果（未削除）",
            description="\n".join(lines),
            color=discord.Color.orange()
        )
        embed.set_footer(
            text=(
                f"音声: {len(orphaned_sounds)}サーバー分 / {_format_bytes_human(total_size)}　"
                f"面接記録: {len(orphaned_interviews)}サーバー分 / {total_interview_records}件　"
                f"実際に削除するには 実行:true を指定してください。"
            )
        )
        await interaction.followup.send(embed=embed, ephemeral=True)
        return

    deleted_sound_count, deleted_sound_size, sound_failed = _delete_orphaned_sound_dirs(orphaned_sounds)
    deleted_interview_guild_count, deleted_interview_record_count, interview_failed = _delete_orphaned_interview_records(orphaned_interviews)
    failed = sound_failed + interview_failed

    embed = discord.Embed(
        title="残留データを削除しました",
        description="\n".join(lines),
        color=discord.Color.green()
    )
    footer_text = (
        f"音声: {deleted_sound_count}サーバー分 / {_format_bytes_human(deleted_sound_size)} を解放　"
        f"面接記録: {deleted_interview_guild_count}サーバー分 / {deleted_interview_record_count}件 を削除"
    )
    if failed:
        footer_text += f"（{len(failed)}件失敗）"
    embed.set_footer(text=footer_text)
    await interaction.followup.send(embed=embed, ephemeral=True)


def _find_orphaned_sound_dirs() -> list:
    """
    SOUNDS_DIR配下で、現在Botが在籍していないサーバーIDのフォルダ一覧を返します。
    戻り値は [(guild_id_str, full_path, size_bytes), ...]（サイズの大きい順）。
    /voice_sound cleanup_orphaned コマンドと、ストレージ自動監視ループの両方から使う共通ロジック。
    """
    if not os.path.isdir(SOUNDS_DIR):
        return []
    current_guild_ids = {str(g.id) for g in bot.guilds}
    orphaned = []
    for entry in os.listdir(SOUNDS_DIR):
        full_path = os.path.join(SOUNDS_DIR, entry)
        if not os.path.isdir(full_path):
            continue
        if not entry.isdigit():
            continue
        if entry in current_guild_ids:
            continue
        size = _get_dir_size_bytes(full_path)
        orphaned.append((entry, full_path, size))
    orphaned.sort(key=lambda x: x[2], reverse=True)
    return orphaned


def _delete_orphaned_sound_dirs(orphaned: list) -> Tuple[int, int, list]:
    """
    _find_orphaned_sound_dirs() の戻り値を受け取り、実際にフォルダを削除します。
    戻り値: (削除成功数, 解放バイト数, 失敗メッセージのリスト)
    """
    deleted_count = 0
    deleted_size = 0
    failed = []
    for gid, full_path, size in orphaned:
        try:
            shutil.rmtree(full_path, ignore_errors=False)
            deleted_count += 1
            deleted_size += size
        except Exception as e:
            failed.append(f"{gid}: {e}")
    return deleted_count, deleted_size, failed


def _find_orphaned_interview_records() -> list:
    """
    現在Botが在籍していないサーバーのうち、面接記録（interview_records）が
    残っているものを検出します。戻り値は [(guild_id_str, record_count), ...]。
    on_guild_remove で本来は削除されるが、それより前にBotが導入されていた
    サーバー分（過去分）を拾うためのバックフィル用。
    """
    all_data = load_data()
    current_guild_ids = {str(g.id) for g in bot.guilds}
    orphaned = []
    for key, cfg in all_data.items():
        if not isinstance(cfg, dict):
            continue
        if not key.isdigit():
            continue  # allowed_users.json のトップレベルキーはギルドIDのみを対象にする
        if key in current_guild_ids:
            continue
        records = cfg.get("interview_records")
        if records:
            orphaned.append((key, len(records)))
    orphaned.sort(key=lambda x: x[1], reverse=True)
    return orphaned


def _delete_orphaned_interview_records(orphaned: list) -> Tuple[int, int, list]:
    """
    _find_orphaned_interview_records() の戻り値を受け取り、対象サーバーの
    interview_records のみを空にして保存します（他のサーバー設定は残す）。
    戻り値: (対象サーバー数, 削除した記録の合計件数, 失敗メッセージのリスト)
    """
    if not orphaned:
        return 0, 0, []
    all_data = load_data()
    deleted_guild_count = 0
    deleted_record_count = 0
    failed = []
    for guild_id_str, _record_count in orphaned:
        try:
            cfg = all_data.get(guild_id_str)
            if isinstance(cfg, dict) and cfg.get("interview_records"):
                deleted_record_count += len(cfg["interview_records"])
                cfg["interview_records"] = {}
                deleted_guild_count += 1
        except Exception as e:
            failed.append(f"{guild_id_str}: {e}")
    if deleted_guild_count > 0:
        save_data(all_data)
    return deleted_guild_count, deleted_record_count, failed


async def _gemini_summarize_storage_cleanup(
    usage_percent: float,
    total_bytes: int,
    used_bytes: int,
    deleted_count: int,
    deleted_size: int,
    remaining_percent: float,
) -> Optional[str]:
    """
    自動ストレージクリーンアップの結果を、Gemini（テキスト生成）で
    Botオーナー向けの短い日本語要約コメントにします。
    GEMINI_API_KEY未設定時、またはAPI呼び出し失敗時はNoneを返し、
    呼び出し元は定型文にフォールバックします（この処理自体は必須ではないため）。
    """
    if not GEMINI_API_KEY:
        return None

    prompt = (
        "あなたはDiscord Botの運用ログを要約するアシスタントです。"
        "以下のストレージ自動クリーンアップの実行結果を踏まえて、"
        "Bot運営者（オーナー）向けに2〜3文程度の短い日本語コメントを書いてください。"
        "事実（数値）を正確に伝えつつ、必要であれば軽い注意喚起や次のアクション案を添えてください。"
        "絵文字や過度な装飾は不要です。\n\n"
        f"・実行前のボリューム使用率: {usage_percent:.1f}%\n"
        f"・ボリューム合計サイズ: {_format_bytes_human(total_bytes)}\n"
        f"・実行前の使用量: {_format_bytes_human(used_bytes)}\n"
        f"・削除した在籍外サーバーのフォルダ数: {deleted_count}件\n"
        f"・解放した容量: {_format_bytes_human(deleted_size)}\n"
        f"・実行後の推定使用率: {remaining_percent:.1f}%\n"
    )

    payload = {
        "contents": [{"role": "user", "parts": [{"text": prompt}]}],
        "generationConfig": {"temperature": 0.4, "maxOutputTokens": 300},
    }
    url = f"https://generativelanguage.googleapis.com/v1beta/models/{GEMINI_MODEL}:generateContent?key={GEMINI_API_KEY}"

    try:
        async with aiohttp.ClientSession() as session:
            async with session.post(
                url, json=payload, timeout=aiohttp.ClientTimeout(total=20)
            ) as resp:
                if resp.status != 200:
                    return None
                data = await resp.json()
        candidate = data["candidates"][0]
        parts = candidate.get("content", {}).get("parts", [])
        text = "".join(p.get("text", "") for p in parts).strip()
        return text or None
    except Exception as e:
        print(f"[ストレージ監視] Gemini要約コメント生成に失敗しました（フォールバック定型文を使用します）: {e}")
        return None


async def _storage_monitor_check_and_cleanup_once():
    """
    ボリューム（/app/data）の使用率を1回チェックし、閾値超過時のみ
    在籍していないサーバーの音声フォルダを自動削除してBotオーナーへ通知します。
    閾値未満の場合は何もしません（サイレント）。
    """
    try:
        total_bytes, used_bytes, free_bytes = shutil.disk_usage(STORAGE_MONITOR_PATH)
    except Exception as e:
        print(f"[ストレージ監視] ディスク使用量の取得に失敗しました: {e}")
        return

    if total_bytes <= 0:
        return
    usage_percent = used_bytes / total_bytes * 100

    if usage_percent < STORAGE_CLEANUP_THRESHOLD_PERCENT:
        return  # 閾値未満のため何もしない

    print(f"[ストレージ監視] 使用率が閾値を超過しました（{usage_percent:.1f}% >= {STORAGE_CLEANUP_THRESHOLD_PERCENT:.1f}%）。自動クリーンアップを開始します。")

    orphaned = _find_orphaned_sound_dirs()
    if not orphaned:
        print("[ストレージ監視] 使用率は高いですが、削除可能な残留データ（在籍外サーバーの音声フォルダ）は見つかりませんでした。")
        deleted_count, deleted_size, failed = 0, 0, []
    else:
        deleted_count, deleted_size, failed = _delete_orphaned_sound_dirs(orphaned)
        print(f"[ストレージ監視] 自動クリーンアップ完了: {deleted_count}件削除、{_format_bytes_human(deleted_size)}解放。")

    remaining_percent = (used_bytes - deleted_size) / total_bytes * 100 if total_bytes else usage_percent

    # Botオーナーへ結果を通知（DM）。要約コメントはGeminiで生成し、失敗時は定型文にフォールバック。
    try:
        owner_id = await resolve_owner_id(bot)
        if owner_id is None:
            return
        owner = await bot.fetch_user(owner_id)

        summary_comment = await _gemini_summarize_storage_cleanup(
            usage_percent, total_bytes, used_bytes, deleted_count, deleted_size, remaining_percent
        )
        if not summary_comment:
            if deleted_count > 0:
                summary_comment = (
                    f"ボリューム使用率が{STORAGE_CLEANUP_THRESHOLD_PERCENT:.0f}%を超えたため、"
                    f"在籍していないサーバーの音声データを自動削除し、容量を解放しました。"
                )
            else:
                summary_comment = (
                    f"ボリューム使用率が{STORAGE_CLEANUP_THRESHOLD_PERCENT:.0f}%を超えていますが、"
                    f"自動削除できる対象（在籍外サーバーの音声データ）が見つかりませんでした。手動での確認をおすすめします。"
                )

        embed = discord.Embed(
            title="[ストレージ自動監視] クリーンアップを実行しました" if deleted_count > 0 else "[ストレージ自動監視] 使用率が高くなっています",
            description=summary_comment,
            color=discord.Color.orange() if deleted_count == 0 else discord.Color.green(),
            timestamp=discord.utils.utcnow(),
        )
        embed.add_field(name="実行前の使用率", value=f"{usage_percent:.1f}%", inline=True)
        embed.add_field(name="実行後の推定使用率", value=f"{remaining_percent:.1f}%", inline=True)
        embed.add_field(name="ボリューム合計", value=_format_bytes_human(total_bytes), inline=True)
        embed.add_field(name="削除件数", value=f"{deleted_count}サーバー分", inline=True)
        embed.add_field(name="解放容量", value=_format_bytes_human(deleted_size), inline=True)
        if failed:
            embed.add_field(name="削除失敗", value=f"{len(failed)}件（ログを確認してください）", inline=True)
        embed.set_footer(text="/voice_sound cleanup_orphaned で手動確認・削除も可能です。")

        await owner.send(embed=embed)
    except Exception as e:
        print(f"[警告] ストレージ自動監視の結果通知（オーナーDM）に失敗しました: {e}")


async def _storage_monitor_loop():
    """
    STORAGE_MONITOR_INTERVAL_SECONDSごとにボリューム使用率をチェックし、
    閾値超過時のみ自動クリーンアップ・オーナー通知を行うバックグラウンドタスクです。
    /app/data（Railwayボリューム想定）が存在する環境でのみ起動されます。
    """
    await bot.wait_until_ready()
    try:
        while True:
            try:
                await _storage_monitor_check_and_cleanup_once()
            except Exception as e:
                print(f"[警告] ストレージ監視チェック中にエラーが発生しました: {e}")
            await asyncio.sleep(STORAGE_MONITOR_INTERVAL_SECONDS)
    except asyncio.CancelledError:
        raise


# ====================================================================
# Railway ステータス監視（CPU/メモリ/ストレージ/料金のリアルタイム表示）
# ====================================================================
# Railway公式のGraphQL Public API（backboard.railway.com/graphql/v2）を使用する。
# 参考: https://docs.railway.com/reference/public-api
#
# 取得する情報:
#   - プロジェクト内の各サービスのCPU使用率・メモリ使用量（metrics クエリ）
#   - ボリューム（ストレージ）の使用量・上限（volumes / volumeInstances クエリ）
#   - 現在の請求期間の推定使用料金（usage クエリ。取得できないプラン/権限の場合もあるため
#     取得失敗時はその旨を正直に表示する）
#
# 注意: RailwayのGraphQLスキーマは非公開の内部実装に依存する部分があり、将来的な
# スキーマ変更で一部フィールドが取得できなくなる可能性がある。取得に失敗した項目は
# 例外を握りつぶして「取得できませんでした」と表示し、Bot全体が落ちないようにする。

_railway_monitor_sessions: dict = {}  # {(guild_id, channel_id): {"message_id": int, "task": asyncio.Task}}


_railway_last_graphql_error: Optional[str] = None


async def _railway_graphql_request(query: str, variables: dict) -> Optional[dict]:
    """Railway GraphQL APIにクエリを送信し、data部分を返します。失敗時はNoneを返します。"""
    global _railway_last_graphql_error
    if not RAILWAY_MONITOR_AVAILABLE:
        return None
    headers = {
        "Authorization": f"Bearer {RAILWAY_API_TOKEN}",
        "Content-Type": "application/json",
    }
    payload = {"query": query, "variables": variables}
    try:
        async with aiohttp.ClientSession() as session:
            async with session.post(
                RAILWAY_GRAPHQL_ENDPOINT, json=payload, headers=headers,
                timeout=aiohttp.ClientTimeout(total=15)
            ) as resp:
                body = await resp.json()
                if resp.status != 200 or "errors" in body:
                    errs = body.get("errors") if isinstance(body, dict) else None
                    _railway_last_graphql_error = f"status={resp.status} errors={errs}"
                    print(f"[Railway監視] GraphQLエラー（status={resp.status}）: {errs}")
                    return None
                _railway_last_graphql_error = None
                return body.get("data")
    except Exception as e:
        _railway_last_graphql_error = f"例外: {e}"
        print(f"[Railway監視] GraphQL API呼び出しに失敗しました: {e}")
        return None


async def _railway_fetch_project_overview() -> Optional[dict]:
    """プロジェクト名・環境一覧・サービス一覧（サービスID/名前）を取得します。"""
    query = """
    query ProjectOverview($projectId: String!) {
        project(id: $projectId) {
            id
            name
            environments {
                edges {
                    node {
                        id
                        name
                    }
                }
            }
            services {
                edges {
                    node {
                        id
                        name
                    }
                }
            }
        }
    }
    """
    data = await _railway_graphql_request(query, {"projectId": RAILWAY_PROJECT_ID})
    if not data or not data.get("project"):
        return None
    return data["project"]


async def _railway_fetch_metrics(environment_id: str) -> list:
    """
    指定環境の直近メトリクス（CPU使用量・メモリ使用量）をサービスごとに取得します。
    Railwayのメトリクス測定種別（measurement）: CPU_USAGE（コア数）, MEMORY_USAGE_GB（GB）。
    groupBy: SERVICE_ID を指定することで、tags.serviceId ごとに値が分解されて返る。
    取得に失敗した場合は空リストを返します（呼び出し側でその旨を表示）。
    """
    now = datetime.datetime.now(datetime.timezone.utc)
    start = now - datetime.timedelta(minutes=10)
    query = """
    query Metrics($environmentId: String!, $startDate: DateTime!, $endDate: DateTime!, $measurements: [MetricMeasurement!]!, $groupBy: [MetricTag!]) {
        metrics(
            environmentId: $environmentId
            startDate: $startDate
            endDate: $endDate
            measurements: $measurements
            groupBy: $groupBy
        ) {
            measurement
            tags {
                serviceId
            }
            values {
                ts
                value
            }
        }
    }
    """
    variables = {
        "environmentId": environment_id,
        "startDate": start.isoformat(),
        "endDate": now.isoformat(),
        "measurements": ["CPU_USAGE", "MEMORY_USAGE_GB"],
        "groupBy": ["SERVICE_ID"],
    }
    data = await _railway_graphql_request(query, variables)
    if not data or data.get("metrics") is None:
        # groupBy引数（enum値名）が違う可能性があるため、groupByなしでも一度試す
        variables_fallback = {k: v for k, v in variables.items() if k != "groupBy"}
        query_fallback = """
        query Metrics($environmentId: String!, $startDate: DateTime!, $endDate: DateTime!, $measurements: [MetricMeasurement!]!) {
            metrics(
                environmentId: $environmentId
                startDate: $startDate
                endDate: $endDate
                measurements: $measurements
            ) {
                measurement
                tags { serviceId }
                values { ts value }
            }
        }
        """
        data = await _railway_graphql_request(query_fallback, variables_fallback)
        if not data or data.get("metrics") is None:
            return []
    metrics = data["metrics"]
    if os.getenv("RAILWAY_MONITOR_DEBUG"):
        print(f"[Railway監視][DEBUG] metrics生データ: {json.dumps(metrics, ensure_ascii=False)[:3000]}")
    return metrics


async def _railway_fetch_volumes() -> list:
    """プロジェクトに紐づくボリューム（ストレージ）の使用量・上限一覧を取得します。"""
    query = """
    query ProjectVolumes($projectId: String!) {
        project(id: $projectId) {
            volumes {
                edges {
                    node {
                        id
                        name
                        volumeInstances {
                            edges {
                                node {
                                    currentSizeMB
                                    sizeMB
                                    environmentId
                                }
                            }
                        }
                    }
                }
            }
        }
    }
    """
    data = await _railway_graphql_request(query, {"projectId": RAILWAY_PROJECT_ID})
    if not data or not data.get("project"):
        return []
    volumes = data["project"].get("volumes", {}).get("edges", [])
    return [v["node"] for v in volumes]


# Railway公式サイト（railway.com/pricing）で公表されている従量課金の単価。
# 2026年7月時点の値。Railway側の価格改定があれば実際の請求額とズレるため、
# あくまで「概算」であることを表示側で明記する。
RAILWAY_PRICE_PER_GB_SECOND_MEMORY = 0.00000386   # メモリ: $/GB秒
RAILWAY_PRICE_PER_VCPU_SECOND_CPU = 0.00000772    # CPU: $/vCPU秒
RAILWAY_PRICE_PER_GB_SECOND_VOLUME = 0.00000006   # ボリューム: $/GB秒
RAILWAY_PRICE_PER_GB_EGRESS = 0.05                # ネットワーク送信(egress): $/GB


async def _railway_fetch_usage_totals() -> Optional[dict]:
    """
    今月（月初〜現在）のCPU・メモリ・ボリューム・ネットワーク使用量の積算値を取得します。
    Railway Public APIには金額そのものを返すフィールドが存在しないため、
    ここで取得した使用量にRailway公式の単価をかけて概算金額を算出する。
    取得失敗時はNoneを返します。
    """
    now = datetime.datetime.now(datetime.timezone.utc)
    month_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
    query = """
    query ProjectUsage($projectId: String!, $startDate: DateTime!, $endDate: DateTime!, $measurements: [MetricMeasurement!]!) {
        usage(
            projectId: $projectId
            startDate: $startDate
            endDate: $endDate
            measurements: $measurements
        ) {
            measurement
            tags {
                serviceId
            }
            value
        }
    }
    """
    variables = {
        "projectId": RAILWAY_PROJECT_ID,
        "startDate": month_start.isoformat(),
        "endDate": now.isoformat(),
        "measurements": ["CPU_USAGE", "MEMORY_USAGE_GB", "DISK_USAGE_GB", "NETWORK_TX_GB"],
    }
    data = await _railway_graphql_request(query, variables)
    if not data or data.get("usage") is None:
        return None

    if os.getenv("RAILWAY_MONITOR_DEBUG"):
        print(f"[Railway監視][DEBUG] usage生データ: {json.dumps(data['usage'], ensure_ascii=False)[:3000]}")

    totals = {"CPU_USAGE": 0.0, "MEMORY_USAGE_GB": 0.0, "DISK_USAGE_GB": 0.0, "NETWORK_TX_GB": 0.0}
    for entry in data["usage"]:
        measurement = entry.get("measurement")
        value = entry.get("value")
        if measurement in totals and value is not None:
            totals[measurement] += float(value)
    return totals


def _railway_estimate_cost_from_usage(totals: dict) -> float:
    """
    使用量の積算値（秒単位の値であることを前提）に、Railway公式単価をかけて
    概算のUSD金額を算出します。
    注意: Railway APIが返すvalueの単位（秒 or 分 or 時間積算）が公式ドキュメントで
    明記されていないため、この計算値はあくまで目安。正確な金額はダッシュボードで確認する。
    """
    cpu_cost = totals.get("CPU_USAGE", 0.0) * RAILWAY_PRICE_PER_VCPU_SECOND_CPU
    mem_cost = totals.get("MEMORY_USAGE_GB", 0.0) * RAILWAY_PRICE_PER_GB_SECOND_MEMORY
    disk_cost = totals.get("DISK_USAGE_GB", 0.0) * RAILWAY_PRICE_PER_GB_SECOND_VOLUME
    egress_cost = totals.get("NETWORK_TX_GB", 0.0) * RAILWAY_PRICE_PER_GB_EGRESS
    return cpu_cost + mem_cost + disk_cost + egress_cost




def _railway_latest_value(metric_values: list) -> Optional[float]:
    """メトリクスのvalues配列（ts昇順とは限らない）から最新の値を取り出します。"""
    if not metric_values:
        return None
    try:
        latest = max(metric_values, key=lambda v: v.get("ts", ""))
        return latest.get("value")
    except Exception:
        return None


async def _railway_build_status_embed() -> discord.Embed:
    """Railwayの現在のCPU/メモリ/ストレージ/料金状況をまとめたEmbedを構築します。"""
    if not RAILWAY_MONITOR_AVAILABLE:
        embed = discord.Embed(
            title="[Railway監視] 未設定",
            description=(
                "環境変数 `RAILWAY_API_TOKEN` / `RAILWAY_PROJECT_ID` が設定されていないため、"
                "Railwayの使用状況を取得できません。\n"
                "Railwayダッシュボード → Account Settings → Tokens でトークンを発行し、"
                "対象プロジェクトのIDとあわせて環境変数に設定してください。"
            ),
            color=discord.Color.red(),
            timestamp=discord.utils.utcnow(),
        )
        return embed

    project = await _railway_fetch_project_overview()
    if project is None:
        embed = discord.Embed(
            title="[Railway監視] 取得エラー",
            description=(
                "Railway APIからプロジェクト情報を取得できませんでした。\n"
                "`RAILWAY_API_TOKEN` の有効性・`RAILWAY_PROJECT_ID` が正しいかご確認ください。"
            ),
            color=discord.Color.red(),
            timestamp=discord.utils.utcnow(),
        )
        return embed

    env_edges = project.get("environments", {}).get("edges", [])

    # 環境ID決定: 指定があればそれを使用、なければ先頭の環境（通常production）
    environment_id = RAILWAY_ENVIRONMENT_ID
    if not environment_id and env_edges:
        environment_id = env_edges[0]["node"]["id"]

    # プロジェクト名・環境名・サービス名は非公開情報のため、Embed上には一切表示しない。
    embed = discord.Embed(
        title="[Railway監視] 稼働状況",
        description=f"自動更新中（{RAILWAY_MONITOR_REFRESH_SECONDS}秒間隔）",
        color=discord.Color.blue(),
        timestamp=discord.utils.utcnow(),
    )

    # --- CPU / メモリ ---
    if environment_id:
        metrics = await _railway_fetch_metrics(environment_id)
    else:
        metrics = []

    if metrics:
        cpu_by_service: dict = {}
        mem_by_service: dict = {}
        for m in metrics:
            measurement = m.get("measurement")
            tags = m.get("tags") or {}
            service_id = tags.get("serviceId")
            value = _railway_latest_value(m.get("values", []))
            if value is None:
                continue
            if measurement == "CPU_USAGE":
                cpu_by_service[service_id] = value
            elif measurement == "MEMORY_USAGE_GB":
                mem_by_service[service_id] = value

        if cpu_by_service or mem_by_service:
            lines = []
            all_service_ids = sorted(set(cpu_by_service.keys()) | set(mem_by_service.keys()), key=lambda x: (x is None, x))
            # サービス名・サービスIDは非公開情報のため表示せず、連番のラベルのみ表示する。
            for idx, sid in enumerate(all_service_ids, start=1):
                name = f"サービス{idx}"
                cpu_val = cpu_by_service.get(sid)
                mem_val = mem_by_service.get(sid)
                cpu_text = f"{cpu_val * 100:.1f}%" if cpu_val is not None else "取得不可"
                mem_text = f"{mem_val:.2f} GB" if mem_val is not None else "取得不可"
                lines.append(f"**{name}**\nCPU: {cpu_text} ／ メモリ: {mem_text}")
            field_value = "\n".join(lines)[:1024]
            embed.add_field(name="CPU・メモリ使用状況（サービス別）", value=field_value[:1024], inline=False)
        else:
            embed.add_field(
                name="CPU・メモリ使用状況",
                value="直近のメトリクスデータが見つかりませんでした（デプロイ直後等は反映まで時間がかかる場合があります）。",
                inline=False,
            )
    else:
        embed.add_field(
            name="CPU・メモリ使用状況",
            value="取得できませんでした（APIエラー、またはこのプランで利用できない可能性があります）。",
            inline=False,
        )

    # --- ストレージ（ボリューム） ---
    volumes = await _railway_fetch_volumes()
    if volumes:
        lines = []
        for vol in volumes:
            vol_name = vol.get("name", "(名称未設定)")
            instances = vol.get("volumeInstances", {}).get("edges", [])
            for inst in instances:
                node = inst["node"]
                current_mb = node.get("currentSizeMB")
                size_mb = node.get("sizeMB")
                if current_mb is not None and size_mb:
                    percent = current_mb / size_mb * 100
                    lines.append(f"**{vol_name}**: {current_mb:,.0f} MB / {size_mb:,.0f} MB（{percent:.1f}%）")
                elif current_mb is not None:
                    lines.append(f"**{vol_name}**: {current_mb:,.0f} MB使用中（上限不明）")
        if lines:
            embed.add_field(name="ストレージ（ボリューム）使用状況", value="\n".join(lines)[:1024], inline=False)
        else:
            embed.add_field(name="ストレージ（ボリューム）使用状況", value="このプロジェクトにボリュームは見つかりませんでした。", inline=False)
    else:
        embed.add_field(
            name="ストレージ（ボリューム）使用状況",
            value="取得できませんでした（ボリューム未作成、またはAPIエラーの可能性があります）。",
            inline=False,
        )

    # --- 料金（概算） ---
    # Railway Public APIには金額そのものを返すフィールドが存在しないため、
    # CPU/メモリ/ストレージ/ネットワークの使用量にRailway公式単価をかけて概算する。
    usage_totals = await _railway_fetch_usage_totals()
    if usage_totals is not None:
        estimated_cost = _railway_estimate_cost_from_usage(usage_totals)
        cost_value = (
            f"**約 ${estimated_cost:.2f}**（今月・月初からの概算）\n"
            f"-# Railway公式単価から算出した概算値です。正確な金額は Railway ダッシュボードの Usage ページでご確認ください。"
        )
        embed.add_field(name="今月の推定使用料金（概算）", value=cost_value, inline=False)
    else:
        cost_value = "取得できませんでした（APIエラー、またはこのプランでは使用量データを取得できない可能性があります。正確な金額は Railway ダッシュボードの Usage ページでご確認ください）。"
        embed.add_field(name="今月の推定使用料金", value=cost_value, inline=False)

    embed.set_footer(text="Railway Public API経由で取得 ／ 値は数分遅延する場合があります ／ 料金は概算です")
    return embed


async def _railway_monitor_update_loop(guild_id: int, channel_id: int, message_id: int):
    """
    設置した埋め込みメッセージを RAILWAY_MONITOR_REFRESH_SECONDS 間隔で編集し続け、
    Railwayの使用状況を常時表示するバックグラウンドタスクです。
    """
    await bot.wait_until_ready()
    try:
        while True:
            await asyncio.sleep(RAILWAY_MONITOR_REFRESH_SECONDS)
            key = (guild_id, channel_id)
            if key not in _railway_monitor_sessions:
                return  # /railway_monitor stop 等でセッションが削除されていたら終了
            channel = bot.get_channel(channel_id)
            if channel is None:
                continue
            try:
                message = await channel.fetch_message(message_id)
            except (discord.NotFound, discord.Forbidden, discord.HTTPException):
                print(f"[Railway監視] メッセージ取得に失敗したため監視ループを終了します（channel_id={channel_id}）。")
                _railway_monitor_sessions.pop(key, None)
                return
            try:
                embed = await _railway_build_status_embed()
                await message.edit(embed=embed)
            except Exception as e:
                print(f"[Railway監視] 埋め込みの自動更新に失敗しました: {e}")
    except asyncio.CancelledError:
        raise


# --------------------------------------------------------------------
# Railway Webhook連動: デプロイ中はBotの「視聴中」ステータスを自動更新する
# --------------------------------------------------------------------
# Railway側のプロジェクト設定 → Webhooks で、このBotのWebサーバーURL + "/webhook/railway"
# を登録することで、デプロイ状態の変化（Building/Deploying/Success/Failed等）を
# リアルタイムで受け取り、Discordのプレゼンス（視聴ステータス）に反映する。
# 参考: https://docs.railway.com/observability/webhooks
#
# Webhookペイロード例:
# {
#   "type": "Deployment.building",
#   "details": {"id": "...", "status": "BUILDING", ...},
#   "resource": {
#       "project": {"id": "...", "name": "..."},
#       "environment": {"id": "...", "name": "..."},
#       "service": {"id": "...", "name": "..."},
#       "deployment": {"id": "..."}
#   },
#   "timestamp": "..."
# }
#
# 任意設定。RAILWAY_WEBHOOK_SECRETを設定すると、Railway側から送られる署名ヘッダ
# （未検証仕様のため、まずはURLの秘匿性のみで防御し、判明次第署名検証を追加する）
# の代わりに、URLパスに秘密のトークンを含める簡易認証を行う。
RAILWAY_WEBHOOK_SECRET = os.getenv("RAILWAY_WEBHOOK_SECRET", "")

# デプロイ完了・失敗後、何秒間その結果表示を維持してから通常のローテーションに戻すか
RAILWAY_DEPLOY_STATUS_HOLD_SECONDS = int(os.getenv("RAILWAY_DEPLOY_STATUS_HOLD_SECONDS", "20"))

# Railwayのデプロイ状態(type末尾 or details.status)ごとの日本語表示テキスト。
# type は "Deployment.<状態>" の形式（例: "Deployment.building"）で送られてくる。
_RAILWAY_DEPLOY_STATUS_TEXT = {
    "queued": "キュー待機中",
    "initializing": "初期化中",
    "building": "ビルド中",
    "deploying": "デプロイ中",
    "success": "デプロイ完了",
    "failed": "デプロイ失敗",
    "crashed": "クラッシュ",
    "removed": "削除済み",
    "removing": "削除中",
    "sleeping": "スリープ中",
}


async def _railway_apply_deploy_status(service_name: str, status_key: str):
    """
    Webhookで受け取ったデプロイ状態をDiscordの視聴ステータスへ即時反映します。
    進行中の状態（ビルド中・デプロイ中等）はそのまま表示し続け、
    完了系の状態（成功・失敗等）は一定時間表示した後、自動的に通常表示へ戻します。
    """
    global _railway_deploy_status_override, _railway_deploy_status_clear_task

    status_text = _RAILWAY_DEPLOY_STATUS_TEXT.get(status_key, status_key)
    display_text = f"{service_name}を{status_text}"

    # 既存のクリア待ちタスクがあればキャンセル（新しいイベントで上書きするため）
    if _railway_deploy_status_clear_task is not None and not _railway_deploy_status_clear_task.done():
        _railway_deploy_status_clear_task.cancel()
        _railway_deploy_status_clear_task = None

    _railway_deploy_status_override = display_text
    try:
        await _set_presence_text(bot, display_text, discord.ActivityType.watching)
    except Exception as e:
        print(f"[Railway Webhook] プレゼンス即時反映に失敗しました: {e}")

    print(f"[Railway Webhook] ステータス反映: {display_text}")

    # 進行中ではない（＝最終状態）の場合は、一定時間後にオーバーライドを解除する
    is_terminal = status_key in ("success", "failed", "crashed", "removed", "sleeping")
    if is_terminal:
        async def _clear_after_delay():
            try:
                await asyncio.sleep(RAILWAY_DEPLOY_STATUS_HOLD_SECONDS)
                global _railway_deploy_status_override
                _railway_deploy_status_override = None
                print("[Railway Webhook] デプロイ状態表示をクリアし、通常表示に戻します。")
            except asyncio.CancelledError:
                pass

        _railway_deploy_status_clear_task = asyncio.create_task(_clear_after_delay())


async def _railway_webhook_handler(request: aiohttp.web.Request) -> aiohttp.web.Response:
    """RailwayのWebhookを受信し、デプロイ状態をBotのステータスへ反映するハンドラです。"""
    # URLパスに秘密トークンを含める簡易認証（RAILWAY_WEBHOOK_SECRET設定時のみ）
    if RAILWAY_WEBHOOK_SECRET:
        token = request.match_info.get("secret", "")
        if token != RAILWAY_WEBHOOK_SECRET:
            return aiohttp.web.Response(status=403, text="Forbidden")

    try:
        payload = await request.json()
    except Exception:
        return aiohttp.web.Response(status=400, text="Invalid JSON")

    event_type = payload.get("type", "")  # 例: "Deployment.building"
    if not event_type.startswith("Deployment."):
        # デプロイ以外のWebhookイベント（ボリューム使用率アラート等）は今回は無視する
        return aiohttp.web.Response(status=200, text="ignored (not a deployment event)")

    status_key = event_type.split(".", 1)[1].lower() if "." in event_type else ""
    resource = payload.get("resource", {}) or {}
    service_name = (resource.get("service") or {}).get("name", "サービス")

    try:
        await _railway_apply_deploy_status(service_name, status_key)
    except Exception as e:
        print(f"[Railway Webhook] 処理中にエラーが発生しました: {e}")

    return aiohttp.web.Response(status=200, text="ok")


