# --------------------------------------------------------------------
# /calc — 数式計算
# --------------------------------------------------------------------

@bot.tree.command(name="calc", description="数式を入力すると計算して答えを返してくれます")
@app_commands.allowed_contexts(guilds=True, dms=True, private_channels=True)
@app_commands.allowed_installs(guilds=True, users=True)
async def calc(interaction: discord.Interaction, 数式: str):
    """
    四則演算・累乗・括弧・関数（sin/cos/sqrt等）に対応。
    import や exec などの危険な操作は禁止されています。
    """
    import math
    import ast as _ast
    import operator as _op

    # 許可する演算子・関数のみのサンドボックス
    ALLOWED_OPS = {
        _ast.Add:    _op.add,
        _ast.Sub:    _op.sub,
        _ast.Mult:   _op.mul,
        _ast.Div:    _op.truediv,
        _ast.Pow:    _op.pow,
        _ast.USub:   _op.neg,
        _ast.UAdd:   _op.pos,
        _ast.Mod:    _op.mod,
        _ast.FloorDiv: _op.floordiv,
    }
    ALLOWED_FUNCS = {
        "sin": math.sin, "cos": math.cos, "tan": math.tan,
        "asin": math.asin, "acos": math.acos, "atan": math.atan,
        "sqrt": math.sqrt, "log": math.log, "log10": math.log10,
        "log2": math.log2, "exp": math.exp, "abs": abs,
        "ceil": math.ceil, "floor": math.floor, "round": round,
        "factorial": math.factorial, "degrees": math.degrees,
        "radians": math.radians,
    }
    ALLOWED_CONSTS = {
        "pi": math.pi, "e": math.e, "tau": math.tau, "inf": math.inf,
    }

    def _safe_eval(node):
        if isinstance(node, _ast.Constant):
            if isinstance(node.value, (int, float)):
                return node.value
            raise ValueError("文字列や他の型は使用できません")
        elif isinstance(node, _ast.BinOp):
            op_type = type(node.op)
            if op_type not in ALLOWED_OPS:
                raise ValueError(f"使用できない演算子です: {op_type.__name__}")
            left  = _safe_eval(node.left)
            right = _safe_eval(node.right)
            if op_type == _ast.Div and right == 0:
                raise ZeroDivisionError("0で割ることはできません")
            return ALLOWED_OPS[op_type](left, right)
        elif isinstance(node, _ast.UnaryOp):
            op_type = type(node.op)
            if op_type not in ALLOWED_OPS:
                raise ValueError(f"使用できない演算子です: {op_type.__name__}")
            return ALLOWED_OPS[op_type](_safe_eval(node.operand))
        elif isinstance(node, _ast.Call):
            if not isinstance(node.func, _ast.Name):
                raise ValueError("関数呼び出しの形式が不正です")
            func_name = node.func.id
            if func_name not in ALLOWED_FUNCS:
                raise ValueError(f"使用できない関数です: `{func_name}`")
            args = [_safe_eval(a) for a in node.args]
            return ALLOWED_FUNCS[func_name](*args)
        elif isinstance(node, _ast.Name):
            if node.id in ALLOWED_CONSTS:
                return ALLOWED_CONSTS[node.id]
            raise ValueError(f"使用できない変数です: `{node.id}`")
        else:
            raise ValueError(f"サポートされていない式の形式です: {type(node).__name__}")

    expr = 数式.strip()
    # 全角数字・記号を半角に変換
    expr = expr.translate(str.maketrans(
        "０１２３４５６７８９＋－×÷＊＾（）　",
        "0123456789+-*/*^ () "
    ))
    expr = expr.replace("^", "**").replace("×", "*").replace("÷", "/")

    try:
        tree = _ast.parse(expr, mode="eval")
        result = _safe_eval(tree.body)
    except ZeroDivisionError as e:
        await interaction.response.send_message(f"[NG] エラー: {e}", ephemeral=True)
        return
    except (ValueError, TypeError) as e:
        await interaction.response.send_message(f"[NG] 計算エラー: {e}", ephemeral=True)
        return
    except SyntaxError:
        await interaction.response.send_message("[NG] 数式の形式が正しくありません。", ephemeral=True)
        return
    except Exception as e:
        await interaction.response.send_message(f"[NG] 予期しないエラー: {e}", ephemeral=True)
        return

    # 結果の整形（整数なら小数点なし）
    if isinstance(result, float) and result.is_integer():
        result_str = str(int(result))
    elif isinstance(result, float):
        result_str = f"{result:.10g}"
    else:
        result_str = str(result)

    embed = discord.Embed(color=discord.Color.blurple())
    embed.add_field(name="計算式", value=f"```\n{数式}\n```", inline=False)
    embed.add_field(name="結果",   value=f"```\n{result_str}\n```", inline=False)
    embed.set_footer(text="使用可能: + - * / ** % // | sin cos sqrt log pi e ...")
    await interaction.response.send_message(embed=embed)


# --------------------------------------------------------------------
# /giveaway — 抽選プレゼント機能
# --------------------------------------------------------------------

# 実行中プレゼント管理 {message_id: asyncio.Task}
_giveaway_tasks: dict[int, asyncio.Task] = {}


class GiveawayJoinView(discord.ui.View):
    """プレゼント参加ボタンビュー。カスタムIDで永続化対応。"""
    def __init__(self):
        super().__init__(timeout=None)

    async def on_error(self, interaction: discord.Interaction, error: Exception, item: discord.ui.Item):
        # [修正] View内のコールバックで想定外の例外が発生した場合の最終防御ライン。
        # join() 内は既にtry/exceptで保護しているが、万一discord.py内部やdiscord側の
        # 挙動変化で例外が漏れてもBotが応答不能に見えないようにする。
        print(f"[GiveawayJoinView] コンポーネントエラー: {error!r}")
        try:
            if interaction.response.is_done():
                await interaction.followup.send("エラーが発生しました。もう一度お試しください。", ephemeral=True)
            else:
                await interaction.response.send_message("エラーが発生しました。もう一度お試しください。", ephemeral=True)
        except discord.HTTPException:
            pass

    @discord.ui.button(
        label="[*] 参加する",
        style=discord.ButtonStyle.success,
        custom_id="giveaway_join"
    )
    async def join(self, interaction: discord.Interaction, button: discord.ui.Button):
        # [修正] 以前はこの関数全体が try/except で保護されておらず、
        # 予期しない例外（KeyError, discord.NotFound 等）が発生すると
        # interaction への応答が一切返らないまま終了し、Discord側で
        # 「このインタラクションは失敗しました」と表示される原因になっていました。
        # また load_data() が同期I/Oでブロッキングするため、データが増えるほど
        # 3秒の応答制限に間に合わなくなる問題もありました（aload_data/asave_data で解消）。
        try:
            await self._handle_join(interaction)
        except Exception as e:
            print(f"[giveaway] 参加処理中にエラーが発生しました: {e}")
            try:
                if interaction.response.is_done():
                    await interaction.followup.send(
                        "処理中にエラーが発生しました。もう一度お試しください。", ephemeral=True
                    )
                else:
                    await interaction.response.send_message(
                        "処理中にエラーが発生しました。もう一度お試しください。", ephemeral=True
                    )
            except Exception:
                pass  # ここまで失敗した場合は静かに諦める（ユーザーへの通知はできないが、Bot自体は継続稼働）

    async def _handle_join(self, interaction: discord.Interaction):
        if not interaction.guild:
            return

        msg_id_str = str(interaction.message.id)
        uid = interaction.user.id

        # イベントループをブロックしないよう非同期版でファイルI/Oを行う
        all_data = await aload_data()
        cfg = get_guild_config(all_data, str(interaction.guild.id))
        giveaways = cfg.get("giveaways", {})

        if msg_id_str not in giveaways:
            await interaction.response.send_message("このプレゼント企画は終了または削除されました。", ephemeral=True)
            return

        gw = giveaways[msg_id_str]
        participants = gw.setdefault("participants", [])
        joined = uid not in participants

        # [修正] 複数人がほぼ同時にボタンを押した際、
        # 「読み込み→変更→保存」の間に他の参加登録が上書きされて消える
        # レースコンディションが起こり得ました。
        # 保存直前に最新データを読み直し、対象giveawayの参加者リストのみを
        # マージしてから保存することで、同時押しによる取りこぼしを防ぎます。
        latest_data = await aload_data()
        latest_cfg = get_guild_config(latest_data, str(interaction.guild.id))
        latest_giveaways = latest_cfg.get("giveaways", {})
        if msg_id_str in latest_giveaways:
            latest_gw = latest_giveaways[msg_id_str]
            latest_participants = set(latest_gw.get("participants", []))
            if joined:
                latest_participants.add(uid)
            else:
                latest_participants.discard(uid)
            latest_gw["participants"] = list(latest_participants)
            participants = latest_gw["participants"]
        all_data = latest_data

        await asave_data(all_data)

        if joined:
            await interaction.response.send_message(
                "[*] プレゼント企画に参加しました！もう一度押すと取り消せます。", ephemeral=True
            )
        else:
            await interaction.response.send_message("プレゼント企画への参加を取り消しました。", ephemeral=True)

        # Embed の参加者数を更新（失敗してもユーザーへの応答自体は既に完了しているので致命的ではない）
        try:
            if interaction.message.embeds:
                embed = interaction.message.embeds[0]
                for i, field in enumerate(embed.fields):
                    if field.name and "参加者" in field.name:
                        embed.set_field_at(i, name="参加者数", value=f"{len(participants)}人", inline=True)
                        break
                await interaction.message.edit(embed=embed)
        except (discord.NotFound, discord.Forbidden, discord.HTTPException):
            pass


def _build_giveaway_embed(prize: str, host: discord.Member, end_dt: datetime.datetime, winners: int, participants: int) -> discord.Embed:
    embed = discord.Embed(
        title=f"[*] プレゼント企画: {prize}",
        color=discord.Color.gold()
    )
    embed.add_field(name="景品", value=prize, inline=True)
    embed.add_field(name="当選人数", value=f"{winners}人", inline=True)
    embed.add_field(name="参加者数", value=f"{participants}人", inline=True)
    embed.add_field(name="主催者", value=host.mention, inline=True)
    embed.add_field(name="終了日時", value=discord.utils.format_dt(end_dt, style="F"), inline=True)
    embed.set_footer(text="[*] ボタンを押して参加！もう一度押すと取り消せます")
    embed.timestamp = end_dt
    return embed


def _cancel_giveaway_task(message_id: int):
    """指定メッセージIDの実行中giveawayタスクがあればキャンセルして辞書から除去します。
    [修正] on_ready は再接続のたびに複数回呼ばれる可能性があり、以前は
    同一giveawayに対して重複してタスクを起動する保護がありませんでした。
    重複タスクが走ると、片方が抽選・データ削除・メッセージ編集を行った後、
    もう片方が既に消えたデータへアクセスして失敗したり、
    メッセージへの二重編集で discord.HTTPException が発生する原因になっていました。"""
    old_task = _giveaway_tasks.pop(message_id, None)
    if old_task and not old_task.done():
        old_task.cancel()


async def _run_giveaway(channel: discord.TextChannel, message_id: int, guild_id: int, end_dt: datetime.datetime):
    """指定時刻まで待機し、抽選を実行します。"""
    try:
        now = discord.utils.utcnow()
        wait_seconds = (end_dt - now).total_seconds()
        if wait_seconds > 0:
            await asyncio.sleep(wait_seconds)

        # 抽選実行（非同期I/Oでイベントループのブロッキングを回避）
        all_data = await aload_data()
        cfg = get_guild_config(all_data, str(guild_id))
        giveaways = cfg.get("giveaways", {})
        msg_id_str = str(message_id)

        if msg_id_str not in giveaways:
            return

        gw = giveaways[msg_id_str]
        participants = gw.get("participants", [])
        winner_count = gw.get("winners", 1)
        prize = gw.get("prize", "景品")

        if not participants:
            result_embed = discord.Embed(
                title="[*] プレゼント企画 終了",
                description=f"**{prize}**\n\n参加者がいなかったため、当選者なしで終了しました。",
                color=discord.Color.greyple()
            )
        else:
            actual_winners = min(winner_count, len(participants))
            chosen = random.sample(participants, actual_winners)
            mentions = " ".join(f"<@{uid}>" for uid in chosen)
            result_embed = discord.Embed(
                title="[*] プレゼント企画 終了！",
                description=f"**景品: {prize}**\n\n[WIN] 当選者: {mentions}\nおめでとうございます！",
                color=discord.Color.gold()
            )
            result_embed.add_field(name="参加者数", value=f"{len(participants)}人", inline=True)
            result_embed.add_field(name="当選人数", value=f"{actual_winners}人", inline=True)

        result_embed.timestamp = discord.utils.utcnow()

        # 元メッセージを更新してボタンを無効化
        try:
            msg = await channel.fetch_message(message_id)
            disabled_view = discord.ui.View()
            disabled_btn = discord.ui.Button(
                label="[*] 終了（参加受付終了）",
                style=discord.ButtonStyle.secondary,
                disabled=True
            )
            disabled_view.add_item(disabled_btn)
            await msg.edit(view=disabled_view)
        except (discord.NotFound, discord.Forbidden, discord.HTTPException):
            pass

        try:
            await channel.send(embed=result_embed)
        except (discord.Forbidden, discord.HTTPException):
            pass

        # データから削除（再読込してから削除することで、待機中に他の変更が
        # 保存されていた場合でも上書きしてしまわないようにする）
        final_data = await aload_data()
        final_cfg = get_guild_config(final_data, str(guild_id))
        final_giveaways = final_cfg.get("giveaways", {})
        final_giveaways.pop(msg_id_str, None)
        await asave_data(final_data)
    except asyncio.CancelledError:
        # [修正] 再接続時に重複タスクをキャンセルする際、ここで静かに終了する。
        # 送出しないと再送出扱いになりタスクの例外ログに残るため、意図した
        # キャンセルであることを明示して握りつぶす。
        raise
    except Exception as e:
        print(f"[giveaway] 抽選処理中にエラーが発生しました (message_id={message_id}): {e}")
    finally:
        _giveaway_tasks.pop(message_id, None)


@bot.tree.command(name="giveaway", description="【管理者専用】プレゼント企画をこの場で始められます")
@discord.app_commands.choices(操作=[
    discord.app_commands.Choice(name="開始する", value="start"),
    discord.app_commands.Choice(name="終了する（即時抽選）", value="end"),
    discord.app_commands.Choice(name="一覧を表示", value="list"),
])
async def giveaway(
    interaction: discord.Interaction,
    操作: discord.app_commands.Choice[str],
    景品: str = None,
    時間_分: int = None,
    当選人数: int = 1,
):
    if not await is_admin_or_allowed(interaction):
        return
    if not interaction.guild:
        return

    if 操作.value == "list":
        all_data = await aload_data()
        cfg = get_guild_config(all_data, str(interaction.guild.id))
        giveaways = cfg.get("giveaways", {})
        if not giveaways:
            await interaction.response.send_message("現在進行中のプレゼント企画はありません。", ephemeral=True)
            return
        embed = discord.Embed(title="進行中のプレゼント企画", color=discord.Color.gold())
        for msg_id, gw in giveaways.items():
            end_dt = datetime.datetime.fromisoformat(gw["end_at"])
            embed.add_field(
                name=f"[*] {gw['prize']}",
                value=(
                    f"メッセージID: `{msg_id}`\n"
                    f"参加者: {len(gw.get('participants', []))}人 / "
                    f"当選: {gw['winners']}人\n"
                    f"終了: {discord.utils.format_dt(end_dt, style='R')}"
                ),
                inline=False
            )
        await interaction.response.send_message(embed=embed, ephemeral=True)
        return

    if 操作.value == "end":
        all_data = await aload_data()
        cfg = get_guild_config(all_data, str(interaction.guild.id))
        giveaways = cfg.get("giveaways", {})
        if not giveaways:
            await interaction.response.send_message("進行中のプレゼント企画がありません。", ephemeral=True)
            return
        # 最新のプレゼントを即時終了
        latest_id = int(list(giveaways.keys())[-1])
        _cancel_giveaway_task(latest_id)  # [修正] 既存タスクの重複起動を確実に防止
        gw = giveaways[str(latest_id)]
        ch = interaction.guild.get_channel(gw.get("channel_id", interaction.channel.id))
        if ch:
            gw["end_at"] = discord.utils.utcnow().isoformat()
            await asave_data(all_data)
            new_task = asyncio.create_task(_run_giveaway(ch, latest_id, interaction.guild.id, discord.utils.utcnow()))
            _giveaway_tasks[latest_id] = new_task
        await interaction.response.send_message("プレゼント企画を即時終了して抽選を実行します。", ephemeral=True)
        return

    # 操作 == "start"
    if not 景品 or not 時間_分:
        await interaction.response.send_message("「開始する」の場合は「景品」と「時間_分」を指定してください。", ephemeral=True)
        return
    if 時間_分 < 1 or 時間_分 > 43200:
        await interaction.response.send_message("時間は1分〜43200分（30日）で指定してください。", ephemeral=True)
        return
    if 当選人数 < 1 or 当選人数 > 20:
        await interaction.response.send_message("当選人数は1〜20人で指定してください。", ephemeral=True)
        return

    await interaction.response.defer(ephemeral=True)

    end_dt = discord.utils.utcnow() + datetime.timedelta(minutes=時間_分)
    embed = _build_giveaway_embed(景品, interaction.user, end_dt, 当選人数, 0)
    view = GiveawayJoinView()

    try:
        msg = await interaction.channel.send(embed=embed, view=view)
    except (discord.Forbidden, discord.HTTPException) as e:
        await interaction.followup.send(f"プレゼント企画の投稿に失敗しました: {e}", ephemeral=True)
        return

    all_data = await aload_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))
    cfg.setdefault("giveaways", {})[str(msg.id)] = {
        "prize": 景品,
        "winners": 当選人数,
        "end_at": end_dt.isoformat(),
        "channel_id": interaction.channel.id,
        "host_id": interaction.user.id,
        "participants": [],
    }
    await asave_data(all_data)

    task = asyncio.create_task(_run_giveaway(interaction.channel, msg.id, interaction.guild.id, end_dt))
    _giveaway_tasks[msg.id] = task

    await interaction.followup.send(
        f"[*] プレゼント企画を開始しました！\n景品: **{景品}** / {時間_分}分後に抽選 / 当選{当選人数}人",
        ephemeral=True
    )


# --------------------------------------------------------------------
# /server protect alt_check — 新規アカウント検知設定
# --------------------------------------------------------------------

@server_protect_group.command(name="alt_check", description="【管理者専用】作られたばかりのアカウント（垢BAN逃れの疑いがあるもの）を自動で検知する設定ができます")
@discord.app_commands.choices(操作=[
    discord.app_commands.Choice(name="有効にする", value="on"),
    discord.app_commands.Choice(name="無効にする", value="off"),
    discord.app_commands.Choice(name="現在の設定を確認", value="status"),
])
@discord.app_commands.choices(アクション=[
    discord.app_commands.Choice(name="通知のみ（ログチャンネルに報告）", value="notify"),
    discord.app_commands.Choice(name="キック（参加拒否）", value="kick"),
    discord.app_commands.Choice(name="BAN", value="ban"),
])
async def alt_check(
    interaction: discord.Interaction,
    操作: discord.app_commands.Choice[str],
    アクション: discord.app_commands.Choice[str] = None,
    閾値_日数: app_commands.Range[int, 1, 365] = None,
):
    if not await is_guild_admin(interaction):
        return
    if not interaction.guild:
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))

    if 操作.value == "status":
        embed = discord.Embed(title="alt_check 設定状況", color=discord.Color.blue())
        embed.add_field(name="状態", value="有効" if cfg.get("alt_check_enabled") else "無効", inline=True)
        embed.add_field(name="閾値", value=f"{cfg.get('alt_check_days', 30)}日未満", inline=True)
        action_label = {"notify": "通知のみ", "kick": "キック", "ban": "BAN"}.get(cfg.get("alt_check_action", "notify"), "不明")
        embed.add_field(name="アクション", value=action_label, inline=True)
        embed.set_footer(text="参加メンバーのアカウント作成日が閾値より新しい場合に反応します（ウェブ認証(/web_auth)にも同じ設定が適用されます）")
        await interaction.response.send_message(embed=embed, ephemeral=True)
        return

    if 操作.value == "off":
        cfg["alt_check_enabled"] = False
        save_data(all_data)
        await interaction.response.send_message("alt_check を無効にしました。", ephemeral=True)
        return

    # on
    cfg["alt_check_enabled"] = True
    if アクション:
        cfg["alt_check_action"] = アクション.value
    if 閾値_日数:
        cfg["alt_check_days"] = 閾値_日数
    save_data(all_data)

    action_label = {"notify": "通知のみ", "kick": "キック", "ban": "BAN"}.get(cfg["alt_check_action"], "通知のみ")
    await interaction.response.send_message(
        f"alt_check を有効にしました。\n"
        f"・閾値: アカウント作成から **{cfg['alt_check_days']}日未満** で反応\n"
        f"・アクション: **{action_label}**\n"
        "ログチャンネルを設定していない場合は通知が届きません（`/automod modlog_set` で設定してください）。\n"
        "この設定は通常の参加時チェックに加え、**ウェブ認証（/web_auth）実行時のチェックにも適用**されます。",
        ephemeral=True
    )


# --------------------------------------------------------------------
# /server protect iplogger_check — IPロガー自動検知設定
# --------------------------------------------------------------------

@server_protect_group.command(name="iplogger_check", description="【管理者専用】IPロガーやフィッシングリンクを自動で見つけて削除する設定ができます")
@discord.app_commands.choices(状態=[
    discord.app_commands.Choice(name="有効にする", value="on"),
    discord.app_commands.Choice(name="無効にする", value="off"),
])
async def iplogger_check(interaction: discord.Interaction, 状態: discord.app_commands.Choice[str]):
    if not await is_guild_admin(interaction):
        return
    if not interaction.guild:
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))
    cfg["iplogger_check_enabled"] = (状態.value == "on")
    save_data(all_data)

    if 状態.value == "on":
        await interaction.response.send_message(
            "IPロガー検知を **有効** にしました。\n"
            "grabify.link / iplogger.org などの既知ドメインと、\n"
            "bit.ly 等の短縮URLの展開先も自動チェックします。\n"
            "検知した場合はメッセージを即削除し、モデレーションログに記録します。",
            ephemeral=True
        )
    else:
        await interaction.response.send_message("IPロガー検知を **無効** にしました。", ephemeral=True)


# --------------------------------------------------------------------
# /server protect ip_ban_check — ウェブ認証を利用したBAN逃れ（IP）対策
# --------------------------------------------------------------------

@server_protect_group.command(name="ip_ban_check", description="【管理者専用】ウェブ認証を使って、同じIPからのBAN逃れを検知する対策を設定できます")
@app_commands.describe(
    操作="有効化 / 無効化 / 現在の設定確認",
    アクション="同一IPを検知した際の処置（onの場合のみ）"
)
@discord.app_commands.choices(
    操作=[
        discord.app_commands.Choice(name="有効にする", value="on"),
        discord.app_commands.Choice(name="無効にする", value="off"),
        discord.app_commands.Choice(name="設定確認", value="status"),
    ],
    アクション=[
        discord.app_commands.Choice(name="通知のみ（認証は継続させる）", value="notify"),
        discord.app_commands.Choice(name="キック", value="kick"),
        discord.app_commands.Choice(name="BAN", value="ban"),
    ]
)
async def ip_ban_check(
    interaction: discord.Interaction,
    操作: discord.app_commands.Choice[str],
    アクション: discord.app_commands.Choice[str] = None
):
    if not await is_guild_admin(interaction):
        return
    if not interaction.guild:
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))

    if 操作.value == "status":
        embed = discord.Embed(title="ip_ban_check 設定状況", color=discord.Color.blue())
        embed.add_field(name="状態", value="有効" if cfg.get("ip_ban_check_enabled") else "無効", inline=True)
        action_label = {"notify": "通知のみ", "kick": "キック", "ban": "BAN"}.get(cfg.get("ip_ban_action", "ban"), "不明")
        embed.add_field(name="アクション", value=action_label, inline=True)
        embed.add_field(name="記録済みBAN済みIP件数", value=str(len(cfg.get("banned_ip_hashes", {}))), inline=True)
        embed.set_footer(text="ウェブ認証(/web_auth)を経由したユーザーのみが対象です（IPはハッシュ化して保存されます）")
        await interaction.response.send_message(embed=embed, ephemeral=True)
        return

    if 操作.value == "off":
        cfg["ip_ban_check_enabled"] = False
        save_data(all_data)
        await interaction.response.send_message("IP対策（BAN逃れ検知）を無効にしました。", ephemeral=True)
        return

    # on
    cfg["ip_ban_check_enabled"] = True
    if アクション:
        cfg["ip_ban_action"] = アクション.value
    save_data(all_data)

    action_label = {"notify": "通知のみ", "kick": "キック", "ban": "BAN"}.get(cfg.get("ip_ban_action", "ban"), "BAN")
    await interaction.response.send_message(
        "IP対策（BAN逃れ検知）を **有効** にしました。\n"
        f"・アクション: **{action_label}**\n\n"
        "【仕組み】\n"
        "・ウェブ認証(/web_auth)を通過したユーザーの接続元IPを、ハッシュ化して記録します。\n"
        "・そのユーザーが後でBANされると、記録済みのIPハッシュが「BAN済みIP」として登録されます。\n"
        "・別アカウントが同じIPからウェブ認証を試みると、BAN逃れとして検知・処置されます。\n\n"
        "⚠️ 注意点\n"
        "・IP検知はウェブ認証を経由したユーザーのみが対象です（通常参加のみのユーザーは対象外）。\n"
        "・スマホの回線切替やVPN、公共Wi-Fi等では同居人・同施設利用者を誤検知する可能性があります。\n"
        "　誤爆が心配な場合はまず「通知のみ」で運用し、ログを見ながら判断することをおすすめします。\n"
        "・ログチャンネルを設定していない場合は通知が届きません（`/automod modlog_set` で設定してください）。",
        ephemeral=True
    )


