class EmbedResponseSubmitModal(discord.ui.Modal):
    """ユーザーが「回答する」ボタンを押した際に開く、固定2項目（タイトル・本文）の回答フォーム。"""

    def __init__(self, guild_id: int, panel_id: int, modal_title: str, title_label: str, body_label: str, allow_attachment: bool = False):
        super().__init__(title=modal_title[:45] or "回答フォーム")
        self.guild_id = guild_id
        self.panel_id = panel_id
        self.allow_attachment = allow_attachment
        self.title_input = discord.ui.TextInput(
            label=title_label[:45] or "タイトル",
            max_length=256,
            required=True
        )
        self.body_input = discord.ui.TextInput(
            label=body_label[:45] or "本文",
            style=discord.TextStyle.paragraph,
            max_length=4000,
            required=True
        )
        self.add_item(self.title_input)
        self.add_item(self.body_input)

    async def on_submit(self, interaction: discord.Interaction):
        # Discordの仕様上、Modal自体にファイル添付欄は置けないため、
        # 「ファイル添付を許可」しているパネルではModal送信後にチャンネルへ
        # ファイルを送ってもらい、Botがそれを拾って回答Embedに添付する。
        if not self.allow_attachment:
            await _handle_embed_response_submit(
                interaction, self.guild_id, self.panel_id,
                self.title_input.value, self.body_input.value
            )
            return

        await interaction.response.send_message(
            "[添付] 続けて、この回答に添付するファイル（画像・PDFなど）を"
            "このチャンネルに60秒以内に送信してください。\n"
            "添付が不要な場合は「スキップ」と入力して送信してください。",
            ephemeral=True
        )

        def _check(m: discord.Message) -> bool:
            return m.author.id == interaction.user.id and m.channel.id == interaction.channel.id

        file_to_send = None
        is_image = False
        try:
            msg = await bot.wait_for("message", timeout=60.0, check=_check)
            if msg.attachments:
                attachment = msg.attachments[0]
                # メッセージを削除する前に、その場でファイルの中身をダウンロードして
                # メモリ（BytesIO）に確保しておく。添付ファイルはメッセージに紐づいた
                # CDN URLのため、msg.delete()後にattachment.to_file()を呼ぶと
                # ダウンロードに失敗する（＝画像が空になる）ことがあるため。
                try:
                    file_bytes = await attachment.read()
                    file_to_send = discord.File(io.BytesIO(file_bytes), filename=attachment.filename)
                    is_image = bool(attachment.content_type and attachment.content_type.startswith("image/"))
                except (discord.HTTPException, discord.NotFound):
                    file_to_send = None
            try:
                await msg.delete()
            except (discord.Forbidden, discord.HTTPException):
                pass
        except asyncio.TimeoutError:
            await interaction.followup.send(
                "[時間切れ] ファイル送信の待機がタイムアウトしました。添付なしで回答を送信します。",
                ephemeral=True
            )

        await _handle_embed_response_submit(
            interaction, self.guild_id, self.panel_id,
            self.title_input.value, self.body_input.value,
            file_to_send=file_to_send, is_image=is_image, use_followup=True
        )


class EmbedResponseButton(discord.ui.Button):
    """送信済みEmbedに添える「回答する」ボタン。custom_idにguild_id/panel_idを埋め込み、
    Bot再起動後も汎用登録（message_id指定なし）で反応できるようにする。"""

    def __init__(self, guild_id: int, panel_id: int, label: str):
        super().__init__(
            label=label[:80] if label else "回答する",
            style=discord.ButtonStyle.primary,
            custom_id=f"embedpanel_answer_{guild_id}_{panel_id}"
        )
        self.guild_id = guild_id
        self.panel_id = panel_id

    async def callback(self, interaction: discord.Interaction):
        all_data = load_data()
        cfg = get_guild_config(all_data, str(self.guild_id))
        panels = cfg.get("embed_response_panels", {})
        panel = panels.get(str(self.panel_id))
        if panel is None:
            await interaction.response.send_message("このパネルの設定が見つかりませんでした。管理者にお問い合わせください。", ephemeral=True)
            return
        modal = EmbedResponseSubmitModal(
            self.guild_id, self.panel_id,
            panel.get("modal_title", "回答フォーム"),
            panel.get("title_field_label", "タイトル"),
            panel.get("body_field_label", "本文"),
            allow_attachment=panel.get("allow_attachment", False),
        )
        await interaction.response.send_modal(modal)


class EmbedResponsePanelView(discord.ui.View):
    """Modal付きEmbedに添えるView（「回答する」ボタンのみ）。timeout=Noneで永続化。"""

    def __init__(self, guild_id: int, panel_id: int, label: str):
        super().__init__(timeout=None)
        self.add_item(EmbedResponseButton(guild_id, panel_id, label))


async def _handle_embed_response_submit(
    interaction: discord.Interaction,
    guild_id: int,
    panel_id: int,
    title_value: str,
    body_value: str,
    file_to_send: discord.File = None,
    is_image: bool = False,
    use_followup: bool = False,
):
    """回答Modal送信時の処理。回答送信先チャンネルへEmbed形式で内容を送信する。
    file_to_send が指定されている場合は、回答Embedにファイルを添付して送信する。
    （呼び出し側で元メッセージ削除前にダウンロード済みのファイルを渡す想定）
    use_followup=True の場合、既にinteractionへ応答済み（ファイル添付待ちの案内を送信済み）
    のため、以降のメッセージは interaction.followup 経由で送る。"""

    async def _reply(content: str):
        if use_followup:
            await interaction.followup.send(content, ephemeral=True)
        else:
            await interaction.response.send_message(content, ephemeral=True)

    guild = bot.get_guild(guild_id)
    if guild is None:
        await _reply("サーバー情報を取得できませんでした。")
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(guild_id))
    panels = cfg.get("embed_response_panels", {})
    panel = panels.get(str(panel_id))
    if panel is None:
        await _reply("このパネルの設定が見つかりませんでした。管理者にお問い合わせください。")
        return

    response_channel_id = panel.get("response_channel_id")
    response_channel = guild.get_channel(response_channel_id) if response_channel_id else None
    if response_channel is None:
        await _reply("回答送信先チャンネルが見つかりませんでした。管理者にお問い合わせください。")
        return

    result_embed = discord.Embed(
        title=title_value[:256],
        description=body_value[:4000],
        color=discord.Color.blurple(),
        timestamp=discord.utils.utcnow()
    )
    result_embed.set_footer(text=f"回答者: {interaction.user}（ID: {interaction.user.id}）")

    mention_role_id = panel.get("mention_role_id")
    mention_content = f"<@&{mention_role_id}>" if mention_role_id else None
    allowed_mentions = discord.AllowedMentions(roles=True) if mention_role_id else discord.AllowedMentions.none()

    # 添付ファイルは呼び出し側で（元メッセージ削除前に）ダウンロード済みのものを受け取る。
    # 画像であればEmbedにも表示する。
    if file_to_send is not None and is_image:
        result_embed.set_image(url=f"attachment://{file_to_send.filename}")

    try:
        if file_to_send is not None:
            await response_channel.send(
                content=mention_content, embed=result_embed, file=file_to_send,
                allowed_mentions=allowed_mentions
            )
        else:
            await response_channel.send(content=mention_content, embed=result_embed, allowed_mentions=allowed_mentions)
    except discord.Forbidden:
        await _reply("回答送信先チャンネルへの送信権限がBotにありません。管理者にお問い合わせください。")
        return
    except discord.HTTPException as e:
        await _reply(f"送信エラー: {e}")
        return

    await _reply("[OK] 回答を送信しました。ご協力ありがとうございました。")


class EmbedBuilderView(discord.ui.View):
    """Embed作成GUIビュー。"""

    def __init__(self, author: discord.abc.User, target_channel: discord.TextChannel):
        super().__init__(timeout=600)
        self.author = author
        self.target_channel = target_channel
        self.embed_data: dict = {
            "title": None,
            "description": None,
            "footer": None,
            "color": "ブルー",
            "image_url": None,
            "thumbnail_url": None,
            "fields": [],   # [{"name": str, "value": str, "inline": bool}]
        }
        # Modal（回答フォーム）を付けるかどうかの設定。response_channel が None のままなら付けない。
        self.modal_config: dict = {
            "enabled": False,
            "response_channel_id": None,
            "button_label": "回答する",
            "modal_title": "回答フォーム",
            "title_field_label": "タイトル",
            "body_field_label": "本文",
            "mention_role_id": None,  # Modal送信時にメンションするロール（1つのみ、任意）
            "allow_attachment": False,  # Modal送信後にファイル添付を受け付けるかどうか
        }
        self.add_item(EmbedColorSelect(self))

    def _build_base_embed(self) -> discord.Embed:
        """Embedの本体（タイトル・本文・フィールド・色など）だけを組み立てる共通処理。"""
        color = EMBED_COLOR_OPTIONS.get(self.embed_data.get("color", "ブルー"), discord.Color.blue())
        embed = discord.Embed(
            title=self.embed_data.get("title") or "（タイトル未入力）",
            description=self.embed_data.get("description") or "（本文未入力）",
            color=color
        )
        for f in self.embed_data.get("fields", []):
            embed.add_field(name=f["name"], value=f["value"], inline=f.get("inline", False))
        if self.embed_data.get("footer"):
            embed.set_footer(text=self.embed_data["footer"])
        if self.embed_data.get("image_url"):
            embed.set_image(url=self.embed_data["image_url"])
        if self.embed_data.get("thumbnail_url"):
            embed.set_thumbnail(url=self.embed_data["thumbnail_url"])
        embed.timestamp = discord.utils.utcnow()
        return embed

    def build_preview(self) -> discord.Embed:
        """管理者用の編集画面（ephemeral）に表示するプレビュー。Modal設定情報もここでは表示する。"""
        embed = self._build_base_embed()
        if self.modal_config.get("enabled") and self.modal_config.get("response_channel_id"):
            mc = self.modal_config
            mention_role_id = mc.get("mention_role_id")
            mention_line = f"\nメンションロール: <@&{mention_role_id}>" if mention_role_id else ""
            attachment_line = "\nファイル添付: 許可（送信後にファイルを送ってもらう案内を表示）" if mc.get("allow_attachment") else ""
            embed.add_field(
                name="[Modal設定：この項目は実際の送信時には含まれません]",
                value=(
                    f"ボタン: 「{mc['button_label']}」\n"
                    f"Modalタイトル: {mc['modal_title']}\n"
                    f"入力欄: 「{mc['title_field_label']}」「{mc['body_field_label']}」\n"
                    f"回答送信先: <#{mc['response_channel_id']}>"
                    f"{mention_line}"
                    f"{attachment_line}"
                ),
                inline=False
            )
        return embed

    def build_final_embed(self) -> discord.Embed:
        """実際にチャンネルへ送信するEmbed。Modal設定情報などの管理者向け情報は含めない。"""
        return self._build_base_embed()

    @discord.ui.button(label="[NOTE] 内容を編集", style=discord.ButtonStyle.primary, row=0)
    async def edit_content(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.author.id:
            await interaction.response.send_message("このパネルはあなた専用です。", ephemeral=True)
            return
        modal = EmbedBuilderModal(self)
        # 現在の値をプリフィル
        if self.embed_data.get("title"):
            modal.embed_title.default = self.embed_data["title"]
        if self.embed_data.get("description"):
            modal.embed_description.default = self.embed_data["description"]
        if self.embed_data.get("footer"):
            modal.embed_footer.default = self.embed_data["footer"]
        if self.embed_data.get("image_url"):
            modal.embed_image_url.default = self.embed_data["image_url"]
        if self.embed_data.get("thumbnail_url"):
            modal.embed_thumbnail_url.default = self.embed_data["thumbnail_url"]
        await interaction.response.send_modal(modal)

    @discord.ui.button(label=" フィールド追加", style=discord.ButtonStyle.secondary, row=0)
    async def add_field(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.author.id:
            await interaction.response.send_message("このパネルはあなた専用です。", ephemeral=True)
            return
        if len(self.embed_data["fields"]) >= 25:
            await interaction.response.send_message("フィールドは最大25個までです。", ephemeral=True)
            return
        await interaction.response.send_modal(EmbedFieldModal(self))

    @discord.ui.button(label="[DEL] フィールド削除", style=discord.ButtonStyle.secondary, row=0)
    async def remove_field(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.author.id:
            await interaction.response.send_message("このパネルはあなた専用です。", ephemeral=True)
            return
        if not self.embed_data["fields"]:
            await interaction.response.send_message("削除できるフィールドがありません。", ephemeral=True)
            return
        # 末尾のフィールドを削除
        removed = self.embed_data["fields"].pop()
        await interaction.response.edit_message(embed=self.build_preview(), view=self)
        await interaction.followup.send(f"フィールド「{removed['name']}」を削除しました。", ephemeral=True)

    @discord.ui.button(label="[Modal] 回答フォームを設定", style=discord.ButtonStyle.secondary, row=4)
    async def configure_modal(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.author.id:
            await interaction.response.send_message("このパネルはあなた専用です。", ephemeral=True)
            return
        modal = EmbedModalConfigModal(self)
        modal.button_label.default = self.modal_config.get("button_label", "回答する")
        modal.modal_title.default = self.modal_config.get("modal_title", "回答フォーム")
        modal.title_field_label.default = self.modal_config.get("title_field_label", "タイトル")
        modal.body_field_label.default = self.modal_config.get("body_field_label", "本文")
        modal.allow_attachment_input.default = "yes" if self.modal_config.get("allow_attachment") else "no"
        self.modal_config["enabled"] = True
        await interaction.response.send_modal(modal)

    @discord.ui.select(
        placeholder="回答送信先チャンネル（Modalを付ける場合に選択）",
        cls=discord.ui.ChannelSelect,
        channel_types=[discord.ChannelType.text],
        row=2,
        min_values=0,
        max_values=1
    )
    async def select_response_channel(self, interaction: discord.Interaction, select: discord.ui.ChannelSelect):
        if interaction.user.id != self.author.id:
            await interaction.response.send_message("このパネルはあなた専用です。", ephemeral=True)
            return
        if select.values:
            self.modal_config["response_channel_id"] = select.values[0].id
            self.modal_config["enabled"] = True
        else:
            self.modal_config["response_channel_id"] = None
            self.modal_config["enabled"] = False
        await interaction.response.edit_message(embed=self.build_preview(), view=self)

    @discord.ui.select(
        placeholder="メンションするロール（Modal送信時に通知する場合に選択）",
        cls=discord.ui.RoleSelect,
        row=3,
        min_values=0,
        max_values=1
    )
    async def select_mention_role(self, interaction: discord.Interaction, select: discord.ui.RoleSelect):
        if interaction.user.id != self.author.id:
            await interaction.response.send_message("このパネルはあなた専用です。", ephemeral=True)
            return
        if select.values:
            self.modal_config["mention_role_id"] = select.values[0].id
        else:
            self.modal_config["mention_role_id"] = None
        await interaction.response.edit_message(embed=self.build_preview(), view=self)

    @discord.ui.button(label="[Modal] 回答フォームを解除", style=discord.ButtonStyle.secondary, row=4)
    async def disable_modal(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.author.id:
            await interaction.response.send_message("このパネルはあなた専用です。", ephemeral=True)
            return
        self.modal_config["enabled"] = False
        self.modal_config["response_channel_id"] = None
        self.modal_config["mention_role_id"] = None
        self.modal_config["allow_attachment"] = False
        await interaction.response.edit_message(embed=self.build_preview(), view=self)

    @discord.ui.button(label="[OK] このチャンネルに送信", style=discord.ButtonStyle.success, row=4)
    async def send_embed(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.author.id:
            await interaction.response.send_message("このパネルはあなた専用です。", ephemeral=True)
            return

        modal_enabled = self.modal_config.get("enabled") and self.modal_config.get("response_channel_id")

        panel_id = None
        response_view = None
        if modal_enabled:
            all_data = load_data()
            cfg = get_guild_config(all_data, str(interaction.guild.id))
            panel_id = cfg.get("embed_response_panel_next_id", 1)
            cfg["embed_response_panel_next_id"] = panel_id + 1
            panels = cfg.setdefault("embed_response_panels", {})
            panels[str(panel_id)] = {
                "button_label": self.modal_config["button_label"],
                "modal_title": self.modal_config["modal_title"],
                "title_field_label": self.modal_config["title_field_label"],
                "body_field_label": self.modal_config["body_field_label"],
                "response_channel_id": self.modal_config["response_channel_id"],
                "mention_role_id": self.modal_config.get("mention_role_id"),
                "allow_attachment": self.modal_config.get("allow_attachment", False),
            }
            save_data(all_data)
            response_view = EmbedResponsePanelView(interaction.guild.id, panel_id, self.modal_config["button_label"])

        embed = self.build_final_embed()
        try:
            if response_view is not None:
                await self.target_channel.send(embed=embed, view=response_view)
            else:
                await self.target_channel.send(embed=embed)
        except discord.Forbidden:
            await interaction.response.send_message(
                f"[NG] {self.target_channel.mention} への送信権限がBotにありません。\n\n"
                f"**対処法**\n"
                f"1. {self.target_channel.mention} の「チャンネル設定」→「権限」を開く\n"
                f"2. 役職の一覧にBotのロール（例: MAKUMAKUBOT）を追加する\n"
                f"3. そのロールの「メッセージを送信」を許可（✓）にする\n\n"
                f"（`@everyone` の送信権限がOFFのチャンネルでは、Bot用ロールに個別で許可を出す必要があります）",
                ephemeral=True
            )
            return
        except Exception as e:
            await interaction.response.send_message(f"送信エラー: {e}", ephemeral=True)
            return
        for item in self.children:
            item.disabled = True
        await interaction.response.edit_message(
            content=f"[OK] {self.target_channel.mention} にEmbedを送信しました。",
            embed=None,
            view=self
        )

    @discord.ui.button(label="[NG] キャンセル", style=discord.ButtonStyle.danger, row=4)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button):
        if interaction.user.id != self.author.id:
            await interaction.response.send_message("このパネルはあなた専用です。", ephemeral=True)
            return
        for item in self.children:
            item.disabled = True
        await interaction.response.edit_message(content="Embed作成をキャンセルしました。", embed=None, view=self)


class EmbedFieldModal(discord.ui.Modal, title="フィールドを追加"):
    field_name = discord.ui.TextInput(
        label="フィールド名",
        placeholder="例: 注意事項",
        max_length=256,
        required=True
    )
    field_value = discord.ui.TextInput(
        label="フィールドの内容",
        style=discord.TextStyle.paragraph,
        placeholder="フィールドの内容を入力...",
        max_length=1024,
        required=True
    )
    field_inline = discord.ui.TextInput(
        label="横並び表示（yes / no）",
        placeholder="yes または no",
        default="no",
        max_length=3,
        required=False
    )

    def __init__(self, parent_view: "EmbedBuilderView"):
        super().__init__()
        self.parent_view = parent_view

    async def on_submit(self, interaction: discord.Interaction):
        inline = self.field_inline.value.strip().lower() in ("yes", "y", "true", "1")
        self.parent_view.embed_data["fields"].append({
            "name": self.field_name.value,
            "value": self.field_value.value,
            "inline": inline,
        })
        await interaction.response.edit_message(embed=self.parent_view.build_preview(), view=self.parent_view)


@embed_group.command(name="builder", description="【管理者専用】画面上でEmbedメッセージを組み立てて、チャンネルに送信できます")
async def embed_builder(
    interaction: discord.Interaction,
    送信先チャンネル: discord.TextChannel = None,
):
    if not await is_admin_or_allowed(interaction):
        return
    if not interaction.guild:
        return

    target_ch = 送信先チャンネル or interaction.channel
    view = EmbedBuilderView(author=interaction.user, target_channel=target_ch)
    await interaction.response.send_message(
        f"Embedビルダーを起動しました。送信先: {target_ch.mention}\n"
        "「[NOTE] 内容を編集」でタイトル・本文・画像URLを入力し、色を選んで「[OK] 送信」を押してください。\n"
        "回答フォーム（Modal）を付ける場合は、下のチャンネル選択で回答送信先を選び、"
        "「[Modal] 回答フォームを設定」でボタン文言・入力欄ラベルを設定してください（未設定時は付きません）。",
        embed=view.build_preview(),
        view=view,
        ephemeral=True
    )



# ====================================================================
# セクション 14: 経済システム（通貨・ロールショップ・自販機）
# ====================================================================
#
# 概要:
#   ・メッセージ送信ごとにクールダウン付きで少額の通貨を自動付与（on_message側で処理）
#   ・通貨はサーバーごとに独立して管理（guild_config["economy_balances"]）
#   ・ロールショップ: 通貨を消費してロールを購入できる
#   ・自販機: 通貨を消費して「アイテム（テキスト内容）」を購入できる。在庫管理あり
#
# 注意:
#   ・通貨の稼ぎ方は「メッセージ送信」のみで、クールダウン（既定60秒）を必ず挟みます。
#     これにより連投・自動送信スクリプトによる無制限な稼ぎを防止します。
#   ・管理者は /economy give で手動付与・没収ができますが、乱用防止のため
#     実行ログ（コマンド実行者）が Embed のフッターに残るようにしています。
# --------------------------------------------------------------------

def _format_currency(guild_config: dict, amount: int) -> str:
    """通貨名付きの金額表示文字列を作成します。"""
    name = guild_config.get("economy_currency_name", "コイン")
    return f"{amount:,} {name}"


# --------------------------------------------------------------------
# /economy setup — 経済システムの有効化・各種パラメータ設定
# --------------------------------------------------------------------

@economy_group.command(name="setup", description="【管理者専用】メッセージ報酬やworkコマンドなど、通貨システムまわりを設定できます")
@discord.app_commands.describe(
    有効化="経済システムを有効化するか",
    通貨名="表示する通貨の名前（例: コイン、ポイント）",
    最小報酬="1メッセージあたりの最小付与額",
    最大報酬="1メッセージあたりの最大付与額",
    クールダウン秒="次のメッセージ報酬が発生するまでの待機時間（秒）。連投対策のため必須です。",
    work最小報酬="/workコマンド1回あたりの最小付与額",
    work最大報酬="/workコマンド1回あたりの最大付与額",
    workクールダウン秒="/workコマンドを再実行できるまでの待機時間（秒）。既定は7200秒（2時間）です。"
)
async def economy_setup(
    interaction: discord.Interaction,
    有効化: bool = None,
    通貨名: str = None,
    最小報酬: int = None,
    最大報酬: int = None,
    クールダウン秒: int = None,
    work最小報酬: int = None,
    work最大報酬: int = None,
    workクールダウン秒: int = None,
):
    if not await is_admin_or_allowed(interaction):
        return
    if not interaction.guild:
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))

    if 有効化 is not None:
        cfg["economy_enabled"] = 有効化
    if 通貨名:
        cfg["economy_currency_name"] = 通貨名[:20]
    if 最小報酬 is not None:
        if 最小報酬 < 0:
            await interaction.response.send_message("最小報酬は0以上で指定してください。", ephemeral=True)
            return
        cfg["economy_reward_min"] = 最小報酬
    if 最大報酬 is not None:
        if 最大報酬 < 0:
            await interaction.response.send_message("最大報酬は0以上で指定してください。", ephemeral=True)
            return
        cfg["economy_reward_max"] = 最大報酬
    if クールダウン秒 is not None:
        if クールダウン秒 < 10:
            await interaction.response.send_message(
                "クールダウンは10秒以上で指定してください（連投による無制限な稼ぎを防ぐための最低制限です）。",
                ephemeral=True
            )
            return
        cfg["economy_cooldown_seconds"] = クールダウン秒
    if work最小報酬 is not None:
        if work最小報酬 < 0:
            await interaction.response.send_message("work最小報酬は0以上で指定してください。", ephemeral=True)
            return
        cfg["economy_work_reward_min"] = work最小報酬
    if work最大報酬 is not None:
        if work最大報酬 < 0:
            await interaction.response.send_message("work最大報酬は0以上で指定してください。", ephemeral=True)
            return
        cfg["economy_work_reward_max"] = work最大報酬
    if workクールダウン秒 is not None:
        if workクールダウン秒 < 60:
            await interaction.response.send_message(
                "workクールダウンは60秒以上で指定してください。", ephemeral=True
            )
            return
        cfg["economy_work_cooldown_seconds"] = workクールダウン秒

    save_data(all_data)

    embed = discord.Embed(title="経済システム設定", color=discord.Color.green())
    embed.add_field(name="有効化", value="[OK] 有効" if cfg.get("economy_enabled") else "[NG] 無効", inline=True)
    embed.add_field(name="通貨名", value=cfg.get("economy_currency_name", "コイン"), inline=True)
    embed.add_field(
        name="報酬額（1メッセージ）",
        value=f"{cfg.get('economy_reward_min', 1)} 〜 {cfg.get('economy_reward_max', 5)}",
        inline=True
    )
    embed.add_field(name="クールダウン（メッセージ）", value=f"{cfg.get('economy_cooldown_seconds', 60)}秒", inline=True)
    embed.add_field(
        name="報酬額（/work）",
        value=f"{cfg.get('economy_work_reward_min', 10)} 〜 {cfg.get('economy_work_reward_max', 50)}",
        inline=True
    )
    work_cd = cfg.get('economy_work_cooldown_seconds', 7200)
    embed.add_field(name="クールダウン（/work）", value=f"{work_cd}秒（{work_cd // 3600}時間）", inline=True)
    await interaction.response.send_message(embed=embed, ephemeral=True)


# --------------------------------------------------------------------
# /balance — 所持金確認（グローバルMコイン対応）
# --------------------------------------------------------------------

@economy_group.command(name="balance", description="自分や、指定したユーザーが今いくらMコインを持っているか（財布・銀行）確認できます")
async def balance(interaction: discord.Interaction, ユーザー: discord.Member = None):
    target = ユーザー or interaction.user
    all_data = load_data()
    wallet = get_global_balance(all_data, target.id)
    bank = get_global_bank(all_data, target.id)
    coin_label = format_mcoin(all_data, 0).split(" ", 1)[1]  # 通貨名だけ取得

    embed = discord.Embed(
        title=f" {target.display_name} の{coin_label}残高",
        color=discord.Color.gold()
    )
    embed.set_thumbnail(url=target.display_avatar.url)
    embed.add_field(name=" 財布", value=f"**{wallet:,} {coin_label}**", inline=True)
    embed.add_field(name=" 銀行", value=f"**{bank:,} {coin_label}**", inline=True)
    embed.add_field(name="合計", value=f"**{wallet + bank:,} {coin_label}**", inline=True)
    embed.set_footer(text="全サーバー共通のMコインです")
    await interaction.response.send_message(embed=embed, ephemeral=(ユーザー is None))


# --------------------------------------------------------------------
# /work — 全サーバー共通クールダウンでMコインを稼ぐ
# --------------------------------------------------------------------

@economy_group.command(name="work", description="働いてMコインを稼げます（2時間に1回まで、全サーバー共通のクールダウンです）")
async def work(interaction: discord.Interaction):
    all_data = load_data()

    # guild依存なし：economy_enabledチェックは任意サーバーで有効なら利用可
    if interaction.guild:
        cfg = get_guild_config(all_data, str(interaction.guild.id))
        if not cfg.get("economy_enabled", False):
            await interaction.response.send_message(
                "このサーバーでは経済システムが有効になっていません。管理者に /economy setup での有効化を依頼してください。",
                ephemeral=True
            )
            return
    else:
        await interaction.response.send_message("このコマンドはサーバー内で実行してください。", ephemeral=True)
        return

    import random

    global_cfg = get_global_config(all_data)
    user_id_str = str(interaction.user.id)
    now_ts = time.time()

    # クールダウンはグローバル（全サーバー共通）
    cooldown = global_cfg.get("global_work_cooldown_seconds", 7200)
    last_work_map = global_cfg.setdefault("global_last_work", {})
    last_ts = last_work_map.get(user_id_str, 0)
    remaining = cooldown - (now_ts - last_ts)

    if remaining > 0:
        hours, rem = divmod(int(remaining), 3600)
        minutes, seconds = divmod(rem, 60)
        time_str = ""
        if hours > 0:
            time_str += f"{hours}時間"
        if minutes > 0:
            time_str += f"{minutes}分"
        time_str += f"{seconds}秒"
        await interaction.response.send_message(
            f"まだ働けません。次に働けるまで: **{time_str}**\n（クールダウンは全サーバー共通です）",
            ephemeral=True
        )
        return

    reward_min = global_cfg.get("global_work_reward_min", 10)
    reward_max = global_cfg.get("global_work_reward_max", 50)
    if reward_max < reward_min:
        reward_max = reward_min
    reward = random.randint(reward_min, reward_max)

    add_global_balance(all_data, interaction.user.id, reward)
    last_work_map[user_id_str] = now_ts
    save_data(all_data)

    wallet = get_global_balance(all_data, interaction.user.id)
    coin_name = global_cfg.get("global_coin_name", "Mコイン")
    embed = discord.Embed(
        title=" 労働完了",
        description=(
            f"働いて **{reward:,} {coin_name}** を獲得しました！\n"
            f" 財布の残高: **{wallet:,} {coin_name}**"
        ),
        color=discord.Color.green()
    )
    cd_h = cooldown // 3600
    embed.set_footer(text=f"次に働けるのは{cd_h}時間後です（全サーバー共通クールダウン）")
    await interaction.response.send_message(embed=embed, ephemeral=True)


# --------------------------------------------------------------------
# /economy give — オーナーによる手動付与・没収（グローバルMコイン対応）
# --------------------------------------------------------------------

@economy_group.command(name="give", description="【オーナー専用】指定したユーザーのMコイン（財布）を増やしたり減らしたりできます")
@discord.app_commands.describe(
    ユーザー="対象ユーザー",
    金額="増減させる金額（負の数を指定すると没収）"
)
async def economy_give(interaction: discord.Interaction, ユーザー: discord.Member, 金額: int):
    if not await is_owner_check(interaction):
        return
    if not interaction.guild:
        return

    all_data = load_data()
    add_global_balance(all_data, ユーザー.id, 金額)
    save_data(all_data)

    new_balance = get_global_balance(all_data, ユーザー.id)
    coin_name = get_global_config(all_data).get("global_coin_name", "Mコイン")
    embed = discord.Embed(
        title=" Mコインを変更しました",
        description=(
            f"対象: {ユーザー.mention}\n"
            f"変更額: {'+' if 金額 >= 0 else ''}{金額} {coin_name}\n"
            f"現在の財布残高: **{new_balance:,} {coin_name}**"
        ),
        color=discord.Color.blue()
    )
    embed.set_footer(text=f"実行者: {interaction.user}")
    await interaction.response.send_message(embed=embed, ephemeral=True)


# --------------------------------------------------------------------
# /gift — 他のユーザーへコインをギフト
# --------------------------------------------------------------------

@economy_group.command(name="gift", description="持っているコインを他のユーザーにプレゼントできます")
@discord.app_commands.describe(
    ユーザー="贈り先のユーザー",
    金額="贈る金額（1以上）",
    メッセージ="一言メッセージ（省略可）"
)
async def gift(
    interaction: discord.Interaction,
    ユーザー: discord.Member,
    金額: app_commands.Range[int, 1, 999999999],
    メッセージ: str = None,
):
    if not interaction.guild:
        await interaction.response.send_message("このコマンドはサーバー内で実行してください。", ephemeral=True)
        return

    # 自分自身へのギフトは禁止
    if ユーザー.id == interaction.user.id:
        await interaction.response.send_message("自分自身にギフトはできません。", ephemeral=True)
        return

    # Bot へのギフトは禁止
    if ユーザー.bot:
        await interaction.response.send_message("Botにギフトはできません。", ephemeral=True)
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))

    if not cfg.get("economy_enabled", False):
        await interaction.response.send_message(
            "このサーバーでは経済システムが有効になっていません。",
            ephemeral=True
        )
        return

    coin_name = get_global_config(all_data).get("global_coin_name", "Mコイン")
    sender_balance = get_global_balance(all_data, interaction.user.id)
    if sender_balance < 金額:
        await interaction.response.send_message(
            f"Mコインが不足しています。\n"
            f"必要: {金額:,} {coin_name} / 財布: {sender_balance:,} {coin_name}",
            ephemeral=True
        )
        return

    # 送信者から引いて受取人へ加算（グローバル残高）
    add_global_balance(all_data, interaction.user.id, -金額)
    add_global_balance(all_data, ユーザー.id, 金額)
    save_data(all_data)

    # ギフト受取通知を受取人にDMで送る（失敗しても握り潰す）
    try:
        dm_embed = discord.Embed(
            title=" Mコインを受け取りました！",
            description=(
                f"**{interaction.guild.name}** で {interaction.user.mention} から "
                f"**{金額:,} {coin_name}** 受け取りました！"
            ),
            color=discord.Color.gold()
        )
        if メッセージ:
            dm_embed.add_field(name="メッセージ", value=メッセージ, inline=False)
        dm_embed.add_field(
            name="あなたの財布残高",
            value=f"{get_global_balance(all_data, ユーザー.id):,} {coin_name}",
            inline=True
        )
        dm_embed.set_footer(text=interaction.guild.name)
        await ユーザー.send(embed=dm_embed)
    except Exception:
        pass

    # 実行チャンネルに公開Embedで通知
    result_embed = discord.Embed(
        title=" ギフト完了！",
        description=(
            f"{interaction.user.mention} → {ユーザー.mention}\n"
            f"**{金額:,} {coin_name}** を贈りました！"
        ),
        color=discord.Color.gold()
    )
    if メッセージ:
        result_embed.add_field(name="メッセージ", value=メッセージ, inline=False)
    result_embed.add_field(
        name="あなたの残り財布残高",
        value=f"{get_global_balance(all_data, interaction.user.id):,} {coin_name}",
        inline=True
    )
    result_embed.set_footer(text=f"送信者: {interaction.user}")
    await interaction.response.send_message(embed=result_embed)


# --------------------------------------------------------------------
# ロールショップ
# --------------------------------------------------------------------

class RoleShopBuyButton(discord.ui.Button):
    """ロールショップの各商品に対応する購入ボタン。"""

    def __init__(self, item: dict):
        self.item_id = item["id"]
        self.role_id = item["role_id"]
        self.price = item["price"]
        label = f"{item['name']} ({item['price']:,})"
        super().__init__(
            label=label[:80],
            style=discord.ButtonStyle.success,
            custom_id=f"roleshop_buy_{item['id']}"
        )

    async def callback(self, interaction: discord.Interaction):
        if not interaction.guild:
            return

        all_data = load_data()
        cfg = get_guild_config(all_data, str(interaction.guild.id))
        global_cfg = get_global_config(all_data)
        coin_name = global_cfg.get("global_coin_name", "Mコイン")

        shop_items = cfg.get("role_shop", [])
        item = next((i for i in shop_items if i["id"] == self.item_id), None)
        if item is None:
            await interaction.response.send_message("この商品は既に削除されています。", ephemeral=True)
            return

        role = interaction.guild.get_role(item["role_id"])
        if role is None:
            await interaction.response.send_message(
                "対応するロールがサーバー上に見つかりません。管理者に確認してください。", ephemeral=True
            )
            return

        owned = cfg.setdefault("owned_shop_roles", {})
        user_owned = owned.setdefault(str(interaction.user.id), [])
        if item["id"] in user_owned:
            await interaction.response.send_message("このロールは既に購入済みです。", ephemeral=True)
            return

        user_balance = get_global_balance(all_data, interaction.user.id)
        if user_balance < item["price"]:
            await interaction.response.send_message(
                f"Mコインが不足しています。必要: {item['price']:,} {coin_name} / "
                f"所持: {user_balance:,} {coin_name}",
                ephemeral=True
            )
            return

        try:
            await interaction.user.add_roles(role, reason="ロールショップ購入")
        except discord.Forbidden:
            await interaction.response.send_message(
                "ロールを付与する権限がBotにありません（ロール順位を確認してください）。", ephemeral=True
            )
            return

        add_global_balance(all_data, interaction.user.id, -item["price"])
        user_owned.append(item["id"])
        save_data(all_data)

        new_balance = get_global_balance(all_data, interaction.user.id)
        await interaction.response.send_message(
            f"[OK] **{role.name}** を購入しました！ 残り所持Mコイン: {new_balance:,} {coin_name}",
            ephemeral=True
        )


class RoleShopView(discord.ui.View):
    """ロールショップの商品一覧パネル（購入ボタン付き）。"""

    def __init__(self, shop_items: list):
        super().__init__(timeout=None)
        # Discordの制約上、1ビューに置けるボタンは最大25個
        for item in shop_items[:25]:
            self.add_item(RoleShopBuyButton(item))


def _build_role_shop_embed(guild_config: dict, guild: discord.Guild, all_data: dict = None) -> discord.Embed:
    shop_items = guild_config.get("role_shop", [])
    if all_data is None:
        all_data = load_data()
    global_cfg = get_global_config(all_data)
    coin_name = global_cfg.get("global_coin_name", "Mコイン")
    embed = discord.Embed(
        title="[SHOP] ロールショップ",
        description=f"ボタンを押すとロールを購入できます（支払い: {coin_name}）。" if shop_items else "現在、販売中のロールはありません。",
        color=discord.Color.purple()
    )
    for item in shop_items:
        role = guild.get_role(item["role_id"])
        role_text = role.mention if role else "（ロール削除済み）"
        embed.add_field(
            name=f"{item['name']}（ID: {item['id']}）",
            value=f"{role_text}\n価格: {item['price']:,} {coin_name}",
            inline=True
        )
    return embed


async def _refresh_role_shop_panel(guild: discord.Guild, guild_config: dict):
    """
    設置済みのロールショップパネル（role_shop_panel_channel_id / role_shop_panel_message_id）が
    存在する場合、最新の商品情報でメッセージを編集して更新します。
    パネルが見つからない場合（手動削除等）は静かに諦めます（エラーにしません）。
    """
    channel_id = guild_config.get("role_shop_panel_channel_id")
    message_id = guild_config.get("role_shop_panel_message_id")
    if not channel_id or not message_id:
        return

    channel = guild.get_channel(channel_id)
    if channel is None:
        return

    try:
        message = await channel.fetch_message(message_id)
    except (discord.NotFound, discord.Forbidden, discord.HTTPException):
        return

    shop_items = guild_config.get("role_shop", [])
    new_embed = _build_role_shop_embed(guild_config, guild)
    new_view = RoleShopView(shop_items) if shop_items else None

    try:
        await message.edit(embed=new_embed, view=new_view)
    except discord.HTTPException:
        pass


@roleshop_group.command(name="add", description="【管理者専用】ロールショップに新しい商品を追加できます")
@discord.app_commands.describe(ロール="販売するロール", 価格="購入に必要な通貨額", 表示名="ショップに表示する商品名")
async def roleshop_add(interaction: discord.Interaction, ロール: discord.Role, 価格: int, 表示名: str = None):
    if not await is_admin_or_allowed(interaction):
        return
    if not interaction.guild:
        return
    if 価格 < 1:
        await interaction.response.send_message("価格は1以上で指定してください。", ephemeral=True)
        return
    if ロール >= interaction.guild.me.top_role:
        await interaction.response.send_message(
            "指定されたロールはBotの最高ロールより上位にあるため付与できません。ロールの順位を確認してください。",
            ephemeral=True
        )
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))
    new_id = issue_economy_id(cfg)
    cfg.setdefault("role_shop", []).append({
        "id": new_id,
        "role_id": ロール.id,
        "name": 表示名 or ロール.name,
        "price": 価格,
    })
    save_data(all_data)

    await _refresh_role_shop_panel(interaction.guild, cfg)

    await interaction.response.send_message(
        f"[OK] ロールショップに **{表示名 or ロール.name}**（{ロール.mention} / 価格: {価格:,}）を追加しました。"
        f"（商品ID: {new_id}）\n"
        f"設置済みパネルがある場合は自動的に更新されました。",
        ephemeral=True
    )


@roleshop_group.command(name="remove", description="【管理者専用】ロールショップから商品を削除できます")
@discord.app_commands.describe(商品id="削除する商品のID（/roleshop panel で確認できます）")
async def roleshop_remove(interaction: discord.Interaction, 商品id: int):
    if not await is_admin_or_allowed(interaction):
        return
    if not interaction.guild:
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))
    shop_items = cfg.get("role_shop", [])
    before_len = len(shop_items)
    cfg["role_shop"] = [i for i in shop_items if i["id"] != 商品id]
    save_data(all_data)

    if len(cfg["role_shop"]) == before_len:
        await interaction.response.send_message("指定されたIDの商品が見つかりませんでした。", ephemeral=True)
    else:
        await _refresh_role_shop_panel(interaction.guild, cfg)
        await interaction.response.send_message(
            f"[OK] 商品ID {商品id} をロールショップから削除しました。設置済みパネルがある場合は自動的に更新されました。",
            ephemeral=True
        )


@roleshop_group.command(name="panel", description="【管理者専用】このチャンネルにロールショップのパネルを設置できます")
async def roleshop(interaction: discord.Interaction):
    if not await is_admin_or_allowed(interaction):
        return
    if not interaction.guild:
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))

    # 既存の設置済みパネルがあれば、ボタンを無効化したメッセージとして残す
    old_channel_id = cfg.get("role_shop_panel_channel_id")
    old_message_id = cfg.get("role_shop_panel_message_id")
    if old_channel_id and old_message_id:
        old_channel = interaction.guild.get_channel(old_channel_id)
        if old_channel:
            try:
                old_message = await old_channel.fetch_message(old_message_id)
                await old_message.edit(
                    content="[!] このロールショップパネルは新しいパネルに置き換えられたため無効です。",
                    embed=None,
                    view=None
                )
            except (discord.NotFound, discord.Forbidden, discord.HTTPException):
                pass

    shop_items = cfg.get("role_shop", [])
    embed = _build_role_shop_embed(cfg, interaction.guild)
    view = RoleShopView(shop_items) if shop_items else None

    await interaction.response.send_message(embed=embed, view=view)
    panel_message = await interaction.original_response()

    cfg["role_shop_panel_channel_id"] = interaction.channel.id
    cfg["role_shop_panel_message_id"] = panel_message.id
    save_data(all_data)

# --------------------------------------------------------------------
# 自販機
# --------------------------------------------------------------------

class VendingBuyButton(discord.ui.Button):
    """自販機の各アイテムに対応する購入ボタン。"""

    def __init__(self, item: dict):
        self.item_id = item["id"]
        stock = item.get("stock", 0)
        disabled = stock <= 0
        label = f"{item['name']} ({item['price']:,}) 残{stock}"
        super().__init__(
            label=label[:80],
            style=discord.ButtonStyle.primary if not disabled else discord.ButtonStyle.secondary,
            custom_id=f"vending_buy_{item['id']}",
            disabled=disabled,
        )

    async def callback(self, interaction: discord.Interaction):
        if not interaction.guild:
            return

        all_data = load_data()
        cfg = get_guild_config(all_data, str(interaction.guild.id))
        global_cfg = get_global_config(all_data)
        coin_name = global_cfg.get("global_coin_name", "Mコイン")

        items = cfg.get("vending_items", [])
        item = next((i for i in items if i["id"] == self.item_id), None)
        if item is None:
            await interaction.response.send_message("この商品は既に削除されています。", ephemeral=True)
            return

        if item.get("stock", 0) <= 0:
            await interaction.response.send_message("この商品は売り切れです。", ephemeral=True)
            return

        user_balance = get_global_balance(all_data, interaction.user.id)
        if user_balance < item["price"]:
            await interaction.response.send_message(
                f"Mコインが不足しています。必要: {item['price']:,} {coin_name} / "
                f"所持: {user_balance:,} {coin_name}",
                ephemeral=True
            )
            return

        item_type = item.get("type", "text")
        content_text = None
        discord_file = None

        if item_type == "file":
            # ファイル商品の場合、先に実体を取得できるか確認してから決済する
            # （取得失敗時に課金してしまうのを防ぐため）
            discord_file = await _fetch_vending_file(interaction.guild, item)
            if discord_file is None:
                await interaction.response.send_message(
                    "[NG] 商品ファイルの取得に失敗しました。管理者に確認してください（決済は行われていません）。",
                    ephemeral=True
                )
                return
        else:
            content_text = item.get("content", "（内容が設定されていません）")

        # 在庫減算・Mコイン減算（グローバル）
        item["stock"] -= 1
        add_global_balance(all_data, interaction.user.id, -item["price"])
        save_data(all_data)

        # 購入内容はDMで送付（失敗時はephemeralメッセージにフォールバック）
        try:
            if item_type == "file":
                await interaction.user.send(
                    f"[VEND] 自販機で **{item['name']}** を購入しました。ファイルを添付します。",
                    file=discord_file
                )
                await interaction.response.send_message(
                    f"[OK] **{item['name']}** を購入しました。ファイルをDMに送信しました。", ephemeral=True
                )
            else:
                await interaction.user.send(
                    f"[VEND] 自販機で **{item['name']}** を購入しました。\n\n内容:\n{content_text}"
                )
                await interaction.response.send_message(
                    f"[OK] **{item['name']}** を購入しました。内容をDMに送信しました。", ephemeral=True
                )
        except discord.Forbidden:
            if item_type == "file":
                # discord.File は一度送信すると再利用できないため、フォールバック用に取り直す
                fallback_file = await _fetch_vending_file(interaction.guild, item)
                await interaction.response.send_message(
                    f"[OK] **{item['name']}** を購入しました。\n"
                    f"（DMが送れなかったため、こちらにファイルを添付します）",
                    file=fallback_file,
                    ephemeral=True
                )
            else:
                await interaction.response.send_message(
                    f"[OK] **{item['name']}** を購入しました。\n"
                    f"（DMが送れなかったため、こちらに表示します）\n内容:\n{content_text}",
                    ephemeral=True
                )

        # パネルの在庫表示を更新
        try:
            new_view = VendingMachineView(cfg.get("vending_items", []))
            new_embed = _build_vending_embed(cfg)
            await interaction.message.edit(embed=new_embed, view=new_view)
        except Exception:
            pass


class VendingMachineView(discord.ui.View):
    """自販機の商品一覧パネル（購入ボタン付き）。"""

    def __init__(self, items: list):
        super().__init__(timeout=None)
        for item in items[:25]:
            self.add_item(VendingBuyButton(item))


def _build_vending_embed(guild_config: dict, all_data: dict = None) -> discord.Embed:
    items = guild_config.get("vending_items", [])
    if all_data is None:
        all_data = load_data()
    global_cfg = get_global_config(all_data)
    coin_name = global_cfg.get("global_coin_name", "Mコイン")
    embed = discord.Embed(
        title="[VEND] 自販機",
        description=f"ボタンを押すと商品を購入できます（支払い: {coin_name}）。内容（テキスト／ファイル）はDMで送付されます。" if items else "現在、販売中の商品はありません。",
        color=discord.Color.teal()
    )
    for item in items:
        stock = item.get("stock", 0)
        type_label = "ファイル" if item.get("type") == "file" else "テキスト"
        embed.add_field(
            name=f"{item['name']}（ID: {item['id']}）",
            value=f"価格: {item['price']:,} {coin_name}\n在庫: {stock if stock > 0 else '売り切れ'}\n種別: {type_label}",
            inline=True
        )
    return embed


async def _refresh_vending_panel(guild: discord.Guild, guild_config: dict):
    """
    設置済みの自販機パネル（vending_panel_channel_id / vending_panel_message_id）が
    存在する場合、最新の商品・在庫情報でメッセージを編集して更新します。
    パネルが見つからない場合（手動削除等）は静かに諦めます（エラーにしません）。
    """
    channel_id = guild_config.get("vending_panel_channel_id")
    message_id = guild_config.get("vending_panel_message_id")
    if not channel_id or not message_id:
        return

    channel = guild.get_channel(channel_id)
    if channel is None:
        return

    try:
        message = await channel.fetch_message(message_id)
    except (discord.NotFound, discord.Forbidden, discord.HTTPException):
        return

    items = guild_config.get("vending_items", [])
    new_embed = _build_vending_embed(guild_config)
    new_view = VendingMachineView(items) if items else None

    try:
        await message.edit(embed=new_embed, view=new_view)
    except discord.HTTPException:
        pass


async def _ensure_vending_storage_channel(guild: discord.Guild, guild_config: dict):
    """
    自販機のファイル商品を保管するための、Bot専用（@everyone非表示）チャンネルを
    取得します。存在しない場合は新規に作成します。
    作成・取得に失敗した場合は None を返します。
    """
    channel_id = guild_config.get("vending_storage_channel_id")
    if channel_id:
        existing = guild.get_channel(channel_id)
        if existing is not None:
            return existing

    try:
        overwrites = {
            guild.default_role: discord.PermissionOverwrite(view_channel=False),
            guild.me: discord.PermissionOverwrite(
                view_channel=True, send_messages=True, attach_files=True, read_message_history=True
            ),
        }
        channel = await guild.create_text_channel(
            "vending-file-storage",
            overwrites=overwrites,
            reason="自販機のファイル商品保管用チャンネルを自動作成"
        )
    except (discord.Forbidden, discord.HTTPException):
        return None

    guild_config["vending_storage_channel_id"] = channel.id
    return channel


async def _store_vending_file(guild: discord.Guild, attachment: discord.Attachment, guild_config: dict):
    """
    自販機で配布するファイルを保管チャンネルへ再アップロードして永続化します。
    （スラッシュコマンドの添付ファイルURLは時間が経つと失効するため、保管チャンネルの
    メッセージ本体を正本として扱い、購入時には毎回そこから取得し直します。）
    保存に成功した場合は item に追加するフィールド（storage_channel_id / storage_message_id /
    file_name）の dict を、失敗した場合は None を返します。
    """
    channel = await _ensure_vending_storage_channel(guild, guild_config)
    if channel is None:
        return None

    try:
        file_bytes = await attachment.read()
        upload_file = discord.File(io.BytesIO(file_bytes), filename=attachment.filename)
        storage_message = await channel.send(
            content=f"[VEND-FILE] {attachment.filename}（自販機販売用の保管メッセージです。削除しないでください）",
            file=upload_file
        )
    except (discord.Forbidden, discord.HTTPException):
        return None

    return {
        "storage_channel_id": channel.id,
        "storage_message_id": storage_message.id,
        "file_name": attachment.filename[:200],
    }


async def _fetch_vending_file(guild: discord.Guild, item: dict):
    """
    保管チャンネルに保存された自販機のファイル商品の実体を取得し、discord.File として
    返します。URLを保存せずメッセージ本体から毎回取得するため、CDN URLの失効による
    配布失敗を避けられます。取得できなかった場合は None を返します。
    """
    channel_id = item.get("storage_channel_id")
    message_id = item.get("storage_message_id")
    if not channel_id or not message_id:
        return None

    channel = guild.get_channel(channel_id)
    if channel is None:
        return None

    try:
        message = await channel.fetch_message(message_id)
    except (discord.NotFound, discord.Forbidden, discord.HTTPException):
        return None

    if not message.attachments:
        return None

    attachment = message.attachments[0]
    try:
        file_bytes = await attachment.read()
    except (discord.NotFound, discord.HTTPException):
        return None

    filename = item.get("file_name") or attachment.filename
    return discord.File(io.BytesIO(file_bytes), filename=filename)


@vendingmachine_group.command(name="add", description="【管理者専用】自販機に商品を追加できます（テキストでもファイルでもOK）")
@discord.app_commands.describe(
    商品名="自販機に表示する商品名",
    価格="購入に必要な通貨額",
    在庫数="販売する個数",
    内容="購入時にDMで送るテキスト内容（シリアルコード等）。添付ファイルを使う場合は不要です",
    添付ファイル="購入時にDMで送るファイル（画像・PDF・ZIP等）。テキストの代わりにこちらを指定できます"
)
async def vendingmachine_add(
    interaction: discord.Interaction,
    商品名: str,
    価格: int,
    在庫数: int,
    内容: str = None,
    添付ファイル: discord.Attachment = None,
):
    if not await is_admin_or_allowed(interaction):
        return
    if not interaction.guild:
        return
    if 価格 < 1:
        await interaction.response.send_message("価格は1以上で指定してください。", ephemeral=True)
        return
    if 在庫数 < 0:
        await interaction.response.send_message("在庫数は0以上で指定してください。", ephemeral=True)
        return
    if not 内容 and not 添付ファイル:
        await interaction.response.send_message(
            "「内容」（テキスト）または「添付ファイル」のどちらかを指定してください。", ephemeral=True
        )
        return
    if 内容 and 添付ファイル:
        await interaction.response.send_message(
            "「内容」と「添付ファイル」は同時に指定できません。どちらか一方にしてください。", ephemeral=True
        )
        return

    # ファイル保存に時間がかかる場合があるため、先に応答を保留する
    await interaction.response.defer(ephemeral=True)

    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))
    new_id = issue_economy_id(cfg)

    new_item = {
        "id": new_id,
        "name": 商品名[:80],
        "price": 価格,
        "stock": 在庫数,
    }

    if 添付ファイル:
        stored = await _store_vending_file(interaction.guild, 添付ファイル, cfg)
        if stored is None:
            await interaction.followup.send(
                "[NG] ファイルの保存に失敗しました。Botに「チャンネルの管理」権限があるか確認してから再度お試しください。",
                ephemeral=True
            )
            return
        new_item["type"] = "file"
        new_item.update(stored)
        type_label = "ファイル"
    else:
        new_item["type"] = "text"
        new_item["content"] = 内容[:1500]
        type_label = "テキスト"

    cfg.setdefault("vending_items", []).append(new_item)
    save_data(all_data)

    await _refresh_vending_panel(interaction.guild, cfg)

    await interaction.followup.send(
        f"[OK] 自販機に **{商品名}**（価格: {価格:,} / 在庫: {在庫数} / 種別: {type_label}）を追加しました。"
        f"（商品ID: {new_id}）\n"
        f"設置済みパネルがある場合は自動的に更新されました。",
        ephemeral=True
    )


@vendingmachine_group.command(name="remove", description="【管理者専用】自販機から商品を削除できます")
@discord.app_commands.describe(商品id="削除する商品のID（/vendingmachine panel で確認できます）")
async def vendingmachine_remove(interaction: discord.Interaction, 商品id: int):
    if not await is_admin_or_allowed(interaction):
        return
    if not interaction.guild:
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))
    items = cfg.get("vending_items", [])
    before_len = len(items)
    removed_item = next((i for i in items if i["id"] == 商品id), None)
    cfg["vending_items"] = [i for i in items if i["id"] != 商品id]
    save_data(all_data)

    if len(cfg["vending_items"]) == before_len:
        await interaction.response.send_message("指定されたIDの商品が見つかりませんでした。", ephemeral=True)
    else:
        # ファイル商品の場合、保管チャンネルに残った実体メッセージも削除する（ベストエフォート）
        if removed_item and removed_item.get("type") == "file":
            storage_ch = interaction.guild.get_channel(removed_item.get("storage_channel_id"))
            if storage_ch:
                try:
                    storage_msg = await storage_ch.fetch_message(removed_item.get("storage_message_id"))
                    await storage_msg.delete()
                except (discord.NotFound, discord.Forbidden, discord.HTTPException):
                    pass

        await _refresh_vending_panel(interaction.guild, cfg)
        await interaction.response.send_message(
            f"[OK] 商品ID {商品id} を自販機から削除しました。設置済みパネルがある場合は自動的に更新されました。",
            ephemeral=True
        )


@vendingmachine_group.command(name="panel", description="【管理者専用】このチャンネルに自販機のパネルを設置できます")
async def vendingmachine(interaction: discord.Interaction):
    if not await is_admin_or_allowed(interaction):
        return
    if not interaction.guild:
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))

    # 既存の設置済みパネルがあれば、ボタンを無効化したメッセージとして残す
    old_channel_id = cfg.get("vending_panel_channel_id")
    old_message_id = cfg.get("vending_panel_message_id")
    if old_channel_id and old_message_id:
        old_channel = interaction.guild.get_channel(old_channel_id)
        if old_channel:
            try:
                old_message = await old_channel.fetch_message(old_message_id)
                await old_message.edit(
                    content="[!] この自販機パネルは新しいパネルに置き換えられたため無効です。",
                    embed=None,
                    view=None
                )
            except (discord.NotFound, discord.Forbidden, discord.HTTPException):
                pass

    items = cfg.get("vending_items", [])
    embed = _build_vending_embed(cfg)
    view = VendingMachineView(items) if items else None

    await interaction.response.send_message(embed=embed, view=view)
    panel_message = await interaction.original_response()

    cfg["vending_panel_channel_id"] = interaction.channel.id
    cfg["vending_panel_message_id"] = panel_message.id
    save_data(all_data)


