async def _complete_handler(request):
    """
    「認証完了」ボタンが押されたときの最終確定エンドポイント。
    ここで初めて認証完了ロールの付与を行い、完了ページを表示します。
    """
    import hmac
    import hashlib

    token = request.rel_url.query.get("token")
    if not token:
        return _result_page_html(
            title="認証エラー",
            message="無効なリクエストです",
            sub="このページを閉じて、Discordのパネルから再度お試しください。",
            ok=False
        )

    try:
        decoded = base64.urlsafe_b64decode(token.encode()).decode()
        parts = decoded.split(":")
        if len(parts) != 3:
            raise ValueError("token フォーマット不正")
        guild_id_str, user_id_str, sig = parts
        guild_id = int(guild_id_str)
        user_id = int(user_id_str)
        expected_sig = hmac.new(
            OAUTH_SECRET_KEY.encode(),
            f"{guild_id_str}:{user_id_str}".encode(),
            hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(sig, expected_sig):
            raise ValueError("署名不一致")
    except Exception as e:
        print(f"[認証完了確定] token検証エラー: {e}")
        return _result_page_html(
            title="認証エラー",
            message="認証トークンが無効です",
            sub="リンクの有効期限が切れている可能性があります。Discordのパネルから再度お試しください。",
            ok=False
        )

    all_data = load_data()
    cfg = get_guild_config(all_data, str(guild_id))
    await _grant_verified_role(bot, guild_id, user_id, cfg)

    return _result_page_html(
        title="認証完了",
        message="認証完了",
        sub="このページを閉じてサーバーをお楽しみください。"
    )


async def _oauth2_callback_handler(request):
    """
    Discord OAuth2 コールバックエンドポイント。
    ユーザーが認証を完了したときにここへリダイレクトされる。
    stateを検証し、ユーザーの参加サーバー一覧を取得してBL照合を行う。
    BL照合をクリアした場合は、ここではロールを確定付与せず、
    ユーザーが「認証完了」ボタンを押した時点（/complete）で確定させます。
    """
    import hmac
    import hashlib

    code = request.rel_url.query.get("code")
    state = request.rel_url.query.get("state")

    _html_page = _result_page_html

    if not code or not state:
        return _html_page(
            title="認証エラー",
            message="無効なリクエストです",
            sub="このページを閉じて、Discordのパネルから再度お試しください。",
            ok=False
        )

    # --- state の検証（HMAC署名確認） ---
    try:
        decoded = base64.urlsafe_b64decode(state.encode()).decode()
        parts = decoded.split(":")
        if len(parts) != 3:
            raise ValueError("state フォーマット不正")
        guild_id_str, user_id_str, sig = parts
        guild_id = int(guild_id_str)
        user_id = int(user_id_str)
        expected_sig = hmac.new(
            OAUTH_SECRET_KEY.encode(),
            f"{guild_id_str}:{user_id_str}".encode(),
            hashlib.sha256
        ).hexdigest()
        if not hmac.compare_digest(sig, expected_sig):
            raise ValueError("署名不一致")
    except Exception as e:
        print(f"[OAuth2] state検証エラー: {e}")
        return _html_page(
            title="認証エラー",
            message="認証トークンが無効です",
            sub="リンクの有効期限が切れている可能性があります。Discordのパネルから再度お試しください。",
            ok=False
        )

    # --- Discord API に code を送りアクセストークンを取得 ---
    async with aiohttp.ClientSession() as session:
        token_res = await session.post(
            "https://discord.com/api/v10/oauth2/token",
            data={
                "client_id": DISCORD_CLIENT_ID,
                "client_secret": DISCORD_CLIENT_SECRET,
                "grant_type": "authorization_code",
                "code": code,
                "redirect_uri": _main_oauth_redirect_uri(),
            },
            headers={"Content-Type": "application/x-www-form-urlencoded"}
        )
        token_data = await token_res.json()

    access_token = token_data.get("access_token")
    if not access_token:
        print(f"[OAuth2] トークン取得失敗: {token_data}")
        return _html_page(
            title="認証エラー",
            message="認証に失敗しました",
            sub="時間をおいてから再度お試しください。",
            ok=False
        )

    # --- アクセストークンでユーザーの参加サーバー一覧を取得 ---
    async with aiohttp.ClientSession() as session:
        guilds_res = await session.get(
            "https://discord.com/api/v10/users/@me/guilds",
            headers={"Authorization": f"Bearer {access_token}"}
        )
        user_guilds = await guilds_res.json()

    if not isinstance(user_guilds, list):
        return _html_page(
            title="認証エラー",
            message="サーバー情報の取得に失敗しました",
            sub="時間をおいてから再度お試しください。",
            ok=False
        )

    user_guild_ids = {int(g["id"]) for g in user_guilds}

    # --- 各種BLとの照合 ---
    all_data = load_data()
    cfg = get_guild_config(all_data, str(guild_id))
    global_cfg_bl = get_global_config(all_data)
    target_guild = bot.get_guild(guild_id)
    action = cfg.get("server_blacklist_action", "ban")
    action_label = "BAN" if action == "ban" else "キック"

    # =========================================================
    # ① IP対策（BAN逃れ検知） — ip_ban_check_enabled がONの場合のみ
    #    このサーバーでBAN済みのユーザーが記録した接続元IPと一致する場合、
    #    別アカウントによるBAN逃れとみなして対処します。
    #    IPは生のまま保存せずソルト付きハッシュのみ保存・照合します。
    # =========================================================
    client_ip = _get_client_ip(request)
    ip_hash = _hash_ip(client_ip) if client_ip else None

    if cfg.get("ip_ban_check_enabled", False) and ip_hash:
        banned_ip_hashes = cfg.get("banned_ip_hashes", {})
        hit = banned_ip_hashes.get(ip_hash)
        if hit:
            ip_action = cfg.get("ip_ban_action", "ban")
            print(f"[ウェブ認証/ip_ban_check] ユーザー {user_id} が BAN済みIPと一致（元アカウント: {hit.get('banned_user_id')}） -> action={ip_action}")

            log_ch_id = cfg.get("server_blacklist_log_channel_id") or cfg.get("mod_log_channel_id")
            if log_ch_id and target_guild:
                log_ch = target_guild.get_channel(log_ch_id)
                if log_ch:
                    ip_embed = discord.Embed(
                        title="[!] ウェブ認証: BAN逃れの疑い（同一IP検知）",
                        color=discord.Color.dark_red()
                    )
                    ip_embed.add_field(name="対象ユーザー", value=f"<@{user_id}> (`{user_id}`)", inline=False)
                    ip_embed.add_field(name="一致したBAN済みアカウント", value=f"<@{hit.get('banned_user_id')}> (`{hit.get('banned_user_id')}`)", inline=False)
                    ip_embed.add_field(name="BAN日時", value=hit.get("date", "不明"), inline=True)
                    ip_embed.add_field(
                        name="実行アクション",
                        value={"notify": "通知のみ（認証は継続）", "kick": "キック", "ban": "BAN"}.get(ip_action, ip_action),
                        inline=True
                    )
                    ip_embed.add_field(name="検出経路", value="ウェブ認証 (OAuth2) - IPハッシュ照合", inline=True)
                    ip_embed.timestamp = discord.utils.utcnow()
                    try:
                        await log_ch.send(embed=ip_embed)
                    except Exception:
                        pass

            if ip_action in ("kick", "ban"):
                if target_guild:
                    member = target_guild.get_member(user_id)
                    if member:
                        try:
                            if ip_action == "ban":
                                await target_guild.ban(
                                    discord.Object(id=user_id),
                                    reason=f"ウェブ認証/ip_ban_check: BAN済みアカウント {hit.get('banned_user_id')} と同一IPを検知"
                                )
                            else:
                                await member.kick(
                                    reason=f"ウェブ認証/ip_ban_check: BAN済みアカウント {hit.get('banned_user_id')} と同一IPを検知"
                                )
                        except Exception as e:
                            print(f"[ウェブ認証/ip_ban_check] {ip_action}実行エラー: {e}")

                ip_action_label = "BAN" if ip_action == "ban" else "キック"
                return _html_page(
                    title="参加不可",
                    message="このサーバーには参加できません",
                    sub=f"BAN逃れの疑いがあるため（IP対策）、{ip_action_label}されました。",
                    ok=False
                )
            # ip_action == "notify" の場合は弾かずに以降のチェックへ進む

    # =========================================================
    # ② サブ垢（新規アカウント）対策 — alt_check_enabled がONの場合のみ
    #    /server protect alt_check の設定をウェブ認証にも適用します。
    #    アクションが「通知のみ」の場合はここでは弾かず、通知のみ行って認証は継続させます。
    # =========================================================
    if cfg.get("alt_check_enabled", False):
        alt_threshold_days = cfg.get("alt_check_days", 30)
        alt_action = cfg.get("alt_check_action", "notify")
        account_created_at = discord.utils.snowflake_time(user_id)
        account_age_days = (discord.utils.utcnow() - account_created_at).days

        if account_age_days < alt_threshold_days:
            print(f"[ウェブ認証/alt_check] ユーザー {user_id} のアカウント日齢 {account_age_days}日（閾値: {alt_threshold_days}日） -> action={alt_action}")

            # ログ通知（アクションに関わらず通知）
            log_ch_id = cfg.get("server_blacklist_log_channel_id") or cfg.get("mod_log_channel_id")
            if log_ch_id and target_guild:
                log_ch = target_guild.get_channel(log_ch_id)
                if log_ch:
                    alt_embed = discord.Embed(
                        title="[!] ウェブ認証: 新規アカウント検知 (alt_check)",
                        color=discord.Color.orange()
                    )
                    alt_embed.add_field(name="対象ユーザー", value=f"<@{user_id}> (`{user_id}`)", inline=False)
                    alt_embed.add_field(name="アカウント作成日", value=account_created_at.strftime("%Y/%m/%d"), inline=True)
                    alt_embed.add_field(name="アカウント日齢", value=f"{account_age_days}日", inline=True)
                    alt_embed.add_field(name="閾値", value=f"{alt_threshold_days}日未満", inline=True)
                    alt_embed.add_field(
                        name="実行アクション",
                        value={"notify": "通知のみ（認証は継続）", "kick": "キック", "ban": "BAN"}.get(alt_action, alt_action),
                        inline=True
                    )
                    alt_embed.add_field(name="検出経路", value="ウェブ認証 (OAuth2)", inline=True)
                    alt_embed.timestamp = discord.utils.utcnow()
                    try:
                        await log_ch.send(embed=alt_embed)
                    except Exception:
                        pass

            if alt_action in ("kick", "ban"):
                if target_guild:
                    member = target_guild.get_member(user_id)
                    if member:
                        try:
                            if alt_action == "ban":
                                await target_guild.ban(
                                    discord.Object(id=user_id),
                                    reason=f"ウェブ認証/alt_check: アカウント日齢 {account_age_days}日（閾値: {alt_threshold_days}日）"
                                )
                            else:
                                await member.kick(
                                    reason=f"ウェブ認証/alt_check: アカウント日齢 {account_age_days}日（閾値: {alt_threshold_days}日）"
                                )
                        except Exception as e:
                            print(f"[ウェブ認証/alt_check] {alt_action}実行エラー: {e}")

                alt_action_label = "BAN" if alt_action == "ban" else "キック"
                return _html_page(
                    title="参加不可",
                    message="このサーバーには参加できません",
                    sub=f"アカウントの作成から日が浅いため（新規アカウント対策）、{alt_action_label}されました。",
                    ok=False
                )
            # alt_action == "notify" の場合は弾かずに以降のBL照合へ進む

    # =========================================================
    # ③ 荒らしリスト（ブラックリスト）照合 — 常時実行
    #    サーバーBL機能のON/OFFに関わらず、荒らしリストに登録済みなら弾く
    # =========================================================
    troll_list = global_cfg_bl.get("troll_list", {})
    troll_entry = troll_list.get(str(user_id))
    if troll_entry:
        print(f"[ウェブ認証/荒らしリスト] ユーザー {user_id} は荒らしリストに登録済み -> {action_label} 実行")
        if target_guild:
            member = target_guild.get_member(user_id)
            if member:
                try:
                    if action == "ban":
                        await target_guild.ban(
                            discord.Object(id=user_id),
                            reason=f"ウェブ認証: 荒らしリスト(ブラックリスト)登録ユーザーを検出: {troll_entry.get('reason', '不明')}"
                        )
                        # 荒らしリストのbanned_inを更新
                        all_data_fresh = load_data()
                        add_to_troll_list(
                            all_data_fresh,
                            member,
                            target_guild,
                            reason=troll_entry.get("reason", "荒らしリスト登録ユーザー")
                        )
                        save_data(all_data_fresh)
                        await _post_troll_board(all_data_fresh, str(member.id))
                        print(f"[ウェブ認証/荒らしリスト] {member} を自動BANしました。")
                    else:
                        await member.kick(
                            reason=f"ウェブ認証: 荒らしリスト(ブラックリスト)登録ユーザーを検出: {troll_entry.get('reason', '不明')}"
                        )
                        print(f"[ウェブ認証/荒らしリスト] {member} をキックしました。")

                    # ログチャンネルへ通知
                    log_ch_id = cfg.get("server_blacklist_log_channel_id") or cfg.get("mod_log_channel_id")
                    if log_ch_id and target_guild:
                        log_ch = target_guild.get_channel(log_ch_id)
                        if log_ch:
                            troll_embed = discord.Embed(
                                title=f"[BL] ウェブ認証: 荒らしリスト - {action_label}実行",
                                color=discord.Color.red()
                            )
                            troll_embed.add_field(
                                name="対象ユーザー",
                                value=f"<@{user_id}> (`{user_id}`)",
                                inline=False
                            )
                            troll_embed.add_field(
                                name="登録理由",
                                value=troll_entry.get("reason", "不明"),
                                inline=False
                            )
                            troll_embed.add_field(
                                name="登録日時",
                                value=(troll_entry.get("date", "") or "不明")[:19].replace("T", " "),
                                inline=True
                            )
                            troll_embed.add_field(name="実行した処置", value=action_label, inline=True)
                            troll_embed.add_field(name="検出経路", value="ウェブ認証 (OAuth2)", inline=True)
                            troll_embed.timestamp = discord.utils.utcnow()
                            try:
                                await log_ch.send(embed=troll_embed)
                            except Exception:
                                pass
                except Exception as e:
                    print(f"[ウェブ認証/荒らしリスト] {action_label}実行エラー: {e}")

        return _html_page(
            title="参加不可",
            message="このサーバーには参加できません",
            sub=f"複数サーバーで報告済みのユーザーとして登録されているため、{action_label}されました。",
            ok=False
        )

    # =========================================================
    # ④ サーバーブラックリスト照合 — server_blacklist_enabled がONの場合のみ
    # =========================================================
    def _record_ip_hash_if_enabled():
        """認証OK確定時、ip_ban_check_enabled であれば今回の接続元IPハッシュを記録します。
        後でこのユーザーがBANされた際、記録済みのこのハッシュが banned_ip_hashes に登録されます。"""
        if cfg.get("ip_ban_check_enabled", False) and ip_hash:
            fresh_data = load_data()
            fresh_cfg = get_guild_config(fresh_data, str(guild_id))
            fresh_cfg.setdefault("ip_hashes", {})[str(user_id)] = ip_hash
            save_data(fresh_data)

    if not cfg.get("server_blacklist_enabled", True):
        # 機能が無効になっていれば認証OK。ロール付与は「認証完了」ボタン押下時に確定させる
        _record_ip_hash_if_enabled()
        complete_token = _generate_web_auth_state(guild_id, user_id)
        complete_url = _build_complete_url(complete_token)
        return aiohttp.web.Response(
            text=_confirm_complete_page_html(complete_url),
            content_type="text/html"
        )

    # BL対象IDは全サーバー共通リストから取得
    blacklist_ids = set(global_cfg_bl.get("global_server_blacklist_ids", []))
    matched = user_guild_ids & blacklist_ids

    if matched:
        # ブラックリスト対象サーバーに参加しているため処置を実行
        matched_id_text = ", ".join(str(sid) for sid in matched)
        print(f"[サーバーBL] ユーザー {user_id} がBL対象サーバー({matched_id_text})に在籍 -> {action_label} 実行")

        if target_guild:
            member = target_guild.get_member(user_id)
            if member:
                try:
                    if action == "ban":
                        await target_guild.ban(
                            discord.Object(id=user_id),
                            reason=f"サーバーBL: BL対象サーバー({matched_id_text})への参加を検出"
                        )
                        # 荒らしリストに追加（BANのみ登録）
                        all_data_fresh = load_data()
                        add_to_troll_list(
                            all_data_fresh,
                            member,
                            target_guild,
                            reason=f"サーバーBL: BL対象サーバー({matched_id_text})への参加を検出"
                        )
                        save_data(all_data_fresh)
                        await _post_troll_board(all_data_fresh, str(member.id))
                        print(f"[荒らしリスト] {member} を荒らしリストに追加しました。")
                    else:
                        await member.kick(
                            reason=f"サーバーBL: BL対象サーバー({matched_id_text})への参加を検出"
                        )

                    # ログチャンネルへ通知
                    log_ch_id = cfg.get("server_blacklist_log_channel_id") or cfg.get("mod_log_channel_id")
                    if log_ch_id:
                        log_ch = target_guild.get_channel(log_ch_id)
                        if log_ch:
                            bl_embed = discord.Embed(
                                title=f"[BL] サーバーブラックリスト - {action_label}実行",
                                color=discord.Color.red()
                            )
                            bl_embed.add_field(
                                name="対象ユーザー",
                                value=f"<@{user_id}> (`{user_id}`)",
                                inline=False
                            )
                            bl_embed.add_field(
                                name="検出されたBL対象サーバーID",
                                value=matched_id_text,
                                inline=False
                            )
                            bl_embed.add_field(name="実行した処置", value=action_label, inline=True)
                            bl_embed.timestamp = discord.utils.utcnow()
                            try:
                                await log_ch.send(embed=bl_embed)
                            except Exception:
                                pass

                except Exception as e:
                    print(f"[サーバーBL] {action_label}実行エラー: {e}")

        return _html_page(
            title="参加不可",
            message="このサーバーには参加できません",
            sub=f"参加が制限されているサーバーへの在籍が確認されたため、{action_label}されました。",
            ok=False
        )
    else:
        # ブラックリスト対象サーバーに参加していない -> 認証OK。
        # ロール付与は「認証完了」ボタン押下時に確定させる
        print(f"[サーバーBL] ユーザー {user_id} はBL対象サーバーに在籍なし -> 認証OK")
        _record_ip_hash_if_enabled()
        complete_token = _generate_web_auth_state(guild_id, user_id)
        complete_url = _build_complete_url(complete_token)
        return aiohttp.web.Response(
            text=_confirm_complete_page_html(complete_url),
            content_type="text/html"
        )


# ====================================================================
# 荒らし対策ダッシュボード（Botオーナー専用 / 秘密リンク方式）
# ====================================================================

def _admin_dashboard_html(
    blacklist_ids: list,
    troll_list: dict,
    dashboard_key: str,
    bot_guilds: list = None,
    bot_latency_ms: int = 0,
    bot_user_str: str = "",
    custom_status_text: str = None,
    flash_message: str = None,
    flash_is_error: bool = False,
) -> str:
    """
    荒らし対策ダッシュボードのHTMLを生成します。
    ・荒らしユーザー一覧の表示・追加・削除
    ・荒らしサーバー（サーバーブラックリスト）一覧の表示・追加・削除
    ・BOTコントロール（導入サーバー一覧・ステータス文言変更）
    を1ページにタブ形式でまとめています。
    ユーザー由来の値（ユーザー名・登録理由など）は html.escape で必ずエスケープし、
    悪意あるDiscordユーザー名等によるHTML/JSインジェクションを防ぎます。
    書き込み系の操作はすべてPOSTフォームで送信し、フォーム内に秘密キーを
    hidden inputとして埋め込むことで認証します（URLクエリのkeyと同じ値）。
    """
    bot_guilds = bot_guilds or []

    color_bg     = "#23272A"
    color_card   = "#2C2F33"
    color_main   = "#5865F2"
    color_text   = "#FFFFFF"
    color_sub    = "#B9BBBE"
    color_box    = "#1E2124"
    color_danger = "#ED4245"
    color_green  = "#3BA55D"

    def esc(value) -> str:
        return html.escape(str(value), quote=True)

    key_esc = esc(dashboard_key)

    # --- フラッシュメッセージ（操作結果通知） ---
    if flash_message:
        flash_cls = "flash-error" if flash_is_error else "flash-ok"
        flash_html = f'<div class="flash {flash_cls}">{esc(flash_message)}</div>'
    else:
        flash_html = ""

    # --- 荒らしサーバー（サーバーブラックリスト）一覧 ---
    if blacklist_ids:
        server_rows = "".join(
            f'''<tr>
                <td class="mono">{esc(sid)}</td>
                <td>
                  <form method="post" action="/admin/blacklist/server/delete" class="inline-form" onsubmit="return confirm('このサーバーIDをブラックリストから削除しますか？');">
                    <input type="hidden" name="key" value="{key_esc}">
                    <input type="hidden" name="server_id" value="{esc(sid)}">
                    <button type="submit" class="btn btn-danger btn-sm">削除</button>
                  </form>
                </td>
              </tr>''' for sid in blacklist_ids
        )
    else:
        server_rows = '<tr><td colspan="2" class="empty">登録されているサーバーはありません</td></tr>'

    # --- 荒らしユーザー一覧（登録日時の新しい順） ---
    sorted_entries = sorted(
        troll_list.items(),
        key=lambda kv: kv[1].get("date", ""),
        reverse=True
    )
    if sorted_entries:
        user_rows_list = []
        for uid_str, entry in sorted_entries:
            username = entry.get("username", "不明")
            reason = entry.get("reason", "不明")
            date_str = (entry.get("date", "") or "")[:19].replace("T", " ") or "不明"
            banned_count = len(entry.get("banned_in", []))
            account_link = entry.get("account_link") or f"https://discord.com/users/{uid_str}"
            avatar_url = entry.get("avatar_url", "")
            search_key = esc(f"{username} {uid_str} {reason}".lower())
            avatar_html = (
                f'<img src="{esc(avatar_url)}" class="avatar" loading="lazy" alt="">'
                if avatar_url else '<div class="avatar avatar-fallback"></div>'
            )
            user_rows_list.append(f"""<tr class="user-row" data-search="{search_key}">
                <td>
                  <div class="user-cell">
                    {avatar_html}
                    <div>
                      <div class="username">{esc(username)}</div>
                      <div class="uid mono">{esc(uid_str)}</div>
                    </div>
                  </div>
                </td>
                <td>{esc(reason)}</td>
                <td class="mono">{esc(date_str)}</td>
                <td>{banned_count}サーバー</td>
                <td><a href="{esc(account_link)}" target="_blank" rel="noopener noreferrer" class="link">プロフィール</a></td>
                <td>
                  <form method="post" action="/admin/blacklist/user/delete" class="inline-form" onsubmit="return confirm('このユーザーを荒らしリストから削除しますか？');">
                    <input type="hidden" name="key" value="{key_esc}">
                    <input type="hidden" name="user_id" value="{esc(uid_str)}">
                    <button type="submit" class="btn btn-danger btn-sm">削除</button>
                  </form>
                </td>
              </tr>""")
        user_rows = "".join(user_rows_list)
    else:
        user_rows = '<tr><td colspan="6" class="empty">登録されているユーザーはいません</td></tr>'

    # --- 導入サーバー一覧（BOTコントロール用） ---
    sorted_guilds = sorted(bot_guilds, key=lambda g: (g.member_count or 0), reverse=True)
    if sorted_guilds:
        guild_rows_list = []
        for g in sorted_guilds:
            owner_id = getattr(g, "owner_id", None)
            owner_text = esc(owner_id) if owner_id else "不明"
            icon_url = str(g.icon.url) if getattr(g, "icon", None) else ""
            icon_html = (
                f'<img src="{esc(icon_url)}" class="avatar" loading="lazy" alt="">'
                if icon_url else '<div class="avatar avatar-fallback"></div>'
            )
            guild_search_key = esc(f"{g.name} {g.id}".lower())
            guild_rows_list.append(f"""<tr class="guild-row" data-search="{guild_search_key}">
                <td>
                  <div class="user-cell">
                    {icon_html}
                    <div>
                      <div class="username">{esc(g.name)}</div>
                      <div class="uid mono">{esc(g.id)}</div>
                    </div>
                  </div>
                </td>
                <td>{g.member_count or 0:,}人</td>
                <td class="mono">{owner_text}</td>
                <td>
                  <form method="post" action="/admin/blacklist/server/add" class="inline-form" onsubmit="return confirm('このサーバーを荒らしサーバー（ブラックリスト）に登録しますか？');">
                    <input type="hidden" name="key" value="{key_esc}">
                    <input type="hidden" name="server_id" value="{esc(g.id)}">
                    <button type="submit" class="btn btn-danger btn-sm">BL登録</button>
                  </form>
                </td>
              </tr>""")
        guild_rows = "".join(guild_rows_list)
    else:
        guild_rows = '<tr><td colspan="4" class="empty">導入されているサーバーがありません</td></tr>'

    current_status_display = esc(custom_status_text) if custom_status_text else "（未設定：自動でサーバー数を表示）"
    current_status_value = esc(custom_status_text) if custom_status_text else ""

    return f"""<!DOCTYPE html>
<html lang="ja">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <meta name="robots" content="noindex, nofollow">
  <title>荒らし対策ダッシュボード</title>
  <style>
    * {{ box-sizing: border-box; margin: 0; padding: 0; }}
    body {{
      background: {color_bg}; color: {color_text};
      font-family: "Helvetica Neue", Arial, "Hiragino Kaku Gothic ProN", "Meiryo", sans-serif;
      padding: 32px 20px 64px;
    }}
    .wrap {{
      max-width: 920px; margin: 0 auto;
      opacity: 0; transform: translateY(12px);
      animation: pageIn 0.45s ease-out forwards;
    }}
    h1 {{ font-size: 24px; font-weight: 700; margin-bottom: 6px; }}
    .caption {{ font-size: 13px; color: {color_sub}; margin-bottom: 28px; }}
    .stats {{ display: flex; gap: 16px; margin-bottom: 32px; flex-wrap: wrap; }}
    .stat-card {{
      background: {color_card}; border-radius: 12px; padding: 18px 24px;
      min-width: 160px; box-shadow: 0 4px 16px rgba(0,0,0,0.3);
    }}
    .stat-num {{ font-size: 28px; font-weight: 700; color: {color_main}; }}
    .stat-label {{ font-size: 12px; color: {color_sub}; margin-top: 4px; }}
    .card {{
      background: {color_card}; border-radius: 12px; padding: 24px;
      margin-bottom: 24px; box-shadow: 0 4px 16px rgba(0,0,0,0.3);
    }}
    .section-head {{
      display: flex; align-items: center; justify-content: space-between;
      flex-wrap: wrap; gap: 12px; margin-bottom: 16px;
    }}
    h2 {{ font-size: 16px; font-weight: 700; }}
    #searchBox {{
      background: {color_box}; border: 1px solid #3a3e44; border-radius: 8px;
      color: {color_text}; padding: 8px 12px; font-size: 13px; min-width: 220px;
      outline: none; transition: border-color 0.15s ease;
    }}
    #searchBox:focus {{ border-color: {color_main}; }}
    table {{ width: 100%; border-collapse: collapse; font-size: 13px; }}
    thead th {{
      text-align: left; color: {color_sub}; font-weight: 700; font-size: 12px;
      padding: 8px 10px; border-bottom: 1px solid #3a3e44;
    }}
    tbody td {{
      padding: 10px; border-bottom: 1px solid #34383e; vertical-align: middle;
    }}
    tbody tr {{ transition: background 0.12s ease; }}
    tbody tr:hover {{ background: rgba(255,255,255,0.03); }}
    .mono {{ font-family: "SFMono-Regular", Consolas, monospace; color: {color_sub}; }}
    .empty {{ text-align: center; color: {color_sub}; padding: 24px 0; }}
    .user-cell {{ display: flex; align-items: center; gap: 10px; }}
    .avatar {{ width: 32px; height: 32px; border-radius: 50%; object-fit: cover; flex-shrink: 0; }}
    .avatar-fallback {{ background: #4a4e54; }}
    .username {{ font-weight: 700; }}
    .uid {{ font-size: 11px; }}
    .link {{ color: {color_main}; text-decoration: none; font-weight: 700; }}
    .link:hover {{ text-decoration: underline; }}
    .warn-banner {{
      background: rgba(237, 66, 69, 0.12); border: 1px solid {color_danger};
      color: #ff9a9c; border-radius: 8px; padding: 10px 14px; font-size: 12px;
      margin-bottom: 24px;
    }}
    .flash {{
      border-radius: 8px; padding: 10px 14px; font-size: 13px; font-weight: 700;
      margin-bottom: 20px;
    }}
    .flash-ok {{ background: rgba(59, 165, 93, 0.15); border: 1px solid {color_green}; color: #8fe3ac; }}
    .flash-error {{ background: rgba(237, 66, 69, 0.15); border: 1px solid {color_danger}; color: #ff9a9c; }}
    .tabs {{ display: flex; gap: 6px; margin-bottom: 20px; flex-wrap: wrap; }}
    .tab-btn {{
      background: {color_card}; color: {color_sub}; border: 1px solid #3a3e44;
      border-radius: 8px; padding: 9px 16px; font-size: 13px; font-weight: 700;
      cursor: pointer; transition: all 0.12s ease;
    }}
    .tab-btn:hover {{ color: {color_text}; }}
    .tab-btn.active {{ background: {color_main}; color: {color_text}; border-color: {color_main}; }}
    .tab-panel {{ display: none; }}
    .tab-panel.active {{ display: block; }}
    .form-grid {{
      display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
      gap: 12px; margin-bottom: 14px;
    }}
    label {{ display: block; font-size: 11px; color: {color_sub}; margin-bottom: 4px; font-weight: 700; }}
    input[type="text"], input[type="number"], textarea {{
      width: 100%; background: {color_box}; border: 1px solid #3a3e44; border-radius: 8px;
      color: {color_text}; padding: 9px 12px; font-size: 13px; outline: none;
      transition: border-color 0.15s ease; font-family: inherit;
    }}
    input[type="text"]:focus, input[type="number"]:focus, textarea:focus {{ border-color: {color_main}; }}
    .btn {{
      border: none; border-radius: 8px; padding: 9px 18px; font-size: 13px; font-weight: 700;
      cursor: pointer; transition: opacity 0.12s ease; color: {color_text};
    }}
    .btn:hover {{ opacity: 0.85; }}
    .btn-main {{ background: {color_main}; }}
    .btn-danger {{ background: {color_danger}; }}
    .btn-sm {{ padding: 6px 12px; font-size: 12px; }}
    .inline-form {{ display: inline-block; }}
    .add-form {{ margin-bottom: 24px; padding-bottom: 20px; border-bottom: 1px solid #34383e; }}
    .sub-label {{ font-size: 12px; color: {color_sub}; margin-bottom: 12px; }}
    .status-form {{ display: flex; gap: 10px; flex-wrap: wrap; align-items: flex-end; }}
    .status-form .field {{ flex: 1; min-width: 220px; }}
    @media (max-width: 640px) {{
      table, thead, tbody, tr, td {{ display: block; }}
      thead {{ display: none; }}
      tbody tr {{ border: 1px solid #34383e; border-radius: 8px; margin-bottom: 10px; padding: 8px; }}
      tbody td {{ border-bottom: none; padding: 4px 4px; }}
    }}
    @keyframes pageIn {{
      to {{ opacity: 1; transform: translateY(0); }}
    }}
  </style>
</head>
<body>
  <div class="wrap">
    <h1>荒らし対策ダッシュボード</h1>
    <p class="caption">このページはBotオーナー専用です。リンク（秘密キー付きURL）を第三者に共有しないでください。</p>
    <div class="warn-banner">このリンクを知っている人は誰でも閲覧できます。漏えいした場合は ADMIN_DASHBOARD_KEY を変更してください。</div>
    {flash_html}

    <div class="stats">
      <div class="stat-card">
        <div class="stat-num">{len(blacklist_ids)}</div>
        <div class="stat-label">荒らしサーバー登録数</div>
      </div>
      <div class="stat-card">
        <div class="stat-num">{len(troll_list)}</div>
        <div class="stat-label">荒らしユーザー登録数</div>
      </div>
      <div class="stat-card">
        <div class="stat-num">{len(bot_guilds)}</div>
        <div class="stat-label">導入サーバー数</div>
      </div>
      <div class="stat-card">
        <div class="stat-num">{bot_latency_ms}ms</div>
        <div class="stat-label">レイテンシ</div>
      </div>
    </div>

    <div class="tabs">
      <button class="tab-btn active" onclick="showTab('tab-users', this)">荒らしユーザー管理</button>
      <button class="tab-btn" onclick="showTab('tab-servers', this)">荒らしサーバー管理</button>
      <button class="tab-btn" onclick="showTab('tab-bot', this)">BOTコントロール</button>
    </div>

    <!-- ============ タブ1: 荒らしユーザー管理 ============ -->
    <div id="tab-users" class="tab-panel active">
      <section class="card">
        <h2>荒らしユーザーを追加</h2>
        <p class="sub-label">全サーバー共有の荒らしリストに新しいユーザーを登録します（参加時の自動BAN対象になります）。</p>
        <form method="post" action="/admin/blacklist/user/add" class="add-form">
          <input type="hidden" name="key" value="{key_esc}">
          <div class="form-grid">
            <div>
              <label>ユーザーID（必須）</label>
              <input type="text" name="user_id" placeholder="例: 123456789012345678" required pattern="[0-9]+" title="数字のみのDiscordユーザーIDを入力してください">
            </div>
            <div>
              <label>理由</label>
              <input type="text" name="reason" placeholder="例: 複数サーバーでの荒らし行為">
            </div>
            <div>
              <label>アカウントリンク（任意）</label>
              <input type="text" name="account_link" placeholder="https://discord.com/users/...">
            </div>
          </div>
          <button type="submit" class="btn btn-main">追加する</button>
        </form>

        <div class="section-head">
          <h2>荒らしユーザー一覧</h2>
          <input type="text" id="searchBox" placeholder="ユーザー名・ID・理由で検索" oninput="filterUsers()">
        </div>
        <table>
          <thead>
            <tr>
              <th>ユーザー</th>
              <th>登録理由</th>
              <th>登録日時</th>
              <th>BAN済みサーバー数</th>
              <th>リンク</th>
              <th>操作</th>
            </tr>
          </thead>
          <tbody id="userTableBody">{user_rows}</tbody>
        </table>
      </section>
    </div>

    <!-- ============ タブ2: 荒らしサーバー管理 ============ -->
    <div id="tab-servers" class="tab-panel">
      <section class="card">
        <h2>荒らしサーバーを追加</h2>
        <p class="sub-label">登録したサーバーIDに参加しているユーザーは、各導入サーバーで自動BAN/Kickの対象になります（サーバーごとの設定 /serverbl_action に従います）。</p>
        <form method="post" action="/admin/blacklist/server/add" class="add-form">
          <input type="hidden" name="key" value="{key_esc}">
          <div class="form-grid">
            <div>
              <label>サーバーID（必須）</label>
              <input type="text" name="server_id" placeholder="例: 123456789012345678" required pattern="[0-9]+" title="数字のみのDiscordサーバーIDを入力してください">
            </div>
          </div>
          <button type="submit" class="btn btn-main">追加する</button>
        </form>

        <h2>荒らしサーバー一覧</h2>
        <table>
          <thead><tr><th>サーバーID</th><th>操作</th></tr></thead>
          <tbody>{server_rows}</tbody>
        </table>
      </section>
    </div>

    <!-- ============ タブ3: BOTコントロール ============ -->
    <div id="tab-bot" class="tab-panel">
      <section class="card">
        <h2>BOT情報</h2>
        <p class="sub-label">ログイン中: <strong>{esc(bot_user_str)}</strong> ／ レイテンシ: <strong>{bot_latency_ms}ms</strong> ／ 導入サーバー数: <strong>{len(bot_guilds)}</strong></p>

        <h2 style="margin-top:20px;">ステータス文言を変更</h2>
        <p class="sub-label">現在の表示: {current_status_display}</p>
        <form method="post" action="/admin/bot/status" class="status-form">
          <input type="hidden" name="key" value="{key_esc}">
          <div class="field">
            <label>新しいステータス文言（空欄でデフォルトに戻す）</label>
            <input type="text" name="status_text" placeholder="例: /help で使い方を確認" value="{current_status_value}">
          </div>
          <button type="submit" class="btn btn-main">更新する</button>
        </form>
      </section>

      <section class="card">
        <div class="section-head">
          <h2>導入サーバー一覧</h2>
          <input type="text" id="guildSearchBox" placeholder="サーバー名・IDで検索" oninput="filterGuilds()">
        </div>
        <table>
          <thead>
            <tr>
              <th>サーバー</th>
              <th>メンバー数</th>
              <th>オーナーID</th>
              <th>操作</th>
            </tr>
          </thead>
          <tbody id="guildTableBody">{guild_rows}</tbody>
        </table>
      </section>
    </div>
  </div>
  <script>
    function showTab(id, btn) {{
      document.querySelectorAll('.tab-panel').forEach(function(p) {{ p.classList.remove('active'); }});
      document.querySelectorAll('.tab-btn').forEach(function(b) {{ b.classList.remove('active'); }});
      document.getElementById(id).classList.add('active');
      btn.classList.add('active');
    }}
    function filterUsers() {{
      var q = document.getElementById('searchBox').value.toLowerCase();
      var rows = document.querySelectorAll('#userTableBody .user-row');
      for (var i = 0; i < rows.length; i++) {{
        var row = rows[i];
        var match = row.getAttribute('data-search').indexOf(q) !== -1;
        row.style.display = match ? '' : 'none';
      }}
    }}
    function filterGuilds() {{
      var q = document.getElementById('guildSearchBox').value.toLowerCase();
      var rows = document.querySelectorAll('#guildTableBody .guild-row');
      for (var i = 0; i < rows.length; i++) {{
        var row = rows[i];
        var match = row.getAttribute('data-search').indexOf(q) !== -1;
        row.style.display = match ? '' : 'none';
      }}
    }}
  </script>
</body>
</html>"""


def _check_dashboard_key(request) -> bool:
    """
    リクエストに含まれるキー（GETはクエリパラメータ、POSTはフォームの場合は呼び出し側で渡す）が
    ADMIN_DASHBOARD_KEY と一致するかをタイミング攻撃耐性のある比較で確認します。
    """
    import hmac
    if not ADMIN_DASHBOARD_KEY:
        return False
    provided_key = request.rel_url.query.get("key", "")
    return bool(provided_key) and hmac.compare_digest(provided_key, ADMIN_DASHBOARD_KEY)


def _check_dashboard_key_value(provided_key: str) -> bool:
    """POSTフォームのkey値を検証します。"""
    import hmac
    if not ADMIN_DASHBOARD_KEY:
        return False
    return bool(provided_key) and hmac.compare_digest(provided_key, ADMIN_DASHBOARD_KEY)


def _dashboard_not_found():
    """
    キー不一致時に存在を悟られないよう返す汎用404ページ。
    """
    return aiohttp.web.Response(
        text="404 Not Found",
        status=404,
        content_type="text/plain"
    )


def _dashboard_redirect(dashboard_key: str, message: str, is_error: bool = False):
    """
    POST処理後、結果メッセージ付きでダッシュボードのGETページへリダイレクトします（PRGパターン）。
    """
    query = urllib.parse.urlencode({
        "key": dashboard_key,
        "msg": message,
        "err": "1" if is_error else "0",
    })
    return aiohttp.web.HTTPSeeOther(location=f"/admin/blacklist?{query}")


async def _admin_dashboard_handler(request):
    """
    荒らしサーバー一覧・荒らしユーザー一覧・BOTコントロールを表示する管理者専用ダッシュボードのエンドポイント。
    ADMIN_DASHBOARD_KEY が未設定、またはキーが一致しない場合は存在を悟られないよう
    汎用的な404ページを返します（秘密リンク方式のため、誤ったキーには詳細を返しません）。
    """
    if not ADMIN_DASHBOARD_KEY:
        print("[管理者ダッシュボード] ADMIN_DASHBOARD_KEY が未設定のため、アクセスを拒否しました。")
        return _dashboard_not_found()

    if not _check_dashboard_key(request):
        return _dashboard_not_found()

    provided_key = request.rel_url.query.get("key", "")
    flash_message = request.rel_url.query.get("msg") or None
    flash_is_error = request.rel_url.query.get("err") == "1"

    all_data = load_data()
    global_cfg = get_global_config(all_data)
    blacklist_ids = global_cfg.get("global_server_blacklist_ids", [])
    troll_list = global_cfg.get("troll_list", {})

    bot_guilds = list(bot.guilds)
    try:
        bot_latency_ms = round(bot.latency * 1000) if not math.isnan(bot.latency) else 0
    except (TypeError, ValueError):
        bot_latency_ms = 0
    bot_user_str = str(bot.user) if bot.user else "未ログイン"

    return aiohttp.web.Response(
        text=_admin_dashboard_html(
            blacklist_ids,
            troll_list,
            dashboard_key=provided_key,
            bot_guilds=bot_guilds,
            bot_latency_ms=bot_latency_ms,
            bot_user_str=bot_user_str,
            custom_status_text=current_custom_status,
            flash_message=flash_message,
            flash_is_error=flash_is_error,
        ),
        content_type="text/html"
    )


async def _admin_user_add_handler(request):
    """荒らしユーザーをWebダッシュボードから追加するハンドラー（POST）。"""
    data = await request.post()
    provided_key = data.get("key", "")
    if not _check_dashboard_key_value(provided_key):
        return _dashboard_not_found()

    user_id_raw = (data.get("user_id") or "").strip()
    reason = (data.get("reason") or "").strip() or "Webダッシュボードからの手動登録"
    account_link = (data.get("account_link") or "").strip()

    if not user_id_raw.isdigit():
        return _dashboard_redirect(provided_key, "ユーザーIDは数字のみで入力してください。", is_error=True)

    user_id = int(user_id_raw)

    # 既にDiscord上でキャッシュ済みのユーザー情報があれば取得（無ければAPIで取得を試みる）
    user_obj = bot.get_user(user_id)
    if user_obj is None:
        try:
            user_obj = await bot.fetch_user(user_id)
        except Exception:
            user_obj = None

    all_data = load_data()
    global_cfg = get_global_config(all_data)
    troll_list = global_cfg["troll_list"]
    uid_str = str(user_id)

    username = str(user_obj) if user_obj else uid_str
    avatar_url = str(user_obj.display_avatar.url) if user_obj and user_obj.display_avatar else ""
    final_account_link = account_link or f"https://discord.com/users/{user_id}"

    if uid_str in troll_list:
        entry = troll_list[uid_str]
        entry["username"] = username
        entry["reason"] = reason
        entry["account_link"] = final_account_link
        if avatar_url:
            entry["avatar_url"] = avatar_url
    else:
        troll_list[uid_str] = {
            "username": username,
            "user_id": user_id,
            "avatar_url": avatar_url,
            "account_link": final_account_link,
            "reason": reason,
            "date": datetime.datetime.now(datetime.timezone.utc).isoformat(),
            "banned_in": [],
        }

    save_data(all_data)

    try:
        await _post_troll_board(all_data, uid_str)
    except Exception as e:
        print(f"[荒らし掲示板投稿エラー] {e}")

    return _dashboard_redirect(provided_key, f"ユーザー {username}（ID: {uid_str}）を荒らしリストに追加しました。")


async def _admin_user_delete_handler(request):
    """荒らしユーザーをWebダッシュボードから削除するハンドラー（POST）。"""
    data = await request.post()
    provided_key = data.get("key", "")
    if not _check_dashboard_key_value(provided_key):
        return _dashboard_not_found()

    user_id_raw = (data.get("user_id") or "").strip()

    all_data = load_data()
    global_cfg = get_global_config(all_data)
    troll_list = global_cfg["troll_list"]

    if user_id_raw in troll_list:
        del troll_list[user_id_raw]
        save_data(all_data)
        return _dashboard_redirect(provided_key, f"ユーザー（ID: {user_id_raw}）を荒らしリストから削除しました。")

    return _dashboard_redirect(provided_key, "指定されたユーザーは荒らしリストに見つかりませんでした。", is_error=True)


async def _admin_server_add_handler(request):
    """荒らしサーバー（サーバーブラックリスト）をWebダッシュボードから追加するハンドラー（POST）。"""
    data = await request.post()
    provided_key = data.get("key", "")
    if not _check_dashboard_key_value(provided_key):
        return _dashboard_not_found()

    server_id_raw = (data.get("server_id") or "").strip()
    if not server_id_raw.isdigit():
        return _dashboard_redirect(provided_key, "サーバーIDは数字のみで入力してください。", is_error=True)

    server_id = int(server_id_raw)

    all_data = load_data()
    global_cfg = get_global_config(all_data)
    blacklist = global_cfg.setdefault("global_server_blacklist_ids", [])

    if server_id in blacklist:
        return _dashboard_redirect(provided_key, "そのサーバーIDは既にブラックリストに登録されています。", is_error=True)

    blacklist.append(server_id)
    save_data(all_data)
    return _dashboard_redirect(provided_key, f"サーバー（ID: {server_id}）を荒らしサーバーリストに追加しました。")


async def _admin_server_delete_handler(request):
    """荒らしサーバー（サーバーブラックリスト）をWebダッシュボードから削除するハンドラー（POST）。"""
    data = await request.post()
    provided_key = data.get("key", "")
    if not _check_dashboard_key_value(provided_key):
        return _dashboard_not_found()

    server_id_raw = (data.get("server_id") or "").strip()
    if not server_id_raw.isdigit():
        return _dashboard_redirect(provided_key, "不正なサーバーIDです。", is_error=True)

    server_id = int(server_id_raw)

    all_data = load_data()
    global_cfg = get_global_config(all_data)
    blacklist = global_cfg.setdefault("global_server_blacklist_ids", [])

    if server_id in blacklist:
        blacklist.remove(server_id)
        save_data(all_data)
        return _dashboard_redirect(provided_key, f"サーバー（ID: {server_id}）を荒らしサーバーリストから削除しました。")

    return _dashboard_redirect(provided_key, "指定されたサーバーIDはブラックリストに見つかりませんでした。", is_error=True)


async def _admin_bot_status_handler(request):
    """BOTのカスタムステータス文言をWebダッシュボードから変更するハンドラー（POST）。"""
    data = await request.post()
    provided_key = data.get("key", "")
    if not _check_dashboard_key_value(provided_key):
        return _dashboard_not_found()

    global current_custom_status
    status_text = (data.get("status_text") or "").strip()

    if status_text:
        current_custom_status = status_text
        await update_bot_status(bot, text=status_text)
        return _dashboard_redirect(provided_key, f"ステータス文言を「{status_text}」に変更しました。")
    else:
        current_custom_status = None
        await update_bot_status(bot)
        return _dashboard_redirect(provided_key, "ステータス文言をデフォルト（サーバー数・コマンド数・稼働時間などのローテーション表示）に戻しました。")


async def _start_web_server():
    """aiohttp による OAuth2 コールバック受け取り用 Webサーバーを起動します。"""
    app = aiohttp.web.Application()
    app.router.add_get("/callback", _oauth2_callback_handler)
    app.router.add_get("/complete", _complete_handler)
    app.router.add_get("/terms", _terms_page_handler)
    app.router.add_get("/admin/blacklist", _admin_dashboard_handler)
    app.router.add_post("/admin/blacklist/user/add", _admin_user_add_handler)
    app.router.add_post("/admin/blacklist/user/delete", _admin_user_delete_handler)
    app.router.add_post("/admin/blacklist/server/add", _admin_server_add_handler)
    app.router.add_post("/admin/blacklist/server/delete", _admin_server_delete_handler)
    app.router.add_post("/admin/bot/status", _admin_bot_status_handler)
    app.router.add_get("/dashboard", _guild_dashboard_handler)
    app.router.add_post("/dashboard/toggle", _guild_dashboard_toggle_handler)
    app.router.add_get("/board", _board_list_handler)
    app.router.add_get("/board/login", _board_login_handler)
    app.router.add_get("/board/oauth_callback", _board_oauth_callback_handler)
    app.router.add_get("/board/servers", _board_server_select_handler)
    app.router.add_get("/board/manage", _board_manage_handler)
    app.router.add_post("/board/manage/save", _board_manage_save_handler)
    app.router.add_get("/", lambda req: aiohttp.web.Response(text="Bot is running."))
    if RAILWAY_MONITOR_AVAILABLE:
        if RAILWAY_WEBHOOK_SECRET:
            app.router.add_post("/webhook/railway/{secret}", _railway_webhook_handler)
        else:
            app.router.add_post("/webhook/railway", _railway_webhook_handler)
    runner = aiohttp.web.AppRunner(app)
    await runner.setup()
    site = aiohttp.web.TCPSite(runner, "0.0.0.0", OAUTH_PORT)
    await site.start()
    print(f"[Webサーバー] OAuth2コールバックサーバーを起動しました（ポート: {OAUTH_PORT}）")


