def _board_manage_redirect(access_query: str, message: str, is_error: bool = False):
    """掲示板管理ページの保存後、結果メッセージ付きで同じページへリダイレクトします（PRGパターン）。"""
    query = f"{access_query}&{urllib.parse.urlencode({'msg': message, 'err': '1' if is_error else '0'})}"
    return aiohttp.web.HTTPSeeOther(location=f"/board/manage?{query}")


def _resolve_board_manage_access(guild_id: int, user_id: int):
    """
    guild_id / user_id について、現在もそのサーバーに在籍し、
    かつ管理者権限（Administrator）を持っているかを検証します。
    戻り値は (guild, error_message) のタプルで、問題なければ error_message は None です。
    """
    guild = bot.get_guild(guild_id)
    if guild is None:
        return None, "Botがこのサーバーから退出しているため、管理ページを表示できません。"
    member = guild.get_member(user_id)
    if member is None:
        return None, "あなたはこのサーバーのメンバーではないため、管理ページにアクセスできません。"
    if not member.guild_permissions.administrator:
        return None, "あなたはこのサーバーの管理者ではないため、管理ページにアクセスできません。"
    return guild, None


def _resolve_board_manage_request(request):
    """
    /board/manage への GET/POST 両方に対応するアクセス解決処理です。
    次の2方式のいずれかで guild_id / user_id / access_query（再利用用クエリ文字列）を解決します。
      (a) token 方式: /board manage コマンドで発行した本人専用リンク（guild固定）
      (b) session 方式: 掲示板ページからのログイン後、guild_id をクエリで指定
    戻り値: (guild_id, user_id, access_query, error_message)
    """
    token = request.get("token")
    if token:
        result = _verify_board_manage_token(token)
        if result is None:
            return None, None, None, "このリンクは無効か、有効期限（発行から30分）が切れています。Discordで /board manage を再実行してください。"
        guild_id, user_id = result
        access_query = urllib.parse.urlencode({"token": token})
        return guild_id, user_id, access_query, None

    session_token = request.get("session")
    guild_id_raw = request.get("guild_id")
    if session_token and guild_id_raw:
        user_id = _verify_board_session_token(session_token)
        if user_id is None:
            return None, None, None, "セッションが無効か、有効期限が切れています。サーバー掲示板ページから再度ログインしてください。"
        try:
            guild_id = int(guild_id_raw)
        except ValueError:
            return None, None, None, "不正なリクエストです。"
        access_query = urllib.parse.urlencode({"session": session_token, "guild_id": guild_id})
        return guild_id, user_id, access_query, None

    return None, None, None, "アクセス情報が不足しています。Discordで /board manage を実行するか、サーバー掲示板ページからログインしてください。"


async def _board_manage_handler(request):
    """サーバー掲示板の登録・編集ページ（GET /board/manage）。token方式・session方式の両方に対応します。"""
    guild_id, user_id, access_query, error_message = _resolve_board_manage_request(request.rel_url.query)
    if error_message:
        return aiohttp.web.Response(text=error_message, status=403, content_type="text/plain")

    guild, error_message = _resolve_board_manage_access(guild_id, user_id)
    if guild is None:
        return aiohttp.web.Response(text=error_message, status=403, content_type="text/plain")

    board_data = load_server_board_data()
    entry = ensure_board_entry(board_data, str(guild_id))
    save_server_board_data(board_data)

    flash_message = request.rel_url.query.get("msg") or None
    flash_is_error = request.rel_url.query.get("err") == "1"

    return aiohttp.web.Response(
        text=_board_manage_html(guild, entry, access_query, flash_message, flash_is_error),
        content_type="text/html"
    )


async def _board_manage_save_handler(request):
    """サーバー掲示板の登録・編集フォームの保存を処理します（POST /board/manage/save）。"""
    data = await request.post()
    access_query = str(data.get("access", ""))

    parsed_access = urllib.parse.parse_qs(access_query)
    request_like = {k: v[0] for k, v in parsed_access.items()}
    if "guild_id" in data:
        request_like["guild_id"] = data.get("guild_id")

    guild_id, user_id, resolved_access_query, error_message = _resolve_board_manage_request(request_like)
    if error_message:
        return aiohttp.web.Response(text=error_message, status=403, content_type="text/plain")

    guild, error_message = _resolve_board_manage_access(guild_id, user_id)
    if guild is None:
        return aiohttp.web.Response(text=error_message, status=403, content_type="text/plain")

    description = str(data.get("description", "")).strip()[:400]
    tags_raw = str(data.get("tags", ""))
    tags = [t.strip() for t in tags_raw.split(",") if t.strip()][:5]
    invite_url = str(data.get("invite_url", "")).strip()

    if invite_url and not (invite_url.startswith("https://discord.gg/") or invite_url.startswith("https://discord.com/invite/")):
        return _board_manage_redirect(
            resolved_access_query,
            "招待リンクは https://discord.gg/ または https://discord.com/invite/ から始まるURLを入力してください。",
            is_error=True
        )

    board_data = load_server_board_data()
    entry = ensure_board_entry(board_data, str(guild_id))
    entry["description"] = description
    entry["tags"] = tags
    entry["invite_url"] = invite_url
    save_server_board_data(board_data)

    return _board_manage_redirect(resolved_access_query, "掲示板情報を保存しました。")


# ====================================================================
# セクション 17.5: AIサーバーセットアップウィザード
# ・/setup コマンドで専用スレッドを開始し、AIとの自由テキスト対話で
#   「どんな用途のサーバーか」「必要なチャンネル構成」「ロール構成」をヒアリング
# ・AIがヒアリング十分と判断すると __PLAN_READY__ + JSON を出力 → プレビューEmbed表示
# ・「作成」ボタン押下で一括構築（既存チャンネル/ロールは変更せず、追加のみ行う安全設計）
# ====================================================================

SETUP_WIZARD_MAX_TURNS = 12                 # ヒアリングの往復上限（無限ループ防止）
SETUP_WIZARD_SESSION_TIMEOUT_SECONDS = 900  # 15分操作が無ければセッションを自動終了
SETUP_WIZARD_COOLDOWN_SECONDS = 5           # 連続メッセージ送信の最低間隔
SETUP_WIZARD_PLAN_MARKER = "__PLAN_READY__"

SETUP_WIZARD_SYSTEM_PROMPT = (
    "あなたはDiscordサーバーの構築を手伝う設定アシスタントです。"
    "ユーザーと日本語で自然に会話しながら、これから作るサーバー（または追加する構成）について "
    "「サーバーの用途・目的」「欲しいテキストチャンネル／ボイスチャンネル」「欲しいロール」を "
    "ヒアリングしてください。\n"
    "ルール:\n"
    "・一度に大量の質問をせず、1〜2個ずつ聞いてください。\n"
    "・ユーザーの回答が曖昧な場合は、一般的なサーバー構成（雑談・お知らせ・自己紹介・ボイス通話等）を"
    "提案しながら具体化してください。\n"
    "・ユーザーが「お任せする」「それでいい」等、構成の決定をあなたに委ねた場合は、"
    "それ以上質問を重ねず、妥当な構成案を自分で決めてすぐに次のルールに従ってプランを出力してください。\n"
    "・ヒアリングが十分に済み、構成案を提示できる状態になったら、必ず出力の先頭に "
    f"半角で「{SETUP_WIZARD_PLAN_MARKER}」という文字列だけを書き、続けて改行し、"
    "以下のJSON形式のみを出力してください（それ以外の文章・Markdownのコードブロック記号は一切付けないこと）。\n"
    "{\n"
    '  "summary": "この構成案の一言説明",\n'
    '  "categories": [\n'
    '    {"name": "カテゴリ名", "channels": [{"type": "text または voice", "name": "チャンネル名"}]}\n'
    "  ],\n"
    '  "roles": [\n'
    '    {"name": "ロール名", "color": "#RRGGBB(任意)", "hoist": true/false(任意), "mentionable": true/false(任意)}\n'
    "  ]\n"
    "}\n"
    "・JSONを出力する時点では、それ以外の説明文は一切書かないでください（マーカーとJSONのみ）。\n"
    "・まだヒアリング中の間は、通常の会話文だけを返し、絶対にマーカーやJSONを出力しないでください。"
)

# {thread_id: {"guild_id": int, "user_id": int, "messages": [...], "turns": int, "last_active": epoch}}
_setup_wizard_sessions: dict = {}
# {guild_id: thread_id} — サーバーごとに同時進行セッションを1つに制限するための逆引き
_setup_wizard_guild_active: dict = {}


def _setup_wizard_cleanup_stale_sessions():
    """タイムアウトした古いセッションを掃除します。"""
    now = time.time()
    stale_thread_ids = [
        tid for tid, s in _setup_wizard_sessions.items()
        if now - s.get("last_active", now) > SETUP_WIZARD_SESSION_TIMEOUT_SECONDS
    ]
    for tid in stale_thread_ids:
        session = _setup_wizard_sessions.pop(tid, None)
        if session and _setup_wizard_guild_active.get(session["guild_id"]) == tid:
            _setup_wizard_guild_active.pop(session["guild_id"], None)


def _setup_wizard_end_session(thread_id: int):
    """セッションを明示的に終了します（完了・キャンセル・エラー時に呼び出し）。"""
    session = _setup_wizard_sessions.pop(thread_id, None)
    if session and _setup_wizard_guild_active.get(session["guild_id"]) == thread_id:
        _setup_wizard_guild_active.pop(session["guild_id"], None)


def _setup_wizard_extract_plan(reply_text: str) -> Optional[dict]:
    """AI応答から __PLAN_READY__ マーカー以降のJSON構成案を抽出します。失敗時はNoneを返します。"""
    marker_idx = reply_text.find(SETUP_WIZARD_PLAN_MARKER)
    if marker_idx == -1:
        return None
    json_part = reply_text[marker_idx + len(SETUP_WIZARD_PLAN_MARKER):].strip()
    # AIがMarkdownのコードブロック記号を付けてしまった場合に備えて除去する
    json_part = re.sub(r"^```(?:json)?\s*|\s*```$", "", json_part.strip())
    try:
        plan = json.loads(json_part)
    except (json.JSONDecodeError, ValueError):
        return None
    if not isinstance(plan, dict):
        return None
    return plan


def _setup_wizard_build_preview_embed(plan: dict, requester: discord.Member) -> discord.Embed:
    """構成案プレビュー用のEmbedを作成します。"""
    embed = discord.Embed(
        title="サーバー構成案プレビュー",
        description=str(plan.get("summary") or "AIが提案したサーバー構成案です。内容を確認してください。")[:400],
        color=discord.Color.green()
    )

    categories = plan.get("categories") or []
    if categories:
        lines = []
        for cat in categories[:25]:
            cat_name = str(cat.get("name", "（無名カテゴリ）"))[:100]
            channels = cat.get("channels") or []
            ch_lines = []
            for ch in channels[:25]:
                ch_type = "🔊" if str(ch.get("type", "text")).lower() == "voice" else "#"
                ch_lines.append(f"　{ch_type}{ch.get('name', '無名チャンネル')}")
            block = f"**📁 {cat_name}**"
            if ch_lines:
                block += "\n" + "\n".join(ch_lines)
            lines.append(block)
        text = "\n".join(lines)
        embed.add_field(name=f"チャンネル構成（カテゴリ数: {len(categories)}）", value=text[:1024] or "（なし）", inline=False)
    else:
        embed.add_field(name="チャンネル構成", value="（提案なし）", inline=False)

    roles = plan.get("roles") or []
    if roles:
        role_lines = [f"・{r.get('name', '無名ロール')}" for r in roles[:25]]
        embed.add_field(name=f"ロール構成（{len(roles)}個）", value="\n".join(role_lines)[:1024], inline=False)
    else:
        embed.add_field(name="ロール構成", value="（提案なし）", inline=False)

    embed.set_footer(text=f"依頼者: {requester.display_name} | 既存のチャンネル・ロールは変更せず、追加のみ行います")
    return embed


async def _setup_wizard_apply_plan(guild: discord.Guild, plan: dict) -> tuple[list[str], list[str]]:
    """
    構成案を実際のサーバーへ適用します（追加のみ・既存要素は一切変更しません）。
    _safe_api_call を使ってレート制限に配慮しながら順番に作成します。
    """
    success_logs: list[str] = []
    fail_logs: list[str] = []

    # 1. ロールを先に作成（チャンネルの権限設定では使わない設計だが、将来の拡張に備えて先に処理）
    allowed_color_re = re.compile(r"^#?[0-9a-fA-F]{6}$")
    for r_data in (plan.get("roles") or [])[:25]:
        if not isinstance(r_data, dict):
            continue
        name = str(r_data.get("name") or "").strip()[:100]
        if not name:
            continue
        color = discord.Color.default()
        color_raw = r_data.get("color")
        if isinstance(color_raw, str) and allowed_color_re.match(color_raw.strip()):
            try:
                color = discord.Color(int(color_raw.strip().lstrip("#"), 16))
            except ValueError:
                pass
        label = f"ロール「{name}」"
        role = await _safe_api_call(
            guild.create_role(
                name=name,
                color=color,
                hoist=bool(r_data.get("hoist", False)),
                mentionable=bool(r_data.get("mentionable", False)),
                reason="AIセットアップウィザードによる自動作成",
            ),
            fail_logs, label
        )
        if role:
            success_logs.append(f"{label} を作成しました")
        await asyncio.sleep(0.5)

    # 2. カテゴリ + 配下チャンネルを作成
    for cat_data in (plan.get("categories") or [])[:25]:
        if not isinstance(cat_data, dict):
            continue
        cat_name = str(cat_data.get("name") or "").strip()[:100]
        if not cat_name:
            continue
        label = f"カテゴリ「{cat_name}」"
        category = await _safe_api_call(
            guild.create_category(name=cat_name, reason="AIセットアップウィザードによる自動作成"),
            fail_logs, label
        )
        if not category:
            continue
        success_logs.append(f"{label} を作成しました")
        await asyncio.sleep(0.5)

        for ch_data in (cat_data.get("channels") or [])[:50]:
            if not isinstance(ch_data, dict):
                continue
            ch_name = str(ch_data.get("name") or "").strip()[:100]
            if not ch_name:
                continue
            ch_type = str(ch_data.get("type", "text")).lower()
            if ch_type == "voice":
                ch_label = f"ボイスch「{ch_name}」"
                ch = await _safe_api_call(
                    guild.create_voice_channel(
                        name=ch_name, category=category, reason="AIセットアップウィザードによる自動作成"
                    ),
                    fail_logs, ch_label
                )
            else:
                ch_label = f"テキストch「#{ch_name}」"
                ch = await _safe_api_call(
                    guild.create_text_channel(
                        name=ch_name, category=category, reason="AIセットアップウィザードによる自動作成"
                    ),
                    fail_logs, ch_label
                )
            if ch:
                success_logs.append(f"{ch_label} を作成しました")
            await asyncio.sleep(0.5)

    return success_logs, fail_logs


class SetupWizardConfirmView(discord.ui.View):
    """構成案プレビュー後の「作成」「キャンセル」ボタンです。"""

    def __init__(self, plan: dict, thread_id: int, requester_id: int):
        super().__init__(timeout=300)
        self.plan = plan
        self.thread_id = thread_id
        self.requester_id = requester_id
        self._running = False

    async def interaction_check(self, interaction: discord.Interaction) -> bool:
        if interaction.user.id != self.requester_id:
            await interaction.response.send_message("このプレビューはセットアップを開始した本人のみ操作できます。", ephemeral=True)
            return False
        return True

    @discord.ui.button(label="この内容で作成する", style=discord.ButtonStyle.success, emoji="✅")
    async def confirm(self, interaction: discord.Interaction, button: discord.ui.Button):
        if not interaction.guild:
            return
        if self._running:
            await interaction.response.send_message("すでに作成処理を実行中です。しばらくお待ちください。", ephemeral=True)
            return
        self._running = True
        for item in self.children:
            item.disabled = True
        await interaction.response.edit_message(view=self)

        await interaction.followup.send(">> 構成の作成を開始します...", ephemeral=False)
        success_logs, fail_logs = await _setup_wizard_apply_plan(interaction.guild, self.plan)

        result_lines = (
            [f"** サーバー構築完了 ** 成功: {len(success_logs)}件 / 失敗: {len(fail_logs)}件\n"]
            + [f"[OK] {s}" for s in success_logs]
            + [f"[NG] {f}" for f in fail_logs]
        )
        chunk = ""
        messages_out = []
        for line in result_lines:
            if len(chunk) + len(line) + 1 > 1900:
                messages_out.append(chunk)
                chunk = line + "\n"
            else:
                chunk += line + "\n"
        if chunk:
            messages_out.append(chunk)
        for msg in messages_out:
            await interaction.followup.send(msg, ephemeral=False)

        _setup_wizard_end_session(self.thread_id)
        self._running = False

    @discord.ui.button(label="キャンセル", style=discord.ButtonStyle.secondary)
    async def cancel(self, interaction: discord.Interaction, button: discord.ui.Button):
        if self._running:
            await interaction.response.send_message("作成処理はすでに実行中のためキャンセルできません。", ephemeral=True)
            return
        for item in self.children:
            item.disabled = True
        await interaction.response.edit_message(content="セットアップをキャンセルしました。構成の作成は行われていません。", embed=None, view=self)
        _setup_wizard_end_session(self.thread_id)


async def _setup_wizard_send_ai_turn(thread: discord.Thread, session: dict, requester: discord.Member):
    """現在の会話履歴をもとにAIを呼び出し、質問の続行またはプラン提示を行います。"""
    try:
        reply_text, _provider = await _ai_call_llm_with_fallback(
            session["messages"],
            enable_search=False,
        )
    except Exception as e:
        print(f"[セットアップウィザード] AI呼び出しに失敗しました: {e!r}")
        await thread.send("[!] AIの呼び出し中にエラーが発生しました。しばらくしてから `/setup` をやり直してください。")
        _setup_wizard_end_session(thread.id)
        return

    plan = _setup_wizard_extract_plan(reply_text)
    if plan is not None:
        embed = _setup_wizard_build_preview_embed(plan, requester)
        view = SetupWizardConfirmView(plan, thread.id, requester.id)
        await thread.send(
            content="ヒアリングが完了しました。以下の内容でサーバーを構築します。よろしければ「作成」を押してください。",
            embed=embed,
            view=view,
        )
        # プレビュー表示中は追加のヒアリングメッセージを受け付けない（ボタン操作待ち）
        session["awaiting_confirmation"] = True
        session["last_active"] = time.time()
        return

    session["messages"].append({"role": "assistant", "content": reply_text})
    session["last_active"] = time.time()
    await thread.send(reply_text[:1900])


async def _handle_setup_wizard_message(message: discord.Message) -> bool:
    """
    セットアップウィザード進行中のスレッドでのメッセージを処理します。
    このスレッド宛のメッセージとして処理した場合は True を返します
    （呼び出し側はTrueが返れば以降の通常メッセージ処理をスキップしてよい）。
    """
    _setup_wizard_cleanup_stale_sessions()
    session = _setup_wizard_sessions.get(message.channel.id)
    if session is None:
        return False

    if message.author.id != session["user_id"]:
        # セットアップ担当者以外の発言は無視する（他の人が同じスレッドに書き込める場合がある）
        return True

    if session.get("awaiting_confirmation"):
        # プレビューのボタン操作待ちの間はテキストでの追加ヒアリングを受け付けない
        return True

    remaining = SETUP_WIZARD_COOLDOWN_SECONDS - (time.time() - session.get("last_active", 0))
    if remaining > 0:
        return True

    if session["turns"] >= SETUP_WIZARD_MAX_TURNS:
        await message.channel.send(
            "ヒアリングの往復上限に達しました。現時点の情報を元に構成案を作成します..."
        )
        session["messages"].append({
            "role": "user",
            "content": message.content[:1000] or "（内容なし）"
        })
        session["messages"].append({
            "role": "system",
            "content": (
                "往復上限に達しました。追加の質問はせず、これまでの情報のみを使って"
                f"必ず{SETUP_WIZARD_PLAN_MARKER}に続けてJSON構成案を出力してください。"
            )
        })
        session["turns"] += 1
        await _setup_wizard_send_ai_turn(message.channel, session, message.author)
        return True

    session["messages"].append({"role": "user", "content": message.content[:1000] or "（内容なし）"})
    session["turns"] += 1
    async with message.channel.typing():
        await _setup_wizard_send_ai_turn(message.channel, session, message.author)
    return True


@bot.tree.command(name="setup", description="【管理者専用】AIとの対話でサーバーのチャンネル・ロール構成をヒアリングし、自動構築します")
@app_commands.allowed_contexts(guilds=True, dms=False, private_channels=False)
@app_commands.allowed_installs(guilds=True, users=False)
async def setup_wizard_command(interaction: discord.Interaction):
    if not await is_guild_admin(interaction):
        return

    if not GROQ_API_KEY:
        await interaction.response.send_message("現在この機能は利用できません（Botの設定が未完了です）。", ephemeral=True)
        return

    guild = interaction.guild
    if guild is None:
        await interaction.response.send_message("このコマンドはサーバー内で実行してください。", ephemeral=True)
        return

    _setup_wizard_cleanup_stale_sessions()
    existing_thread_id = _setup_wizard_guild_active.get(guild.id)
    if existing_thread_id:
        await interaction.response.send_message(
            f"このサーバーでは既にセットアップセッションが進行中です。<#{existing_thread_id}> で続きを行ってください。",
            ephemeral=True
        )
        return

    if not isinstance(interaction.channel, discord.TextChannel):
        await interaction.response.send_message(
            "このコマンドは通常のテキストチャンネル内で実行してください。", ephemeral=True
        )
        return

    if not guild.me.guild_permissions.create_public_threads or not guild.me.guild_permissions.manage_channels:
        await interaction.response.send_message(
            "Botに「スレッドの作成」および「チャンネルの管理」権限がないため、この機能を利用できません。",
            ephemeral=True
        )
        return

    await interaction.response.defer(ephemeral=True)

    try:
        thread = await interaction.channel.create_thread(
            name=f"サーバー設定ウィザード-{interaction.user.display_name}"[:100],
            type=discord.ChannelType.public_thread,
            reason="AIセットアップウィザード開始",
        )
    except discord.HTTPException as e:
        await interaction.followup.send(f"スレッドの作成に失敗しました: {e}", ephemeral=True)
        return

    session = {
        "guild_id": guild.id,
        "user_id": interaction.user.id,
        "messages": [{
            "role": "system",
            "content": _ai_chat_finalize_system_prompt(SETUP_WIZARD_SYSTEM_PROMPT, include_search_guide=False),
        }],
        "turns": 0,
        "last_active": time.time(),
        "awaiting_confirmation": False,
    }
    _setup_wizard_sessions[thread.id] = session
    _setup_wizard_guild_active[guild.id] = thread.id

    await interaction.followup.send(f"セットアップウィザードを開始しました: {thread.mention}", ephemeral=True)
    await thread.send(
        f"{interaction.user.mention} こんにちは！このサーバーのチャンネル・ロール構成のセットアップをお手伝いします。\n"
        "まず、このサーバーをどんな用途で使いたいか教えてください（例: ゲームコミュニティ、勉強会、会社の連絡用 など）。\n"
        "-# このスレッド内で自由に返信してください。「お任せします」と伝えれば、AIがおすすめの構成を提案します。"
    )


# ====================================================================
# セクション 18: チケット（問い合わせ）システム
# ・ユーザーがパネルのボタンを押すと、本人とスタッフのみ閲覧できる
#   専用チャンネルが自動作成される
# ・スタッフまたは作成者本人がクローズボタン／コマンドでチャンネルを削除できる
# ====================================================================

class TicketCreateButton(discord.ui.Button):
    """チケットパネルに設置する「問い合わせを作成」ボタン。"""

    def __init__(self):
        super().__init__(
            label="問い合わせを作成",
            style=discord.ButtonStyle.primary,
            custom_id="ticket_create_button"
        )

    async def callback(self, interaction: discord.Interaction):
        guild = interaction.guild
        if guild is None:
            return

        await interaction.response.defer(ephemeral=True)

        all_data = load_data()
        cfg = get_guild_config(all_data, str(guild.id))
        open_channels = cfg.setdefault("ticket_open_channels", {})

        # 既に本人が対応中のチケットを持っていないか確認（1人1チケットまで）
        for ch_id_str, info in list(open_channels.items()):
            if info.get("user_id") == interaction.user.id:
                existing = guild.get_channel(int(ch_id_str))
                if existing:
                    await interaction.followup.send(
                        f"既に対応中のチケットがあります: {existing.mention}", ephemeral=True
                    )
                    return
                else:
                    # チャンネルが手動削除されていた場合は古い記録を掃除する
                    open_channels.pop(ch_id_str, None)

        category_id = cfg.get("ticket_category_id")
        category = guild.get_channel(category_id) if category_id else None
        if not isinstance(category, discord.CategoryChannel):
            category = None

        staff_role_id = cfg.get("ticket_staff_role_id")
        staff_role = guild.get_role(staff_role_id) if staff_role_id else None

        ticket_id = cfg.get("ticket_next_id", 1)
        cfg["ticket_next_id"] = ticket_id + 1

        overwrites = {
            guild.default_role: discord.PermissionOverwrite(view_channel=False),
            guild.me: discord.PermissionOverwrite(view_channel=True, send_messages=True, manage_channels=True),
            interaction.user: discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True),
        }
        if staff_role:
            overwrites[staff_role] = discord.PermissionOverwrite(
                view_channel=True, send_messages=True, read_message_history=True
            )

        channel_name = f"ticket-{ticket_id:04d}"
        try:
            ticket_channel = await guild.create_text_channel(
                name=channel_name,
                category=category,
                overwrites=overwrites,
                reason=f"チケット作成: {interaction.user}"
            )
        except discord.Forbidden:
            await interaction.followup.send(
                "チャンネルを作成する権限がBotにありません。管理者に確認してください。", ephemeral=True
            )
            return
        except discord.HTTPException as e:
            await interaction.followup.send(f"チャンネル作成に失敗しました: {e}", ephemeral=True)
            return

        open_channels[str(ticket_channel.id)] = {
            "user_id": interaction.user.id,
            "ticket_id": ticket_id,
            "opened_at": int(time.time())
        }
        save_data(all_data)

        embed = discord.Embed(
            title=f"[TICKET] お問い合わせ #{ticket_id:04d}",
            description=(
                f"{interaction.user.mention} さんの問い合わせチャンネルです。\n"
                f"内容をこちらにご記入ください。対応完了後は下のボタン、または `/ticket close` でクローズできます。"
            ),
            color=discord.Color.blurple()
        )
        await ticket_channel.send(
            content=f"{interaction.user.mention}" + (f" {staff_role.mention}" if staff_role else ""),
            embed=embed,
            view=TicketCloseView()
        )

        await interaction.followup.send(f"[OK] チケットを作成しました: {ticket_channel.mention}", ephemeral=True)


class TicketPanelView(discord.ui.View):
    """チケットパネル（作成ボタン付き）。custom_idが固定なのでBot起動時に1回登録すれば全パネルで動作する。"""

    def __init__(self):
        super().__init__(timeout=None)
        self.add_item(TicketCreateButton())


class TicketCloseButton(discord.ui.Button):
    """チケットチャンネル内に設置する「クローズ」ボタン。"""

    def __init__(self):
        super().__init__(
            label="チケットをクローズ",
            style=discord.ButtonStyle.danger,
            custom_id="ticket_close_button"
        )

    async def callback(self, interaction: discord.Interaction):
        await _close_ticket_channel(interaction)


class TicketCloseView(discord.ui.View):
    def __init__(self):
        super().__init__(timeout=None)
        self.add_item(TicketCloseButton())


async def _close_ticket_channel(interaction: discord.Interaction):
    """チケットチャンネルをクローズ（ログ送信後にチャンネル削除）します。"""
    guild = interaction.guild
    channel = interaction.channel
    if guild is None or channel is None:
        await interaction.response.send_message("このコマンドはサーバー内でのみ使用できます。", ephemeral=True)
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(guild.id))
    open_channels = cfg.setdefault("ticket_open_channels", {})
    info = open_channels.get(str(channel.id))

    if info is None:
        await interaction.response.send_message("このチャンネルはチケットチャンネルではありません。", ephemeral=True)
        return

    # 権限確認：チケット作成者本人、またはスタッフロール/管理者/許可ユーザー
    is_owner_of_ticket = interaction.user.id == info.get("user_id")
    is_staff = bool(getattr(interaction.user, "guild_permissions", None)) and interaction.user.guild_permissions.manage_channels
    staff_role_id = cfg.get("ticket_staff_role_id")
    if staff_role_id and any(r.id == staff_role_id for r in getattr(interaction.user, "roles", [])):
        is_staff = True

    if not (is_owner_of_ticket or is_staff):
        await interaction.response.send_message("このチケットをクローズする権限がありません。", ephemeral=True)
        return

    await interaction.response.send_message("[LOCK] 5秒後にこのチケットをクローズします...")

    # ログチャンネルが設定されていれば記録を送信
    log_channel_id = cfg.get("ticket_log_channel_id")
    if log_channel_id:
        log_channel = guild.get_channel(log_channel_id)
        if log_channel:
            ticket_user = guild.get_member(info.get("user_id"))
            log_embed = discord.Embed(
                title=f"[TICKET] チケット #{info.get('ticket_id', 0):04d} クローズ",
                description=(
                    f"作成者: {ticket_user.mention if ticket_user else info.get('user_id')}\n"
                    f"クローズ実行者: {interaction.user.mention}\n"
                    f"チャンネル名: {channel.name}"
                ),
                color=discord.Color.red(),
                timestamp=discord.utils.utcnow()
            )
            try:
                await log_channel.send(embed=log_embed)
            except discord.HTTPException:
                pass

    open_channels.pop(str(channel.id), None)
    save_data(all_data)

    await asyncio.sleep(5)
    try:
        await channel.delete(reason=f"チケットクローズ（実行者: {interaction.user}）")
    except (discord.Forbidden, discord.HTTPException):
        pass


@ticket_group.command(name="setup", description="【管理者専用】このチャンネルに問い合わせ用のチケットパネルを設置できます")
@discord.app_commands.describe(
    タイトル="パネルに表示するタイトル",
    説明="パネルに表示する説明文",
    スタッフロール="チケットチャンネルを閲覧できるスタッフロール",
    チケット作成先カテゴリ="チケットチャンネルを作成するカテゴリ（未指定の場合はカテゴリなしで作成）",
    ログチャンネル="クローズ時に記録を送るチャンネル（任意）"
)
async def ticket_setup(
    interaction: discord.Interaction,
    タイトル: str,
    説明: str,
    スタッフロール: discord.Role,
    チケット作成先カテゴリ: discord.CategoryChannel = None,
    ログチャンネル: discord.TextChannel = None
):
    if not await is_admin_or_allowed(interaction):
        return
    if not interaction.guild or not isinstance(interaction.channel, discord.TextChannel):
        await interaction.response.send_message("このコマンドはサーバーのテキストチャンネルでのみ使用できます。", ephemeral=True)
        return

    embed = discord.Embed(title=タイトル, description=説明, color=discord.Color.blurple())
    view = TicketPanelView()

    try:
        message = await interaction.channel.send(embed=embed, view=view)
    except discord.Forbidden:
        await interaction.response.send_message("このチャンネルにメッセージを送信する権限がBotにありません。", ephemeral=True)
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))
    cfg["ticket_panel_channel_id"] = interaction.channel.id
    cfg["ticket_panel_message_id"] = message.id
    cfg["ticket_staff_role_id"] = スタッフロール.id
    cfg["ticket_category_id"] = チケット作成先カテゴリ.id if チケット作成先カテゴリ else None
    cfg["ticket_log_channel_id"] = ログチャンネル.id if ログチャンネル else None
    save_data(all_data)

    await interaction.response.send_message(
        f"[OK] チケットパネルを設置しました。（スタッフロール: {スタッフロール.mention} / "
        f"カテゴリ: {チケット作成先カテゴリ.name if チケット作成先カテゴリ else 'なし'} / "
        f"ログ: {ログチャンネル.mention if ログチャンネル else '未設定'}）",
        ephemeral=True
    )


@ticket_group.command(name="close", description="今いるチャンネルがチケットなら、そのままクローズできます")
async def ticket_close(interaction: discord.Interaction):
    await _close_ticket_channel(interaction)


# ====================================================================
# 招待トラッキング（/invite stats, /invite leaderboard）
# ====================================================================

@invite_group.command(name="stats", description="招待した人数のランキングや、指定したユーザーの招待成績を確認できます")
async def invite_stats_cmd(interaction: discord.Interaction, ユーザー: discord.Member = None):
    if not interaction.guild:
        await interaction.response.send_message("このコマンドはサーバー内で実行してください。", ephemeral=True)
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))

    if not cfg.get("invite_tracking_enabled", True):
        await interaction.response.send_message(
            "このサーバーでは招待トラッキングが無効になっています。",
            ephemeral=True
        )
        return

    target = ユーザー or interaction.user
    stats = cfg.get("invite_stats", {}).get(str(target.id), {"joins": 0, "leaves": 0})
    joins = stats.get("joins", 0)
    leaves = stats.get("leaves", 0)
    net = joins - leaves

    embed = discord.Embed(
        title=f"招待成績: {target.display_name}",
        color=discord.Color.blue()
    )
    embed.set_thumbnail(url=target.display_avatar.url)
    embed.add_field(name="累計招待参加数", value=f"{joins}人", inline=True)
    embed.add_field(name="うち退出済み", value=f"{leaves}人", inline=True)
    embed.add_field(name="現在の招待実績（純増）", value=f"{net}人", inline=True)
    embed.set_footer(text="Bot起動中に取得できた招待作成者情報のみ集計されます（Vanity URL経由の参加は集計対象外）")
    await interaction.response.send_message(embed=embed)


@invite_group.command(name="leaderboard", description="サーバー内での招待人数ランキングを見られます")
async def invite_leaderboard_cmd(interaction: discord.Interaction):
    if not interaction.guild:
        await interaction.response.send_message("このコマンドはサーバー内で実行してください。", ephemeral=True)
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))
    stats = cfg.get("invite_stats", {})

    if not stats:
        await interaction.response.send_message("まだ招待トラッキングのデータがありません。", ephemeral=True)
        return

    # 純増数（joins - leaves）の降順でランキング化
    ranked = sorted(
        stats.items(),
        key=lambda item: item[1].get("joins", 0) - item[1].get("leaves", 0),
        reverse=True
    )[:10]

    embed = discord.Embed(
        title="招待ランキング TOP10",
        description=f"{interaction.guild.name} における招待実績（純増数）ランキングです。",
        color=discord.Color.gold()
    )
    medals = ["🥇", "🥈", "🥉"]
    lines = []
    for i, (user_id_str, entry) in enumerate(ranked):
        joins = entry.get("joins", 0)
        leaves = entry.get("leaves", 0)
        net = joins - leaves
        prefix = medals[i] if i < 3 else f"{i + 1}."
        lines.append(f"{prefix} <@{user_id_str}> — **{net}人**（参加{joins} / 退出{leaves}）")

    embed.add_field(name="ランキング", value="\n".join(lines) if lines else "データがありません", inline=False)
    await interaction.response.send_message(embed=embed)


@invite_group.command(name="toggle", description="【管理者専用】招待トラッキング機能をON/OFF切り替えできます")
async def invite_toggle_cmd(interaction: discord.Interaction):
    if not await is_guild_admin(interaction):
        return
    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))
    cfg["invite_tracking_enabled"] = not cfg.get("invite_tracking_enabled", True)
    save_data(all_data)
    state = "有効" if cfg["invite_tracking_enabled"] else "無効"
    await interaction.response.send_message(f"招待トラッキング機能を{state}にしました。", ephemeral=True)


# ====================================================================
# AFK機能（/afk）
# ====================================================================
# 席を外す際に /afk を実行しておくと、他の人からメンションされた際に
# Botが「離席中です」と自動で知らせてくれます。本人が次に発言すると
# 自動的にAFK状態が解除されます。

@bot.tree.command(name="afk", description="離席（AFK）中だとみんなに知らせておけます。次に発言すると自動的に解除されます")
async def afk_cmd(interaction: discord.Interaction, 理由: str = "離席中"):
    if not interaction.guild:
        await interaction.response.send_message("このコマンドはサーバー内で実行してください。", ephemeral=True)
        return

    all_data = load_data()
    guild_id_str = str(interaction.guild.id)
    user_id_str = str(interaction.user.id)

    member = interaction.guild.get_member(interaction.user.id)
    old_nick = member.nick if member else None

    set_afk_status(all_data, guild_id_str, user_id_str, 理由, old_nick)
    save_data(all_data)

    # ニックネームに[AFK]を付与（表示上分かりやすくするための任意演出。権限不足時は無視）
    if member and not (member.nick or "").startswith("[AFK] "):
        try:
            new_nick = f"[AFK] {member.display_name}"
            if len(new_nick) <= 32:
                await member.edit(nick=new_nick, reason="AFK設定")
        except Exception:
            pass

    embed = discord.Embed(
        title="[AFK] 離席モードにしました",
        description=f"理由: {理由}\n\nメンションされると、代わりにBotが離席中である旨をお知らせします。\n次に何か発言すると自動的に解除されます。",
        color=discord.Color.greyple()
    )
    await interaction.response.send_message(embed=embed, ephemeral=True)


@bot.command(name="afk")
async def afk_text_cmd(ctx: commands.Context, *, 理由: str = "離席中"):
    """
    テキストコマンド版のAFK設定です（!afk 理由）。
    Discordの仕様上、スラッシュコマンド（/afk）はグループDM内では使用できないため、
    グループDM・通常DM・サーバーのいずれでも使えるテキストコマンドとして用意しています。
    """
    if ctx.guild is not None:
        # サーバー内では /afk（スラッシュコマンド版）に案内する
        # ※ !afk 自体もサーバー内で動作させたい場合はこの分岐を削除してください
        all_data = load_data()
        guild_id_str = str(ctx.guild.id)
        user_id_str = str(ctx.author.id)
        member = ctx.guild.get_member(ctx.author.id)
        old_nick = member.nick if member else None
        set_afk_status(all_data, guild_id_str, user_id_str, 理由, old_nick)
        save_data(all_data)
        if member and not (member.nick or "").startswith("[AFK] "):
            try:
                new_nick = f"[AFK] {member.display_name}"
                if len(new_nick) <= 32:
                    await member.edit(nick=new_nick, reason="AFK設定")
            except Exception:
                pass
        await ctx.send(f"[AFK] {ctx.author.mention} を離席モードにしました。理由: {理由}")
        return

    # DM／グループDM: グローバルAFKストレージを使用（サーバーロール等は存在しないため）
    all_data = load_data()
    global_cfg = get_global_config(all_data)
    global_cfg.setdefault("global_afk_users", {})[str(ctx.author.id)] = {
        "reason": 理由,
        "since": int(time.time()),
    }
    save_data(all_data)
    await ctx.send(f"[AFK] {ctx.author.mention} を離席モードにしました。理由: {理由}")


# ====================================================================
# セクション 19: 面接（応募）システム
# /面接 → DMまたは専用チャンネルで質問に順番に回答 → Embedにまとめて
# 運営用チャンネルへ送信 → 管理者が合格/不合格/保留ボタンで判定 →
# 応募者へ結果をDM通知
# ====================================================================

class InterviewResultButton(discord.ui.Button):
    """面接結果パネルに設置する合格/不合格/保留ボタン。"""

    def __init__(self, action: str, guild_id: int, record_id: int, style: discord.ButtonStyle, label: str):
        super().__init__(
            label=label,
            style=style,
            custom_id=f"interview_{action}_{guild_id}_{record_id}"
        )
        self.action = action
        self.guild_id = guild_id
        self.record_id = record_id

    async def callback(self, interaction: discord.Interaction):
        await _handle_interview_decision(interaction, self.action, self.guild_id, self.record_id)


class InterviewResultView(discord.ui.View):
    """面接結果パネル(合格/不合格/保留の3ボタン)。custom_idにguild_id/record_idを埋め込むため、
    Bot再起動後も対象を特定して再登録できる。"""

    def __init__(self, guild_id: int, record_id: int):
        super().__init__(timeout=None)
        self.add_item(InterviewResultButton("pass", guild_id, record_id, discord.ButtonStyle.success, "合格"))
        self.add_item(InterviewResultButton("fail", guild_id, record_id, discord.ButtonStyle.danger, "不合格"))
        self.add_item(InterviewResultButton("hold", guild_id, record_id, discord.ButtonStyle.secondary, "保留"))


async def _handle_interview_decision(interaction: discord.Interaction, action: str, guild_id: int, record_id: int):
    """管理者が合格/不合格/保留ボタンを押した際の処理。記録の更新・パネル更新・応募者への通知を行う。"""
    guild = bot.get_guild(guild_id)
    if guild is None:
        await interaction.response.send_message("サーバー情報を取得できませんでした。", ephemeral=True)
        return

    # 権限確認：サーバー管理者、または『コマンド許可ユーザー/ロール』、Botオーナーのみ操作可能
    member = guild.get_member(interaction.user.id)
    is_permitted = False
    if member and member.guild_permissions.administrator:
        is_permitted = True
    if not is_permitted:
        owner_id = await resolve_owner_id(interaction.client)
        if interaction.user.id == owner_id:
            is_permitted = True
    if not is_permitted:
        all_data_check = load_data()
        cfg_check = get_guild_config(all_data_check, str(guild_id))
        allowed_ids = set(cfg_check.get("allowed_users", []))
        allowed_role_ids = set(cfg_check.get("allowed_roles", []))
        user_role_ids = {r.id for r in getattr(member, "roles", [])} if member else set()
        if interaction.user.id in allowed_ids or (allowed_role_ids & user_role_ids):
            is_permitted = True

    if not is_permitted:
        await interaction.response.send_message("この操作を行う権限がありません（管理者または許可ユーザー専用）。", ephemeral=True)
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(guild_id))
    records = cfg.setdefault("interview_records", {})
    record = records.get(str(record_id))
    if record is None or record.get("status") != "pending_review":
        await interaction.response.send_message("この面接記録は既に判定済み、または削除されています。", ephemeral=True)
        return

    label_map = {"pass": "合格", "fail": "不合格", "hold": "保留"}
    color_map = {"pass": discord.Color.green(), "fail": discord.Color.red(), "hold": discord.Color.light_grey()}
    result_label = label_map[action]

    record["status"] = action
    record["decided_by"] = interaction.user.id
    save_data(all_data)

    # 元のEmbedへ判定結果を反映し、ボタンを無効化する
    if interaction.message and interaction.message.embeds:
        new_embed = interaction.message.embeds[0]
        new_embed.color = color_map[action]
        new_embed.set_footer(text=f"判定: {result_label}（担当: {interaction.user}）")
        try:
            await interaction.response.edit_message(embed=new_embed, view=None)
        except discord.HTTPException:
            pass
    else:
        await interaction.response.send_message(f"[OK] 判定を「{result_label}」で記録しました。", ephemeral=True)

    # 応募者本人へ結果をDM通知
    applicant_id = record.get("applicant_id")
    applicant = guild.get_member(applicant_id) if applicant_id else None
    if applicant is None and applicant_id:
        try:
            applicant = await bot.fetch_user(applicant_id)
        except discord.HTTPException:
            applicant = None

    if applicant is not None:
        notify_embed = discord.Embed(
            title=f"[面接結果] {guild.name}",
            description=f"あなたの面接結果は **{result_label}** となりました。",
            color=color_map[action]
        )
        try:
            await applicant.send(embed=notify_embed)
        except discord.Forbidden:
            pass
        except discord.HTTPException:
            pass

        # 合格時のみ：管理者が設定した任意のメッセージ・URL（招待リンク等）を追加送信
        if action == "pass":
            pass_message = cfg.get("interview_pass_message")
            if pass_message:
                try:
                    await applicant.send(pass_message)
                except discord.Forbidden:
                    pass
                except discord.HTTPException:
                    pass


@interview_group.command(name="setup", description="【管理者専用】面接のやり方や結果の通知先などをまとめて設定できます")
@discord.app_commands.describe(
    有効化="面接機能を有効にするか",
    結果通知先チャンネル="応募内容をEmbedで送る運営用チャンネル",
    実施方式="DMで実施するか、専用チャンネルを作成して実施するか",
    専用チャンネル作成先カテゴリ="実施方式が「専用チャンネル」の場合のみ使用するカテゴリ（任意）"
)
@discord.app_commands.choices(実施方式=[
    discord.app_commands.Choice(name="DM", value="dm"),
    discord.app_commands.Choice(name="専用チャンネル", value="channel"),
])
async def interview_setup(
    interaction: discord.Interaction,
    有効化: bool,
    結果通知先チャンネル: discord.TextChannel,
    実施方式: discord.app_commands.Choice[str],
    専用チャンネル作成先カテゴリ: discord.CategoryChannel = None
):
    if not await is_admin_or_allowed(interaction):
        return
    if not interaction.guild:
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))
    cfg["interview_enabled"] = 有効化
    cfg["interview_result_channel_id"] = 結果通知先チャンネル.id
    cfg["interview_mode"] = 実施方式.value
    cfg["interview_category_id"] = 専用チャンネル作成先カテゴリ.id if 専用チャンネル作成先カテゴリ else None
    save_data(all_data)

    await interaction.response.send_message(
        f"[OK] 面接システムを設定しました。\n"
        f"有効: {'はい' if 有効化 else 'いいえ'} / 方式: {実施方式.name} / "
        f"結果通知先: {結果通知先チャンネル.mention}\n"
        f"質問への回答は埋め込みフォーム（Modal）形式です。\n"
        f"質問がまだの場合は `/interview question add` で登録してください。\n"
        f"合格時に招待URL等を自動送信したい場合は `/interview pass_message` で設定してください。",
        ephemeral=True
    )



@interview_group.command(name="pass_message", description="【管理者専用】面接に合格した人へ追加で送るメッセージ（招待URLなど）を設定できます")
@discord.app_commands.describe(
    メッセージ="合格時に追加でDM送信するメッセージ。招待URLなども入力できます。空欄のまま実行するとクリア（送信なし）になります"
)
async def interview_pass_message(interaction: discord.Interaction, メッセージ: str = None):
    if not await is_admin_or_allowed(interaction):
        return
    if not interaction.guild:
        return

    all_data = load_data()
