@interview_group.command(name="panel", description="【管理者専用】このチャンネルに「面接を受ける」ボタン付きのパネルを設置できます")
@discord.app_commands.describe(
    タイトル="パネルに表示するタイトル（未指定の場合は既定文を使用）",
    説明="パネルに表示する説明文（未指定の場合は既定文を使用）"
)
async def interview_panel(interaction: discord.Interaction, タイトル: str = None, 説明: str = None):
    if not await is_admin_or_allowed(interaction):
        return
    if not interaction.guild or not isinstance(interaction.channel, discord.TextChannel):
        await interaction.response.send_message("このコマンドはサーバーのテキストチャンネルでのみ使用できます。", ephemeral=True)
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(interaction.guild.id))
    if not cfg.get("interview_enabled"):
        await interaction.response.send_message(
            "面接機能が有効になっていません。先に `/interview setup` で設定してください。", ephemeral=True
        )
        return
    if not cfg.get("interview_questions"):
        await interaction.response.send_message(
            "質問が1つも登録されていません。先に `/interview question add` で登録してください。", ephemeral=True
        )
        return

    embed = discord.Embed(
        title=タイトル or "面接（応募）受付",
        description=説明 or "下のボタンを押すと面接を開始します。質問に順番にお答えください。",
        color=discord.Color.blurple()
    )
    view = InterviewPanelView()

    try:
        message = await interaction.channel.send(embed=embed, view=view)
    except discord.Forbidden:
        await interaction.response.send_message("このチャンネルにメッセージを送信する権限がBotにありません。", ephemeral=True)
        return

    cfg["interview_panel_channel_id"] = interaction.channel.id
    cfg["interview_panel_message_id"] = message.id
    save_data(all_data)

    await interaction.response.send_message("[OK] 面接パネルを設置しました。", ephemeral=True)


class InterviewAnswerModal(discord.ui.Modal):
    """1問分の回答を入力するModal（埋め込みフォーム）。
    送信すると回答を「仮登録」し、内容を確認した上で確定 or やり直しを選べる
    確認画面（InterviewConfirmView）を表示する。"""

    def __init__(self, guild_id: int, record_id: int, question_index: int, question_text: str, default_answer: str = None):
        super().__init__(title=f"質問 {question_index + 1}"[:45])
        self.guild_id = guild_id
        self.record_id = record_id
        self.question_index = question_index
        self.question_text = question_text
        self.answer_input = discord.ui.TextInput(
            label=question_text[:45] if question_text else f"質問{question_index + 1}",
            style=discord.TextStyle.paragraph,
            required=True,
            max_length=1000,
            placeholder="ここに回答を入力してください",
            default=default_answer[:1000] if default_answer else None
        )
        self.add_item(self.answer_input)

    async def on_submit(self, interaction: discord.Interaction):
        await _handle_interview_answer_submit(
            interaction, self.guild_id, self.record_id, self.question_index,
            self.question_text, self.answer_input.value
        )


class InterviewAnswerButton(discord.ui.Button):
    """質問embedに添える「回答する」ボタン。押すとModalが開く。
    custom_idにguild_id/record_id/question_indexを埋め込むため、Bot再起動後も対象を特定できる。
    すでに仮登録済みの回答がある場合は、その内容を初期値としてModalに表示する。"""

    def __init__(self, guild_id: int, record_id: int, question_index: int):
        super().__init__(
            label="回答する",
            style=discord.ButtonStyle.primary,
            custom_id=f"interview_answer_{guild_id}_{record_id}_{question_index}"
        )
        self.guild_id = guild_id
        self.record_id = record_id
        self.question_index = question_index

    async def callback(self, interaction: discord.Interaction):
        all_data = load_data()
        cfg = get_guild_config(all_data, str(self.guild_id))
        records = cfg.setdefault("interview_records", {})
        record = records.get(str(self.record_id))
        if record is None or record.get("status") != "in_progress":
            await interaction.response.send_message("この面接は既に終了・中断されています。", ephemeral=True)
            return
        if interaction.user.id != record.get("applicant_id"):
            await interaction.response.send_message("この面接はあなた宛てではありません。", ephemeral=True)
            return
        if record.get("current_question_index", 0) != self.question_index:
            await interaction.response.send_message("この質問は既に回答済みです。", ephemeral=True)
            return

        questions = cfg.get("interview_questions", [])
        if self.question_index >= len(questions):
            await interaction.response.send_message("質問データが見つかりませんでした。", ephemeral=True)
            return

        question_text = questions[self.question_index]
        pending = record.get("pending_answer") or {}
        default_answer = pending.get("answer") if pending.get("question_index") == self.question_index else None
        modal = InterviewAnswerModal(self.guild_id, self.record_id, self.question_index, question_text, default_answer)
        await interaction.response.send_modal(modal)


class InterviewConfirmProceedButton(discord.ui.Button):
    """回答確認画面の「この内容で確定する」ボタン。"""

    def __init__(self, guild_id: int, record_id: int, question_index: int):
        super().__init__(
            label="この内容で確定する",
            style=discord.ButtonStyle.success,
            custom_id=f"interview_confirm_{guild_id}_{record_id}_{question_index}"
        )
        self.guild_id = guild_id
        self.record_id = record_id
        self.question_index = question_index

    async def callback(self, interaction: discord.Interaction):
        await _handle_interview_answer_confirm(interaction, self.guild_id, self.record_id, self.question_index)


class InterviewRedoButton(discord.ui.Button):
    """回答確認画面の「回答をやり直す」ボタン。入力し直すためのModalを再度開く。"""

    def __init__(self, guild_id: int, record_id: int, question_index: int):
        super().__init__(
            label="回答をやり直す",
            style=discord.ButtonStyle.secondary,
            custom_id=f"interview_redo_{guild_id}_{record_id}_{question_index}"
        )
        self.guild_id = guild_id
        self.record_id = record_id
        self.question_index = question_index

    async def callback(self, interaction: discord.Interaction):
        await _handle_interview_answer_redo(interaction, self.guild_id, self.record_id, self.question_index)


class InterviewConfirmView(discord.ui.View):
    """回答内容を確認し、「確定する」か「やり直す」かを選ぶView。timeout=Noneで永続化。"""

    def __init__(self, guild_id: int, record_id: int, question_index: int):
        super().__init__(timeout=None)
        self.add_item(InterviewConfirmProceedButton(guild_id, record_id, question_index))
        self.add_item(InterviewRedoButton(guild_id, record_id, question_index))


class InterviewQuestionView(discord.ui.View):
    """1問分の質問embedに添えるView（「回答する」ボタンのみ）。timeout=Noneで永続化。"""

    def __init__(self, guild_id: int, record_id: int, question_index: int):
        super().__init__(timeout=None)
        self.add_item(InterviewAnswerButton(guild_id, record_id, question_index))


def _build_interview_question_embed(question_index: int, total: int, question_text: str) -> discord.Embed:
    embed = discord.Embed(
        title=f"[面接] 質問 {question_index + 1}/{total}",
        description=question_text,
        color=discord.Color.blurple()
    )
    embed.set_footer(text="下の「回答する」ボタンを押すと入力フォームが開きます。")
    return embed


async def _send_interview_question(target, guild_id: int, record_id: int, question_index: int, question_text: str, total: int):
    """指定の質問embed+回答ボタンを送信する共通処理。"""
    embed = _build_interview_question_embed(question_index, total, question_text)
    view = InterviewQuestionView(guild_id, record_id, question_index)
    await target.send(embed=embed, view=view)


async def _handle_interview_answer_submit(
    interaction: discord.Interaction, guild_id: int, record_id: int,
    question_index: int, question_text: str, answer_text: str
):
    """Modal送信時のコールバック本体。回答をいったん「仮登録」し、
    内容を確認した上で確定 or やり直しを選べる確認画面を表示する。
    （この時点ではまだ次の質問へは進まない）"""
    guild = bot.get_guild(guild_id)
    if guild is None:
        await interaction.response.send_message("サーバー情報を取得できませんでした。", ephemeral=True)
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(guild_id))
    records = cfg.setdefault("interview_records", {})
    record = records.get(str(record_id))
    if record is None or record.get("status") != "in_progress":
        await interaction.response.send_message("この面接は既に終了・中断されています。", ephemeral=True)
        return
    if record.get("current_question_index", 0) != question_index:
        await interaction.response.send_message("この質問は既に回答済みです。", ephemeral=True)
        return

    record["pending_answer"] = {
        "question_index": question_index,
        "question": question_text,
        "answer": answer_text or "(空の回答)",
    }
    save_data(all_data)

    confirm_embed = discord.Embed(
        title="回答内容の確認",
        description="以下の内容で回答します。よろしければ「この内容で確定する」を、\n入力し直す場合は「回答をやり直す」を押してください。",
        color=discord.Color.orange()
    )
    confirm_embed.add_field(name=f"Q{question_index + 1}. {question_text[:256]}", value=(answer_text or "(空の回答)")[:1024], inline=False)

    await interaction.response.send_message(
        embed=confirm_embed,
        view=InterviewConfirmView(guild_id, record_id, question_index),
        ephemeral=True
    )


async def _handle_interview_answer_redo(interaction: discord.Interaction, guild_id: int, record_id: int, question_index: int):
    """「回答をやり直す」ボタンのコールバック本体。前回入力した内容を初期値としてModalを再度開く。"""
    all_data = load_data()
    cfg = get_guild_config(all_data, str(guild_id))
    records = cfg.setdefault("interview_records", {})
    record = records.get(str(record_id))
    if record is None or record.get("status") != "in_progress":
        await interaction.response.send_message("この面接は既に終了・中断されています。", ephemeral=True)
        return
    if record.get("current_question_index", 0) != question_index:
        await interaction.response.send_message("この質問は既に回答済みです。", ephemeral=True)
        return

    questions = cfg.get("interview_questions", [])
    if question_index >= len(questions):
        await interaction.response.send_message("質問データが見つかりませんでした。", ephemeral=True)
        return

    question_text = questions[question_index]
    pending = record.get("pending_answer") or {}
    default_answer = pending.get("answer") if pending.get("question_index") == question_index else None

    modal = InterviewAnswerModal(guild_id, record_id, question_index, question_text, default_answer)
    await interaction.response.send_modal(modal)


async def _handle_interview_answer_confirm(interaction: discord.Interaction, guild_id: int, record_id: int, question_index: int):
    """「この内容で確定する」ボタンのコールバック本体。仮登録された回答を確定し、
    次の質問へ進むか、全問終了していれば集計して結果チャンネルへ送信する。"""
    guild = bot.get_guild(guild_id)
    if guild is None:
        await interaction.response.send_message("サーバー情報を取得できませんでした。", ephemeral=True)
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(guild_id))
    records = cfg.setdefault("interview_records", {})
    record = records.get(str(record_id))
    if record is None or record.get("status") != "in_progress":
        await interaction.response.send_message("この面接は既に終了・中断されています。", ephemeral=True)
        return
    if record.get("current_question_index", 0) != question_index:
        await interaction.response.send_message("この質問は既に回答済みです。", ephemeral=True)
        return

    pending = record.get("pending_answer") or {}
    if pending.get("question_index") != question_index:
        await interaction.response.send_message("回答データが見つかりませんでした。もう一度「回答する」からやり直してください。", ephemeral=True)
        return

    question_text = pending.get("question", "")
    answer_text = pending.get("answer", "(空の回答)")

    answers = record.setdefault("answers", [])
    answers.append({"question": question_text, "answer": answer_text})
    record.pop("pending_answer", None)

    questions = cfg.get("interview_questions", [])
    next_index = question_index + 1

    if next_index < len(questions):
        # 次の質問へ進む
        record["current_question_index"] = next_index
        save_data(all_data)

        try:
            await interaction.response.edit_message(content="[OK] 回答を確定しました。次の質問を表示します。", embed=None, view=None)
        except discord.HTTPException:
            pass

        next_question_text = questions[next_index]
        target = interaction.channel if record.get("interview_channel_id") else interaction.user
        try:
            await _send_interview_question(target, guild_id, record_id, next_index, next_question_text, len(questions))
        except discord.HTTPException:
            pass
        return

    # 全問終了：集計して結果チャンネルへ送信
    record["status"] = "pending_review"
    save_data(all_data)

    try:
        await interaction.response.edit_message(
            content="[OK] 全ての質問への回答が完了しました。ご協力ありがとうございました。結果は追ってお知らせします。",
            embed=None, view=None
        )
    except discord.HTTPException:
        pass

    result_channel_id = cfg.get("interview_result_channel_id")
    result_channel = guild.get_channel(result_channel_id) if result_channel_id else None

    applicant_id = record.get("applicant_id")
    applicant = guild.get_member(applicant_id) if applicant_id else None
    if applicant is None and applicant_id:
        try:
            applicant = await bot.fetch_user(applicant_id)
        except discord.HTTPException:
            applicant = None

    if result_channel is None:
        if applicant is not None:
            try:
                await applicant.send("[警告] 結果通知先チャンネルが設定されていないため、運営へ送信できませんでした。管理者にご連絡ください。")
            except discord.HTTPException:
                pass
        return

    result_embed = discord.Embed(
        title=f"[面接] 応募結果 #{record_id:04d}",
        description=f"応募者: <@{applicant_id}>（{applicant if applicant else applicant_id}）\nユーザーID: `{applicant_id}`",
        color=discord.Color.gold(),
        timestamp=discord.utils.utcnow()
    )
    for i, qa in enumerate(answers, start=1):
        q_text = qa["question"][:256]
        a_text = (qa["answer"] or "(未回答)")[:1024]
        result_embed.add_field(name=f"Q{i}. {q_text}", value=a_text, inline=False)
    result_embed.set_footer(text="下のボタンで合否を選択してください。")

    result_view = InterviewResultView(guild.id, record_id)
    try:
        result_message = await result_channel.send(embed=result_embed, view=result_view)
    except discord.Forbidden:
        if applicant is not None:
            try:
                await applicant.send("[警告] 結果を運営チャンネルへ送信できませんでした。管理者にご連絡ください。")
            except discord.HTTPException:
                pass
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(guild.id))
    records = cfg.setdefault("interview_records", {})
    if str(record_id) in records:
        records[str(record_id)]["result_message_id"] = result_message.id
        records[str(record_id)]["result_channel_id"] = result_channel.id
        save_data(all_data)

    interview_channel_id = record.get("interview_channel_id")
    if interview_channel_id:
        interview_channel = guild.get_channel(interview_channel_id)
        if interview_channel is not None:
            try:
                await asyncio.sleep(10)
                await interview_channel.delete(reason="面接完了のため専用チャンネルを削除")
            except (discord.Forbidden, discord.HTTPException):
                pass


async def _start_interview(interaction: discord.Interaction):
    """面接開始処理の本体。/面接 コマンドと、パネルの「面接を受ける」ボタンの両方から呼び出される。
    最初の質問をembed+「回答する」ボタン形式で送信し、以降はModal経由で1問ずつ進行する。"""
    guild = interaction.guild
    if guild is None:
        await interaction.response.send_message("このコマンドはサーバー内で実行してください。", ephemeral=True)
        return

    all_data = load_data()
    cfg = get_guild_config(all_data, str(guild.id))

    if not cfg.get("interview_enabled"):
        await interaction.response.send_message(
            "このサーバーでは面接機能が有効になっていません。管理者にお問い合わせください。", ephemeral=True
        )
        return

    questions = cfg.get("interview_questions", [])
    if not questions:
        await interaction.response.send_message(
            "質問が1つも登録されていません。管理者に `/interview question add` での登録を依頼してください。",
            ephemeral=True
        )
        return

    result_channel_id = cfg.get("interview_result_channel_id")
    result_channel = guild.get_channel(result_channel_id) if result_channel_id else None
    if result_channel is None:
        await interaction.response.send_message(
            "結果通知先チャンネルが設定されていません。管理者にお問い合わせください。", ephemeral=True
        )
        return

    records = cfg.setdefault("interview_records", {})
    for rec in records.values():
        if rec.get("applicant_id") == interaction.user.id and rec.get("status") == "in_progress":
            await interaction.response.send_message(
                "既に進行中の面接があります。前回のセッションを完了してから再度お試しください。", ephemeral=True
            )
            return

    mode = cfg.get("interview_mode", "dm")

    interview_channel = None
    target = None

    if mode == "channel":
        category_id = cfg.get("interview_category_id")
        category = guild.get_channel(category_id) if category_id else None
        if not isinstance(category, discord.CategoryChannel):
            category = None
        overwrites = {
            guild.default_role: discord.PermissionOverwrite(view_channel=False),
            guild.me: discord.PermissionOverwrite(view_channel=True, send_messages=True, manage_channels=True),
            interaction.user: discord.PermissionOverwrite(view_channel=True, send_messages=True, read_message_history=True),
        }
        try:
            interview_channel = await guild.create_text_channel(
                name=f"interview-{interaction.user.name}"[:90],
                category=category,
                overwrites=overwrites,
                reason=f"面接開始: {interaction.user}"
            )
        except discord.Forbidden:
            await interaction.response.send_message(
                "専用チャンネルを作成する権限がBotにありません。管理者に確認してください。", ephemeral=True
            )
            return
        except discord.HTTPException as e:
            await interaction.response.send_message(f"チャンネル作成に失敗しました: {e}", ephemeral=True)
            return
        target = interview_channel
        await interaction.response.send_message(f"面接用チャンネルを作成しました: {interview_channel.mention}", ephemeral=True)
    else:
        try:
            target = await interaction.user.create_dm()
            await target.send(f"こんにちは、{interaction.user.mention}さん。これから面接（アンケート）を開始します。")
        except discord.Forbidden:
            await interaction.response.send_message(
                "あなたにDMを送信できませんでした。プライバシー設定でDMを許可してから再度お試しください。",
                ephemeral=True
            )
            return
        await interaction.response.send_message("DMに質問を送信しました。DMをご確認ください。", ephemeral=True)

    record_id = cfg.get("interview_next_id", 1)
    cfg["interview_next_id"] = record_id + 1
    records[str(record_id)] = {
        "applicant_id": interaction.user.id,
        "status": "in_progress",
        "answers": [],
        "interview_channel_id": interview_channel.id if interview_channel else None,
        "current_question_index": 0,
    }
    save_data(all_data)

    try:
        await _send_interview_question(target, guild.id, record_id, 0, questions[0], len(questions))
    except discord.HTTPException:
        # 最初の質問送信に失敗した場合は記録を破棄
        all_data = load_data()
        cfg = get_guild_config(all_data, str(guild.id))
        records = cfg.setdefault("interview_records", {})
        records.pop(str(record_id), None)
        save_data(all_data)
        if interview_channel is not None:
            try:
                await interview_channel.delete(reason="面接質問の送信に失敗したため削除")
            except (discord.Forbidden, discord.HTTPException):
                pass


# ====================================================================
# Botの起動
# ====================================================================

async def _main():
    """BotとWebサーバーを同時に起動します。"""
    # OAuth2設定、またはRailway Webhook機能（デプロイ連動ステータス）のいずれかが
    # 有効な場合にWebサーバーを起動する。
    if DISCORD_CLIENT_ID and DISCORD_CLIENT_SECRET and OAUTH_REDIRECT_URI:
        await _start_web_server()
    elif RAILWAY_MONITOR_AVAILABLE:
        await _start_web_server()
        print("[Webサーバー] OAuth2は未設定ですが、Railway Webhook機能のためWebサーバーを起動しました。")
    else:
        print("[警告] OAuth2の環境変数（DISCORD_CLIENT_ID / DISCORD_CLIENT_SECRET / OAUTH_REDIRECT_URI）が未設定のため、Webサーバーは起動しません。")
        print("       サーバーブラックリスト機能を使用する場合は、これらの環境変数を設定してください。")

    try:
        async with bot:
            await bot.start(TOKEN)
    finally:
        # プロセス終了時（正常終了・Railway再デプロイ等のSIGTERM含む）にも、
        # ここまでの稼働時間・未保存のコマンド実行数を最終保存しておくことで、
        # 再起動後の累計表示の誤差を最小限にする。
        try:
            await _persist_uptime_once()
        except Exception as e:
            print(f"[警告] 終了時の稼働時間保存に失敗しました: {e}")
        try:
            global _command_exec_count_unsaved
            if _command_exec_count_unsaved > 0:
                pending = _command_exec_count_unsaved
                _command_exec_count_unsaved = 0
                await _flush_command_exec_count(pending)
        except Exception as e:
            print(f"[警告] 終了時のコマンド実行数保存に失敗しました: {e}")
        try:
            if _ai_command_usage_unsaved:
                pending_usage = dict(_ai_command_usage_unsaved)
                pending_usage_names = dict(_ai_command_usage_last_seen_names)
                _ai_command_usage_unsaved.clear()
                _ai_command_usage_last_seen_names.clear()
                await _flush_ai_command_usage(pending_usage, pending_usage_names)
        except Exception as e:
            print(f"[警告] 終了時の/aiコマンド利用統計保存に失敗しました: {e}")


asyncio.run(_main())